window.PACK={"book":{"id":"nasikh-nahhas","title":"الناسخ والمنسوخ","type":"usulbook","ilm":"ulumquran","author":"أبو جعفر النحاس (ت ٣٣٨هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"مكتبة الفلاح - الكويت","optional":true,"packVersion":"fc211ab29956"},"items":[{"id":"nasikh-nahhas:1","bookId":"nasikh-nahhas","type":"section","seq":1,"chapter":"مقدمة","title":"باب الترغيب في تعلم الناسخ والمنسوخ","page":"ص0","text":"حدثنا أبو جعفر أحمد بن محمد قال: حدثنا محمد بن جعفر بن أبي داود الأنباري، بالأنبار، قال: حدثنا يحيى بن جعفر، قال: حدثنا معاوية بن عمرو، عن أبي إسحاق، عن عطاء بن السائب، عن أبي البختري، قال","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:2","bookId":"nasikh-nahhas","type":"section","seq":2,"chapter":"ص: 48","title":"ص: 48","page":"ج1 ص47","text":": دخل علي بن أبي طالب رضي الله عنه المسجد فإذا رجل يخوف الناس فقال: ما هذا؟ فقالوا: رجل يذكر الناس، فقال: ليس برجل يذكر الناس ولكنه يقول: أنا فلان ابن فلان فاعرفوني، فأرسل إليه أتعرف الناسخ من المنسوخ؟ فقال: لا قال: فاخرج من مسجدنا ولا تذكر فيه\nقال: أبو جعفر وحدثنا محمد بن جعفر، قال: أخبرنا عبد الله بن يحيى، قال: حدثنا أبو نعيم، قال: حدثنا سفيان الثوري، عن أبي حصين، عن أبي","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:3","bookId":"nasikh-nahhas","type":"section","seq":3,"chapter":"ص: 48","title":"ص: 49","page":"ج1 ص47","text":"عبد الرحمن السلمي، قال: انتهى علي بن أبي طالب رضي الله عنه إلى رجل يقص فقال: «أعلمت الناسخ من المنسوخ؟» قال: لا قال: «هلكت وأهلكت»\nأبو جعفر قال: وحدثنا محمد بن جعفر، قال: حدثنا ابن ديسم، قال: حدثنا سليمان، قال: حدثنا شعبة، عن أبي حصين، عن أبي عبد الرحمن السلمي، قال: مر علي بن أبي طالب رضي الله عنه برجل يقص فقال «أعرفت الناسخ والمنسوخ؟» قال: لا قال: «هلكت وأهلكت»\nقال: أبو جعفر","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:4","bookId":"nasikh-nahhas","type":"section","seq":4,"chapter":"ص: 48","title":"ص: 50","page":"ج1 ص49","text":"وحدثنا بكر بن سهل، قال: حدثنا أبو صالح عبد الله بن صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، في قول الله تعالى {ومن يؤت الحكمة فقد أوتي خيرا كثيرا} [البقرة: 269] قال: «المعرفة بالقرآن ناسخه ومنسوخه ومحكمه ومتشابهه ومقدمه ومؤخره وحرامه وحلاله وأمثاله»\nقال: أبو جعفر حدثنا محمد بن جعفر، قال: حدثنا عبد الله بن يحيى، قال: أخبرنا أبو نعيم، عن سلمة بن نبيط، عن الضحاك بن مزاحم","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:5","bookId":"nasikh-nahhas","type":"section","seq":5,"chapter":"ص: 48","title":"ص: 51","page":"ج1 ص49","text":"، قال: مر ابن عباس بقاص يقص فركله برجله وقال: \" أتدري ما الناسخ من المنسوخ؟ قال: لا قال: «هلكت وأهلكت»\nقال: أبو جعفر وحدثنا محمد بن جعفر، قال: حدثنا ابن ديسم، عن موسى، عن أبي هلال الراسبي، قال: سمعت محمدا، وحدثت عنه، قال: قال حذيفة: \" إنما يفتي الناس أحد ثلاثة: رجل يعلم منسوخ القرآن وذلك عمر، ورجل قاض لا يجد من القضاء بدا، ورجل متكلف فلست بالرجلين الماضيين وأكره أن أكون الثالث \"\nقال: أبو جعفر وحدثنا محمد بن جعفر، قال: حدثنا ابن ديسم، عن موسى، عن حماد بن سلمة، عن عطاء، عن أبي البختري، أن عليا، عليه السلام","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:6","bookId":"nasikh-nahhas","type":"section","seq":6,"chapter":"ص: 48","title":"ص: 52","page":"ج1 ص51","text":"دخل مسجد الكوفة فرأى قاصا يقص فقال: «ما هذا؟» فقالوا: رجل محدث، قال: \" إن هذا يقول: اعرفوني سلوه هل يعرف الناسخ من المنسوخ؟ \" فسألوه فقال: لا، فقال: «لا تحدث»","bab":"باب الترغيب في تعلم الناسخ والمنسوخ"},{"id":"nasikh-nahhas:7","bookId":"nasikh-nahhas","type":"section","seq":7,"chapter":"ص: 48","title":"باب اختلاف العلماء في الذي ينسخ القرآن والسنة للعلماء في هذا خمسة أقوال فمنهم من يقول: ينسخ القرآن القرآن والسنة وهذا قول الكوفيين ومنهم من","page":"ج1 ص51","text":"والسنة وقال قوم: تنسخ السنة السنة ولا ينسخها القرآن والقول الخامس: قاله محمد بن شجاع قال: الأقوال قد تقابلت فلا أحكم على أحدها بالآخر قال أبو جعفر: وحجة أصحاب القول الأول في أن القرآن ينسخ بالقرآن والسنة قول الله تعالى {وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا} [الحشر: 7] وقال تعالى {فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم} [النور\n: 63] وقال تعالى {فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم} [النساء: 65] الآية وقد أجمع الجميع على أن القرآن إذا نزل بلفظ مجمل ففسره رسول الله صلى الله عليه وسلم وبينه كان بمنزلة القرآن المتلو فكذا سبيل النسخ واحتجوا بآيات من القرآن تأولوها على نسخ القرآن بالسنة ستمر في السور إن شاء الله عز وجل واحتج من قال: لا ينسخ القرآن إلا قرآن بقوله تعالى {نأت بخير منها أو مثلها} [البقرة: 106] ، وبقوله تعالى {قل ما يكون لي أن أبدله من تلقاء نفسي} [يونس: 15] وأصحاب القول الأول يقولون: لم ينسخه من قبل نفسه ولكنه بوحي غير القرآن وهكذا سبيل الأحكام إنما تكون من قبل الله تعالى\nوقد روى الضحاك، عن ابن عباس، {نأت بخير منها} [البقرة: 106] \" نجعل مكانها أنفع لكم منها وأخف عليكم {أو مثلها} [البقرة: 106] في المنفعة {أو ننسها} [البقرة: 106] يقول: أو نتركها كما هي فلا ننسخها \" واحتج أصحاب القول الثالث في أن السنة لا ينسخها إلا سنة بأن السنة هي المبينة للقرآن فلا ينسخها، والحجة عليهم أن القرآن هو المبين نبوة رسول الله صلى الله عليه وسلم والآمر بطاعته فكيف لا ينسخ قوله؟","bab":"باب اختلاف العلماء في الذي ينسخ القرآن والسنة للعلماء في هذا خمسة أقوال فمنهم من يقول: ينسخ القرآن القرآن والسنة وهذا قول الكوفيين ومنهم من يقول: ينسخ القرآن ال"},{"id":"nasikh-nahhas:8","bookId":"nasikh-nahhas","type":"section","seq":8,"chapter":"ص: 48","title":"ص: 55","page":"ج1 ص54","text":"وفي هذا أشياء قاطعة قال الله عز وجل {فإن علمتموهن مؤمنات فلا ترجعوهن إلى الكفار} [الممتحنة: 10] فنسخ بهذا ما فارق النبي صلى الله عليه وسلم المشركين\nقال أبو جعفر: ومن هذا أن بكر بن سهل حدثنا قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر، أن اليهود، جاءوا إلى رسول","bab":"باب اختلاف العلماء في الذي ينسخ القرآن والسنة للعلماء في هذا خمسة أقوال فمنهم من يقول: ينسخ القرآن القرآن والسنة وهذا قول الكوفيين ومنهم من يقول: ينسخ القرآن ال"},{"id":"nasikh-nahhas:9","bookId":"nasikh-nahhas","type":"section","seq":9,"chapter":"ص: 48","title":"ص: 56","page":"ج1 ص54","text":"الله صلى الله عليه وسلم فقالوا إن رجلا منا وامرأة زنيا فقال لهم النبي صلى الله عليه وسلم: «ما تجدون في التوراة في شأن الرجم؟» قالوا: نجلدهم ويفضحون فقال لهم عبد الله بن سلام: كذبتم إن فيها للرجم فذهبوا فأتوا بالتوراة فنشروها فجعل رجل منهم يده على آية الرجم ثم قرأ ما قبلها وما بعدها فقال له عبد الله بن سلام: ارفع يدك فرفعها فإذا فيها آية الرجم قالوا: صدق يا محمد، إن فيها آية الرجم فأمر بهما رسول الله صلى الله عليه وسلم فرجما قال عبد الله بن عمر: فرأيته يجنئ على المرأة يقيها الحجارة حكى أهل اللغة أنه يقال: جنأ فلان على فلان إذا أكب عليه ومنه الحديث: أن أبا بكر الصديق رضي الله عنه جنأ على رسول الله صلى الله عليه وسلم بعد موته وقبل بين عينيه وقال: «طبت حيا وميتا» قال أبو جعفر: وهذا من النبي صلى الله عليه وسلم لا يكون إلا من قبل أن ينزل عليه في الزناة شيء ثم نسخ الله جل وعز فعله هذا بقوله تعالى {واللاتي يأتين الفاحشة من نسائكم} [النساء: 15] وما بعده","bab":"باب اختلاف العلماء في الذي ينسخ القرآن والسنة للعلماء في هذا خمسة أقوال فمنهم من يقول: ينسخ القرآن القرآن والسنة وهذا قول الكوفيين ومنهم من يقول: ينسخ القرآن ال"},{"id":"nasikh-nahhas:10","bookId":"nasikh-nahhas","type":"section","seq":10,"chapter":"ص: 48","title":"باب أصل النسخ واشتقاقه \" اشتقاق النسخ من شيئين أحدهما أنه يقال: نسخت الشمس الظل إذا أزالته وحلت محله، ونظير هذا {فينسخ الله ما يلقي الشيطان}","page":"ج1 ص55","text":"فيجعل حراما أو يكون حراما فيجعل حلالا أو يكون محظورا فيجعل مباحا أو مباحا فيجعل محظورا، يكون هذا في الأمر والنهي والحظر والإطلاق والإباحة والمنع","bab":"باب أصل النسخ واشتقاقه \" اشتقاق النسخ من شيئين أحدهما أنه يقال: نسخت الشمس الظل إذا أزالته وحلت محله، ونظير هذا {فينسخ الله ما يلقي الشيطان} [الحج: 52] والآخر م"},{"id":"nasikh-nahhas:11","bookId":"nasikh-nahhas","type":"section","seq":11,"chapter":"ص: 48","title":"باب النسخ على كم يكون من ضرب أكثر النسخ في كتاب الله جل وعز على ما تقدم في الباب الذي قبل هذا أن يزال الحكم بنقل العباد عنه مشتق من نسخت الك","page":"ج1 ص57","text":"قال أبو جعفر: كما حدثنا محمد بن جعفر الأنباري، قال: حدثنا الحسن بن محمد بن الصباح، قال: حدثنا شبابة، عن ورقاء، عن ابن أبي نجيح، عن مجاهد، {ما ننسخ من آية} [البقرة: 106] قال: «نزيل حكمها ونثبت خطها» ونسخ ثان قال أبو جعفر:\nكما حدثنا محمد بن جعفر، قال: حدثنا ابن ديسم، قال: حدثنا أبو عمرو الدوري، عن الكسائي، {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته} [الحج: 52] قال: \" في تلاوته {فينسخ الله ما يلقي الشيطان} [الحج: 52] قال: يزيله فلا يتلى ولا يثبت في المصحف \" قال أبو جعفر: \" وهذا مشتق من نسخت الشمس الظل، وقد زعم أبو عبيد أن هذا النسخ الثاني قد كان ينزل على النبي صلى الله عليه وسلم السورة فترفع فلا تتلى ولا تكتب واحتج أبو عبيد بأحاديث صحيحة السند وخولف أبو عبيد فيما قال، والذين خالفوه على قولين\nمنهم من قال: لا يجوز ما قال ولا يسلب النبي صلى الله عليه وسلم شيئا من القرآن بعدما نزل عليه واحتجوا بقوله جل وعز {ولئن شئنا لنذهبن بالذي أوحينا إليك} [الإسراء: 86] والقول الآخر أن أبا عبيد قد جاء بأحاديث إلا أنه قد غلط في تأويلها لأن تأويلها على النسيان لا على النسخ وقد تأول مجاهد وقتادة {أو ننسها} [البقرة: 106] على هذا من النسيان وهو معنى قول سعد بن أبي وقاص وفيه قولان آخران: أحدهما: عن ابن عباس قال {ما ننسخ من آية} [البقرة: 106] «نرفع حكمها» {أو ننسها} [البقرة: 106] نتركها فلا ننسخها، وقيل {ننسها} [البقرة: 106] نبيح لكم تركها وعلى قراءة البصريين (ننسأها) أحسن ما قيل في معناه أو نتركها ونؤخرها فلا ننسخها ونسخ ثالث، وهو من نسخت الكتاب لم يذكر أبو عبيد إلا هذه الثلاثة\nوذكر غيره رابعا فقال: تنزل الآية وتتلى في القرآن ثم تنسخ فلا تتلى في القرآن ولا تثبت في الخط ويكون حكمها ثابتا\nكما روى الزهري، عن عبيد الله، عن ابن عباس، قال: خطبنا عمر بن الخطاب رضي الله عنه قال: «كنا نقرأ الشيخ والشيخة إن زنيا فارجموهما البتة بما قضيا من اللذة» قال أبو جعفر: وإسناد الحديث صحيح إلا أنه ليس حكمه حكم القرآن الذي نقله الجماعة عن الجماعة ولكنه سنة ثابتة وقد يقول الإنسان: كنت أقرأ كذا لغير القرآن والدليل على هذا أنه قال: ولولا أني أكره أن يقال: زاد عمر في القرآن لزدتها","bab":"باب النسخ على كم يكون من ضرب أكثر النسخ في كتاب الله جل وعز على ما تقدم في الباب الذي قبل هذا أن يزال الحكم بنقل العباد عنه مشتق من نسخت الكتاب ويبقى المنسوخ مت"},{"id":"nasikh-nahhas:12","bookId":"nasikh-nahhas","type":"section","seq":12,"chapter":"ص: 48","title":"باب الفرق بين النسخ والبداء الفرق بين النسخ والبداء أن النسخ تحويل العباد من شيء قد كان حلالا فيحرم أو كان حراما فيحلل أو كان مطلقا فيحظر أو","page":"ج1 ص61","text":"وقت الأمر به أنه سينسخه إلى ذلك الوقت فكان المطلق على الحقيقة غير المحظور فالصلاة كانت إلى بيت المقدس إلى وقت بعينه ثم حظرت فصيرت إلى الكعبة وكذا قوله جل وعز {إذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة} [المجادلة: 12] قد علم الله جل وعز أنه إلى وقت بعينه ثم نسخه في ذلك الوقت وكذا تحريم السبت كان في وقت بعينه على قوم ثم نسخ وأمر قوم آخرون بإباحة العمل فيه، وكان الأول المنسوخ حكمة وصوابا ثم نسخ وأزيل بحكمة وصواب كما تزال الحياة بالموت وكما تنقل الأشياء فلذلك لم يقع النسخ في الأخبار لما فيها من الصدق والكذب؟ وأما البداء فهو ترك ما عزم عليه كقولك: امض إلى فلان اليوم ثم تقول: لا تمض إليه فيبدو لك عن القول الأول وهذا يلحق البشر لنقصانهم وكذا إن قلت: ازرع كذا في هذه السنة ثم قلت: لا تفعل، فهذا البداء فإن قلت: يا فلان ازرع فقد علم أنك تريد مرة واحدة، وكذا النسخ إذا أمر الله جل وعز بشيء في وقت نبي أو في وقت يتوقع فيه\nنبي فقد علم أنه حكمة وصواب إلى أن ينسخ وقد نقل من الجماعة من لا يجوز عليهم الغلط نسخ شرائع الأنبياء من لدن آدم صلى الله عليه وسلم إلى وقت نبينا صلى الله عليه وسلم وهم الذين نقلوا علامات الأنبياء وقد غلط جماعة في الفرق بين النسخ والبداء كما غلطوا في تأويل أحاديث حملوها على النسخ أو على غير معناها","bab":"باب الفرق بين النسخ والبداء الفرق بين النسخ والبداء أن النسخ تحويل العباد من شيء قد كان حلالا فيحرم أو كان حراما فيحلل أو كان مطلقا فيحظر أو كان محظورا فيطلق أو"},{"id":"nasikh-nahhas:13","bookId":"nasikh-nahhas","type":"section","seq":13,"chapter":"ص: 48","title":"باب ذكر بعض هذه الأحاديث","page":"ج1 ص63","text":"قال أبو جعفر: فمن ذلك: ما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن عبد الله بن أبي بكر، عن عمرة، عن عائشة قالت: «كان فيما نزل من القرآن عشر رضعات معلومات فنسخن خمسا معلومات يحرمن فتوفي رسول الله صلى الله عليه وسلم وهن مما يقرأ من القرآن» فتنازع العلماء هذا الحديث لما فيه من الإشكال، فمنهم من تركه وهو مالك بن أنس وهو راوي الحديث، ولم يروه عن عبد الله سواه وقال: رضعة واحدة تحرم وأخذ بظاهر القرآن قال الله جل وعز {وأخواتكم من الرضاعة} [النساء: 23]","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:14","bookId":"nasikh-nahhas","type":"section","seq":14,"chapter":"ص: 48","title":"ص: 65","page":"ج1 ص64","text":"وممن تركه أحمد بن محمد بن حنبل وأبو ثور وقالا: «يحرم ثلاث رضعات» ؛ لقول النبي صلى الله عليه وسلم: «لا تحرم المصة ولا المصتان» قال أبو جعفر وفي الحديث لفظة شديدة الإشكال وهي قولها: «فتوفي رسول الله صلى الله عليه وسلم وهن مما يقرأ من القرآن» فقال بعض جلة أصحاب الحديث: قد روى هذا الحديث رجلان جليلان أثبت من عبد الله بن أبي بكر فلم يذكرا هذا فيه وهما القاسم بن محمد بن أبي بكر الصديق","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:15","bookId":"nasikh-nahhas","type":"section","seq":15,"chapter":"ص: 48","title":"ص: 66","page":"ج1 ص64","text":"رضي الله عنه، ويحيى بن سعيد الأنصاري وممن قال بهذا الحديث، وأنه لا يحرم إلا خمس رضعات الشافعي، فأما القول في تأويل «وهن مما يقرأ من القرآن» فقد ذكرنا رد من رده ومن صححه قال: الذي يقرأ من القرآن {وأخواتكم من الرضاعة} [النساء: 23] ، فأما قول من قال: إن هذا كان يقرأ بعد وفاة رسول الله صلى الله عليه وسلم فعظيم؛ لأنه لو كان مما يقرأ لكانت عائشة رحمها الله قد نبهت عليه ولكان قد نقل إلينا في المصاحف التي نقلها الجماعة الذين لا يجوز عليهم الغلط وقد قال الله جل وعز {إنا نحن نزلنا الذكر وإنا له لحافظون} [الحجر: 9] وقال جل وعز {إن علينا جمعه وقرآنه} [القيامة: 17] ولو كان بقي منه شيء لم ينقل إلينا لجاز أن يكون مما لم ينقل ناسخا لما نقل فيبطل العمل بما نقل ونعوذ بالله من هذا فإنه كفر ومما يشكل من هذا\nما رواه الليث بن سعد، عن يونس، عن الزهري، عن أبي بكر بن عبد الرحمن بن الحارث بن هشام قال: قرأ رسول الله صلى الله عليه وسلم بمكة {والنجم إذا هوى} [النجم: 1] فلما بلغ {أفرأيتم اللات والعزى} [النجم: 19] قال: «فإن شفاعتهن ترتجى» فسها","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:16","bookId":"nasikh-nahhas","type":"section","seq":16,"chapter":"ص: 48","title":"ص: 67","page":"ج1 ص64","text":"فلقيه المشركون والذين في قلوبهم مرض فسلموا عليه وفرحوا فقال لهم: «إنما ذلك من الشيطان» فأنزل الله جل وعز {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان} [الحج: 52] الآية \" وقال قتادة: قرأ «فإن شفاعتهن ترتجى وإنهن لهن الغرانيق العلا» قال أبو جعفر: الحديثان منقطعان والكلام على التأويل فيهما قريب فقال قوم: هذا على التوبيخ أي تتوهمون هذا وعندكم أن","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:17","bookId":"nasikh-nahhas","type":"section","seq":17,"chapter":"ص: 48","title":"ص: 68","page":"ج1 ص64","text":"شفاعتهن ترتجى، ومثله {وتلك نعمة تمنها علي} [الشعراء: 22] وقيل: شفاعتهن ترتجى على قولكم، ومثله {فلما رأى الشمس بازغة قال هذا ربي} [الأنعام: 78] ومثله {أين شركائي} [النحل: 27] أي على قولكم وقيل: المعنى والغرانيق العلا يعني الملائكة ترتجى شفاعتهم فسها، يدلك على هذا الجواب وقيل: إنما قال جل وعز {ألقى الشيطان في أمنيته} [الحج: 52] ولم يقل: إنه قال كذا فيجوز أن يكون شيطان من الجن ألقى هذا أو من الإنس ومما يشكل من هذا الحديث في أن قوله جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284]","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:18","bookId":"nasikh-nahhas","type":"section","seq":18,"chapter":"ص: 48","title":"ص: 69","page":"ج1 ص64","text":"نسخه {لا يكلف الله نفسا إلا وسعها} [البقرة: 286] وهذا لا يجوز أن يقع فيه نسخ؛ لأنه خبر ولكن التأويل في الحديث؛ لأن فيه لما أنزل الله جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] اشتد عليهم ووقع بقلوبهم منه شيء عظيم فنسخ ذلك {لا يكلف الله نفسا إلا وسعها} [البقرة: 286] أي نسخ ما وقع بقلوبهم أي أزاله ورفعه ومن هذا المشكل قوله جل وعز {والذين لا يدعون مع الله إلها آخر} [الفرقان: 68] إلى {ومن يفعل ذلك يلق أثاما يضاعف له العذاب يوم القيامة ويخلد فيه مهانا إلا من تاب} [الفرقان: 69]","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:19","bookId":"nasikh-nahhas","type":"section","seq":19,"chapter":"ص: 48","title":"ص: 70","page":"ج1 ص64","text":"ثم نسخه {ومن يقتل مؤمنا متعمدا} [النساء: 93] وهذا لا يقع فيه ناسخ ولا منسوخ؛ لأنه خبر ولكن تأويله إن صح نزل بنسخته والآيتان واحد يدلك على ذلك {وإني لغفار لمن تاب وءامن} ومن هذا {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] قال عبد الله بن مسعود: \" نسخها {فاتقوا الله ما استطعتم} [التغابن: 16] \" أي نزل بنسختها وهما واحد والدليل على ذلك: قول ابن مسعود: حق تقاته أن يطاع فلا يعصى وأن يشكر فلا يكفر وأن يذكر فلا ينسى قال أبو جعفر: فهذا لا يجوز أن ينسخ؛ لأن الناسخ هو المخالف للمنسوخ من جميع جهاته الرافع له المزيل حكمه، وهذه الأشياء تشرح بأكثر من هذا في مواضعها من السور إن شاء الله","bab":"باب ذكر بعض هذه الأحاديث"},{"id":"nasikh-nahhas:20","bookId":"nasikh-nahhas","type":"section","seq":20,"chapter":"ص: 48","title":"فأول ذلك السورة التي تذكر فيها البقرة","page":"ج1 ص71","text":"قال أبو جعفر: حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: \" فكان أول ما نسخ الله جل وعز من القرآن القبلة وذلك أن رسول الله صلى الله عليه وسلم لما هاجر إلى المدينة وكان أكثر أهلها اليهود أمره الله جل وعز أن يستقبل بيت المقدس ففرحت اليهود بذلك فاستقبلها رسول الله صلى الله عليه وسلم بضعة عشر شهرا فكان رسول الله صلى الله عليه وسلم يحب قبلة إبراهيم صلى الله عليه وسلم فكان يدعو الله جل وعز وينظر إلى السماء فأنزل الله جل وعز {قد نرى تقلب وجهك في السماء} [البقرة: 144] إلى قوله جل وعز {فولوا وجوهكم شطره} [البقرة: 144] يعني نحوه فارتاب من ذلك اليهود وقالوا: {ما ولاهم عن قبلتهم التي كانوا عليها} [البقرة: 142] فأنزل الله جل وعز {قل لله المشرق والمغرب} [البقرة: 142] وقال {فأينما تولوا فثم وجه الله} [البقرة: 115] وقال الله جل وعز {وما جعلنا القبلة التي كنت عليها إلا لنعلم من يتبع الرسول ممن ينقلب على عقبيه} [البقرة: 143] \" قال ابن عباس: ليتميز أهل اليقين من أهل الشك والريبة \" قال أبو جعفر: فهذا يسهل في حفظ نسخ هذه الآية ونذكر ما فيها من الإطالة كما شرطنا\nفمن ذلك ما قرئ على أحمد بن عمرو، عن","bab":"باب السور التي فيها الناسخ والمنسوخ"},{"id":"nasikh-nahhas:21","bookId":"nasikh-nahhas","type":"section","seq":21,"chapter":"ص: 48","title":"ص: 72","page":"ج1 ص71","text":"محمد بن المثنى قال: حدثنا يحيى بن حماد قال: حدثنا أبو عوانة قال: حدثنا الأعمش، عن مجاهد، عن ابن عباس قال: «صلى رسول الله صلى الله عليه وسلم بمكة إلى بيت المقدس والكعبة بين يديه وبعدما هاجر ستة عشر شهرا»\nقال أبو جعفر: وحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا ابن نمير، قال: حدثنا يحيى بن حماد، قال: حدثنا أبو عوانة، عن الأعمش، عن","bab":"باب السور التي فيها الناسخ والمنسوخ"},{"id":"nasikh-nahhas:22","bookId":"nasikh-nahhas","type":"section","seq":22,"chapter":"ص: 48","title":"ص: 73","page":"ج1 ص71","text":"مجاهد، عن ابن عباس، قال: «صلى النبي صلى الله عليه وسلم بمكة نحو بيت المقدس والكعبة بين يديه وبعدما هاجر إلى المدينة ستة عشر شهرا ثم صرف إلى الكعبة» قال أبو جعفر: وفي حديث البراء «صلى ستة عشر أو سبعة عشر شهرا»\nوروى الزهري، عن عبد الرحمن بن عبد الله بن كعب بن مالك، قال: «صرف رسول الله صلى الله عليه وسلم إلى الكعبة في جمادى» وقال ابن إسحاق: «في رجب» وقال\nالواقدي: «في النصف من شعبان» قال أبو جعفر: وأولاها بالصواب القول الأول؛ لأن الذي قال به أجل، ولأن رسول الله صلى الله عليه وسلم قدم المدينة في شهر ربيع الأول فإذا صرف في آخر جمادى الآخرة إلى الكعبة صار ذلك ستة عشر شهرا كما قال ابن عباس وأيضا فإذا صلى إلى الكعبة في جمادى فقد صلى إليها فيما بعدها فعلى قول ابن عباس إن الله جل وعز كان أمره بالصلاة إلى بيت المقدس ثم نسخه. وقال غيره: بل نسخ فعله ولم يكن أمره بالصلاة إلى بيت المقدس ولكن النبي صلى الله عليه وسلم كان يتبع آثار الأنبياء قبله حتى يؤمر بنسخ ذلك وقال قوم: بل نسخ الله جل وعز قوله {فأينما تولوا فثم وجه الله} [البقرة: 115] بالأمر بالصلاة إلى الكعبة\nقال أبو جعفر: وأولى الأقوال بالصواب الأول وهو صحيح عن ابن عباس والذي يطعن في إسناده يقول: ابن أبي طلحة لم يسمع من ابن عباس وإنما أخذ التفسير عن مجاهد وعكرمة وهذا القول لا يوجب طعنا؛ لأنه أخذه عن رجلين ثقتين وهو في نفسه ثقة صدوق وحدثني أحمد بن محمد الأزدي، قال: سمعت علي بن الحسين، يقول: سمعت الحسين بن عبد الرحمن بن فهم، يقول: سمعت أحمد بن حنبل، يقول بمصر: «كتاب التأويل عن معاوية بن صالح لو جاء رجل إلى مصر فكتبه ثم انصرف به ما كانت رحلته عندي ذهبت باطلا» فأما أن تكون الآية ناسخة لقول الله جل وعز {فأينما تولوا فثم وجه الله} [البقرة: 115] فبعيد؛ لأنها تحتمل أشياء سنبينها في ذكر الآية الثانية","bab":"باب السور التي فيها الناسخ والمنسوخ"},{"id":"nasikh-nahhas:23","bookId":"nasikh-nahhas","type":"section","seq":23,"chapter":"ص: 48","title":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {ولله المشرق والمغرب فأينما تولوا فثم وجه الله إن الله واسع عليم} [البقرة: 115] فللعلماء","page":"ج1 ص75","text":"وجه الله جل وعز لا يخلو منه مكان كما قال جل وعز {ما يكون من نجوى ثلاثة إلا هو رابعهم} [المجادلة: 7] الآية، وقال ابن زيد: «كانوا أبيحوا أن يصلوا إلى أي قبلة شاءوا؛ لأن المشارق والمغارب لله جل وعز» فأنزل الله جل وعز {فأينما تولوا فثم وجه الله} [البقرة: 115] فقال النبي صلى الله عليه وسلم: «هؤلاء يهود قد استقبلوا بيتا من بيوت الله تبارك وتعالى» يعني بيت المقدس فصلوا إليه فصلى رسول الله صلى الله عليه وسلم وأصحابه إليه بضعة عشر شهرا فقالت اليهود: ما اهتدى لقبلته حتى\nهديناه فكره النبي صلى الله عليه وسلم قولهم ورفع طرفه إلى السماء فأنزل الله عز وجل {قد نرى تقلب وجهك في السماء} [البقرة: 144] قال أبو جعفر: فهذا قول وقال مجاهد، والضحاك في قوله جل وعز {فأينما تولوا فثم وجه الله} [البقرة: 115] معناه أينما تولوا من مشرق أو مغرب فثم وجه الله التي أمر بها وهي استقبال الكعبة فجعلوا الآية ناسخة، وجعل قتادة، وابن زيد الآية منسوخة وقال إبراهيم النخعي: \" من صلى في سفر في مطر وظلمة شديدة إلى غير القبلة ولم يعلم فلا إعادة عليه {فأينما تولوا فثم وجه الله} [البقرة: 115] \" والقول الرابع أن قوما قالوا: لما صلى النبي صلى الله عليه وسلم على النجاشي صلى عليه وكان يصلي إلى غير قبلتنا فأنزل الله جل وعز {ولله المشرق والمغرب} [البقرة: 115] والقول الخامس أن المعنى ادعوا كيف شئتم مستقبلي القبلة وغير مستقبليها فأينما تولوا فثم وجه الله يستجب لكم والقول السادس من أجلها قولا وهو أن المصلي في السفر على راحلته النوافل جائز له أن يصلي إلى القبلة وإلى غير القبلة\nقال أبو جعفر: وهذا القول عليه فقهاء الأمصار ويدلك على صحته أنه:\nقرئ على أحمد بن شعيب، عن محمد بن المثنى، وعمرو بن علي، عن يحيى بن سعيد، عن عبد الملك، قال: حدثنا سعيد بن جبير، عن ابن عمر، \" أن رسول الله صلى الله عليه وسلم كان يصلي وهو مقبل من مكة إلى المدينة على دابته وفي ذلك أنزل الله {فأينما تولوا فثم وجه الله} [البقرة: 115] \"\nقال وأخبرنا قتيبة، عن مالك، عن","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {ولله المشرق والمغرب فأينما تولوا فثم وجه الله إن الله واسع عليم} [البقرة: 115] فللعلماء في هذه الآية ستة أق"},{"id":"nasikh-nahhas:24","bookId":"nasikh-nahhas","type":"section","seq":24,"chapter":"ص: 48","title":"ص: 79","page":"ج1 ص78","text":"عبد الله بن دينار، عن ابن عمر، «أن رسول الله صلى الله عليه وسلم كان يصلي على راحلته حيثما توجهت به» قال أبو جعفر: والصواب أن يقال: ليست الآية ناسخة ولا منسوخة لأن العلماء قد تنازعوا القول فيها وهي محتملة لغير النسخ وما كان محتملا لغير النسخ لم يقل فيه ناسخ ولا منسوخ إلا بحجة يجب التسليم لها فأما ما كان يحتمل المجمل والمفسر والعموم والخصوص فعن النسخ بمعزل ولا سيما مع هذا الاختلاف وقد اختلفوا أيضا في الآية الثالثة","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {ولله المشرق والمغرب فأينما تولوا فثم وجه الله إن الله واسع عليم} [البقرة: 115] فللعلماء في هذه الآية ستة أق"},{"id":"nasikh-nahhas:25","bookId":"nasikh-nahhas","type":"section","seq":25,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة من هذه السورة قال الله جل وعز {حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين} [البقرة: 238] قال أبو جعفر: أما ما","page":"ج1 ص78","text":"والصلاة الوسطى وهي صلاة العصر فأما {وقوموا لله قانتين} [البقرة: 238] فمن الناس من يقول: القنوت القيام، ومنهم من يقول بحديث\nعمرو بن الحارث، عن دراج، عن أبي الهيثم، عن أبي سعيد الخدري، عن النبي صلى الله عليه وسلم قال: «كل قنوت في القرآن فهو","bab":"باب ذكر الآية الثالثة من هذه السورة قال الله جل وعز {حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين} [البقرة: 238] قال أبو جعفر: أما ما ذكر في الحديث «والص"},{"id":"nasikh-nahhas:26","bookId":"nasikh-nahhas","type":"section","seq":26,"chapter":"ص: 48","title":"ص: 81","page":"ج1 ص80","text":"طاعة» وقال قوم: {وقوموا لله قانتين} [البقرة: 238] ناسخ للكلام في الصلاة قال أبو جعفر: وهذا أحسن ما قيل\nكما قرئ على أحمد بن شعيب، عن سويد بن نصر، عن عبد الله بن المبارك، عن إسماعيل بن أبي خالد، عن الحارث بن شبيل، عن أبي عمرو الشيباني، عن زيد بن أرقم، قال: \" كنا نتكلم في الصلاة في عهد رسول الله صلى الله عليه وسلم يتكلم أحدنا بحاجته حتى نزلت {وقوموا لله قانتين} [البقرة: 238] فنهينا حينئذ عن الكلام \"","bab":"باب ذكر الآية الثالثة من هذه السورة قال الله جل وعز {حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين} [البقرة: 238] قال أبو جعفر: أما ما ذكر في الحديث «والص"},{"id":"nasikh-nahhas:27","bookId":"nasikh-nahhas","type":"section","seq":27,"chapter":"ص: 48","title":"ص: 82","page":"ج1 ص80","text":"قال أبو جعفر: وهذا إسناد صحيح وهو موافق للقول الأول إن القنوت الطاعة أي: وقوموا لله مطيعين فيما أمركم به من ترك الكلام في الصلاة فصح أن الآية ناسخة للكلام في الصلاة قال أبو جعفر: فهذا ما في هذه السورة من الناسخ والمنسوخ من أمر الصلاة وهي ثلاث آيات، والآية الرابعة في القصاص","bab":"باب ذكر الآية الثالثة من هذه السورة قال الله جل وعز {حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين} [البقرة: 238] قال أبو جعفر: أما ما ذكر في الحديث «والص"},{"id":"nasikh-nahhas:28","bookId":"nasikh-nahhas","type":"section","seq":28,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع","page":"ج1 ص81","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام السدوسي، قال: حدثنا عاصم بن سليمان، قال: حدثنا جويبر، عن الضحاك، عن ابن عباس، {الحر بالحر والعبد بالعبد والأنثى بالأنثى} [البقرة: 178] قال: \" نسختها {وكتبنا عليهم فيها أن النفس بالنفس} [المائدة: 45] \"\nوروى ابن أبي طلحة، عن ابن عباس، قال: \" كان الرجل لا يقتل بالمرأة ولكن يقتل الرجل بالرجل والمرأة بالمرأة فنزلت {أن النفس بالنفس} [المائدة: 45]","bab":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه"},{"id":"nasikh-nahhas:29","bookId":"nasikh-nahhas","type":"section","seq":29,"chapter":"ص: 48","title":"ص: 84","page":"ج1 ص83","text":"\" قال أبو جعفر: فهذا قول وقال الشعبي: نزلت في قوم تقاتلوا فقتل بينهم خلق فنزل هذا لأنهم قالوا: لا نقتل بالعبد منا إلا الحر ولا بالأنثى إلا الذكر وقال السدي: نزلت في فريقين وقعت بينهم قتلى فأمر النبي صلى الله عليه وسلم أن يقاص بينهم ديات النساء بديات النساء وديات الرجال بديات الرجال والقول الرابع قول الحسن البصري، رواه عنه قتادة، وعوف، وزعم أنه قول علي بن أبي طالب رضي الله عنه قال: هذا على التراجع إذا قتل رجل امرأة كان أولياء المرأة بالخيار إن شاءوا قتلوا الرجل وأدوا نصف الدية وإن شاءوا أخذوا نصف الدية فإذا قتلت امرأة رجلا فإن شاء أولياء الرجل قتلوا","bab":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه"},{"id":"nasikh-nahhas:30","bookId":"nasikh-nahhas","type":"section","seq":30,"chapter":"ص: 48","title":"ص: 85","page":"ج1 ص83","text":"المرأة وأخذوا نصف الدية وإن شاءوا أخذوا الدية كاملة، وإذا قتل رجل عبدا فإن شاء مولى العبد أن يقتل الرجل ويؤدي بقية الدية بعد ثمن العبد، وإذا قتل عبد رجلا فإن شاء أولياء الرجل أن يقتلوا العبد ويأخذوا بقية الدية وإن شاءوا أخذوا الدية والقول الخامس: إن الآية معمول بها يقتل الحر بالحر والعبد بالعبد والأنثى بالأنثى بهذه الآية ويقتل الرجل بالمرأة، والمرأة بالرجل، والحر بالعبد، والعبد بالحر لقوله جل وعز {ومن قتل مظلوما فقد جعلنا لوليه سلطانا} [الإسراء: 33] ولقول رسول الله صلى الله عليه وسلم الذي نقله الجماعة: «المؤمنون تتكافأ دماؤهم» وهو صحيح عن النبي صلى الله عليه وسلم\nكما قرئ على أحمد بن شعيب، عن محمد بن المثنى، قال: حدثنا يحيى بن سعيد، قال: حدثنا سعيد، عن قتادة، عن الحسن، عن قيس بن عباد، قال: انطلقت أنا والأشتر إلى علي بن أبي طالب","bab":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه"},{"id":"nasikh-nahhas:31","bookId":"nasikh-nahhas","type":"section","seq":31,"chapter":"ص: 48","title":"ص: 86","page":"ج1 ص83","text":"رضي الله عنه فقلنا: هل عهد إليك نبي الله صلى الله عليه وسلم شيئا لم يعهده إلى الناس؟ قال: لا إلا ما في كتابي هذا، فأخرج كتابا من قراب سيفه فإذا فيه «المؤمنون تتكافأ دماؤهم وهم يد على من سواهم ويسعى بذمتهم أدناهم، لا يقتل مؤمن بكافر ولا ذو عهد في عهده، من أحدث حدثا فعلى نفسه ومن آوى محدثا فعليه لعنة الله والملائكة والناس أجمعين» قال أبو جعفر: فسوى رسول الله صلى الله عليه وسلم بين المؤمنين في الدماء شريفهم ووضيعهم وحرهم وعبدهم وهذا قول الكوفيين في العبد خاصة فأما في الذكر والأنثى فلا اختلاف بينهم إلا ما ذكرناه من التراجع والموضع الآخر قوله تعالى {فمن عفي له من أخيه شيء فاتباع بالمعروف} [البقرة: 178] الآية قيل: هي ناسخة لما كان عليه بنو إسرائيل من القصاص بغير دية\nكما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر عن ابن أبي","bab":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه"},{"id":"nasikh-nahhas:32","bookId":"nasikh-nahhas","type":"section","seq":32,"chapter":"ص: 48","title":"ص: 87","page":"ج1 ص85","text":"نجيح، عن مجاهد، وابن عيينة، عن عمرو بن دينار، عن مجاهد، عن ابن عباس، قال: \" كان القصاص في بني إسرائيل ولم تكن الدية فقال الله جل وعز لهذه الأمة {فمن عفي له من أخيه شيء} [البقرة: 178] قال: والعفو أن تقبل الدية في العمد، {فاتباع بالمعروف} [البقرة: 178] من الطالب ويؤدي إليه المطلوب بإحسان {ذلك تخفيف من ربكم ورحمة} [البقرة: 178] عما كتب على من كان قبلكم \" قال أبو جعفر: يكون التقدير فمن صفح له عن الواجب عليه من الدم فأخذت منه الدية، وقيل: عفي بمعنى كثر من قوله جل وعز {حتى عفوا} [الأعراف: 95] وقيل: كتب بمعنى فرض على التمثيل، وقيل: كتب عليكم في اللوح المحفوظ وكذا كتب في آية الوصية وهي الآية الخامسة","bab":"باب ذكر الآية الرابعة {يا أيها الذين آمنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والأنثى بالأنثى فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه"},{"id":"nasikh-nahhas:33","bookId":"nasikh-nahhas","type":"section","seq":33,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة قال الله جل وعز {كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين} [البقرة","page":"ج1 ص86","text":"يجوز أن ينسخ القرآن إلا قرآن قال: نسختها الفرائض\nكما حدثنا علي بن الحسين، عن الحسن بن محمد، قال: حدثنا حجاج، عن ابن جريج، وعثمان بن عطاء، عن عطاء","bab":"باب ذكر الآية الخامسة قال الله جل وعز {كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين} [البقرة: 180] في هذه الآية "},{"id":"nasikh-nahhas:34","bookId":"nasikh-nahhas","type":"section","seq":34,"chapter":"ص: 48","title":"ص: 89","page":"ج1 ص88","text":"، عن ابن عباس، في قوله جل وعز {الوصية للوالدين والأقربين} [البقرة: 180] قال: \" كان ولد الرجل يرثونه وللوالدين والأقربين الوصية فنسخها {للرجال نصيب مما ترك الوالدان والأقربون وللنساء نصيب مما ترك الوالدان والأقربون} [النساء: 7] \" وقال مجاهد: \" نسختها {يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين} [النساء: 11] \" والقول الثالث قاله الحسن قال: «نسخت الوصية للوالدين وثبتت للأقربين الذين لا يرثون» ، وكذا روى ابن أبي طلحة عن ابن عباس وقال الشعبي، والنخعي: «الوصية للوالدين والأقربين على الندب لا على الحتم» والقول الخامس: إن الوصية للوالدين والأقربين واجبة بنص القرآن إذا كانوا لا يرثون قال أبو جعفر: وهذا قول الضحاك، وطاوس قال طاوس: «من","bab":"باب ذكر الآية الخامسة قال الله جل وعز {كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين} [البقرة: 180] في هذه الآية "},{"id":"nasikh-nahhas:35","bookId":"nasikh-nahhas","type":"section","seq":35,"chapter":"ص: 48","title":"ص: 90","page":"ج1 ص88","text":"أوصى لأجنبيين وله أقرباء انتزعت الوصية فردت إلى الأقرباء» وقال الضحاك: «من مات وله شيء ولم يوص لأقربائه فقد مات عن معصية لله جل وعز» وقال الحسن: «إذا أوصى رجل لقوم غرباء بثلثه وله أقرباء أعطي الغرباء ثلث الثلث ورد الباقي على الأقرباء» قال أبو جعفر: فتنازع العلماء معنى هذه الآية وهي متلوة فالواجب أن لا يقال: إنها منسوخة؛ لأن حكمها ليس بناف حكم ما فرضه الله جل وعز من الفرائض فوجب أن يكون {كتب عليكم إذا حضر أحدكم} [البقرة: 180] الآية كقوله {كتب عليكم الصيام} [البقرة: 183]","bab":"باب ذكر الآية الخامسة قال الله جل وعز {كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين} [البقرة: 180] في هذه الآية "},{"id":"nasikh-nahhas:36","bookId":"nasikh-nahhas","type":"section","seq":36,"chapter":"ص: 48","title":"باب ذكر قوله جل وعز {كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون} [البقرة: 183] وهي الآية السادسة قال أبو جعفر: في هذه الآية خمس","page":"ج1 ص88","text":"صيام شهر رمضان نسخ ذلك فمن شاء صام يوم عاشوراء ومن شاء أفطره وإن كان قد صح عن النبي صلى الله عليه وسلم من حديث أبي قتادة «صوم يوم عاشوراء يكفر سنة مستقبلة» وقال عطاء: {كتب عليكم الصيام كما كتب على الذين من قبلكم} [البقرة: 183] «كتب عليكم صيام ثلاثة أيام من كل شهر» قال أبو جعفر: فهذان قولان على أن الآية ناسخة\nوقال أبو العالية والسدي: هي منسوخة؛ لأن الله جل وعز كتب على من قبلنا إذا نام بعد المغرب لم يأكل ولم يقرب النساء، ثم كتب ذلك علينا فقال جل ثناؤه {كتب عليكم الصيام كما كتب على الذين من قبلكم} [البقرة: 183] ثم نسخه بقوله جل وعز {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] وبما بعده، والقول الرابع: إن الله جل وعز كتب علينا الصيام شهرا كما كتب على الذين من قبلنا وأن نفعل كما كانوا يفعلون من ترك الوطء والأكل بعد النوم ثم أباح الوطء والأكل بعد النوم إلى طلوع الفجر والقول الخامس: إنه كتب علينا الصيام وهو شهر رمضان كما كتب صوم شهر رمضان على من قبلنا قال مجاهد: كتب الله جل وعز صوم شهر رمضان على كل أمة وقال قتادة: كتب الله جل وعز صوم شهر رمضان على من قبلنا وهم النصارى قال أبو جعفر: وهذا أشبه بما في الآية، وفيه حديث يدل على صحته قد مر قبل هذا غير مسند ثم كتبناه مسندا\nعن محمد بن محمد بن","bab":"باب ذكر قوله جل وعز {كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون} [البقرة: 183] وهي الآية السادسة قال أبو جعفر: في هذه الآية خمسة أقوال: قال جابر بن"},{"id":"nasikh-nahhas:37","bookId":"nasikh-nahhas","type":"section","seq":37,"chapter":"ص: 48","title":"ص: 93","page":"ج1 ص92","text":"عبد الله، قال: حدثنا الليث بن الفرج، قال: حدثنا معاذ بن هشام بن أبي عبد الله الدستوائي، قال: حدثني أبي، عن قتادة، عن الحسن، عن دغفل بن حنظلة، عن النبي صلى الله عليه وسلم قال: \" كان على النصارى صوم شهر فمرض رجل منهم فقالوا: لئن الله جل وعز شفاه لنزيدن عشرا، ثم كان ملك آخر فأكل لحما فأوجع فاه فقالوا: لئن الله جل وعز شفاه لنزيدن سبعا، ثم كان ملك آخر فقال: لنتمن هذه السبعة الأيام ونجعل صومنا في الربيع \" قال: فصار خمسين \" قال أبو جعفر: أما قول عطاء: إنها ناسخة لصوم ثلاثة أيام فغير معروف وقول من قال: إنه نسخ منها ترك الأكل والوطء بعد النوم لا يمتنع، وقد تكون الآية ينسخ منها الشيء كما قيل في الآية السابعة","bab":"باب ذكر قوله جل وعز {كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون} [البقرة: 183] وهي الآية السادسة قال أبو جعفر: في هذه الآية خمسة أقوال: قال جابر بن"},{"id":"nasikh-nahhas:38","bookId":"nasikh-nahhas","type":"section","seq":38,"chapter":"ص: 48","title":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 18","page":"ج1 ص92","text":"الله عليه وسلم\nكما قرئ على أحمد بن شعيب، عن قتيبة بن سعيد، قال: حدثنا بكر بن مضر، عن عمرو بن الحارث، عن بكير، عن يزيد، مولى سلمة بن الأكوع، عن سلمة بن الأكوع، قال: \" لما نزلت هذه الآية {وعلى الذين يطيقونه فدية طعام مسكين} [البقرة: 184] كان من شاء منا صام ومن شاء أن يفتدي فعل حتى نسختها الآية التي بعدها \"\nقال أبو جعفر: حدثنا علي بن الحسين، عن الحسن بن محمد، قال: حدثنا حجاج، عن ابن جريج، وعثمان بن عطاء، عن عطاء، عن ابن عباس، في قول الله تبارك وتعالى {وعلى الذين يطيقونه فدية طعام مسكين} [البقرة: 184] قال: \" كان الرجل يصبح صائما أو المرأة في شهر رمضان ثم إن شاء أفطر وأطعم مسكينا فنسختها {فمن شهد منكم الشهر فليصمه} [البقرة: 185] \" قال أبو جعفر: فهذا قول وقال السدي {وعلى الذين يطيقونه} [البقرة: 184] كان الرجل يصوم من رمضان ثم يعرض له العطاش فأطلق له الفطر وكذلك الشيخ الكبير والمرضع يفطرون ويطعمون عن كل يوم مسكينا {فمن تطوع خيرا} [البقرة: 184] فأطعم مسكينين فهو خير له وقال الزهري {فمن تطوع خيرا} [البقرة: 184] صام وأطعم مسكينا فهو خير له وقيل: المعنى الذين يطيقونه على جهد قال أبو جعفر: الصواب أن يقال: الآية منسوخة بقوله جل وعز {فمن شهد منكم الشهر فليصمه} [البقرة: 185] ؛ لأن من لم يجعلها منسوخة جعله مجازا وقال المعنى: يطيقونه على جهد أو قال: كانوا يطيقونه فأضمر كان وهو مستغن عن هذا","bab":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 184] قال أبو جعفر: في "},{"id":"nasikh-nahhas:39","bookId":"nasikh-nahhas","type":"section","seq":39,"chapter":"ص: 48","title":"ص: 96","page":"ج1 ص94","text":"وقد اعترض قوم بقراءة من قرأ «يطوقونه» ، «ويطوقونه» ولا يجوز لأحد أن يعترض بالشذوذ على ما نقله جماعة المسلمين في قراءتهم وفي مصاحفهم ظاهرا مكشوفا وما نقل على هذه الصورة فهو الحق الذي لا شك فيه أنه من عند الله جل وعز ومحظور على المسلمين أن يعارضوا ما تثبت به الحجة أنه من عند الله بالظنون والأوهام والشذوذ، وما لا يوقف منه على حقيقة غير أن العلماء قد احتجوا بهذه الآية وإن كانت منسوخة؛ لأنها ثابتة في الخط وهذا لا يمتنع، فقد أجمع العلماء على أن قوله جل وعز {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم} [النساء: 15] أنه منسوخ وثبتوا منها شهادة أربعة في الزنا فكذا","bab":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 184] قال أبو جعفر: في "},{"id":"nasikh-nahhas:40","bookId":"nasikh-nahhas","type":"section","seq":40,"chapter":"ص: 48","title":"ص: 97","page":"ج1 ص94","text":"{وعلى الذين يطيقونه فدية طعام مسكين} [البقرة: 184] وإن كانت منسوخة ففيها غير حجة وذلك أنه قد أجمع العلماء على أن المشايخ والعجائز الذين هم لا يطيقون الصيام أو يطيقونه على مشقة شديدة فلهم الإفطار، وقال ربيعة، ومالك: لا شيء عليهم إذا أفطروا غير أن مالكا قال: لو أطعموا عن كل يوم مسكينا مدا كان أحب إلي، وقال أنس بن مالك، وابن عباس، وقيس بن السائب، وأبو هريرة عليهم الفدية وهو قول الشافعي اتباعا منه لقول الصحابة وهذا أصل من أصوله، وحجة أخرى فيمن قال: عليهم الفدية: إن هذا ليس بمرض ولا هم مسافرون فوجبت عليهم الفدية لقول الله جل وعز {وعلى الذين يطيقونه فدية طعام مسكين} [البقرة: 184] والحجة لمن قال: لا شيء عليهم أنه من أفطر ممن أبيح له الفطر فإنما عليه القضاء إذا وصل إليه","bab":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 184] قال أبو جعفر: في "},{"id":"nasikh-nahhas:41","bookId":"nasikh-nahhas","type":"section","seq":41,"chapter":"ص: 48","title":"ص: 98","page":"ج1 ص94","text":"وهؤلاء لا يصلون إلى القضاء، وأموال الناس محظورة إلا بحجة يجب التسليم لها ولم يأت ذلك ومما وقع فيه الاختلاف أيضا الحبلى والمرضع إذا خافتا على ولديهما فأفطرتا فمن الناس من يقول: عليهما القضاء بلا كفارة هذا قول الحسن، وعطاء، والضحاك، وإبراهيم، وهو قول أهل المدينة وقول ابن عمر، ومجاهد عليهما القضاء والكفارة وهو قول الشافعي وقول ابن عباس، وسعيد بن جبير، وعكرمة عليهما الفدية ولا قضاء عليهما والحجة لمن قال عليهما القضاء بلا كفارة أن من أفطر وهو مأذون له في الفطر فإنما عليه يوم يصومه كاليوم الذي أفطره","bab":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 184] قال أبو جعفر: في "},{"id":"nasikh-nahhas:42","bookId":"nasikh-nahhas","type":"section","seq":42,"chapter":"ص: 48","title":"ص: 99","page":"ج1 ص94","text":"وحجة من قال: عليهما القضاء والكفارة أنهما أفطرتا من أجل غيرهما فعليهما القضاء لتكملا العدة وعليهما الكفارة لقول الله جل وعز {وعلى الذين يطيقونه فدية طعام مسكين} [البقرة: 184] وحجة من قال: عليهما الفدية بغير قضاء الآية أيضا وليس في الآية قضاء فاحتج العلماء بالآية وإن كانت منسوخة وكان بعضهم يقول: ليست بمنسوخة، والصحيح أنها منسوخة والآية الثامنة ناسخة بإجماع","bab":"باب ذكر الآية السابعة قال جل وعز {وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم إن كنتم تعلمون} [البقرة: 184] قال أبو جعفر: في "},{"id":"nasikh-nahhas:43","bookId":"nasikh-nahhas","type":"section","seq":43,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة قال الله جل وعز {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] الآية قال أبو العالية، وعطاء: هي ناسخة لقوله جل و","page":"ج1 ص95","text":"حدثنا أبو جعفر قال: حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أحمد بن عبد الملك، قال: حدثنا زهير، قال: حدثنا أبو إسحاق، عن البراء \" أن الرجل منهم كان إذا نام قبل أن يتعشى في رمضان لم يحل له أن يأكل ليلته ومن الغد حتى نزلت {وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر} [البقرة: 187]","bab":"باب ذكر الآية الثامنة قال الله جل وعز {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] الآية قال أبو العالية، وعطاء: هي ناسخة لقوله جل وعز {كما كتب على الذي"},{"id":"nasikh-nahhas:44","bookId":"nasikh-nahhas","type":"section","seq":44,"chapter":"ص: 48","title":"ص: 101","page":"ج1 ص100","text":"نزلت في أبي قيس وهو ابن عمرو أتى أهله وهو صائم يعني بعد المغرب قال: هل عندكم من شيء؟ فقالت له امرأته: لا تنم حتى أخرج فألتمس لك شيئا فلما رجعت وجدته نائما فقالت: لك الخيبة، فبات وأصبح صائما إلى ارتفاع النهار فغشي عليه فنزلت {وكلوا واشربوا} [البقرة: 187] الآية وقال كعب بن مالك: وكان الناس في رمضان إذا نام أحدهم بعد المساء حرم عليه الطعام والشراب والنساء فسمر عمر بن الخطاب رضي الله عنه عند النبي صلى الله عليه وسلم ليلة فأتى منزله فأراد امرأته فقالت: إني قد نمت فقال: ما نمت فوقع عليها وصنع كعب بن مالك مثل ذلك فأتى عمر النبي صلى الله عليه وسلم فأخبره فنزلت {علم الله أنكم كنتم تختانون أنفسكم فتاب عليكم وعفا عنكم فالآن باشروهن} [البقرة: 187] الآية، فاتفقت الأقوال أنها ناسخة إما بفعلهم وإما بالآية فذلك غير متناقض وفي هذه الآية {ولا تباشروهن وأنتم عاكفون في المساجد} [البقرة: 187] قال الضحاك كانوا يجامعون وهم معتكفون في المساجد، فنزلت، يعني هذه الآية","bab":"باب ذكر الآية الثامنة قال الله جل وعز {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] الآية قال أبو العالية، وعطاء: هي ناسخة لقوله جل وعز {كما كتب على الذي"},{"id":"nasikh-nahhas:45","bookId":"nasikh-nahhas","type":"section","seq":45,"chapter":"ص: 48","title":"ص: 102","page":"ج1 ص100","text":"وقال مجاهد: كانت الأنصار تجامع يعني في الاعتكاف قال الشافعي: فدل أن المباشرة قبل نزول الآية كانت مباحة في الاعتكاف حتى نسخ بالنهي عنه، والله جل وعز أعلم واختلف العلماء في الآية التاسعة، والصحيح أنه لا نسخ فيها","bab":"باب ذكر الآية الثامنة قال الله جل وعز {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] الآية قال أبو العالية، وعطاء: هي ناسخة لقوله جل وعز {كما كتب على الذي"},{"id":"nasikh-nahhas:46","bookId":"nasikh-nahhas","type":"section","seq":46,"chapter":"ص: 48","title":"باب ذكر ما في الآية التاسعة قال جل وعز {وقولوا للناس حسنا}","page":"ج1 ص100","text":"[البقرة: 83]\nقال سعيد، عن قتادة،: «نسختها آية السيف» وقال عطاء «قولوا للناس كلهم حسنا» وقال سفيان: {قولوا للناس حسنا} [البقرة: 83] «مروهم بالمعروف وانهوهم عن المنكر» وهذا أحسن ما قيل فيها لأن الأمر بالمعروف والنهي عن المنكر فرض من الله جل وعز كما قال {ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر} [آل عمران: 104] فجميع المنكر النهي عنه فرض، والأمر بالمعروف من الفرائض فرض وعن النبي صلى الله عليه وسلم «لتأمرن بالمعروف ولتنهون عن المنكر ولتأطرن عليه أطرا أو ليعمنكم الله منه بعذاب» فصح أن الآية غير منسوخة وأن معنى {وقولوا للناس حسنا} [البقرة: 83] ادعوهم إلى الله جل وعز كما قال جل ثناؤه {ادع إلى سبيل ربك بالحكمة والموعظة الحسنة} [النحل: 125] والبين في الآية العاشرة أنها منسوخة","bab":"باب ذكر ما في الآية التاسعة قال جل وعز {وقولوا للناس حسنا}"},{"id":"nasikh-nahhas:47","bookId":"nasikh-nahhas","type":"section","seq":47,"chapter":"ص: 48","title":"باب ذكر الآية العاشرة قال جل وعز {يا أيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا}","page":"ج1 ص103","text":"[البقرة: 104]\nقرئ على عبد الله بن الصقر بن نصر، عن زياد بن أيوب، عن هشيم، قال: حدثنا عبد الملك، عن عطاء، {يا أيها الذين آمنوا لا تقولوا راعنا} [البقرة: 104] قال: «كانت لغة الأنصار في الجاهلية فنزلت هذه الآية» قال أبو جعفر: فنسخ هذا ما كان مباحا قوله، وكان السبب في ذلك","bab":"باب ذكر الآية العاشرة قال جل وعز {يا أيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا}"},{"id":"nasikh-nahhas:48","bookId":"nasikh-nahhas","type":"section","seq":48,"chapter":"ص: 48","title":"ص: 105","page":"ج1 ص104","text":"أن اليهود كانت هذه الكلمة فيهم سبا فنسخها الله جل وعز من كلام المسلمين لئلا تجد اليهود بذلك سببا إلى سب النبي صلى الله عليه وسلم قال مجاهد: «راعنا خلافا، وهذا ما لا يعرف في اللغة» ومعنى راعنا عند العرب فرغ لنا سمعك وتفهم عنا ومنه أرعني سمعك قال أبو جعفر: ولراعنا موضع آخر تكون من الرعية وهي الرقبة، وأما قراءة الحسن «راعنا» بالتنوين فشاذة ومحظور على المسلمين أن يقرءوا بالشواذ أو أن يخرجوا عما قامت به الحجة مما أدته الجماعة والبين في الآية الحادية عشرة أنه قد نسخ منها","bab":"باب ذكر الآية العاشرة قال جل وعز {يا أيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا}"},{"id":"nasikh-nahhas:49","bookId":"nasikh-nahhas","type":"section","seq":49,"chapter":"ص: 48","title":"باب ذكر الآية الحادية عشرة قال الله جل وعز {ود كثير من أهل الكتاب لو يردونكم من بعد إيمانكم كفارا حسدا من عند أنفسهم من بعد ما تبين لهم الحق","page":"ج1 ص104","text":"[البقرة: 109]\nحدثنا أبو جعفر قال: حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا حسين، قال: حدثنا عمرو، قال: حدثنا أسباط، عن السدي، {فاعفوا واصفحوا} [البقرة: 109] قال: \" هي منسوخة نسختها {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] \" قال أبو جعفر: وإنما قلنا: إن البين أن منها منسوخا وهو {فاعفوا واصفحوا} [البقرة: 109] لأن المؤمنين كانوا بمكة يؤذون ويضربون فيتفلتون على قتال المشركين فحظر عليهم وأمروا بالعفو والصفح حتى يأتي الله جل وعز بأمره فأتى الله بأمره ونسخ ذلك والبين في الآية الثانية عشرة أنها غير منسوخة","bab":"باب ذكر الآية الحادية عشرة قال الله جل وعز {ود كثير من أهل الكتاب لو يردونكم من بعد إيمانكم كفارا حسدا من عند أنفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى "},{"id":"nasikh-nahhas:50","bookId":"nasikh-nahhas","type":"section","seq":50,"chapter":"ص: 48","title":"باب ذكر الآية الثانية عشرة قال جل وعز {وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين} [البقرة: 190] قال ابن زيد: \"","page":"ج1 ص106","text":"فحدثنا أبو جعفر قال: حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر، «أن رسول الله صلى الله عليه وسلم رأى في بعض مغازيه امرأة مقتولة فكره ذلك ونهى عن قتل النساء والصبيان» وهكذا، يروى أن عمر بن عبد العزيز رحمه الله كتب: لا تقتلوا النساء والصبيان والرهبان في دار الحرب فتعتدوا {إن الله لا يحب المعتدين} [البقرة: 190]","bab":"باب ذكر الآية الثانية عشرة قال جل وعز {وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين} [البقرة: 190] قال ابن زيد: \" هي منسوخة نسخها {وق"},{"id":"nasikh-nahhas:51","bookId":"nasikh-nahhas","type":"section","seq":51,"chapter":"ص: 48","title":"ص: 108","page":"ج1 ص107","text":"والدليل على هذا من اللغة أن فاعل يكون من اثنين فإنما هو من أنك تقاتله ويقاتلك فهذا لا يكون في النساء ولا في الصبيان ولهذا قال من قال من الفقهاء: لا يؤخذ من الرهبان جزية لقول الله جل وعز {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] إلى {حتى يعطوا الجزية عن يد وهم صاغرون} [التوبة: 29] وليس الرهبان ممن يقاتل فصار المعنى: وقاتلوا في طريق الله وأمره الذين يقاتلونكم ولا تعتدوا فتقتلوا النساء والصبيان والرهبان ومن أعطى الجزية فصح أن الآية غير منسوخة وقد تكلم العلماء في الآية الثالثة عشرة","bab":"باب ذكر الآية الثانية عشرة قال جل وعز {وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين} [البقرة: 190] قال ابن زيد: \" هي منسوخة نسخها {وق"},{"id":"nasikh-nahhas:52","bookId":"nasikh-nahhas","type":"section","seq":52,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191","page":"ج1 ص107","text":"منسوخة واحتجوا بآيات غيرها وبأحاديث من السنن\nفممن قال: إنها غير منسوخة مجاهد روى عنه ابن أبي نجيح أنه قال: «فإن قاتلوكم في الحرم فاقتلوهم لا يحل لأحد أن يقاتل أحدا في الحرم إلا أن يقاتله فإن عدا عليك فقاتلك فقاتله» وهذا قول طاوس، والاحتجاج لهما بظاهر الآية ومن الحديث\nبما حدثناه أحمد بن شعيب، قال: أخبرنا محمد بن رافع، قال: حدثنا","bab":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191] هذه الآية من أصعب "},{"id":"nasikh-nahhas:53","bookId":"nasikh-nahhas","type":"section","seq":53,"chapter":"ص: 48","title":"ص: 110","page":"ج1 ص109","text":"يحيى بن آدم، قال: حدثنا مفضل، عن منصور، عن مجاهد، عن طاوس، عن ابن عباس، قال: قال رسول الله صلى الله عليه وسلم يوم فتح مكة: «إن هذا البلد حرام حرمه الله جل وعز لم يحل فيه القتال لأحد قبلي وأحل لي ساعة وهو حرام بحرمة الله جل وعز» وأما من قال: إنها منسوخة فمنهم قتادة\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا","bab":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191] هذه الآية من أصعب "},{"id":"nasikh-nahhas:54","bookId":"nasikh-nahhas","type":"section","seq":54,"chapter":"ص: 48","title":"ص: 111","page":"ج1 ص109","text":"روح، عن سعيد، عن قتادة، {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه} [البقرة: 191] \" فكان هذا كذا حتى نسخ فأنزل الله جل وعز {وقاتلوهم حتى لا تكون فتنة} [البقرة: 193] أي شرك {ويكون الدين لله} [البقرة: 193] أي لا إله إلا الله عليها قاتل رسول الله صلى الله عليه وسلم وإليها دعا {فإن انتهوا فلا عدوان إلا على الظالمين} [البقرة: 193] من أبى أن يقول: لا إله إلا الله، أن يقاتل حتى يقول لا إله إلا الله \" قال أبو جعفر: وأكثر أهل النظر على هذا القول؛ إن الآية منسوخة وإن المشركين يقاتلون في الحرم وغيره بالقرآن والسنة قال جل وعز {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] وبراءة نزلت بعد سورة البقرة بسنين وقال جل وعز {وقاتلوا المشركين كافة كما يقاتلونكم كافة} [التوبة: 36] وأما السنة:\nفحدثنا أحمد بن شعيب، قال: أخبرنا قتيبة، قال: حدثنا مالك، عن ابن شهاب، عن أنس، أن رسول الله صلى الله عليه وسلم دخل مكة وعليه المغفر فقيل له: إن ابن خطل متعلق بأستار الكعبة فقال: «اقتلوه»\nوقرئ على محمد بن جعفر بن أعين، عن الحسن بن بشر بن سلم","bab":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191] هذه الآية من أصعب "},{"id":"nasikh-nahhas:55","bookId":"nasikh-nahhas","type":"section","seq":55,"chapter":"ص: 48","title":"ص: 112","page":"ج1 ص111","text":"الكوفي، قال: حدثنا الحكم بن عبد الملك، عن قتادة، عن أنس، قال: \" أمن رسول الله صلى الله عليه وسلم أهل مكة يوم الفتح إلا أربعة من الناس: عبد العزى بن خطل، ومقيس بن صبابة الكناني، وعبد الله بن سعد بن أبي سرح، وأم سارة، فأما ابن خطل فقتل وهو متعلق بأستار الكعبة \" وذكر الحديث وقرأ أكثر الكوفيين (ولا تقتلوهم عند المسجد الحرام حتى يقتلوكم فيه فإن قتلوكم فاقتلوهم) وهذه قراءة بينة البعد وقد زعم قوم أنه لا يجوز القراءة بها؛ لأن الله جل وعز لم يفرض على أحد من المسلمين أن لا يقتل المشركين حتى يقتلوا المسلمين","bab":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191] هذه الآية من أصعب "},{"id":"nasikh-nahhas:56","bookId":"nasikh-nahhas","type":"section","seq":56,"chapter":"ص: 48","title":"ص: 113","page":"ج1 ص111","text":"وقال الأعمش: \" العرب تقول: قتلناهم أي قتلنا منهم \" قال أبو جعفر: فهذا أيضا المطالبة فيه قائمة غير أنه قد قرأ به جماعة والله جل وعز أعلم بمخرج قراءتهم وقد تنازع العلماء أيضا في الآية الرابعة عشرة","bab":"باب ذكر الآية الثالثة عشرة قال جل وعز {ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين} [البقرة: 191] هذه الآية من أصعب "},{"id":"nasikh-nahhas:57","bookId":"nasikh-nahhas","type":"section","seq":57,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة عشرة قال جل وعز {الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم}","page":"ج1 ص111","text":"[البقرة: 194]\nقال أبو جعفر: حدثنا محمد بن جعفر الأنباري، قال: حدثنا عبد الله بن أيوب، وعبد الله بن يحيى، قالا: حدثنا حجاج، عن ابن جريج، قال: قلت لعطاء: قول الله جل وعز {الشهر الحرام بالشهر الحرام والحرمات قصاص} [البقرة: 194] قال: «هذا يوم الحديبية صدوا رسول الله صلى الله عليه وسلم عن البيت الحرام وكان معتمرا فدخل في السنة التي بعدها معتمرا مكة فعمرة في الشهر الحرام بعمرة في الشهر الحرام» وقال مجاهد: فخرت قريش بردها رسول الله صلى الله عليه وسلم محرما في ذي القعدة فاعتمر في السنة الثانية في ذي القعدة قال أبو جعفر: التقدير عمرة الشهر الحرام بعمرة الشهر الحرام، والشهر الحرام هاهنا ذو القعدة بلا اختلاف وسمي ذا القعدة لأنهم كانوا يقعدون فيه عن القتال","bab":"باب ذكر الآية الرابعة عشرة قال جل وعز {الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم}"},{"id":"nasikh-nahhas:58","bookId":"nasikh-nahhas","type":"section","seq":58,"chapter":"ص: 48","title":"ص: 115","page":"ج1 ص114","text":"، وكان النبي صلى الله عليه وسلم اعتمر في ذي القعدة من سنة ست من الهجرة فمنعوه من مكة قال ابن عباس: \" فرجعه الله تبارك وتعالى في السنة الأخرى فأقصه منهم {والحرمات قصاص} [البقرة: 194] \" وروي عن ابن عباس، أنه قال: {والحرمات قصاص} [البقرة: 194] «منسوخة كان الله جل وعز قد أطلق للمسلمين إذا اعتدى عليهم أحد أن يقتصوا منه فنسخ الله جل وعز ذلك وصيره إلى السلطان فلا يجوز لأحد أن يقتص من أحد إلا بأمر السلطان ولا أن يقطع يد سارق ولا غير ذلك» وأما مجاهد فذهب إلى أن «المعنى فمن اعتدى عليكم فيه أي في الحرم فاعتدوا عليه بمثل ما اعتدى عليكم» والذي قاله مجاهد أشبه بسياق الكلام؛ لأن قبله ذكر الحرم وهو متصل به إلا أنه منسوخ عند أكثر العلماء وقد أجمع المسلمون أن المشركين أو الخوارج لو غلبوا على الحرم لقوتلوا حتى يخرجوا منه فإن قيل فما معنى الحديث «أحلت لي ساعة وهي حرام بحرمة الله جل وعز» فالجواب أن النبي صلى الله عليه وسلم دخلها غير محرم يوم الفتح ولا يحل هذا لأحد بعده إذا لم يكن من أهل الحرم","bab":"باب ذكر الآية الرابعة عشرة قال جل وعز {الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم}"},{"id":"nasikh-nahhas:59","bookId":"nasikh-nahhas","type":"section","seq":59,"chapter":"ص: 48","title":"ص: 116","page":"ج1 ص114","text":"فأما {والحرمات} [البقرة: 194] فإنما جمع والله أعلم؛ لأنه أريد به حرمة الإحرام وحرمة الشهر الحرام وحرمة البلد الحرام وأما {فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم} [البقرة: 194] فسمي الثاني اعتداء وإنما الاعتداء الأول ففيه جوابان أحدهما أنه مجاز على ازدواج الكلام سمي الثاني باسم الأول مثل {وجزاء سيئة مثلها} والجواب الآخر أنه حقيقة يكون من الشد والوثوب أي: من شد عليكم ووثب بالظلم فشدوا عليه وثبوا بالحق وقد تكلم العلماء من الصحابة وغيرهم بأجوبة مختلفة في الآية الخامسة عشرة","bab":"باب ذكر الآية الرابعة عشرة قال جل وعز {الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم}"},{"id":"nasikh-nahhas:60","bookId":"nasikh-nahhas","type":"section","seq":60,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة عشرة قال جل وعز: {كتب عليكم القتال وهو كره لكم} [البقرة: 216] فقال قوم: هي ناسخة لحظر القتال عليهم ولما أمروا به من ال","page":"ج1 ص114","text":"، وأما قول من قال: هي منسوخة فلا يصح؛ لأنه ليس في قوله جل وعز {وما كان المؤمنون لينفروا كافة} [التوبة: 122] نسخ لفرض القتال وأما قول من قال: هي على الندب فغير صحيح؛ لأن الأمر إذا وقع بشيء لم يحمل على غير الواجب إلا بتوقيف من الرسول صلى الله عليه وسلم أو بدليل قاطع وأما قول عطاء: إنها فرض ولكنه فرض على الصحابة فقول مرغوب عنه وقد رده العلماء حتى قال الشافعي رحمه الله في إلزامه: من قال: {وإذا كنت فيهم فأقمت لهم الصلاة} [النساء: 102] إن هذا للنبي صلى الله عليه وسلم خاصة ولا تصلى صلاة الخوف بعده فعارضه بقوله جل وعز {خذ من أموالهم صدقة تطهرهم وتزكيهم بها} [التوبة: 103] فقول عطاء أسهل ردا من قول من قال: هي على الندب؛ لأن الذي قال: هي على الندب قال: هي مثل قوله جل وعز {يا أيها الذين آمنوا كتب عليكم إذا حضر أحدكم الموت} الآية قال أبو جعفر: وهذا ليس على الندب وقد بيناه فيما تقدم، فأما قول من قال: إن الجهاد فرض بالآية فقوله صحيح وهو قول حذيفة، وعبد الله بن عمرو وقول الفقهاء الذين تدور عليهم الفتيا إلا أنه\nفرض يحمله بعض الناس عن بعض فإن احتيج إلى الجماعة نفروا فرضا واجبا؛ لأن نظير {كتب عليكم القتال} [البقرة: 216] {كتب عليكم الصيام} [البقرة: 183] قال حذيفة: الإسلام ثمانية أسهم: الإسلام سهم والصلاة سهم والزكاة سهم والصيام والحج سهم والجهاد سهم والأمر بالمعروف سهم والنهي عن المنكر سهم ونظير الجهاد في أنه فرض يقوم به بعض المسلمين عن بعض الصلاة على المسلمين إذا ماتوا ومواراتهم قال أبو عبيد: وعيادة المريض ورد السلام وتشميت العاطس وأما قول من قال: الجهاد نافلة، فيحتج بأشياء وهو قول ابن عمر، وابن شبرمة، وسفيان الثوري ومن حجتهم قول النبي صلى الله عليه وسلم رواه ابن عمر: \" بني الإسلام على خمس: شهادة أن لا إله إلا الله، وأن محمدا عبده ورسوله، والصلاة، والصيام، والزكاة، وحج البيت \" قال أبو جعفر: وهذا لا حجة فيه؛ لأنه قد روي عن ابن عمر أنه قال: \" استنبطت هذا ولم يرفعه ولو كان رفعه صحيحا لما كان فيه أيضا حجة؛ لأنه يجوز أن يترك ذكر الجهاد هاهنا لأنه مذكور في القرآن، أو لأن بعض الناس يحمله عن بعض فقد صح فرض الجهاد بنص القرآن وبسنة رسول الله صلى الله عليه وسلم\nكما روى مالك، عن نافع، عن ابن عمر، عن النبي صلى الله عليه وسلم قال: «الخيل معقود في نواصيها الخير إلى يوم القيامة» فسره العلماء أنه في الغزو وفي ذلك أحاديث كثيرة كرهنا أن نطول الكتاب بها لأن فيما تقدم كفاية، والصحيح في الآية السادسة عشرة أنها منسوخة","bab":"باب ذكر الآية الخامسة عشرة قال جل وعز: {كتب عليكم القتال وهو كره لكم} [البقرة: 216] فقال قوم: هي ناسخة لحظر القتال عليهم ولما أمروا به من الصفح والعفو بمكة وقال"},{"id":"nasikh-nahhas:61","bookId":"nasikh-nahhas","type":"section","seq":61,"chapter":"ص: 48","title":"باب ذكر الآية السادسة عشرة قال جل وعز: {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] الآية العلماء على أن هذه الآية منسو","page":"ج1 ص120","text":"ويحتج له بما حدثناه إبراهيم بن شريك، قال: حدثنا أحمد يعني ابن عبد الله بن يونس، قال: حدثنا ليث، عن أبي","bab":"باب ذكر الآية السادسة عشرة قال جل وعز: {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] الآية العلماء على أن هذه الآية منسوخة وأن قتال المشركين"},{"id":"nasikh-nahhas:62","bookId":"nasikh-nahhas","type":"section","seq":62,"chapter":"ص: 48","title":"ص: 122","page":"ج1 ص121","text":"الزبير، عن جابر، قال: «كان رسول الله صلى الله عليه وسلم لا يقاتل في الشهر الحرام إلا أن يغزى أو يغزو فإذا حضر ذلك أقام حتى ينسلخ» قال أبو جعفر: وهذا الحديث يجوز أن يكون قبل نسخ الآية، وابن عباس، وسعيد بن المسيب، وسليمان بن يسار، وقتادة، والأوزاعي على أن الآية منسوخة فمن ذلك:\nما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، قال: حدثنا جويبر، عن الضحاك، عن ابن عباس، قال: وقوله {يسألونك عن الشهر الحرام، قتال فيه} [البقرة: 217] أي في الشهر الحرام {قل قتال فيه كبير} [البقرة: 217] \" أي عظيم، فكان القتال فيه محظورا حتى نسخته آية السيف في براءة {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] فأبيحوا القتال في الأشهر الحرم وفي غيرها \"\nحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال: حدثنا يزيد، قال: أخبرنا سعيد، عن قتادة، في قوله جل وعز {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] \" فكان كذلك حتى نسخه هاتان الآيتان في براءة {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] ثم قال جل وعز {وقاتلوا المشركين كافة كما يقاتلونكم كافة} [التوبة: 36] والأشهر الحرم عهد كان بين رسول الله صلى الله عليه وسلم وبين مشركي قريش، انسلاخ أربعة أشهر بعد يوم النحر لمن كان له عهد ومن لم يكن له عهد فإلى انسلاخ المحرم فأمر الله جل وعز نبيه صلى الله عليه وسلم إذا انسلخت الأشهر الأربعة أن يقاتل المشركين في الحرم وغيره حتى يشهدوا أن لا إله إلا الله وأن محمدا رسول الله \" قال أبو جعفر: هذه الأشهر التي ذكرها قتادة وقال: «هي الحرم هي أشهر السياحة فسماها حرما؛ لأنه حظر القتال فيها» فأما الأشهر الحرم فهي أربعة والعلماء يختلفون في اللفظ بها فمن أهل المدينة من يقول: أولها ذو القعدة، وذو الحجة، والمحرم، ورجب، ومنهم من يبدأ برجب، وأهل الكوفة يقولون: أولها المحرم، ورجب، وذو القعدة، وذو الحجة، وينكرون ما قاله المدنيون وقالوا: قولنا أولى لتكون من سنة واحدة، ومن قال من المدنيين: أولها رجب احتج بأن النبي صلى الله عليه وسلم قدم المدينة في شهر ربيع الأول فوجب أن يكون أولها رجب على هذا","bab":"باب ذكر الآية السادسة عشرة قال جل وعز: {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] الآية العلماء على أن هذه الآية منسوخة وأن قتال المشركين"},{"id":"nasikh-nahhas:63","bookId":"nasikh-nahhas","type":"section","seq":63,"chapter":"ص: 48","title":"ص: 124","page":"ج1 ص122","text":"قال أبو جعفر: والأمر في هذا كله سهل؛ لأن الواو لا تدل على أن الثاني بعد الأول عند أحد من النحويين علمته فإذا كان الأمر على هذا فالأولى أن يؤتى بالأشهر الحرم على ما لفظ به رسول الله صلى الله عليه وسلم وأدي عنه بالأسانيد الصحاح وهو قول المدنيين الأول روى أبو بكرة، وغيره، أن النبي صلى الله عليه وسلم خطب فقال: «إن الزمان قد استدار كهيئته يوم خلق الله السموات والأرض فالسنة اثنا عشر شهرا منها أربعة حرم ذو القعدة وذو الحجة والمحرم ورجب مضر الذي بين جمادى وشعبان» قال أبو جعفر: وقد قامت الحجة بأن قوله جل وعز {يسألونك عن الشهر الحرام قتال فيه} [البقرة: 217] منسوخ بما ذكرناه من نص القرآن وقول العلماء وأيضا فإن النقل يبين ذلك؛ لأنه نقل إلينا أن هذه الآية نزلت في جمادى الآخرة أو في رجب في السنة الثانية من هجرة رسول الله صلى الله عليه وسلم إلى المدينة وقد قاتل رسول الله صلى الله عليه وسلم هوازن بحنين وثقيفا بالطائف في شوال","bab":"باب ذكر الآية السادسة عشرة قال جل وعز: {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] الآية العلماء على أن هذه الآية منسوخة وأن قتال المشركين"},{"id":"nasikh-nahhas:64","bookId":"nasikh-nahhas","type":"section","seq":64,"chapter":"ص: 48","title":"ص: 125","page":"ج1 ص122","text":"وذي القعدة وذو القعدة من الأشهر الحرم وذلك في سنة ثمان من الهجرة قال أبو جعفر: فهذا ما في القتال والجهاد من الناسخ والمنسوخ في هذه السورة مجموعا بعضه إلى بعض ثم نرجع إلى ما فيها من ذكر الحج في الآية السابعة عشرة","bab":"باب ذكر الآية السادسة عشرة قال جل وعز: {يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير} [البقرة: 217] الآية العلماء على أن هذه الآية منسوخة وأن قتال المشركين"},{"id":"nasikh-nahhas:65","bookId":"nasikh-nahhas","type":"section","seq":65,"chapter":"ص: 48","title":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصح","page":"ج1 ص123","text":"العمرة فقالوا فيه أربعة أقوال، فمنهم من قال: إنه منسوخ: كما روي عن عمر، رحمه الله أنه قال في {وأتموا الحج والعمرة لله} [البقرة: 196] : «إتمامهما أن لا يفسخا وقد قيل في إتمامهما غير هذا»\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح، قال: حدثنا شعبة، عن عمرو بن مرة، عن عبد الله بن سلمة، عن علي بن أبي طالب، رضي الله","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:66","bookId":"nasikh-nahhas","type":"section","seq":66,"chapter":"ص: 48","title":"ص: 127","page":"ج1 ص126","text":"عنه في قول الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] قال: «أن تحرم من دويرة أهلك» وقال سفيان: «إتمام الحج والعمرة أن تخرج قاصدا لهما لا لتجارة» ، وقيل: إتمامهما أن تكون النفقة حلالا وقال مجاهد، وإبراهيم: «إتمامهما أن يفعل فيهما كل ما أمر به، وهذا قول جامع» وذهب أبو عبيد إلى أن فسخ الحج إلى العمرة منسوخ بما فعله الخلفاء الراشدون المهديون أبو بكر، وعمر، وعثمان، وعلي رضي الله عنهم؛ لأنهم لم يفسخوا حجهم ولم يحلوا إلى يوم النحر فهذا قول في فسخ الحج: إنه منسوخ والقول الثاني إن فسخ الحج إنما كان لعلة وذلك أنهم كانوا لا يرون العمرة في أشهر الحج ويرون أن ذلك عظيم فأمرهم رسول الله صلى الله عليه وسلم بفسخ الحج وتحويله إلى العمرة ليعلموا أن العمرة في أشهر الحج جائزة، والدليل على أنهم كانوا يتجنبون العمرة في أشهر الحج وهي شوال وذو القعدة وذو الحجة في قول ابن عمر وفي قول ابن عباس: «شوال وذو القعدة وعشر من ذي الحجة» والقولان صحيحان؛ لأن العرب تقول: جئتك رجبا ويوم الجمعة وإنما جئت في بعضه فذو الحجة شهر الحج؛ لأن الحج فيه\nولأن أحمد بن شعيب حدثنا قال: أخبرنا عبد الأعلى بن واصل بن عبد الأعلى، قال: حدثنا أبو أسامة، عن وهيب بن خالد، قال: حدثنا عبد الله بن طاوس، عن أبيه، عن ابن عباس، قال: كانوا يرون أن العمرة، في أشهر الحج من أفجر فجور في الأرض ويجعلون المحرم صفرا ويقولون: إذا برأ الدبر وعفا الوبر وانسلخ صفر أو قال: دخل صفر حلت العمرة لمن اعتمر، فقدم رسول الله صلى الله عليه وسلم وأصحابه رضي الله عنهم صبيحة رابعة مهلين بالحج فأمرهم رسول الله صلى الله عليه وسلم أن يجعلوها عمرة فتعاظم ذلك عندهم فقالوا: يا رسول الله، أي الحل نحل؟ قال: «الحل كله» فهذان قولان والقول الثالث: إن ابن عباس كان يرى الفسخ جائزا ويقول: من حج فطاف بالبيت فقد حل لا اختلاف في ذلك عنه","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:67","bookId":"nasikh-nahhas","type":"section","seq":67,"chapter":"ص: 48","title":"ص: 129","page":"ج1 ص126","text":"قال ابن أبي مليكة: قال له عروة يا ابن عباس، أضللت الناس قال له: بم ذاك يا عرية؟ قال: تفتي الناس بأنهم إذا طافوا بالبيت حلوا وقد حج أبو بكر، وعمر فلم يحلا إلى يوم النحر فقال له ابن عباس: قال الله جل وعز {ثم محلها إلى البيت العتيق} [الحج: 33] أأقول لك قال الله جل وعز ثم تقول لي قال أبو بكر، وعمر وقد أمر رسول الله صلى الله عليه وسلم بالفسخ؟ قال أبو جعفر: وهذا القول انفرد به ابن عباس كما انفرد بأشياء غيره فأما قوله جل وعز {ثم محلها إلى البيت العتيق} [الحج: 33] فليس فيه حجة لأن الضمير للبدن وليس للناس ومحل الناس يوم النحر على قول الجماعة ولهذا سمي يوم الحج الأكبر وذلك صحيح عن النبي صلى الله عليه وسلم","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:68","bookId":"nasikh-nahhas","type":"section","seq":68,"chapter":"ص: 48","title":"ص: 130","page":"ج1 ص126","text":"وعن علي بن أبي طالب رضي الله عنه، وعن ابن عباس، وإن كان قد روي عن ابن عباس أنه يوم عرفات فهذه ثلاثة أقوال في فسخ الحج والقول الرابع: أصحها للتوقيف من رسول الله صلى الله عليه وسلم وهو أنه مخصوص\nكما حدثنا أحمد بن شعيب، قال: أخبرنا إسحاق بن إبراهيم، عن عبد العزيز عن ربيعة بن أبي عبد الرحمن، عن الحارث بن بلال، عن أبيه، قال: قلنا: يا رسول الله، أفسخ الحج لنا خاصة أم للناس عامة؟ قال: «بل لنا خاصة» وقال أبو ذر: كان فسخ الحج لنا رخصة فإن احتج محتج بقول النبي صلى الله عليه وسلم في غير هذا الحديث: «ذلك لأبد الأبد» فلا حجة له فيه؛ لأنه يعني بذلك جواز العمرة في أشهر الحج فأما حديث عمر أنه قال في المتعة: إن أتيت بمن فعلها عاقبته، وكذا المتعة الأخرى فإحداهما المتعة المحرمة بالنساء التي هي بمنزلة الزنا، والأخرى فسخ الحج فلا ينبغي لأحد أن يتأول عليه أنها المتعة","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:69","bookId":"nasikh-nahhas","type":"section","seq":69,"chapter":"ص: 48","title":"ص: 131","page":"ج1 ص128","text":"في أشهر الحج لأن الله جل وعز قد أباحها بقوله جل وعز {فمن تمتع بالعمرة إلى الحج فما استيسر من الهدي} [البقرة: 196] واختلف العلماء في العمرة فقال بعضهم: هي واجبة بفرض الله جل وعز، وقال بعضهم: هي واجبة بسنة رسول الله صلى الله عليه وسلم وقال بعضهم: ليست واجبة ولكنها سنة فممن يروى عنه أنه قال: إنها واجبة عمر وابن عمر، وابن عباس، وهو قول الثوري، والشافعي وأما السنة:\nفحدثنا أحمد بن شعيب، قال: أخبرنا محمد بن عبد الأعلى، قال: حدثنا خالد، قال: حدثنا شعبة، قال: سمعت النعمان بن سالم، قال: سمعت عمرو بن أوس، يحدث عن أبي رزين، أنه قال: يا رسول الله، إن أبي شيخ كبير لا يستطيع الحج ولا العمرة ولا الظعن قال: «حج عن أبيك واعتمر»","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:70","bookId":"nasikh-nahhas","type":"section","seq":70,"chapter":"ص: 48","title":"ص: 132","page":"ج1 ص130","text":"واحتج قوم في وجوبها بظاهر قول الله جل وعز {ولله على الناس حج البيت من استطاع} [آل عمران: 97] والحج القصد وهو يقع للحج والعمرة، وقال جل وعز {يوم الحج الأكبر} [التوبة: 3] والحج الأصغر العمرة إلا أن أهل اللغة يقولون: اشتقاق العمرة من غير اشتقاق الحج، لأن العرب تقول: اعتمرت فلانا أي زرته فمعنى العمرة زيارة البيت ولهذا كان ابن عباس لا يرى العمرة لأهل مكة لأنهم بها فلا معنى لزيارتهم إياها، والحج في اللغة القصد وممن قال: العمرة غير واجبة جابر بن عبد الله، وسعيد بن المسيب وهو قول مالك وأبى حنيفة وقال من احتج لهم:\nروى الحجاج بن أرطأة، عن محمد بن المنكدر، عن جابر، قال: قيل: يا رسول الله، العمرة واجبة؟ قال: «لا وأن تعتمروا خير لكم» قال أبو جعفر: وهذا لا حجة فيه؛ لأن الحجاج بن أرطاة يدلس عمن لقيه وعمن لم يلقه فلا تقوم بحديثه حجة إلا أن يقول: حدثنا أو أخبرنا أو سمعت ولكن الحجة في ذلك قول من قال: الفرائض لا تقع باختلاف وإنما تقع باتفاق","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:71","bookId":"nasikh-nahhas","type":"section","seq":71,"chapter":"ص: 48","title":"ص: 133","page":"ج1 ص131","text":"ومما يدخل في هذا الباب الاشتراط في الحج وهو أن يقول إذا لبى بالحج إن حبسني حابس فمحلي حيث حبسني فممن قال بالاشتراط في الحج عمر، وعلي، وابن مسعود، ومعاذ، وسعيد بن جبير، وعطاء، والحسن، وقتادة، وابن سيرين وهو قول أحمد بن محمد بن حنبل، وإسحاق بن راهويه وقول الشافعي بالعراق ثم تركه بمصر وممن لم يقل به مالك، وأبو حنيفة، والشافعي بمصر وحجة الذين قالوا به:\nما حدثنا أحمد بن شعيب، قال: أخبرنا إسحاق بن إبراهيم، قال: أخبرنا عبد الرزاق، قال: أخبرنا معمر، عن الزهري، عن عروة، عن عائشة، وعن هشام بن عروة، عن أبيه، عن عائشة، رضي الله عنها أن رسول الله صلى الله عليه وسلم دخل على ضباعة فقالت: يا رسول الله، إني أريد الحج، وأنا شاكية فقال: حجي واشترطي أن محلي حيث تحبسني \" قال إسحاق: قلت لعبد الرزاق: الزهري، وهشام قالا: عن","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:72","bookId":"nasikh-nahhas","type":"section","seq":72,"chapter":"ص: 48","title":"ص: 134","page":"ج1 ص132","text":"عائشة؟ قال: نعم كلاهما، قال أحمد بن شعيب: لم يصله إلا عبد الرزاق، عن معمر فلا أدري من أيهما ذلك؟\nوحدثنا أحمد بن شعيب، قال: أخبرني عمران بن يزيد، قال: حدثنا شعيب، وهو ابن إسحاق قال: حدثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع طاوسا، وعكرمة، يخبران عن ابن عباس، قال جاءت ضباعة بنت الزبير إلى رسول الله صلى الله عليه وسلم فقالت: إني امرأة ثقيلة وأنا أريد الحج فكيف تأمرني أن أصنع؟ قال: «أهلي واشترطي أن محلي حيث حبستني» قال أبو جعفر: أهلي معناه لبي، وأصله من رفع الصوت، ومنه استهل المولود ومنه {وما أهل لغير الله به} [المائدة: 3] فقد صح عن النبي صلى الله عليه وسلم الاشتراط في الحج فقال بهذا من ذكرناه واتبعوا ما جاء عن الرسول صلى الله عليه وسلم، وكرهه قوم واحتجوا بحديث الزهري عن سالم، عن أبيه أنه كره الاشتراط في الحج، وقال «أما حسبكم سنة نبيكم صلى الله عليه وسلم أنه لم يشترط» ، واحتج بعض من كرهه بأن النبي صلى الله عليه وسلم إنما قال لها: «واشترطي أن محلي حيث حبستني» ولم يقل لها: إنه ليس عليك حج إن أحصرت","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:73","bookId":"nasikh-nahhas","type":"section","seq":73,"chapter":"ص: 48","title":"ص: 135","page":"ج1 ص133","text":"وفي الآية {فمن تمتع بالعمرة إلى الحج فما استيسر من الهدي} [البقرة: 196] فكان هذا ناسخا لما كانوا يعتقدونه من أن العمرة لا تجوز في أشهر الحج فجازت في أشهر الحج وجاز القرآن ولم يكونوا يستعملونه ثم اختلف العلماء في حجة الوداع فقال قوم: إن رسول الله صلى الله عليه وسلم أفرد الحج فيها، وقال قوم: بل تمتع بالعمرة إلى الحج، وقال قوم: بل قرن وجمع بين الحج والعمرة وكل هذا مروي بأسانيد صحاح حتى طعن بعض أهل الأهواء وبعض الملحدين في هذا وقالوا: هذه الحجة التي حجها رسول الله صلى الله عليه وسلم أجمع ما كان أصحابه فقد اختلفتم فيها وهي أصل من أصول الدين، فكيف يقبل منكم ما رويتموه من أخبار الآحاد، وهذا الطعن من أحد اثنين إما أن يكون الطاعن به جاهلا باللغة التي خوطب بها القوم وإما أن يكون جائرا عن الحق، وسنذكر أصح ما روي من الاختلاف في هذا ونبين أنه غير متضاد وقد قال الشافعي: «هذا من أيسر ما اختلفوا فيه وإن كان قبيحا» وهذا كلام صحيح؛ لأن المسلمين قد أجمعوا أنه يجوز الإفراد والتمتع والقران وإن كان بعضهم قد اختار بعض هذا\nقال أبو جعفر: كما قرئ على أحمد بن محمد بن خالد البراثي، عن خلف بن","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:74","bookId":"nasikh-nahhas","type":"section","seq":74,"chapter":"ص: 48","title":"ص: 136","page":"ج1 ص134","text":"هشام المقرئ، قال: سمعت مالك بن أنس، في \" الإفراد بالحج: إنه أحب إليه لا التمتع والقران قال: وليس على المفرد هدي \"\nقال البراثي، وحدثنا عبد الله بن عون، قال: حدثنا مالك بن أنس، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، رضي الله عنها «أن رسول الله صلى الله عليه وسلم أفرد الحج» وهذا إسناد مستقيم لا مطعن فيه والحجة لمن اختار الإفراد أن المفرد أكثر تعبا من المتمتع لإقامته على الإحرام فرأى أن ذلك أعظم لثوابه والحجة في اتفاق الأحاديث أن رسول الله صلى الله عليه وسلم لما أمر بالتمتع والقرآن جاز أن يقال: تمتع رسول الله صلى الله عليه وسلم وقرن كما قال جل وعز {ونادى فرعون في قومه} [الزخرف: 51] وقال عمر بن الخطاب رضي الله عنه: «رجمنا ورجم رسول الله صلى الله عليه وسلم، وإنما أمرنا بالرجم»\nوحدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر، «أن رسول الله صلى الله عليه وسلم قطع في مجن قيمته ثلاثة دراهم» وإنما أمر من قطع فلما كان رسول الله صلى الله عليه وسلم قد أمر بالتمتع والقران جاز هذا ومن الدليل على أمره بذلك:\nأن أحمد بن شعيب حدثنا قال: أخبرنا يحيى بن حبيب بن عربي، قال: حدثنا حماد، عن هشام بن عروة، عن أبيه، عن عائشة، قالت: خرجنا مع رسول الله صلى الله عليه وسلم موافين لهلال ذي الحجة، فقال:: «من شاء منكم أن يهل بحجة فليهل، ومن شاء أن يهل بعمرة فليهل بعمرة» قال أبو جعفر: هذا احتجاج لمن رأى إفراد الحج، وسنذكر غيره، فأما التمتع بالعمرة إلى الحج فهذا موضع ذكره\nقال أبو جعفر: قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن عبد الله بن","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:75","bookId":"nasikh-nahhas","type":"section","seq":75,"chapter":"ص: 48","title":"ص: 138","page":"ج1 ص137","text":"بكير، عن الليث بن سعد، قال: حدثني عقيل، عن الزهري، قال: أخبرني سالم بن عبد الله، عن عبد الله بن عمر، قال: تمتع رسول الله صلى الله عليه وسلم بالعمرة إلى الحج وأهدى فساق الهدي من ذي الحليفة وبدأ فأهل بالعمرة ثم أهل بالحج وتمتع الناس مع رسول الله صلى الله عليه وسلم بالعمرة إلى الحج، وساق الحديث قال الزهري: وأخبرني عروة، عن عائشة،، عن رسول الله صلى الله عليه وسلم في تمتعه بالعمرة إلى الحج مثل الذي أخبرني سالم عن عبد الله بن عمر، عن رسول الله صلى الله عليه وسلم قال أبو جعفر: فإن قال قائل: هذا متناقض رويتم عن القاسم، عن عائشة أن رسول الله صلى الله عليه وسلم أفرد الحج، ورويتم هاهنا عن الزهري، عن عروة، عن عائشة التمتع، قيل له: الحديثان متفقان وذلك بين ألا ترى أن في هذا الحديث نصا، وبدأ رسول الله صلى الله عليه وسلم فأهل بالعمرة ثم أهل بالحج أفلا ترى الحج مفردا من العمرة فهذا بين جدا\nقال أبو جعفر","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:76","bookId":"nasikh-nahhas","type":"section","seq":76,"chapter":"ص: 48","title":"ص: 139","page":"ج1 ص137","text":": حدثنا أحمد بن شعيب، قال: أخبرنا محمد بن المثنى، عن عبد الرحمن، عن سفيان، عن قيس بن مسلم، عن طارق بن شهاب، عن أبي موسى، قال: قدمت على رسول الله صلى الله عليه وسلم وهو بالبطحاء فقال: «بم أهللت؟» فقلت بإهلال النبي صلى الله عليه وسلم قال: «هل سقت من هدي؟» قلت: لا قال: «فطف بالبيت وبالصفا والمروة وحل» فطفت بالبيت وبالصفا والمروة ثم أتيت امرأة من قومي فمشطتني وغسلت رأسي فلم أزل أفتي الناس بذلك في إمارة أبي بكر وإمارة عمر فإني لقائم بالموسم إذ أتاني رجل فقال: إنك لا تدري ما أحدث أمير المؤمنين في النسك، فقلت: يا أيها الناس من أفتيناه بشيء فليتئد فإن أمير المؤمنين قادم فأتموا به فلما قدم قلت: يا أمير المؤمنين ما أحدثت في النسك؟ قال: أن نأخذ بكتاب الله جل وعز فقد قال الله","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:77","bookId":"nasikh-nahhas","type":"section","seq":77,"chapter":"ص: 48","title":"ص: 140","page":"ج1 ص137","text":"جل ثناؤه {وأتموا الحج والعمرة لله} [البقرة: 196] وأن نأخذ بسنة رسول الله صلى الله عليه وسلم فإنه لم يحل حتى نحر الهدي \" قال أبو جعفر: قوله: فليتئد معناه فليتثبث، مشتق من التؤدة، وقوله: لم يحل أي: لم يحل من إحرامه، أي: لم يستحل لبس الثياب والطيب وما أشبههما وفي هذا الحديث من رسول الله صلى الله عليه وسلم أمر أبي موسى بالتمتع وفيه أن أبا موسى توقف عن الفتيا بالتمتع وقد أمره به رسول الله صلى الله عليه وسلم إلى أن وافى عمر فلما وافى عمر منع من التمتع فلم يراده أبو موسى، لأن النبي صلى الله عليه وسلم قد أجاز غيره فدل هذا على أن إمام المسلمين إذا اختار قولا يجوز ويجوز غيره وجب أن لا يخالف عليه ونظير هذا أن رسول الله صلى الله عليه وسلم قال: «أنزل القرآن على سبعة أحرف» فرأى عثمان رضي الله عنه أن يزيل منها ستة وأن يجمع الناس على حرف واحد فلم يخالفه أكثر الصحابة حتى قال علي رضي الله","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:78","bookId":"nasikh-nahhas","type":"section","seq":78,"chapter":"ص: 48","title":"ص: 141","page":"ج1 ص137","text":"عنه: «لو كنت موضعه لفعلت كما فعل» وفي هذا الحديث أن النبي صلى الله عليه وسلم قال لأبي موسى: «طف بالبيت وبين الصفا والمروة وحل» ولم يقل له: احلق ولا قصر فدل على أن الحلق والتقصير غير واجبين وفيه أهللت بإهلال النبي صلى الله عليه وسلم فدل هذا على أن هذا جائز لمن فعله، وقال بعض أهل العلم: هذا يدل على أنه جائز أن يلبي الرجل ولا يريد حجا ولا عمرة ثم يوجب بعد ذلك ما شاء واستدل قائل هذا على أن النبي صلى الله عليه وسلم لبى مرة بالإفراد ومرة بالتمتع ومرة بالقران حتى نزل عليه القضاء فقرن وقال بعض أهل العلم: كان رسول الله صلى الله عليه وسلم قارنا وإذا كان قارنا فقد حج واعتمر، واتفقت الأحاديث ومن أحسن ما قيل في هذا أن رسول الله صلى الله عليه وسلم أهل بعمرة فقال من رآه تمتع ثم أهل بحجة فقال من رآه أفرد ثم قال: «لبيك بحجة وعمرة» فقال من سمعه: قرن فاتفقت الأحاديث والدليل على هذا أنه لم يرو أحد عن النبي صلى الله عليه وسلم أنه قال أفردت ولا تمتعت وصح عنه أنه قال «قرنت»\nكما حدثنا أحمد بن شعيب","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:79","bookId":"nasikh-nahhas","type":"section","seq":79,"chapter":"ص: 48","title":"ص: 142","page":"ج1 ص138","text":"، قال: أخبرني معاوية بن صالح، قال: حدثنا يحيى بن معين، قال: حدثنا حجاج، قال: حدثنا يونس، عن أبي إسحاق، عن البراء، قال: كنت مع علي بن أبي طالب رضي الله عنه حين أمره رسول الله صلى الله عليه وسلم على اليمن فلما قدم على النبي صلى الله عليه وسلم قال علي: أتيت رسول الله صلى الله عليه وسلم فقال لي رسول الله صلى الله عليه وسلم: \" ماذا صنعت؟ قلت: أهللت بإهلالك قال: «فإني سقت الهدي وقرنت» ثم أقبل على أصحابه فقال: «لو استقبلت من أمري كما استدبرت لفعلت كما فعلتم ولكن سقت الهدي وقرنت»\nوحدثنا أحمد بن شعيب، قال: حدثنا يعقوب، قال: حدثنا","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:80","bookId":"nasikh-nahhas","type":"section","seq":80,"chapter":"ص: 48","title":"ص: 143","page":"ج1 ص141","text":"هشيم، قال: أخبرنا حميد، قال: حدثنا بكر بن عبد الله المزني، قال: سمعت أنس بن مالك، يقول: سمعت رسول الله صلى الله عليه وسلم يلبي بالعمرة والحج جميعا فحدثت بذلك ابن عمر، فقال: لبى بالحج وحده، فلقيت أنسا فحدثته فقال: ما تعدوننا إلا صبيانا سمعت رسول الله صلى الله عليه وسلم يقول: «لبيك عمرة وحجة معا» فهذه أحاديث بينة ويزيدك في ذلك بيانا\nأن بكر بن سهل حدثنا، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر، عن حفصة، قالت: قلت: يا رسول الله، ما بال الناس قد حلوا من عمرتهم ولم تحل؟ قال: «إني لبدت رأسي وسقت هديي فلا أحل حتى أنحر» وهذا يبين أنه كان قارنا، لأنه لو كان","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:81","bookId":"nasikh-nahhas","type":"section","seq":81,"chapter":"ص: 48","title":"ص: 144","page":"ج1 ص142","text":"متمتعا أو مفردا لم يمتنع من نحر الهدي فهذا ما في الحج من ناسخ ومنسوخ واحتجاج، ونذكر بعده ما في الخمر من النسخ ونذكر قول من قال: إن الآية التي في سورة البقرة ناسخه لما كان مباحا من شرب الخمر، وقول من قال إنها","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:82","bookId":"nasikh-nahhas","type":"section","seq":82,"chapter":"ص: 48","title":"ص: 145","page":"ج1 ص142","text":"منسوخة ونذكر ما هو بمنزلة الخمر من الشراب وما يدل على ذلك من الأحاديث الصحاح عن رسول الله صلى الله عليه وسلم، وما يدل من المعقول ومن الاشتقاق واللغة على أن ما أسكر كثيره فقليله حرام وأنه خمر ونذكر الشبهة التي أدخلها قوم وهذا كله في الآية الثامنة عشرة","bab":"باب ذكر الآية السابعة عشرة قال الله جل وعز {وأتموا الحج والعمرة لله} [البقرة: 196] الآية، وقد صح عن رسول الله صلى الله عليه وسلم أنه أمر أصحابه بعد أن أحرموا با"},{"id":"nasikh-nahhas:83","bookId":"nasikh-nahhas","type":"section","seq":83,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جما","page":"ج1 ص143","text":"جعفر: وسنذكر حجج الجميع فمن قال: إنها منسوخة احتج بأن المنافع التي فيها إنما كانت قبل التحريم ثم نسخت وأزيلت\nكما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا إبراهيم بن عبد الله، عن محمد بن يزيد، عن جويبر، عن الضحاك، في قوله جل وعز {يسألونك عن الخمر، والميسر} [البقرة: 219] ، قل فيهما إثم كبير ومنافع للناس قال: «المنافع قبل التحريم»\nوحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا محمد بن هارون، قال: حدثنا صفوان، عن عمر بن عبد الواحد، عن عثمان بن عطاء، عن أبيه، {يسألونك عن الخمر، والميسر، قل فيهما إثم كبير ومنافع للناس} [البقرة: 219] قال: \" نسختها {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] يعني المساجد ثم أنزل {ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا} [النحل: 67]","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:84","bookId":"nasikh-nahhas","type":"section","seq":84,"chapter":"ص: 48","title":"ص: 148","page":"ج1 ص146","text":"، ثم أنزل {يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان فاجتنبوه} [المائدة: 90] \" الآيتين واحتج من قال: إنها ناسخة بالأحاديث المتواترة التي فيها بيان علة نزول تحريم الخمر وبغير ذلك قال أبو جعفر: فمن الحجج:\nما قرئ على أحمد بن محمد بن الحجاج، أن عبد العزيز بن عمران بن أيوب بن مقلاص حدثهم سنة تسع وعشرين ومائتين قال: حدثنا محمد بن يوسف، قال: حدثنا إسرائيل، عن أبي إسحاق، عن أبي ميسرة عمرو بن شرحبيل، عن عمر، أنه قال","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:85","bookId":"nasikh-nahhas","type":"section","seq":85,"chapter":"ص: 48","title":"ص: 149","page":"ج1 ص147","text":": \" اللهم بين لنا في الخمر، فنزلت {يسألونك عن الخمر والميسر} [البقرة: 219] الآية فقرئت عليهم فقال: اللهم بين لنا في الخمر بيانا شافيا فإنها تذهب العقل والمال فنزلت {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] فكان منادي رسول الله صلى الله عليه وسلم ينادي وقت الصلاة لا يقربن الصلاة سكران فدعى عمر فقرئت عليه فقال: اللهم بين لنا في الخمر بيانا شافيا فإنها تذهب العقل والمال فنزلت {يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان} [المائدة: 90] إلى {فهل أنتم منتهون} [المائدة: 91] فقال عمر رضي الله عنه: انتهينا انتهينا \"\nقال أحمد بن محمد بن الحجاج: وحدثنا عمر بن خالد، سنة خمس وعشرين قال: حدثنا زهير، قال: حدثنا سماك، قال: حدثني مصعب بن سعد، عن سعد، قال: \" مررت بنفر من المهاجرين","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:86","bookId":"nasikh-nahhas","type":"section","seq":86,"chapter":"ص: 48","title":"ص: 150","page":"ج1 ص148","text":"والأنصار فقالوا لي: تعال نطعمك ونسقيك خمرا وذلك قبل أن تحرم الخمر: فأتيتهم في حش قال والحش البستان فإذا عندهم رأس جزور مشوي وزق خمر فأكلنا وشربنا فذكرت الأنصار فقلت: المهاجرون خير من الأنصار فأخذ رجل منهم أحد لحيي الرأس فجرح به أنفي فأتيت رسول الله صلى الله عليه وسلم فأخبرته فنزلت {يا أيها الذين آمنوا إنما الخمر والميسر} [المائدة: 90] \" قال أبو جعفر: وفي حديث سعيد بن جبير، عن ابن عباس: نزل تحريم الخمر في حيين من قبائل الأنصار لما ثملوا شج بعضهم بعضا ووقعت بينهم الضغائن فنزلت {يا أيها الذين آمنوا إنما الخمر والميسر} [المائدة: 90] إلى {منتهون} [المائدة: 91] قال أبو جعفر: فهذا يبين أن الآية ناسخة ومن الحجة لذلك أيضا أن جماعة من الفقهاء يقولون: تحريم الخمر بآيتين من القرآن بقوله جل وعز {قل فيهما إثم كبير} [البقرة: 219] وبقوله {قل إنما حرم ربي الفواحش ما ظهر منها وما بطن والإثم} [الأعراف: 33] فلما حرم الإثم وأخبر أن في الخمر إثما وجب أن تكون محرمة فأما قول من قال: إن الخمر يقال لها الإثم فغير معروف من حديث ولا لغة","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:87","bookId":"nasikh-nahhas","type":"section","seq":87,"chapter":"ص: 48","title":"ص: 151","page":"ج1 ص148","text":"والقول الأول جائز وأبين منه أنها محرمة بقوله تعالى {فاجتنبوه} [المائدة: 90] وإذا نهى الله جل وعز عن شيء فهو محرم وفي الأحاديث التي ذكرناها ما يحتاج إلى تفسير فمن ذلك ثملوا معناه: سكروا، وبعضهم يروي في حديث سعد: ففزر به أنفي، أي فلقه وشقه ومنه فزرت الثوب، والفزر القطعة من الغنم وفي الأحاديث في سبب نزول تحريم الخمر أسباب يقول القائل: كيف يتفق بعضها مع بعض وعمر رضي الله عنه يقول شيئا وسعد يقول غيره وابن عباس قد أتى بسواهما قال أبو جعفر: والجواب أن الأحاديث متفقة لأن عمر رضي الله عنه سأل بيانا شافيا في تحريم الخمر ولم يقل: نزلت في ذلك لا في غيره فيجوز أن يكون سؤال عمر وافق ما كان من سعد بن أبي وقاص ومن الحيين اللذين من قبائل الأنصار، فتتفق الأحاديث ولا تتضاد وفيها من الفقه أن منادي رسول الله صلى الله عليه وسلم كان ينادي وقت الصلاة لا يقربن الصلاة سكران فدل بهذا على أن القول ليس كما قال بعض الفقهاء إن السكران الذي لا يعرف السماء من الأرض ولا الذكر من الأنثى وإن رجلا لو قال له وأشار إلى السماء ما هذه؟ فقال: الأرض لم يكن سكران لأنه قد فهم عنه كلامه","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:88","bookId":"nasikh-nahhas","type":"section","seq":88,"chapter":"ص: 48","title":"ص: 152","page":"ج1 ص148","text":"ولو كان الأمر على هذا لما جاز أن يخاطب من لا يعرف الذكر من الأنثى ولا يفهم الكلام فيقال له: لا تقرب الصلاة وأنت سكران فتبين بهذا الحديث أن السكران هو الذي أكثر أمره التخليط\nوقد حكى أحمد بن محمد بن الحجاج أن أحمد بن صالح سئل عن السكران فقال: أنا آخذ فيه بما رواه ابن جريج عن عمرو بن دينار، عن يعلى بن منية، عن أبيه قال: سألت عمر بن الخطاب رضي الله عنه عن حد السكران، فقال: «هو الذي إذا استقرأته سورة لم يقرأها وإذا خلطت ثوبه مع ثياب لم يخرجه»\nوفي الحديث من الفقه أن قوله: «لا يقربن الصلاة سكران» قد دل على أن قول الله جل وعز {لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] ليس من النوم وأنه من الشرب حين كان مباحا وقد تبين أن الآية ناسخة لما ذكرنا وبقي البيان عن الخمر المحرمة وما هي؟ لأن قوما قد أوقعوا في هذا شبهة فقالوا: الخمر هي المجمع عليها ولا يدخل فيها ما اختلف فيه فهذا ظلم من القول يجب على قائله أن لا يحرم شيئا اختلف فيه وهذا عظيم من القول واحتج أيضا بأن من قال: الخمر التي لا اختلاف فيها محلها كافر وليس كذا غيرها وهذان الاحتجاجان أشد ما لهم فأما الأحاديث التي جاءوا بها فلا حجة فيها لضعف أسانيدها ولتأويلهم إياها على غير الحق وقد قال عبد الله بن المبارك: ما صح تحليل النبيذ الذي يسكر كثيره عن أحد من الصحابة ولا التابعين إلا عن إبراهيم النخعي\nقال أبو جعفر: فأما الاحتجاجان الأولان اللذان يعتمدون عليهما فقد بينا الرد في أحدهما وسنذكر الآخر فالخمر المحرمة تنقسم قسمين أحدهما المجمع عليها وهي عصير العنب إذا رغا وأزبد فهذه الخمر التي من أحلها كافر والخمر الأخرى التي من أحلها ليس بكافر وهي التي جاء بها التوقيف عن رسول الله صلى الله عليه وسلم أنها الخمر وعن أصحابه رضي الله عنهم بالأسانيد التي لا يدفعها إلا صاد عن الحق أو جاهل إذ قد صح عنه صلى الله عليه وسلم تسميتها خمرا وتحريمها، فمن ذلك:\nما حدثناه بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك بن أنس، عن ابن شهاب، عن أبي سلمة، عن عائشة، أنها قالت: سئل رسول الله صلى الله عليه وسلم عن البتع فقال: «كل شراب أسكر حرام» قال أبو جعفر: فلو لم يكن في هذا الباب إلا هذا الحديث لكفى لصحة إسناده واستقامة طريقه وقد أجمع الجميع أن الآخر لا يسكر إلا بالأول فقد حرم الجميع بتوقيف رسول الله صلى الله عليه وسلم","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:89","bookId":"nasikh-nahhas","type":"section","seq":89,"chapter":"ص: 48","title":"ص: 155","page":"ج1 ص154","text":"وفي هذا الباب مما لا يدفع\nما قرئ على أبي القاسم عبد الله بن محمد بن عبد العزيز، عن أبي عبد الله أحمد بن محمد بن حنبل قال: حدثنا يونس بن محمد، قال حدثنا حماد بن زيد، عن أيوب، عن نافع، عن ابن عمر قال: قال رسول الله صلى الله عليه وسلم: «كل مسكر خمر وكل مسكر حرام» قال أبو عبد الله: هذا إسناد صحيح\nقال أبو عبد الله، وحدثنا روح بن عبادة، قال: حدثنا ابن جريح، قال: أخبرني موسى بن عقبة، عن نافع، عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال: «كل مسكر حرام وكل مسكر خمر»\nقال أبو عبد الله: وحدثنا يزيد بن هارون، قال: أخبرنا محمد بن عمرو، عن أبي سلمة، عن ابن عمر، قال: قال رسول الله صلى الله عليه وسلم: «كل مسكر خمر وكل مسكر حرام»\nقال أبو عبد الله: وحدثنا محمد بن جعفر، قال: حدثنا شعبة، عن سعيد بن أبي بردة، عن أبيه، عن جده، قال: سمعت رسول الله صلى الله عليه وسلم حين وجه أبا موسى، ومعاذ بن جبل إلى اليمن فقال أبو موسى: يا رسول الله، إنا بأرض يصنع بها شراب من العسل يقال له البتع، وشراب من شعير يقال له المزر فقال رسول الله صلى الله عليه وسلم: «كل مسكر حرام»\nقال أبو عبد الله: وحدثنا يحيى بن سعيد، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، عن النبي صلى الله عليه وسلم قال: «كل مسكر حرام»","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:90","bookId":"nasikh-nahhas","type":"section","seq":90,"chapter":"ص: 48","title":"ص: 157","page":"ج1 ص156","text":"فهذه الأسانيد المتفق على صحتها\nوقرئ على أبي بكر أحمد بن عمرو، عن علي بن الحسين الدرهمي، قال: حدثنا أنس بن عياض، قال: حدثنا موسى بن عقبة، عن سالم بن عبد الله بن عمر، عن أبيه، أن النبي صلى الله عليه وسلم قال: «ما أسكر كثيره فقليله حرام» فهذا تحريم قليل ما أسكر كثيره نصا عن رسول الله صلى الله عليه وسلم بهذا الإسناد المستقيم قال أبو بكر أحمد بن عمرو وقد روى التحريم عائشة، وسعد بن أبي وقاص، وجابر، وعمر، وابن عباس، وأنس، وأبو سعيد الخدري، وعبد الله بن عمر، وأبو هريرة، وقرة بن إياس","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:91","bookId":"nasikh-nahhas","type":"section","seq":91,"chapter":"ص: 48","title":"ص: 158","page":"ج1 ص156","text":"، وخوات بن جبير، والديلم بن الهوشع، وأبو موسى الأشعري، وبريدة الأسلمي، وأم سلمة، وميمونة، وقيس بن سعد وإسناد حديث عائشة وابن عمر، وأنس صحيح وسائر الأحاديث يؤيد بعضها بعضا\nوقرئ على أحمد بن شعيب بن علي أبي","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:92","bookId":"nasikh-nahhas","type":"section","seq":92,"chapter":"ص: 48","title":"ص: 159","page":"ج1 ص157","text":"عبد الرحمن، عن هشام بن عمار، قال: حدثنا صدقة بن خالد، عن زيد بن واقد، قال: أخبرني خالد بن عبد الله بن حسين، عن أبي هريرة، قال: علمت أن رسول الله صلى الله عليه وسلم كان يصوم فتحينت فطره بنبيذ صنعته له في دباء فجئته به فقال: «أدنه» فأدنيته منه فإذا هو ينش فقال: «اضرب بهذا الحائط فإن هذا شراب من لا يؤمن بالله واليوم الآخر» قال أبو عبد الرحمن: وفي هذا دليل على تحريم المسكر قليله وكثيره ليس كما يقوله المخادعون لأنفسهم بتحريمهم آخر الشربة وتحليلهم ما تقدمها الذي سرى في العروق قبلها قال: ولا خلاف بين أهل العلم أن السكر بكليته لا يحدث عن الشربة الآخرة دون الأولى والثانية بعدها\nقال أبو عبد الرحمن: وأخبرنا عبيد الله بن سعيد، قال: حدثنا يحيى، عن عبيد الله، قال: حدثنا عمرو بن شعيب، عن أبيه، عن جده، أن النبي صلى الله عليه وسلم قال: «ما أسكر كثيره فقليله حرام» قال أبو عبد الرحمن: \" إنما يتكلم في حديث عمرو بن شعيب إذا رواه عنه غير الثقات فأما إذا رواه الثقات فهو حجة، وعبد الله بن عمرو جد عمرو بن شعيب كان يكتب ما سمع من النبي صلى الله عليه وسلم وحديثه من أصح الحديث\nقال أبو عبد الرحمن: وأخبرنا إسحاق بن إبراهيم، قال: أخبرنا أبو عامر، والنضر بن شميل، ووهب بن جرير، قالوا: حدثنا شعبة، عن سلمة بن كهيل، قال: سمعت أبا الحكم، يحدث قال: قال ابن عباس: «من سره أن يحرم إن كان محرما ما حرم الله ورسوله، فليحرم النبيذ»\nقال أبو عبد الرحمن: وأخبرنا قتيبة، قال: حدثنا عبد العزيز، عن عمارة بن غزية، عن أبي الزبير، عن جابر، أن رجلا، من جيشان وجيشان من اليمن قدم فسأل النبي صلى الله عليه وسلم عن شراب يشربونه بأرضهم من الذرة يقال له المزر فقال النبي صلى الله عليه وسلم: «أو مسكر هو؟» قال: نعم قال رسول الله صلى الله عليه وسلم: «كل مسكر حرام إن الله عز وجل عهد لمن","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:93","bookId":"nasikh-nahhas","type":"section","seq":93,"chapter":"ص: 48","title":"ص: 162","page":"ج1 ص161","text":"شرب المسكر أن يسقيه من طينة الخبال» قالوا: يا رسول الله، وما طينة الخبال؟ قال: عرق أهل النار \" أو قال: «عصارة أهل النار» وما يبين أن الخمر تكون من غير عصير العنب من لفظ رسول الله صلى الله عليه وسلم وأصحابه ومن اللغة ومن الاشتقاق، فأما لفظ رسول الله صلى الله عليه وسلم مما لا يدفع إسناده\nأنه قرئ على أحمد بن شعيب، عن سويد بن نصر، عن ابن المبارك، عن الأوزاعي، قال: حدثني أبو كثير، واسمه يزيد بن عبد الرحمن، قال أبو عبد الرحمن: وأخبرني حميد بن مسعدة، عن سفيان وهو ابن حبيب، عن الأوزاعي، قال: حدثنا أبو كثير، قال: سمعت أبا هريرة، يقول: قال رسول الله صلى الله عليه وسلم: «الخمر من هاتين الشجرتين» قال سويد: في هاتين الشجرتين النخلة والعنبة، فوقفنا رسول الله صلى الله عليه وسلم على أن الخمر من النخلة، فخالف ذلك قوم وقالوا: لا يكون إلا من العنبة ثم نقضوا قولهم وقالوا: نقيع التمر والزبيب خمر؛ لأنه لم يطبخ\nوقرئ على أحمد بن عمرو، وأبي بكر، عن علي بن سعيد المسروقي، قال: حدثنا عبد الرحيم بن سليمان، قال: حدثنا السري بن إسماعيل، عن الشعبي، عن النعمان بن بشير، عن النبي صلى الله عليه وسلم قال: «الخمر من خمسة من الحنطة والشعير والتمر والزبيب والعسل وما خمرته فهو خمر»\nوقرئ على أحمد بن شعيب عن يعقوب بن إبراهيم، قال حدثنا: ابن علية، قال: حدثنا أبو حيان، قال: حدثني الشعبي، عن ابن عمر، قال: سمعت عمر، يخطب على منبر المدينة قال: «أيها الناس ألا إنه نزل تحريم الخمر يوم نزل وهي من خمسة من العنب، والتمر، والعسل والحنطة، والشعير، والخمر ما خامر العقل»","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:94","bookId":"nasikh-nahhas","type":"section","seq":94,"chapter":"ص: 48","title":"ص: 164","page":"ج1 ص163","text":"فهذا توقيف في الخمر أنها من غير عنب وفيه بيان الاشتقاق وأنه ما خامر العقل مشتق من الخمر وهو كل ما وارى من نخل وغيره فقيل: خمر؛ لأنها تستر العقل ومنه فلان مخمور يقال هذا فيما كان من عصير العنب وغيره لا فرق بينهما وما منهما إلا ما يريد الشيطان أن يوقع بينهم فيه العداوة والبغضاء ويصد به عن ذكر الله وعن الصلاة فالقليل من هذا ومن هذا واحد فهذا أصح ما قيل في اشتقاقها وأجله إسنادا قاله عمر رضي الله عنه على المنبر بحضرة الصحابة فأما سعيد بن المسيب فروي عنه أنه قال: إنما سميت الخمر خمرا؛ لأنها صعد صفوها ورسب كدرها قال أبو جعفر: فاشتقاق هذا أيضا على أن الصفو ستر الكدر وقال بعض المتأخرين: سميت خمرا؛ لأنها تخمر أي: تغطي وسمي نبيذا؛ لأنه ينبذ ولو صح هذا لكان النبيذ أيضا يخمر ومما يشبه ما تقدم\nما حدثناه بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: حدثنا مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك، قال: \" كنت أسقي أبا عبيدة بن الجراح، وأبا طلحة","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:95","bookId":"nasikh-nahhas","type":"section","seq":95,"chapter":"ص: 48","title":"ص: 165","page":"ج1 ص163","text":"الأنصاري، وأبي بن كعب شراب فضيخ وتمر فجاءهم آت فقال: إن الخمر قد حرمت فقال أبو طلحة: يا أنس، قم إلى تلك الجرار فاكسرها فقمت إلى مهراس لنا فدفعتها بأسفله فكسرتها \" قال أبو جعفر: ففي هذه الأحاديث من الفقه تصحيح قول من قال: إن ما أسكر كثيره فقليله حرام عن النبي صلى الله عليه وسلم والصحابة ثم كان الصحابة على ذلك وبه يفتون أشدهم فيه علي بن أبي طالب رضي الله عنه يخاطبهم نصا «بأن ما أسكر كثيره فقليله حرام» ثم ابن عمر لما سئل عن نبيذ ينبذ بالغداة ويشرب بالعشي قال محمد بن سيرين فقال للسائل: إني أنهاك عن قليل، ما أسكر كثيره وإني أشهد الله جل وعز عليك فإن أهل خيبر يشربون شرابا يسمونه كذا وهي الخمر وإن أهل فدك يشربون شرابا يسمونه كذا وهي الخمر وإن أهل يعني مصر يشربون شرابا من العسل يسمونه البتع وهي الخمر ثم عائشة رضي الله عنها لما سئلت عن غير عصير العنب فقالت: صدق الله ورسوله، سمعت رسول الله صلى الله عليه وسلم يقول: «يشرب قوم","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:96","bookId":"nasikh-nahhas","type":"section","seq":96,"chapter":"ص: 48","title":"ص: 166","page":"ج1 ص163","text":"الخمر يسمونها بغير أسمائها» فلم يزل الذين يروون هذه الأحاديث يحملونها على هذا عصرا بعد عصر حتى عرض فيها قوم فقالوا: المحرم الشربة الآخرة التي تسكر وقالوا قد قالت اللغة الخبز المشبع والماء المروي قال أبو جعفر: فإن صح هذا في اللغة فهو حجة عليهم لا لهم؛ لأنه لا يخلو من إحدى جهتين إما أن يكون معناه للجنس كله أي صفة الخبز أنه يشبع وصفة الماء أنه يروي فيكون هذا لقليل الخبز وكثيره؛ لأنه جنس فكذا قليل ما يسكر، أو يكون الخبز المشبع فهو لا يشبع إلا بما كان قبله فكله مشبع فكذا قليل المسكر وكثيره وإن كانوا قد تأولوه على أن معنى المشبع هو الآخر الذي يشبع وكذا الماء المروي فيقال لهم: ما حد ذلك المروي والذي لا يروي؟ فإن قالوا: لا حد له فهو كله إذا مرو وإن حدوه قيل لهم: ما","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:97","bookId":"nasikh-nahhas","type":"section","seq":97,"chapter":"ص: 48","title":"ص: 167","page":"ج1 ص163","text":"البرهان على ذلك؟ وهل يمتنع الذي لا يروي مما حددتموه أن يكون يروي عصفورا؟ وما أشبهه فبطل الحد وصار القليل مما يسكر كثيره داخلا في التحريم وعارضوا بأن المسكر بمنزلة القاتل لا يسمى مسكرا حتى يسكر كما لا يسمى القاتل قاتلا حتى يقتل قال أبو جعفر: وهذا لا يشبه من هذا شيئا، لأن المسكر جنس وليس كذا القاتل ولو كان كما قالوا لوجب ألا يسمى الكثير من المسكر مسكرا حتى يسكر وكان يجب أن يحلوه، وهذا خارج عن قول الجميع وقالوا: معنى: كل مسكر حرام، على القدح الذي يسكر وهذا","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:98","bookId":"nasikh-nahhas","type":"section","seq":98,"chapter":"ص: 48","title":"ص: 168","page":"ج1 ص163","text":"خطأ من جهة اللغة وكلام العرب، لأن «كل» معناها العموم فالقدح الذي يسكر مسكر والجنس كله مسكر وقد حرم رسول الله صلى الله عليه وسلم الكل فلا يجوز الاختصاص إلا بتوقيف وإنما قولنا: مسكر يقع للجنس القليل والكثير كما يقال: التمر بالتمر زيادة ما بينهما ربا فدخل في هذه التمرة والتمرتان والقليل والكثير، كذا دخل في كل مسكر القليل والكثير وشبه بعضهم هذا بالدواء والبنج الذي يحرم كثيره ويحل قليله وهذا التشبيه بعيد لأن النبي صلى الله عليه وسلم قال: «ما أسكر كثيره فقليله حرام» وقال: «كل مسكر خمر» فالمسكر وهو الخمر هو الجنس الذي قال الله جل وعز فيه {إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء في الخمر والميسر} [المائدة: 91] وليس هذا في الدواء والبنج، وإنما هذا في كل شراب فهو هكذا، وعارضوا بأن قالوا: فليس ما أسكر كثيره بمنزلة الخمر في كل أحواله قال أبو جعفر: وهذه مغالطة وتمويه على السامع، لأنه لا يجب من هذا إباحة، وقد علمنا أنه ليس من قتل مسلما غير نبي بمنزلة من قتل نبيا فليس يجب إذا لم يكن بمنزلة في جميع الأحوال أن يكون مباحا كذا من شرب ما أسكر كثيره وإن لم يكن بمنزلة من شرب عصير العنب الذي قد نش فليس يجب من هذا أن يباح له ما قد شرب ولكنه بمنزلته في أنه قد شرب محرما وشرب خمرا وأنه يحد في القليل منه كما يحد في القليل من الخمر","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:99","bookId":"nasikh-nahhas","type":"section","seq":99,"chapter":"ص: 48","title":"ص: 169","page":"ج1 ص163","text":"، وهذا قول من لا يدفع قوله منهم عمر، وعلي رضي الله عنهما ومعنى «كل مسكر خمر» يجوز أن يكون بمنزلة الخمر في التحريم وأن يكون المسكر كله يسمى خمرا كما سماه رسول الله صلى الله عليه وسلم ومن ذكرنا من الصحابة والتابعين بالأسانيد الصحيحة وقد عارض قوم بعض الأسانيد من غير ما ذكرناه فمن ذلك:\nما قرئ على عبد الله بن محمد بن عبد العزيز، عن شيبان بن فروخ، عن مهدي بن ميمون، قال حدثنا أبو عثمان الأنصاري، قال: حدثنا القاسم بن محمد، عن عائشة، قالت: قال رسول الله صلى الله عليه وسلم: «كل مسكر حرام وما أسكر الفرق فملء الكف منه حرام» قال أبو جعفر: الفرق بفتح الراء لا غير وهو ثلاث أصوع وكذا فرق الصبح بالفتح وكذا الفرق من الفزع والفرق أيضا تباعد ما بين الشيئين فأما الفرق بإسكان الراء ففرق الشعر وكذا الفرق بين الحق والباطل\nوقرئ على أبي القاسم عبد الله بن محمد بن عبد العزيز، عن أبي سعيد الأشج، عن","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:100","bookId":"nasikh-nahhas","type":"section","seq":100,"chapter":"ص: 48","title":"ص: 170","page":"ج1 ص169","text":"الوليد بن كثير، قال: حدثنا الضحاك بن عثمان، عن بكير بن عبد الله بن الأشج، عن عامر بن سعد، عن أبيه، قال: قال رسول الله صلى الله عليه وسلم: «أنهاكم عن قليل، ما أسكر كثيره»\nقال أبو القاسم: وحدثنا أحمد بن محمد بن حنبل قال حدثنا سليمان بن داود يعني الهاشمي، قال: حدثنا إسماعيل بن جعفر، قال: حدثنا داود بن بكر يعني ابن أبي الفرات، قال: حدثنا محمد بن المنكدر، عن جابر، قال: قال رسول الله صلى الله عليه وسلم: «ما أسكر كثيره فقليله حرام»","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:101","bookId":"nasikh-nahhas","type":"section","seq":101,"chapter":"ص: 48","title":"ص: 171","page":"ج1 ص169","text":"قال أبو جعفر: فمن عجيب ما عارضوا به أن قالوا: أبو عثمان الأنصاري مجهول والمجهول لا تقوم به حجة فقيل لهم: ليس بمجهول والدليل على ذلك أنه قد روى عنه الربيع بن صبيح، وليث بن أبي سليم، ومهدي بن ميمون، ومن روى عنه اثنان فليس بمجهول وقالوا: الضحاك بن عثمان مجهول قيل لهم: قد روى عنه عبد العزيز بن محمد، وعبد العزيز بن أبي حازم، ومحمد بن جعفر بن أبي كثير، وابن أبي فديك وقالوا: داود بن بكر مجهول قيل لهم: قد روى عنه إسماعيل بن جعفر، وأنس بن عياض وإنما تعجب من معارضتهم بهذا؛ لأنهم يقولون في دين الله جل وعز بما رواه أبو فزارة زعموا عن أبي زيد، عن ابن مسعود: أنه كان مع النبي صلى الله عليه وسلم ليلة الجن وأنه توضأ بنبيذ التمر، وأبو زيد لا يعرف ولا يدرى من أين هو؟\nوقد روى إبراهيم عن علقمة قال: سألت عبد الله هل كنت مع النبي صلى الله عليه وسلم ليلة الجن؟ فقال «لا وبودي أن لو كنت معه»","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:102","bookId":"nasikh-nahhas","type":"section","seq":102,"chapter":"ص: 48","title":"ص: 173","page":"ج1 ص170","text":"ويحتجون بحديث رووه قال أبو جعفر: سنذكره بإسناده:\nعن أبي إسحاق، عن ابن ذي لعوة، أن عمر، حد رجلا شرب من إداوته وقال: «أحدك على السكر» وهذا من عظيم ما جاءوا به، وابن ذي لعوة لا يعرف، وهكذا قول أبي بكر بن عياش، لعبد الله بن إدريس \"\nحدثنا أبو إسحاق، عن أصحابه، أن ابن مسعود، \" كان يشرب الشديد فقال له عبد الله بن إدريس: استحييت لك يا شيخ \" من أصحابه؟ وأبو إسحاق إذا سمى من حدث عنه ولم يقل: سمعت لم يكن حجة، وما هذا الشديد؟ أهو خل أم نبيذ؟\nولكن حدثنا محمد بن عمرو، عن أبي سلمة عن ابن عمر، وأبي هريرة أن النبي صلى الله عليه وسلم قال: «كل مسكر خمر وكل مسكر حرام»\nوحدثنا محمد بن عمرو، عن أبي سلمة، عن عائشة عن النبي صلى الله عليه وسلم قال: «كل شراب أسكر حرام» فأفحم أبو بكر بن عياش، وكان عبد الله بن إدريس في الكوفيين متشددا في تحريم قليل ما أسكر كثيره وقال الأوزاعي: قلت لسفيان الثوري: \" إن الله جل وعز لا يسألني يوم القيامة لم لم تشرب النبيذ؟ ويسألني لم شربته؟ فقال: «لا أفتي به أبدا» وقال أبو يوسف: «في أنفسنا من الفتيا به أمثال الجبال ولكن عادة البلد» ، ثم اجتمعوا جميعا على تحريم المعاقرة وتحريم النقيع، وقال أبو حنيفة: «هو بمنزلة الخمر» فأما الأحاديث التي احتجوا بها فما علمت أنها تخلو من إحدى جهتين إما أن تكون واهية الإسناد وإما تكون لا حجة لهم فيها إلا التمويه فرأينا أن نذكرها ونذكر ما فيها ليكون الباب كامل المنفعة","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:103","bookId":"nasikh-nahhas","type":"section","seq":103,"chapter":"ص: 48","title":"ص: 175","page":"ج1 ص174","text":"فمن ذلك:\nما حدثناه أحمد بن محمد الأزدي، قال: حدثنا روح، قال: حدثنا عمرو، قال: حدثنا أبو إسحاق، عن عمرو بن ميمون، قال: شهدت عمر حين طعن فجاءه الطبيب فقال: أي الشراب أحب إليك؟ قال: «النبيذ» قال: فأتي بنبيذ فشربه فخرج من إحدى طعناته وكان يقول: \" إنا نشرب من هذا النبيذ شرابا يقطع لحوم الإبل قال: وشربت من نبيذه فكان كأشد النبيذ \" قال أبو جعفر: هذا الحديث لا تقوم به حجة؛ لأن أبا إسحاق لم يقل: حدثنا عمرو بن ميمون، وهو مدلس لا تقوم بحديثه حجة حتى يقول: حدثنا وما أشبهه، ولو صححنا الحديث على قولهم لما كانت لهم فيه حجة؛ لأن النبيذ غير محظور إذا لم يسكر كثيره ومعنى النبيذ في اللغة منبوذ وإنما هو ماء نبذ فيه تمر أو زبيب أو نظيرهما مما يطيب الماء ويحليه؛ لأن مياه المدينة كانت غليظة فما في هذا الحديث من الحجة؟ واحتجوا\nبما حدثناه أحمد بن محمد الأزدي، قال: حدثنا فهد، قال: حدثنا عمر بن حفص بن غياث، قال: حدثنا أبي، عن الأعمش، قال: حدثنا حبيب بن أبي ثابت، عن نافع بن علقمة، قال: أمر عمر رضي الله عنه بنزل له في بعض تلك المنازل فأبطأ عليهم ليلة فجيء بطعام فطعم ثم أتي بنبيذ قد أخلف واشتد فشرب منه ثم قال: «إن هذا لشديد ثم أمر بماء فصب عليه ثم شرب هو وأصحابه»","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:104","bookId":"nasikh-nahhas","type":"section","seq":104,"chapter":"ص: 48","title":"ص: 176","page":"ج1 ص175","text":"قال أبو جعفر: هذا الحديث فيه غير علة منها أن حبيب بن أبي ثابت على محله لا تقوم بحديثه حجة لمذهبه وكان مذهبه أنه قال: لو حدثني رجل، عنك بحديث ثم حدثت به عنك لكنت صادقا\nومن هذا أنه روي عن عروة، عن عائشة: «أن النبي صلى الله عليه وسلم قبل بعض نسائه ثم صلى ولم يتوضأ» فعيب بعض الناس؛ لأنه رد بهذا على الشافعي؛ لأنه أوجب الوضوء في القبلة فقيل له لا تثبت بهذا حجة لانفراد حبيب به قال أبو جعفر: وفيه من العلل أن نافع بن علقمة ليس بمشهور بالرواية ولو صح الحديث عن عمر لما كانت فيه حجة؛ لأن اشتداده قد يكون من حموضته وقد اعترض بعضهم فقال: من أين لكم أن مزجه بالماء كان لحموضته؟ أفتقولون هذا ظنا؟ فالظن لا يغني من الحق شيئا، قال: وليس يخلو من أن يكون نبيذ عمر يسكر كثيره أو يكون خلا قال أبو جعفر: فهذه المعارضة على من عارض بها لا له؛ لأنه الذي قال بالظن؛ لأنه قد ثبتت الرواية عمن قد صحت عدالته أن ذلك من حموضته قال نافع: «كان لتخلله» ، وهم قد رووا حديثا متصلا فيه أنه كان مزجه إياه لأنه كاد يكون خلا\nقال أبو جعفر: حدثنا أحمد بن محمد، قال: حدثنا وهبان بن عثمان، قال: حدثنا الوليد بن شجاع، قال: حدثنا يحيى بن زكريا بن أبي زائدة، قال: حدثنا إسماعيل، عن قيس، قال: حدثني عتبة بن فرقد، قال: أتي عمر بعس من نبيذ قد كاد يكون خلا فقال لي: «اشرب» فأخذته وما أكاد أستطيعه فأخذه مني فشربه، وذكر الحديث فزال الظن بالتوقيف ممن شاهد عمر رحمه الله وهو من روايتهم وأما قوله لا يخلو من أن يكون نبيذا يسكر كثيره أو يكون خلا فقد خلا من ذينك؛ لأن العرب تقول: للنبيذ إذا دخلته حموضة نبيذ حامض فإذا زادت صار خلا فترك هذا القسم وهو لا يخيل على من عرف اللغة، ثم روى حديثا إن كانت فيه حجة فهي عليه\nحدثنا أحمد بن محمد، قال: حدثنا فهد، قال: حدثنا عمر بن حفص، قال: حدثنا أبي قال،: حدثنا الأعمش، قال: حدثني إبراهيم، عن همام بن الحارث، قال: أتي عمر بنبيذ فشرب منه فقطب ثم قال: \" إن نبيذ الطائف له عرام ثم ذكر شدة لا أحفظها ثم دعا بماء فصب عليه ثم شرب قال أبو جعفر: وهذا لعمري إسناد مستقيم ولا حجة له فيه بل الحجة عليه؛ لأنه إنما يقال: قطب لشدة حموضة الشيء ومعنى قطب في كلام العرب خالطت بياضه حمرة، مشتق من قطبت الشيء أقطبه وأقطبه إذا خلطته","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:105","bookId":"nasikh-nahhas","type":"section","seq":105,"chapter":"ص: 48","title":"ص: 178","page":"ج1 ص177","text":"وفي الحديث له عرام أي خبث، ورجل عارم أي: خبيث\nحدثنا أحمد بن محمد الأزدي، قال: حدثنا فهد، قال: حدثنا عمر بن حفص، قال: حدثنا أبي، عن الأعمش، قال: حدثني أبو إسحاق، عن سعيد بن ذي حدان أو ابن ذي لعوة، قال: جاء رجل قد ظمئ إلى خازن عمر فاستسقاه فلم يسقه فأتي بسطيحة لعمر فشرب منها فسكر فأتي به عمر فاعتذر إليه فقال: إنما شربت من سطيحتك فقال عمر: «إنما أضربك على السكر» فضربه عمر \" قال أبو جعفر: هذا الحديث من أقبح ما روي في هذا الباب وعلله بينة لمن لم يتبع الهوى فمنها أن ابن ذي لعوة لا يعرف ولم يرو عنه إلا هذا الحديث ولم يرو عنه إلا أبو إسحاق، ولم يذكر أبو إسحاق فيه سماعا وهو مخالف لما نقله أهل العدالة عن عمر\nقال أبو جعفر: حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن الزهري، عن السائب بن يزيد، أن عمر، رضي الله عنه خرج عليهم فقال: «إني وجدت من فلان ريح شراب قد زعم أنه شرب الطلاء وأنا سائل عما شرب فإن كان يسكر جلدته الحد» ، قال: فجلده عمر الحد ثمانين فهذا إسناد لا مطعن فيه والسائب","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:106","bookId":"nasikh-nahhas","type":"section","seq":106,"chapter":"ص: 48","title":"ص: 179","page":"ج1 ص178","text":"بن يزيد رجل من أصحاب النبي صلى الله عليه وسلم فهل يعارض مثل هذا بابن ذي لعوة، وعمر رضي الله عنه يخبر بحضرة الصحابة أنه يجلد في الرائحة من غير سكر لأنه لو كان سكران ما احتاج أن يسأل عما شرب فرووا عن عمر رحمه الله ما لا يحل لأحد أن يحكيه عنه من غير جهة لوهاء الحديث وأنه زعم شرب من سطيحته وأنه يحد على السكر وذلك ظلم لأن السكر ليس من فعل الإنسان وإنما هو شيء يحدث عن الشرب وإنما الضرب عن الشرب كما أن الحد في الزنا إنما هو على الفعل لا على اللذة ومن هذا قيل لهم: تحريم السكر محال؛ لأن الله جل وعز إنما يأمر وينهى بما في الطاقة وقد يشرب الإنسان يريد السكر فلا يسكر ويريد أن لا يسكر فيسكر وقيل لهم: كيف يحصل ما يسكر وطباع الناس فيه مختلفة؟ ثم تعلقوا بشيء روي عن ابن عباس:\nحدثناه أحمد بن محمد، قال: حدثنا فهد، قال: حدثنا أبو نعيم، عن مسعر، عن أبي عون، عن عبد الله بن شداد، عن ابن عباس، قال: «حرمت الخمر بعينها قليلها وكثيرها، والسكر من كل شراب» قال أبو جعفر: وهذا الحديث قد رواه شعبة على إتقانه وحفظه على غير هذا\nكما قرئ على عبد الله بن محمد بن عبد العزيز، عن أحمد بن","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:107","bookId":"nasikh-nahhas","type":"section","seq":107,"chapter":"ص: 48","title":"ص: 180","page":"ج1 ص179","text":"محمد بن حنبل، قال: حدثنا محمد بن جعفر، قال: حدثنا شعبة، عن مسعر، عن أبي عون، عن عبد الله بن شداد، عن ابن عباس، قال: «حرمت الخمر بعينها والمسكر من كل شراب» وقد بينا أن السكر ليس من فعل الإنسان وإذا جاء حديث معارض لما قد ثبتت صحته وقد اختلفت روايته فلا معنى للاحتجاج به\nوقد روى يحيى القطان، عن عثمان الشحام، بصري مشهور، عن عكرمة، عن ابن عباس، قال: «نزل تحريم الخمر وهي الفضيخ» قال أبو جعفر: فهذا خلاف ذاك؛ لأن الفضيخ بسر يفضخ فجعله خمرا وأخبر بالتنزيل فيه وفي تحريمه\nقال أبو جعفر: حدثنا أحمد بن محمد، قال: حدثنا محمد بن عمرو بن يونس السوسي، قال: حدثنا أسباط بن محمد القرشي، عن الشيباني، عن عبد الملك بن نافع، قال: سألت ابن عمر فقلت: إن أهلنا ينتبذون نبيذا في سقاء لو نكهته لأخذ في فقال ابن عمر: \" إنما البغي على من أراد البغي شهدت رسول الله صلى الله عليه وسلم عند هذا الركن وأتاه رجل بقدح من نبيذ فأدناه إلى فيه فقطب ورده فقال رجل: يا رسول الله، أحرام هو؟ فرد الشراب ثم دعا بماء فصبه عليه ثم قال: «إذا اغتلمت عليكم هذه الأسقية فاقطعوا متونها بالماء» قال أحمد بن شعيب: عبد الملك بن نافع لا يحتج بحديثه وليس بالمشهور، وقد روى أهل العدالة سالم، ونافع، ومحمد بن سيرين، عن ابن","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:108","bookId":"nasikh-nahhas","type":"section","seq":108,"chapter":"ص: 48","title":"ص: 182","page":"ج1 ص180","text":"عمر خلاف ما روى وليس يقوم مقام واحد منهم ولو عاضده جماعة من أشكاله قال أبو جعفر: ثم رجعنا إلى متن الحديث فقلنا: لو صح ما كانت فيه حجة لمن احتج به بل الحجة عليه به بينة وذلك أن قوله صلى الله عليه وسلم: «إذا اغتلمت عليكم» وبعضهم يقول: «إذا رابكم من شرابكم ريب فاكسروا متنه بالماء» ، والريب في الأصل الشك ثم يستعمل بمعنى المخافة والظن مجازا فاحتجوا بهذا وقالوا: معناه إذا خفتم أن يسكر كثيره فاكسروه بالماء قال أبو جعفر: وهذا من قبيح الغلط؛ لأنه لو كان كثيره يسكر لكان قد زال الخوف وصار يقينا ولكن الحجة فيه لمن خالفهم أن النبي صلى الله عليه وسلم أمر أن لا يقر الشراب إذا خيف منه أن ينتقل إلى الحرام حتى يكسر بالماء الذي يزيل الخوف ومع هذا فحجة قاطعة عند من عرف معاني كلام العرب وذلك أن الشراب الذي بمكة لم يزل في الجاهلية والإسلام لا يطبخ بنار وإنما هو ماء يجعل فيه زبيب أو تمر ليطيب؛ لأن مياههم فيها ملوحة وغلظ ولم تتخذه للذة","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:109","bookId":"nasikh-nahhas","type":"section","seq":109,"chapter":"ص: 48","title":"ص: 183","page":"ج1 ص180","text":"وقد أجمع العلماء منهم أبو حنيفة، وأبو يوسف، ومحمد أن ما نقع ولم يطبخ بالنار وكان كثيره يسكر فهو خمر والخمر إذا صب فيها الماء أو صبت على الماء فلا اختلاف بين المسلمين أنها قد نجست الماء إذا كان قليلا فقد صار حكم هذا حكم الخمر وإذا أسكر كثيره فقليله حرام بإجماع المسلمين، فزالت الحجة بهذا الحديث لو صح\nقال أبو جعفر: حدثنا أحمد، قال: حدثنا فهد، قال: حدثنا محمد بن سعيد الأصبهاني، قال: حدثنا يحيى بن اليمان، عن الثوري، عن منصور، عن خالد بن سعد، عن أبي مسعود، قال: \" عطش النبي صلى الله عليه وسلم حول الكعبة فاستسقى فأتي بنبيذ من نبيذ السقاية فشمه فقطب فصب عليه من ماء زمزم ثم شرب فقال رجل: أحرام هو؟ قال: «لا» قال أبو جعفر: قد ذكرنا النبيذ الذي في السقاية بما فيه كفاية على أن هذا الحديث لا يحل لأحد من أهل العلم أن يحتج به فإن كان من أهل الجهل فينبغي أن يتعرف ما يحتج به في الحلال والحرام قبل أن يقطع به قال أحمد بن شعيب: هذا الحديث لا يحتج به؛ لأن يحيى بن","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:110","bookId":"nasikh-nahhas","type":"section","seq":110,"chapter":"ص: 48","title":"ص: 184","page":"ج1 ص181","text":"اليمان انفرد به، عن الثوري دون أصحابه، ويحيى بن اليمان ليس بحجة لسوء حفظه وكثرة خطئه وقال غير أبي عبد الرحمن: أصل هذا الحديث أنه من رواية الكلبي فغلط يحيى بن اليمان فنقل متن حديث إلى حديث آخر وقد سكت العلماء عن كل ما رواه الكلبي فلم يحتجوا بشيء منه\nوحدثنا أحمد، قال: حدثنا علي بن معبد، قال: حدثنا يونس بن محمد، قال: حدثنا شريك، عن أبي إسحاق، عن أبي بردة، عن أبيه، قال: بعثني رسول الله صلى الله عليه وسلم أنا ومعاذا، إلى اليمن فقلنا: يا رسول الله، إن بها شرابين يصنعان من البر والشعير أحدهما يقال له المزر والآخر البتع فما نشرب؟ قال: «اشربا ولا تسكرا» قال أبو جعفر: هذا الحديث أتى من شريك في حروف فيه يبين لك ذلك:\nما قرئ على أحمد بن شعيب، عن أحمد بن عبد الله بن علي بن مسروق، قال: حدثنا عبد الرحمن يعني ابن مهدي، قال: حدثنا","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:111","bookId":"nasikh-nahhas","type":"section","seq":111,"chapter":"ص: 48","title":"ص: 185","page":"ج1 ص184","text":"إسرائيل، قال: حدثنا أبو إسحاق، عن أبي بردة، عن أبي موسى، قال: بعثني رسول الله صلى الله عليه وسلم أنا ومعاذا، إلى اليمن فقال معاذ: يا رسول الله، إنك تبعثنا إلى بلد كثير شراب أهله فما نشرب؟ قال: «اشرب ولا تشرب مسكرا» واحتجوا بحديثين عن ابن مسعود أحدهما من رواية الحجاج بن أرطأة وقد ذكرنا ما في حديثه من العلة\nوالحديث الآخر حدثناه أحمد بن محمد، قال: حدثنا إبراهيم بن مرزوق، قال: حدثنا محمد بن كثير، قال: حدثنا سفيان الثوري، عن أبيه، عن لبيد بن شماس، قال: قال عبد الله: «إن القوم ليجلسون على الشراب وهو حل لهم فما يزالون حتى يحرم عليهم» قال أبو جعفر: هذا الحديث لا يحتج به؛ لأن لبيد بن شماس، وشريك يقول: شماس بن لبيد لا يعرف ولم يرو عنه أحد إلا سعيد بن مسروق، ولا روي عنه إلا هذا الحديث، والمجهول لا تقوم به حجة فلم تقم لهم حجة عن النبي صلى الله عليه وسلم ولا عن أحد من أصحابه","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:112","bookId":"nasikh-nahhas","type":"section","seq":112,"chapter":"ص: 48","title":"ص: 186","page":"ج1 ص184","text":"والحق في هذا ما قاله ابن المبارك\nقرئ على أحمد بن شعيب، عن أبي قدامة عبيد الله بن سعيد، قال: حدثنا أبو أسامة وهو حماد بن أسامة، قال: سمعت عبد الله بن المبارك، يقول: «ما وجدت الرخصة في المسكر عن أحد صحيحة إلا عن إبراهيم» قال أبو أسامة: وما رأيت أحدا أطلب للعلم من عبد الله بن المبارك بالشام ومصر والحجاز واليمن قال أبو جعفر: وأما الميسر فهو القمار\nكما حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس: {يسألونك عن الخمر، والميسر} [البقرة: 219] قال: «كان أحدهم يقامر بأهله وماله فإذا قمر أخذ أهله وماله» قال أبو جعفر: حكى أهل العلم بكلام العرب أن الميسر كان القمار في الجزر خاصة قال أبو إسحاق: «فلما حرم حرم جميع القمار كما أنه لما حرمت الخمر حرم كل ما أسكر كثيره» ، وذكر الشعبي «أن القمار كان حلالا ثم حرم» ويدل على ما قال: حديث ابن عباس قال: «لما أنزل الله جل وعز {ألم غلبت الروم في أدنى الأرض وهم من بعد غلبهم سيغلبون} وكانت قريش\nتحب أن تغلب فارس لأنهم أهل أوثان وكان المسلمون يحبون أن تغلب الروم فخاطرهم أبو بكر إلى أجل» قال أبو جعفر: وقيل: لا يقال: كان هذا حلالا ولكن يقال: مباحا ثم نسخ بتحريمه، وتحريم الخمر وفي هذه الآية قوله جل وعز {ويسألونك ماذا ينفقون} [البقرة: 219] قال أبو جعفر: وهذا آخر الآية في عدد المدني الأول، والجواب في أول الآية التاسعة عشرة","bab":"باب ذكر الآية الثامنة عشرة قال جل وعز {يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما} [البقرة: 219] قال جماعة من العلماء: هذه ا"},{"id":"nasikh-nahhas:113","bookId":"nasikh-nahhas","type":"section","seq":113,"chapter":"ص: 48","title":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال","page":"ج1 ص187","text":"أخبرنا أبو جعفر قال: حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس في قوله: {ويسألونك ماذا ينفقون قل العفو} [البقرة: 219] قال: «هو ما لا يتبين وهذا قبل أن تفرض الصدقة» قال أبو جعفر: وقال الضحاك: «نسخت الزكاة كل صدقة في القرآن» فهذا قول من قال: إنها منسوخة\nوحدثنا أبو جعفر قال: حدثنا علي بن الحسين، عن الحسن بن محمد، قال: حدثنا شبابة، قال: حدثنا ورقاء، عن ابن أبي نجيح، عن مجاهد، في قوله جل وعز {ويسألونك ماذا ينفقون قل العفو} [البقرة: 219] قال: «الصدقة المفروضة» قال أبو جعفر: والزكاة هي لعمري شيء يسير من كثير إلا أن هذا القول لا يعرف إلا عن مجاهد والقول الذي قبله: إنها منسوخة بعيد؛ لأنهم إنما سألوا عن شيء فأجيبوا عنه بأنهم سبيلهم أن ينفقوا ما سهل عليهم","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:114","bookId":"nasikh-nahhas","type":"section","seq":114,"chapter":"ص: 48","title":"ص: 189","page":"ج1 ص188","text":"والقول الثالث عليه أكثر أهل التفسير:\nكما حدثنا علي بن الحسين، عن الحسن بن محمد، قال: حدثنا أبو معاوية، قال: حدثنا ابن أبي ليلى، عن الحكم، عن مقسم، عن ابن عباس، في قوله جل وعز {ويسألونك ماذا ينفقون قل العفو} [البقرة: 219] قال: «ما فضل عن العيال» قال أبو جعفر: فهذا القول بين وهو مشتق من عفا يعفو إذا كثر وفضل والمعنى والله أعلم: ويسألونك ماذا ينفقون قل: ينفقون ما سهل عليهم وفضل عن حاجتهم وأكثر التابعين على هذا التفسير: قال طاوس: «العفو اليسير من كل شيء» وقال الحسن: {قل العفو} [البقرة: 219] «أي لا تجهد مالك حتى تبقى تسأل الناس» وقال خالد بن أبي عمران: سألت القاسم، وسالما عن قول الله جل وعز {ويسألونك ماذا ينفقون قل العفو} [البقرة: 219] فقالا: «هو فضل المال ما كان عن ظهر غني» قال أبو جعفر: وهذا من حسن العبارة في معنى الآية، وهو موافق لقول رسول الله صلى الله عليه وسلم:\nكما حدثنا أبو الحسين محمد بن الحسن بن سماعة","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:115","bookId":"nasikh-nahhas","type":"section","seq":115,"chapter":"ص: 48","title":"ص: 190","page":"ج1 ص189","text":"بالكوفة، قال: حدثنا أبو نعيم، قال: حدثنا عمرو يعني ابن عثمان بن عبد الله بن موهب، قال: سمعت موسى بن طلحة، يذكر عن حكيم بن حزام، قال: قال رسول الله صلى الله عليه وسلم: «خير الصدقة عن ظهر غنى واليد العليا خير من اليد السفلى وابدأ بمن تعول» قال أبو جعفر: فصار المعنى ويسألونك ماذا ينفقون قل: ما سهل عليكم ونظيره {خذ العفو وأمر بالعرف} [الأعراف: 199] أي خذ ما سهل من أخلاق الناس ولا تتقص عليهم فهذا العفو من أخلاق الناس وذاك العفو مما ينفقون كما قال عبد الله بن الزبير وقد تلا {خذ العفو} [الأعراف: 199] قال: «من أخلاق الناس وايم الله لأستعملن ذاك فيهم» وقال أخوه عروة وتلا {خذ العفو} [الأعراف: 199] قال: خذ ما ظهر من أعمالهم، وقولهم","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:116","bookId":"nasikh-nahhas","type":"section","seq":116,"chapter":"ص: 48","title":"ص: 191","page":"ج1 ص189","text":"قال أبو جعفر: ومن هذه الآية في عدد المدني الأول {ويسألونك عن اليتامى قل إصلاح لهم خير وإن تخالطوهم فإخوانكم} [البقرة: 220] فزعم قوم أنها ناسخة لقول الله جل وعز {إن الذين يأكلون أموال اليتامى ظلما} [النساء: 10] الآية ورووا هذا عن ابن عباس قال أبو جعفر: وهذا مما لا يجوز فيه ناسخ ولا منسوخ؛ لأنه خبر ووعيد ونهي عن الظلم والتعدي فمحال نسخه فإن صح ذلك عن ابن عباس فتأويله من اللغة أن هذه الآية على نسخة تلك الآية فهذا جواب واضح منه ما عليه أهل التأويل قال سعيد بن جبير: \" لما نزلت {إن الذين يأكلون أموال اليتامى ظلما} [النساء: 10] اشتدت على الناس وامتنعوا من مخالطة اليتامى حتى نزلت {ويسألونك عن اليتامى} [البقرة: 220] الآية فالمعنى على هذا القول أنه لما وقع بقلوبهم أنه لا ينبغي أن يخالطوا اليتامى في شيء لئلا يحرجوا بذلك، فنسخ الله جل وعز ما وقع بقلوبهم منه أي أزاله بأن أباح لهم مخالطة اليتامى وبين مجاهد ما هذه المخالطة، فقال: «في الراعي والإدام» ، ومعنى هذا أن يكون لليتيم تمر أو ما أشبهه ولوليه مثله فيخلطه معه فيأكلا جميعا فتوقفوا عن هذا مخافة أن يكون الولي يأكل أكثر مما يأكل اليتيم فأباح الله جل وعز ذلك إذا كان على جهة الإصلاح ولم يقصد فيه الإفساد ودل على هذا {والله يعلم المفسد من المصلح} [البقرة: 220]","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:117","bookId":"nasikh-nahhas","type":"section","seq":117,"chapter":"ص: 48","title":"ص: 192","page":"ج1 ص189","text":"قال مجاهد: \" {ولو شاء الله لأعنتكم} [البقرة: 220] أي حرم عليكم مخالطتهم \" قال أبو جعفر: فهذا الظاهر في اللغة أن تكون المخالطة في الطعام لا في الشركة؛ لأن مشاركة اليتيم إن وقع فيها استبداد بشيء فهي خيانة وإن كانت الشركة قد يقال لها مخالطة فليس باسمها المعروف فثبت بهذا أنه لا ناسخ في هذا ولا منسوخ إلا على ما ذكرناه وقد قال بعض الفقهاء: وما أعرف آية في الوعيد هي أشد ولا أوكد على المسلمين من قوله جل وعز {إن الذين يأكلون أموال اليتامى ظلما إنما يأكلون في بطونهم نارا وسيصلون سعيرا} [النساء: 10]","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:118","bookId":"nasikh-nahhas","type":"section","seq":118,"chapter":"ص: 48","title":"ص: 193","page":"ج1 ص189","text":"والذين في اللغة عام فأوجب الله سبحانه النار على العموم لكل من فعل هذا والآية التي هي تتمة العشرين قد أدخلها العلماء في الناسخ والمنسوخ وإن كان فيها اختلاف بين الصحابة","bab":"باب ذكر الآية التاسعة عشرة قال جل وعز {قل العفو} [البقرة: 219] فيه ثلاثة أقوال من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي الزكاة، ومنهم م"},{"id":"nasikh-nahhas:119","bookId":"nasikh-nahhas","type":"section","seq":119,"chapter":"ص: 48","title":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسو","page":"ج1 ص189","text":"كما حدثنا بكر بن سهل، قال حدثنا عبد الله بن صالح، عن معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {ولا تنكحوا المشركات حتى يؤمن} [البقرة: 221] قال: \" ثم استثنى نساء أهل الكتاب فقال جل ثناؤه: {والمحصنات من الذين أوتوا الكتاب} [المائدة: 5] حل لكم {إذا آتيتموهن أجورهن} [المائدة: 5] يعني مهورهن {محصنات غير مسافحات} [النساء: 25] يقول: عفائف غير زوان \" قال أبو جعفر: هكذا في الحديث حل لكم وليس هو في التلاوة وهكذا قال {محصنات غير مسافحات} [النساء: 25] وفي التلاوة «محصنين غير مسافحين» فهذه قراءة على التفسير وهكذا كل قراءة خالفت المصحف المجمع عليه","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:120","bookId":"nasikh-nahhas","type":"section","seq":120,"chapter":"ص: 48","title":"ص: 195","page":"ج1 ص194","text":"، وممن قال إن الآية منسوخة أيضا مالك بن أنس وسفيان بن سعيد، وعبد الرحمن بن عمرو، فأما من قال إنها ناسخة فقوله شاذ\nحدثنا جعفر بن مجاشع، قال سمعت إبراهيم بن إسحاق الحربي، يقول «فيه وجه ذهب إليه قوم جعلوا التي في البقرة هي الناسخة والتي في المائدة هي المنسوخة يعني فحرموا نكاح كل مشركة كتابية أو غير كتابية» قال أبو جعفر: ومن الحجة لقائل هذا مما صح سنده\nما حدثناه محمد بن زبان، قال حدثنا محمد بن رمح، قال أخبرنا الليث بن","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:121","bookId":"nasikh-nahhas","type":"section","seq":121,"chapter":"ص: 48","title":"ص: 196","page":"ج1 ص195","text":"سعد، عن نافع، أن عبد الله بن عمر، \" كان إذا سئل عن نكاح الرجل النصرانية، أو اليهودية قال: \" حرم الله عز وجل المشركات على المسلمين ولا أعرف شيئا من الإشراك أعظم من أن تقول المرأة: ربها عيسى أو عبد من عباد الله جل وعز \" والقول الثالث قال به جماعة من العلماء\nكما حدثنا أحمد بن محمد بن نافع، قال حدثنا سلمة، قال حدثنا عبد الرزاق، قال أخبرنا معمر، عن قتادة، {ولا تنكحوا المشركات حتى يؤمن} [البقرة: 221] قال «المشركات من غير نساء أهل الكتاب وقد تزوج حذيفة نصرانية أو يهودية»\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال حدثنا وكيع، قال حدثنا سفيان، عن حماد، قال: سألت سعيد بن جبير عن قول الله، جل وعز {ولا تنكحوا المشركات حتى يؤمن} [البقرة: 221] قال: «هم أهل الأوثان» قال أبو جعفر: وهذا أحد قولي الشافعي رحمه الله أن تكون الآية عامة يراد بها الخاص فتكون المشركات هاهنا أهل الأوثان","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:122","bookId":"nasikh-nahhas","type":"section","seq":122,"chapter":"ص: 48","title":"ص: 197","page":"ج1 ص196","text":"والمجوس فأما من قال إنها ناسخة للتي في المائدة وزعم أنه لا يجوز نكاح نساء أهل الكتاب، فقوله خارج عن قول الجماعة الذين تقوم بهم الحجة؛ لأنه قد قال بتحليل نكاح نساء أهل الكتاب من الصحابة والتابعين جماعة منهم عثمان وطلحة، وابن عباس، وجابر، وحذيفة ومن التابعين سعيد بن المسيب، وسعيد بن جبير، والحسن، ومجاهد، وطاووس، وعكرمة، والشعبي، والضحاك، وفقهاء الأمصار عليه وأيضا فيمتنع أن تكون هذه الآية من سورة البقرة ناسخة للآية التي في سورة المائدة لأن البقرة من أول ما نزل بالمدينة والمائدة من آخر ما نزل وإنما الآخر ينسخ الأول وأما حديث ابن عمر فلا حجة فيه؛ لأن ابن عمر رحمه الله كان رجلا متوقفا فلما سمع الآيتين، في واحدة التحليل وفي الأخرى التحريم ولم يبلغه النسخ توقف ولم يؤخذ عنه ذكر للنسخ وإنما تؤول عليه وليس يؤخذ الناسخ والمنسوخ بالتأويل وأبين ما في الآية أن تكون منسوخة على قول من قال ذلك من العلماء وهو أيضا أحد قولي الشافعي وذلك أن الآية إذا كانت عامة لم تحمل على الخصوص إلا بدليل قاطع فإن قال قائل فقد قال قوم من العلماء إنه لا يقال لأهل الكتاب مشركون وإنما المشرك من عبد وثنا مع الله جل وعز فأشرك به قال أبو جعفر: وممن يروى عنه هذا القول أبو حنيفة وزعم أن قول الله تعالى: {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28]","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:123","bookId":"nasikh-nahhas","type":"section","seq":123,"chapter":"ص: 48","title":"ص: 198","page":"ج1 ص196","text":"أنه يراد به أهل الأوثان وأن لليهود والنصارى أن يقربوا المسجد الحرام قال أبو جعفر: \" وهذا قول خارج عن قول الجماعة من أهل العلم واللغة وأكثر من هذا أن في كتاب الله جل وعز نصا تسميه اليهود والنصارى بالمشركين، قال الله جل وعز: {اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح ابن مريم وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو سبحانه عما يشركون} [التوبة: 31] فهذا نص القرآن فمن أشكل عليه أن قيل له اليهود والنصارى لم يشركوا أجيب عن هذا بجوابين","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:124","bookId":"nasikh-nahhas","type":"section","seq":124,"chapter":"ص: 48","title":"ص: 199","page":"ج1 ص196","text":"أحدهما أن يكون هذا اسما إسلاميا ولهذا نظائر قد بينها من يحسن الفقه واللغة من ذلك مؤمن أصله من آمن إذا صدق ثم صار لا يقال مؤمن إلا لمن آمن بمحمد صلى الله عليه وسلم ثم تبع ذلك العمل ومن الأسماء الإسلامية المنافق ومنها على قول بعض العلماء الخمر سمي ما أسكر كثيره خمرا على لسان رسول الله صلى الله عليه وسلم والجواب الآخر وهو عن أبي إسحاق بن إبراهيم بن السري قال: كل من كفر بمحمد صلى الله عليه وسلم فهو مشرك، قال وهذا من اللغة؛ لأن محمدا صلى الله عليه وسلم قد جاء من البراهين بما لا يجوز أن يأتي به بشر إلا من عند الله جل وعز فإذا كفر بمحمد صلى الله عليه وسلم فقد زعم أن ما لا يأتي به إلا الله قد جاء به غير الله جل وعز فجعل لله جل وعز شريكا قال أبو جعفر: وهذا من لطيف العلم وحسنه فأما نكاح إماء أهل الكتاب فحرام عند العلماء إلا أبا حنيفة وأصحابه، فإنهم أجازوه واحتج لهم محتج بشيء قاسه قال: لما أجمعوا على أن قوله جل وعز: {ولا تنكحوا المشركات} [البقرة: 221] يدخل فيه الأحرار والإماء وجب في القياس أن يكون قوله {والمحصنات من الذين أوتوا الكتاب} [المائدة: 5] داخلا فيه الحرائر والإماء لتكون الناسخة مثل المنسوخة قال أبو جعفر: وهذا الاحتجاج خطأ من غير جهة","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:125","bookId":"nasikh-nahhas","type":"section","seq":125,"chapter":"ص: 48","title":"ص: 200","page":"ج1 ص196","text":"، فمن ذلك أنه لم يجمع على أن الآية التي في البقرة منسوخة ومن ذلك أن القياسات والتمثيلات لا يؤخذ بها في الناسخ والمنسوخ، وإنما يؤخذ الناسخ والمنسوخ بالتيقن والتوقيف وأيضا فقد قال الله جل وعز نصا {ومن لم يستطع منكم طولا أن ينكح المحصنات المؤمنات فمن ما ملكت أيمانكم من فتياتكم المؤمنات} [النساء: 25] فكيف يقبل ممن قال من فتياتكم الكافرات؟ وأما نكاح الحربيات فروي عن ابن عباس وإبراهيم النخعي أنهما منعا من ذلك وغيرهما من العلماء يجيز ذلك، ونص الآية يوجب جوازه","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:126","bookId":"nasikh-nahhas","type":"section","seq":126,"chapter":"ص: 48","title":"ص: 201","page":"ج1 ص196","text":"، وهو قول مالك والشافعي إلا أنهما كرها ذلك مخافة تنصير الولد أو الفتنة وأما نكاح الإماء المجوسيات والوثنيات فالعلماء على تحريمه\nإلا ما رواه يحيى بن أيوب، عن ابن جريج، عن عطاء، وعمرو بن دينار، \" أنهما سئلا عن نكاح الإماء المجوسيات، فقالا لا بأس بذلك وتأولا قول الله جل وعز: {ولا تنكحوا المشركات} [البقرة: 221] فهذا عندهما على عقد النكاح لا على الأمة المشتراة، واحتجا بسبي أوطاس وأن الصحابة نكحوا الإماء منهن بملك اليمين \" قال أبو جعفر: وهذا قول شاذ، أما سبي أوطاس فقد يجوز أن يكون الإماء أسلمن فجاز نكاحهن وأما الاحتجاج بقوله جل وعز: {ولا تنكحوا المشركات حتى يؤمن} [البقرة: 221] فغلط لأنهم حملوا النكاح على العقد والنكاح في اللغة يقع على العقد وعلى الوطء، فلما قال جل وعز: {ولا تنكحوا المشركات} [البقرة: 221] حرم كل نكاح يقع على المشركات من نكاح ووطء، وفي هذا من اللغة شيء بين حدثني من أثق به قال: سمعت أحمد بن يحيى يقول: \" أصل النكاح في اللغة الوطء وإنما يقع للعقد مجازا قال: والدليل على هذا أن العرب تقول أنكحت الأرض البر إذا أدخلت البر في الأرض قال أبو جعفر: وهذا من حسن اللغة والاستخراج اللطيف ووجب من\nهذا أن يكون قوله جل وعز: {فلا تحل له من بعد حتى تنكح زوجا غيره} [البقرة: 230] حتى يطأها وبذلك جاءت السنة أيضا وقد أدخلت الآية التي تلي هذه في الناسخ والمنسوخ وهي الآية الحادية والعشرون","bab":"باب ذكر الآية التي هي تتمة العشرين قال الله جل وعز {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] فيها ثلاثة أقوال من العلماء من قال هي منسوخة ومنهم من قال هي ن"},{"id":"nasikh-nahhas:127","bookId":"nasikh-nahhas","type":"section","seq":127,"chapter":"ص: 48","title":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة","page":"ج1 ص202","text":"يأكلوا معها ولا يشربوا، فنسخ الله جل وعز ذلك من شريعتهم\nكما قرئ على أحمد بن عمرو بن عبد الخالق، عن محمد بن أحمد بن الجنيد البغدادي، عن عمرو بن عاصم، قال حدثنا حماد بن سلمة، عن ثابت، وعاصم الأحول، عن أنس بن مالك، قال \" كانت اليهود يعتزلون النساء في الحيض فأنزل الله جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن} [البقرة: 222] الآية فأمرنا رسول الله صلى الله عليه وسلم أن نؤاكلهن ونشاربهن ونصنع كل شيء إلا النكاح فقالت اليهود: ما يريد محمد أن يدع شيئا من أمرنا إلا خالفنا فيه \" قال أبو جعفر: \" فدل هذا الحديث على أنه لا يحرم من الحائض إلا النكاح في الفرج، وهذا قول جماعة من العلماء أن الرجل له أن يباشر الحائض وينال منها ما دون الوطء في الفرج، وهو قول عائشة رضي الله","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:128","bookId":"nasikh-nahhas","type":"section","seq":128,"chapter":"ص: 48","title":"ص: 204","page":"ج1 ص203","text":"عنها وأم سلمة، وابن عباس، ومسروق، والحسن، وعطاء، والشعبي، وإبراهيم النخعي، وسفيان الثوري، ومحمد بن الحسن وهو الصحيح من قول الشافعي قال أبو جعفر: وهذا الحديث المسند دال عليه\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال حدثنا عبد الرحمن بن زياد، عن عبيد الله بن عمرو، قال حدثنا أيوب السختياني، عن أبي معشر، عن إبراهيم، عن مسروق، قال سألت عائشة رضي الله عنها ما يحل لي من امرأتي وهي حائض؟ قالت: «كل شيء إلا الفرج» قال أبو جعفر: فهذا إسناد متصل والحديث الآخر أنها قالت «كان رسول الله صلى الله عليه وسلم يباشرني فوق الإزار» ليس فيه دليل على حظر غير ذلك وقد يحتمل أن يكون المعنى فوق الإزار وهو مفروش فهذا قول قال عبيدة: «اللحاف واحد والفراش مختلف وهذا قول شاذ يمنع منه ما صح عن رسول الله صلى الله عليه وسلم من مباشرته نساءه وهن حيض» وقول ثالث أن يعتزل الحائض فيما بين السرة والركبة وهو قول جماعة من العلماء منهم ميمونة ويروى عن ابن عباس ومنهم سعيد بن المسيب، ومالك بن أنس وأبو حنيفة","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:129","bookId":"nasikh-nahhas","type":"section","seq":129,"chapter":"ص: 48","title":"ص: 205","page":"ج1 ص203","text":"والحجة لهم\nما حدثناه إبراهيم بن شريك، قال حدثنا أحمد بن عبد الله بن يونس، قال حدثنا ليث يعني ابن سعد، عن الزهري، عن حبيب، مولى عروة، عن ندبة، مولاة ميمونة عن ميمونة «أن النبي صلى الله عليه وسلم كان يباشر المرأة من نسائه وهي حائض إذا كان إزارها إلى نصف فخذيها أو إلى ركبتيها محتجزة به» قال أبو جعفر: الليث يقول ندبة وغيره يقول بدية وليس في هذا الحديث دليل على حظر ما تقدمت إباحته وقد زعم قوم أن حديث أنس الذي بدأنا به منسوخ لأنه كان في أول ما نزلت الآية وأن الناسخ له\nحديث أبي إسحاق عن عمير، مولى عمر عن عمر، عن النبي صلى الله عليه وسلم أنه قال في الحائض «لك ما فوق الإزار وليس لك ما تحته»","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:130","bookId":"nasikh-nahhas","type":"section","seq":130,"chapter":"ص: 48","title":"ص: 206","page":"ج1 ص205","text":"قال أبو جعفر: وهذا ادعاء في النسخ ولا يعجز أحدا ذلك، والإسناد الأول أحسن استقامة من هذا، وهذا القول قال به جماعة قد ذكرناهم، ولم يقل أحد منهم فيه بنسخ والذي قال هذا بعض المحدثين والتقدير على القول الأول فاعتزلوا جماع النساء في موضع المحيض أي في الفرج فيكون المحيض اسما للموضع كما أن المجلس اسم للموضع الذي يجلس فيه وكذا {ولا تقربوهن} [البقرة: 222]\nكما حدثنا بكر بن سهل، قال حدثنا أبو صالح، قال حدثني","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:131","bookId":"nasikh-nahhas","type":"section","seq":131,"chapter":"ص: 48","title":"ص: 207","page":"ج1 ص205","text":"معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {فاعتزلوا النساء في المحيض} [البقرة: 222] قال «اعتزلوا نكاح فروجهن» قال أبو جعفر: ومن قرأ {حتى يطهرن} [البقرة: 222] فمعناه حتى يحل لهن أن يطهرن كما تقول قد حلت المرأة للأزواج أي حل لها أن تتزوج ومن قرأ {حتى يطهرن} [البقرة: 222] جعله بمعنى يغتسلن وقد قرأ الجماعة بالقراءتين وهما بمنزلة آيتين لا تحل له حتى تطهر وتطهر فأما قول من قال إنها تحل له إذا غسلت فرجها من الأذى بعد أن تخرج من الحيض فقول خارج عن الإجماع، وعن ظاهر القرآن، قال الله جل وعز: {وإن كنتم جنبا فاطهروا} [المائدة: 6] وفي موضع آخر {ولا جنبا إلا عابري سبيل حتى تغتسلوا} [النساء: 43] فجاء القرآن يتطهروا ويغتسلوا بمعنى واحد، وكذا حتى يطهرن أي الطهور الذي يصلين به","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:132","bookId":"nasikh-nahhas","type":"section","seq":132,"chapter":"ص: 48","title":"ص: 208","page":"ج1 ص205","text":"وأما قول من قال: إذا طهرت من الحيض حلت وإن لم تغتسل إذا دخل عليها وقت صلاة أخرى فخارج أيضا عن الإجماع وليس يعرف من قول واحد، وإنما قيس على شيء من قول أبي حنيفة أنه قال: إذا طلق الرجل امرأته طلاقا يملك معه الرجعة كان له أن يراجعها من غير إذنها ما لم تغتسل من الحيضة الثالثة إلا أن تطهر من الحيضة الثالثة فيدخل عليها وقت صلاة أخرى ولم تغتسل، فقاسوا على هذا","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:133","bookId":"nasikh-nahhas","type":"section","seq":133,"chapter":"ص: 48","title":"ص: 209","page":"ج1 ص205","text":"والدليل على ذلك\nما حدثناه أحمد بن محمد الأزدي، قال حدثنا إبراهيم بن مرزوق، قال: حدثنا أبو حذيفة، قال حدثنا سفيان، عن ابن أبي نجيح، عن مجاهد، في قوله جل وعز {ولا تقربوهن حتى يطهرن} [البقرة: 222] قال «من الدم فإذا تطهرن قال اغتسلن» قال أحمد بن محمد: ولا أعلم بين العلماء في هذا اختلافا قال أبو جعفر: فأما {من حيث أمركم الله} [البقرة: 222] ففي معناه اختلاف فعن ابن عباس، ومجاهد، قالا «في الفرج» وعن محمد بن","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:134","bookId":"nasikh-nahhas","type":"section","seq":134,"chapter":"ص: 48","title":"ص: 210","page":"ج1 ص206","text":"علي بن الحنفية، قال: «من قبل الحلال من قبل التزويج» وعن أبي رزين، قال: «من قبل الطهر لا من قبل الحيض» قال أبو جعفر: وهذا القول أشبه بسياق الكلام وأصح في اللغة لأنه لو كان المراد به الفرج كانت في هاهنا أولى فإن قيل لم لا يكون معناه من قبل الفرج، قيل لو كان كذا لم يجز أن يطأها من دبرها في فرجها، والإجماع على غير ذلك {إن الله يحب التوابين} [البقرة: 222] قال عطاء: «أي من الذنوب» وهذا لا اختلاف فيه واختلفوا في معنى {ويحب المتطهرين} [البقرة: 222] فمن أهل التفسير من قال: المتطهرين من أدبار النساء، وقيل من الذنوب وقال عطاء: «المتطهرين بالماء» وهذا أولى بسياق الآية والله جل وعز أعلم وأما الآية الثانية والعشرون فقد أدخلها بعض العلماء في الناسخ والمنسوخ وهو قتادة فذكرناها ليكون الكتاب مشتملا على ما ذكره العلماء\nباب\nذكر الآية الثانية والعشرين قال جل وعز: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة: 228] الآية قال أبو جعفر: فممن جعلها في الناسخ والمنسوخ الضحاك عن ابن عباس، وقتادة إلا أن لفظ ابن عباس أن قال: استثنى، ولفظ قتادة نسخ قال: قال الله تبارك وتعالى: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة: 228] ثم نسخ من الثلاث الحيض المطلقات اللواتي لم يدخل بهن في سورة الأحزاب فقال جل ثناؤه: {يا أيها الذين آمنوا إذا نكحتم المؤمنات ثم طلقتموهن من قبل أن تمسوهن فما لكم عليهن من عدة تعتدونها} [الأحزاب: 49] ، ونسخ الحيض عن أولات الحمل فقال جل وعز: {وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق: 4] قال أبو جعفر: وقال غيرهما من العلماء ليس هذا بنسخ ولكنه تبيين بين جل وعز بهاتين الآيتين أنه لم يرد بالأقراء الحوامل ولا اللواتي لم يدخل بهن ثم اختلف العلماء في الأقراء فقالوا فيها ثلاثة أقوال\nكما حدثنا أحمد بن محمد الأزدي، قال حدثنا محمود بن حسان، قال حدثنا","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:135","bookId":"nasikh-nahhas","type":"section","seq":135,"chapter":"ص: 48","title":"ص: 212","page":"ج1 ص211","text":"عبد الملك بن هشام، قال: حدثنا أبو زيد الأنصاري، قال: سمعت أبا عمرو بن العلاء، يقول: «العرب تسمي الطهر قرءا، وتسمي الحيض قرءا، وتسمي الطهر مع الحيض جميعا قرءا» وقال الأصمعي: «أصل القرء الوقت يقال أقرأت النجوم إذا طلعت لوقتها» قال أبو جعفر: فلما صح في اللغة أن القرء الطهر، والقرء الحيض وأنه لهما جميعا وجب أن يطلب الدليل على المراد بقوله {ثلاثة قروء} [البقرة: 228] من غير اللغة إلا أن بعض العلماء يقول: هي الأطهار ويرده إلى اللغة من جهة الاشتقاق وسنذكر قوله بعد ذكر ما في ذلك عن الصحابة والتابعين وفقهاء الأمصار، فممن قال الأقراء الأطهار عائشة بلا اختلاف عنها\nكما قرئ على إسحاق بن إبراهيم بن جابر، عن سعيد بن الحكم بن محمد بن أبي مريم، قال","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:136","bookId":"nasikh-nahhas","type":"section","seq":136,"chapter":"ص: 48","title":"ص: 213","page":"ج1 ص211","text":"حدثنا عبد الله بن عمر بن حفص، قال أخبرني عبد الرحمن بن القاسم، عن أبيه، عن عائشة، قالت: «إنما الأقراء الأطهار» قال أبو جعفر: وقد رواه الزهري عن عروة وعمرة عن عائشة وممن روي عنه الأقراء الأطهار باختلاف ابن عمر، وزيد بن ثابت\nقال أبو جعفر كما حدثنا بكر بن سهل، قال حدثنا عبد الله بن يوسف، قال أخبرنا مالك، عن نافع، عن ابن عمر، أنه كان يقول: «إذا طلق الرجل امرأته فرأت الدم من الحيضة الثالثة فقد برئت منه وبرئ منها ولا ترثه ولا يرثها» وإنما وقع الخلاف فيه عن ابن عمر\nلأن بكر بن سهل حدثنا، قال حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن عبد الله بن عمر، أنه كان يقول: «إذا طلق العبد امرأته اثنتين حرمت عليه حتى تنكح زوجا غيره حرة كانت أو أمة، وعدة الأمة حيضتان وعدة الحرة ثلاث حيض»","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:137","bookId":"nasikh-nahhas","type":"section","seq":137,"chapter":"ص: 48","title":"ص: 214","page":"ج1 ص213","text":"قال أبو جعفر: والحديثان جميعا في الموطأ، فأما حديث زيد ففيه روايتان\nإحداهما من حديث الزهري، عن قبيصة بن ذؤيب، عن زيد بن ثابت، قال «عدة الأمة حيضتان، وعدة الحرة ثلاث حيض» والمخالف له\nما حدثنا إبراهيم بن شريك، قال: حدثنا أحمد يعني ابن عبد الله بن يونس، قال حدثنا ليث، عن نافع، أن سليمان بن يسار، حدثه \" أن الأحوص وهو ابن حكيم طلق امرأته بالشام فهلك وهي في آخر حيضتها يعني الثالثة فكتب معاوية إلى زيد بن ثابت يسأله فكتب إليه لا ترثه ولا يرثها وقد برئت منه وبرئ منها، قال نافع: فقال عبد الله بن عمر مثل ذلك \"\nوقرئ على بكر بن سهل، عن سعيد بن منصور، قال: حدثنا سفيان بن عيينة، عن الزهري، عن عمرة، عن عائشة، وعن سليمان بن يسار، عن زيد بن ثابت، قالا «يبينها من زوجها إذا طعنت في الحيضة الثالثة»","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:138","bookId":"nasikh-nahhas","type":"section","seq":138,"chapter":"ص: 48","title":"ص: 215","page":"ج1 ص214","text":"قال أبو جعفر: فهؤلاء الصحابة الذين روي عنهم أن الأقراء الأطهار وهم ثلاثة فأما التابعون وفقهاء الأمصار ففيهم القاسم، وسالم، وسليمان بن يسار، وأبو بكر بن عبد الرحمن، وأبان بن عثمان، ومالك بن أنس والشافعي، وأبو ثور وأما الذين قالوا الأقراء الحيض فأحد عشر من أصحاب رسول الله صلى الله عليه وسلم بلا اختلاف عنهم وزيادة اثنين باختلاف\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: وحدثنا خالد بن إسماعيل، ووكيع بن الجراح، قالا: حدثنا عيسى بن أبي عيسى، عن الشعبي، قال أحد عشر من أصحاب رسول الله صلى الله عليه وسلم أو اثنا عشر الخير فالخير منهم عمر وزاد وكيع وأبو بكر قالا وعلي، وابن مسعود وابن عباس: «إذا طلق الرجل امرأته تطليقة أو تطليقتين فله عليها الرجعة ما لم تغتسل من القرء الثالث وقال وكيع في حديثه ما لم تغتسل من حيضتها الثالثة» قال أبو جعفر: «الأحد عشر أبو بكر، وعمر، وعثمان، وعلي وابن عباس وابن مسعود، ومعاذ وعبادة وأبو الدرداء، وأبو موسى وأنس والاثنان بالاختلاف ابن عمر، وزيد»\nقرئ على بكر بن سهل، عن سعيد بن منصور، قال حدثنا سفيان بن عيينة، عن الزهري، عن سعيد بن المسيب، في الرجل يطلق امرأته تطليقة أو تطليقتين قال: قال علي: «هو أحق برجعتها ما لم تغتسل من الحيضة الثالثة»\nقال سفيان، حدثنا منصور، عن إبراهيم، عن علقمة، عن عمر، وابن مسعود أنهما قالا: «هو أحق بها ما لم تغتسل»\nقال سفيان: وحدثنا أيوب، عن الحسن عن أبي موسى الأشعري،: مثل ذلك ومن التابعين وفقهاء الأمصار سعيد بن المسيب، وسعيد بن جبير، وطاووس، وعطاء والضحاك ومحمد بن سيرين، والشعبي، والحسن، وقتادة، والأوزاعي، والثوري، وأبو حنيفة وأصحابه، وإسحاق، وأبو عبيد وحكى الأثرم عن أحمد بن حنبل أنه كان يقول الأقراء الأطهار ثم وقف فقال: وكان الأكابر من أصحاب محمد صلى الله عليه وسلم يقولون غير هذا قال أبو جعفر: فهذا ما جاء عن العلماء بالروايات ونذكر ما في ذلك من النظر واللغة من احتجاجاتهم إذ كان الخلاف قد وقع، فمن أحسن ما احتج به من قال الأقراء الأطهار قوله جل وعز: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة: 228] فأخبر جل وعز أن القروء هي العدد، والعدد عقيبة الطلاق وإنما يكون الطلاق في الطهر فلو كانت الأقراء هي الحيض كان بين الطلاق والعدة فصل واحتجوا بالحديث\nحدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر \" أنه طلق امرأته وهي حائض فسأل عمر بن الخطاب رسول الله صلى الله عليه وسلم فقال: «مره فليراجعها ثم ليمسكها حتى تطهر ثم تحيض ثم تطهر ثم إن شاء أمسك بعد وإن شاء طلق قبل أن يمس فتلك العدة التي أمر الله جل وعز أن يطلق لها النساء» قال المحتج فتلك إشارة إلى الطهر\nوفي حديث أبي الزبير، عن ابن عمر، وتلا رسول الله صلى الله عليه وسلم: فطلقوهن في قبل عدتهن قال: «فقبل عدتهن هو الطهر» قال أبو جعفر: ومخالفه يحتج عليه بالحديث بعينه وسيأتي ذلك واحتج بعضهم بأنه من قريت الماء أي حبسته فكذا القرء: احتباس الحيض وهذا غلط بين لأن قريت الماء غير مهموز وهذا مهموز فاللغة تمنع أخذ هذا من هذا واحتج بعضهم بأن الآية ثلاثة قروء بالهاء فوجب أن تكون للطهر لأن الطهر مذكر وعدد المذكر يدخل فيه الهاء ولو كان للحيضة لقيل ثلاث قال أبو جعفر: وهذا غلط في العربية لأن الشيء يكون له اسمان مذكر ومؤنث فإذا جئت بالمؤنث أنثته وإذا جئت بالمذكر ذكرته كما تقول","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:139","bookId":"nasikh-nahhas","type":"section","seq":139,"chapter":"ص: 48","title":"ص: 218","page":"ج1 ص217","text":"رأيت ثلاث أدؤر ورأيت ثلاثة منازل لأن الدار مؤنثة والمنزل مذكر والمعنى واحد وأما احتجاج الذين قالوا الأقراء الحيض فبشيء من القرآن ومن الإجماع ومن السنة ومن القياس قالوا قال الله جل وعز {واللائي يئسن من المحيض من نسائكم إن ارتبتم فعدتهن ثلاثة أشهر} [الطلاق: 4] فجعل الميئوس منه الحيض فدل على أنه هو العدة وجعل العوض منه الأشهر إذا كان معدوما وقال الله جل وعز: {فطلقوهن لعدتهن} [الطلاق: 1] وبين رسول الله صلى الله عليه وسلم أن معنى {فطلقوهن لعدتهن} [الطلاق: 1] أن يطلق في طهر لم يجامع فيه ولا تخلو لعدتهن من أن يكون معناه ليعتددن في المستقبل أو يكون للحال أو للماضي، ومحال أن تكون العدة قبل الطلاق أو أن يطلقها في حال عدتها فوجب أن تكون للمستقبل قال أبو جعفر: والطهر كله جائز أن يطلق فيه وليس بعد الطهر إلا الحيض وقال جل وعز: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة: 228] قالوا: فإذا طلقها في الطهر ثم احتسبت به قرءا فلم تعتد إلا قرئين وشيئا وليس هكذا نص القرآن وقد احتج محتج في هذا فقال: التثنية جمع واحتج بقوله جل وعز: {الحج أشهر معلومات} [البقرة: 197] وإنما ذلك شهران وأيام","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:140","bookId":"nasikh-nahhas","type":"section","seq":140,"chapter":"ص: 48","title":"ص: 219","page":"ج1 ص217","text":"فهذا الاحتجاج غلط لأنه لم يقل جل وعز ثلاثة أشهر فيكون مثل ثلاثة قروء وإنما هذا مثل قوله جل وعز: {يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] فلا يجوز أن يكون أقل منها وكذا فصيام ثلاثة أيام في الحج وسبعة إذا رجعتم\nفأما من السنة فحدثنا الحسن بن غليب، قال: حدثنا يحيى بن عبد الله، قال أخبرني الليث، عن يزيد بن أبي حبيب، عن بكير بن عبد الله بن الأشج، عن المنذر بن المغيرة، عن عروة بن الزبير، أن فاطمة ابنة أبي حبيش أخبرته أنها، أتت رسول الله صلى الله عليه وسلم فشكت إليه الدم فقال: «إنما ذلك عرق فانظري إذا أتاك قرؤك فلا تصلي وإذا مر القرء فتطهري ثم صلي من القرء إلى القرء»","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:141","bookId":"nasikh-nahhas","type":"section","seq":141,"chapter":"ص: 48","title":"ص: 220","page":"ج1 ص217","text":"وهذا لفظ رسول الله صلى الله عليه وسلم سمى الحيض قرءا في أربعة مواضع وأما الإجماع: فأجمع المسلمون على الاستبراء بحيضة وقال عمر بن الخطاب رضي الله عنه بحضرة أصحاب رسول الله صلى الله عليه وسلم عدة الأمة حيضتان نصف عدة الحرة ولو قدرت على أن أجعلها حيضة ونصفا لفعلت وهذا يدخل في باب الإجماع لأنه لم ينكره عليه أحد من الصحابة وقالوا قد أجمع العلماء على أن المطلقة ثلاثا إذا ولدت فقد خرجت من العدة لا اختلاف في ذلك وإنما اختلفوا في المتوفى عنها زوجها قالوا فالقياس أن يكون الحيض بمنزلة الولد؛ لأنهما جميعا يخرجان من الجوف وفي سياق الآية أيضا دليل، قال الله جل وعز: {ولا يحل لهن أن يكتمن ما خلق الله في أرحامهن} [البقرة: 228] فللعلماء في هذا قولان: قال ابن عباس «الحبل» وقال الزهري «الحيض» ، وليس ثم دليل يدل على اختصاص أحدهما فوجب أن يكون لهما جميعا، وإنما حظر عليها كتمان الحيض والحبل لأن زوجها إذا طلقها طلاقا يملك معه الرجعة كان له أن يراجعها من غير أمرها ما لم تنقض عدتها","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:142","bookId":"nasikh-nahhas","type":"section","seq":142,"chapter":"ص: 48","title":"ص: 221","page":"ج1 ص217","text":"فإذا كرهته قالت قد حضت الحيضة الثالثة أو قد ولدت لئلا يراجعها فنهيت عن ذلك قال جل وعز: {وبعولتهن أحق بردهن في ذلك} [البقرة: 228]\nحدثنا أحمد بن محمد بن نافع، قال حدثنا سلمة، قال حدثنا عبد الرزاق، قال أخبرنا معمر، عن قتادة، {وبعولتهن أحق بردهن في ذلك} [البقرة: 228] قال: «هو أحق بردها في العدة» قال أبو جعفر: التقدير في العربية في ذلك الأجل وأما {ولهن مثل الذي عليهن بالمعروف} [البقرة: 228] فقال فيه ابن زيد «عليه أيضا أن يتقي الله فيها» وأما {وللرجال عليهن درجة} [البقرة: 228] ففيه أقوال: فقال ابن زيد: «عليها أن تطيعه وليس عليه أن يطيعها» قال الشعبي: «إذا قذفها لاعن ولم يحد وإذا قذفته حدت» ومن أحسن ما قيل فيه ما رواه عكرمة عن ابن عباس قال: «ما أريد أن أستنظف حقوقي على زوجتي»","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:143","bookId":"nasikh-nahhas","type":"section","seq":143,"chapter":"ص: 48","title":"ص: 222","page":"ج1 ص219","text":"قال أبو جعفر: ومعنى هذا أن الله تبارك وتعالى ندب الرجال إلى أن يتفضلوا على نسائهم وأن تكون لهم عليهن درجة في العفو والتفضل والاحتمال؛ لأن معنى: درجة في اللغة زيادة وارتفاع قال أبو العالية: «والله عزيز في انتقامه حكيم في تدبيره» قال أبو جعفر: وهذا قول حسن أي عزيز في انتقامه ممن خالف أمره وحدوده في أمر الطلاق والعدة حكيم فيما دبر لخلقه واختلف العلماء في الآية التي تلي هذه فمنهم من جعلها ناسخة ومنهم من جعلها منسوخة ومنهم من جعلها محكمة وهي الآية الثالثة والعشرون","bab":"باب ذكر الآية الحادية والعشرين قال جل وعز: {ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن} [البقرة: 222] قال أبو جعفر:"},{"id":"nasikh-nahhas:144","bookId":"nasikh-nahhas","type":"section","seq":144,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في","page":"ج1 ص221","text":"إذا طلقها ثلاثا لم تحل له حتى تنكح زوجا غيره وإذا طلقها واحدة أو اثنتين كانت له مراجعتها ما دامت في العدة، فقال جل وعز: {الطلاق مرتان} [البقرة: 229] أي الطلاق الذي تملك معه الرجعة وهذا معنى قول عروة\nوحدثنا أبو جعفر قال: قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال حدثنا روح بن عبادة، عن سعيد، عن قتادة، في قوله جل وعز {الطلاق مرتان} [البقرة: 229] قال: «فنسخ هذا ما كان قبله فجعل الله جل وعز حد الطلاق ثلاثا وجعل له الرجعة ما لم يطلق ثلاثا» فهذا قول والقول الثاني: إنها منسوخة بقوله جل وعز: {فطلقوهن لعدتهن} [الطلاق: 1]","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:145","bookId":"nasikh-nahhas","type":"section","seq":145,"chapter":"ص: 48","title":"ص: 224","page":"ج1 ص223","text":"والقول الثالث: إنها محكمة وافترق قول من قال إنها محكمة على ثلاث جهات: فمنهم من قال لا ينبغي للرجال إذا أراد أن يطلق امرأته أن يطلقها إلا اثنتين لقول الله تبارك وتعالى {الطلاق مرتان} [البقرة: 229] ثم إن شاء طلق الثالثة بعد وهذا قول عكرمة والقول الثاني: أنه يطلقها في طهر لم يجامعها فيه إن شاء واحدة وإن شاء اثنتين وإن شاء ثلاثا وهذا قول الشافعي والقول الثالث: الذي عليه أكثر العلماء أن يطلقها في كل طهر طلقة","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:146","bookId":"nasikh-nahhas","type":"section","seq":146,"chapter":"ص: 48","title":"ص: 225","page":"ج1 ص223","text":"واحدة ويحتج لصاحب هذا القول: بقول رسول الله صلى الله عليه وسلم لعمر «مره فليراجعها ثم ليمسكها حتى تطهر ثم تحيض ثم تطهر ثم إن شاء أمسك وإن شاء طلق قبل أن يجامع» قال أبو جعفر: وقد ذكرناه بإسناده وكانت السنة أن يكون بين كل طلقتين حيضة فلو طلق رجل امرأته وهي حائض ثم راجعها ثم طلقها في الطهر الذي يلي الحيضة وقعت تطليقتان بينهما حيضة واحدة، وهذا خلاف السنة فلهذا أمر أن يراجعها ثم يمسكها حتى تطهر ثم تحيض ثم تطهر ومن الحجة أيضا {الطلاق مرتان} [البقرة: 229] لأن مرتين يدل على التفريق كذا هو في اللغة قال سيبويه: وقد تقول سير عليه مرتين تجعله للدهر أي ظرفا فسيبويه يجعل مرتين ظرفا فالتقدير أوقات الطلاق مرتان\nوحدثنا أحمد بن محمد بن نافع، قال حدثنا سلمة، قال حدثنا عبد الرزاق، قال أخبرنا سفيان الثوري، قال أخبرني إسماعيل بن","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:147","bookId":"nasikh-nahhas","type":"section","seq":147,"chapter":"ص: 48","title":"ص: 226","page":"ج1 ص223","text":"سميع، عن أبي رزين، أن رجلا، قال يا رسول الله أسمع الله تبارك وتعالى يقول {الطلاق مرتان} [البقرة: 229] فأين الثالثة؟ قال: «التسريح بإحسان» قال أبو جعفر: وفي هذه الآية ما قد اختلف فيه اختلاف كثير وجعله بعضهم في المنسوخ بعد الاتفاق على أنه في مخالفة الرجل امرأته قال جل وعز: {ولا يحل لكم أن تأخذوا مما آتيتموهن شيئا إلا أن يخافا ألا يقيما حدود الله} [البقرة: 229] إلى آخر الآية قال عقبة بن أبي الصهباء سألت بكر بن عبد الله المزني عن","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:148","bookId":"nasikh-nahhas","type":"section","seq":148,"chapter":"ص: 48","title":"ص: 227","page":"ج1 ص223","text":"الرجل تريد امرأته أن تخالعه، فقال: \" لا يحل له أن يأخذ منها شيئا قلت فأين قول الله عز وجل في كتابه {فإن خفتم أن لا يقيما حدود الله فلا جناح عليهما فيما افتدت به} قال نسخت، قلت: فأين جعلت؟ قال في سورة النساء {وإن أردتم استبدال زوج مكان زوج وآتيتم إحداهن قنطارا فلا تأخذوا منه شيئا أتأخذونه بهتانا وإثما مبينا} [النساء: 20] والآية الأخرى \" قال أبو جعفر: وهذا قول شاذ خارج عن الإجماع وليس إحدى الآيتين رافعة للأخرى فيقع النسخ لأن قوله جل وعز {فإن خفتم أن لا يقيما حدود الله فلا جناح عليهما فيما افتدت به} ليس بمزال بتلك لأنهما إذا خافا هذا لم يدخل الزوج في {وإن أردتم استبدال زوج مكان زوج} [النساء: 20] لأن هذا للرجال خاصة ومن الشذوذ في هذا ما روي عن سعيد بن جبير، ومحمد بن سيرين، والحسن أنهم قالوا: لا يجوز الخلع إلا بأمر السلطان قال شعبة قلت لقتادة عمن أخذ الحسن الخلع إلى السلطان قال عن زياد","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:149","bookId":"nasikh-nahhas","type":"section","seq":149,"chapter":"ص: 48","title":"ص: 228","page":"ج1 ص223","text":"قال أبو جعفر: وهو صحيح معروف عن زياد ولا معنى لهذا القول لأن الرجل إذا خالع امرأته فإنما هو على ما يتراضيان به ولا يجوز أن يجبره السلطان على ذلك فلا معنى لقول من قال: هو إلى السلطان ومع هذا فقول الصحابة وأكثر التابعين إن الخلع جائز من غير إذن السلطان فممن قال ذلك عمر، وعثمان، وابن عمر\nكما حدثنا محمد بن زيان، قال حدثنا محمد بن رمح، قال أخبرني الليث، عن نافع، أنه سمع الربيع ابنة معوذ بن عفراء، تخبر عبد الله بن عمر أنها اختلعت من زوجها في عهد عثمان فجاء عمها معاذ بن عفراء إلى عثمان فقال إن ابنة معوذ اختلعت من زوجها أفتنتقل؟ فقال عثمان: «لتنتقل ولا ميراث بينهما ولا عدة عليها ولكن لا تنكح حتى تحيض حيضة خشية أن يكون بها حمل» فقال ابن عمر: عثمان خيرنا وأعلمنا\nوفي حديث أيوب، وعبيد الله، عن نافع، عن ابن عمر، عن عثمان، «ولا نفقة لها» وفي هذا الحديث أحكام وعلوم فمنها أن عثمان رحمه الله أجاز الخلع على خلاف ما قال بكر بن عبد الله وأجازه من غير إذن السلطان على خلاف ما قال زياد وجعله طلاقا على خلاف ما يروى عن ابن عباس وأجازه بالمال ولم يسأل أهو\nأكثر من صداقها أم أقل على خلاف ما يقول أبو حنيفة وأصحابه: إن الخلع لا يجوز بأكثر مما ساق إليها من الصداق وأجاز للمختلعة أن تنتقل وجعلها خلاف المطلقة ولم يجعل عليها عدة كالمطلقة وقال بهذا القول إسحاق بن راهويه قال: وليس على المختلعة عدة وإنما عليها الاستبراء بحيضة وهو قول ابن عباس بلا اختلاف وعن ابن عمر فيه اختلاف فلما جاء عن ثلاثة من الصحابة لم يقل بغيره ولا سيما ولم يصح عن أحد من الصحابة خلافه فأما عن غيرهم فكثير قال جماعة من العلماء عدة المختلعة عدة المطلقة منهم سعيد بن المسيب، وسليمان بن يسار، وسالم بن عبد الله، وعروة بن الزبير، وعمر بن عبد العزيز والزهري، والحسن، وإبراهيم النخعي، وسفيان الثوري، والأوزاعي، ومالك، وأبو حنيفة وأصحابه والشافعي، وأحمد بن حنبل وفي حديث عثمان أنه أوجب أن المختلعة أملك بنفسها لا تتزوج إلا برضاها وإن كانت لم تطلق إلا واحدة، وفيه أنها لا نفقة لها ولا سكنى وأنهما لا يتوارثان، وإن كان إنما طلقها واحدة وفيه أنها لا تنكح حتى تحيض حيضة\nوفيه أن عبد الله بن عمر خبر أن عثمان خير وأعلم من كل من ولي عليه\nوأما حديث ابن عباس فحدثناه، أحمد بن محمد الأزدي، قال حدثنا محمد بن خزيمة، قال حدثنا حجاج، قال حدثنا أبو عوانة، عن ليث، عن طاوس: أن ابن عباس، «جمع بين رجل وامرأته بعد أن طلقها تطليقتين وخالعها» وهذا قول شاذ خارج عن الإجماع والمعقول وذلك أنه إذا قال لامرأته: أنت طالق إذا كان كذا فوقعت الصفة طلقت بإجماع فكيف يكون إذا أخذ منها شيئا وطلق بصفة لم يقع الطلاق فهذا محال في المعقول، وطاوس وإن كان رجلا صالحا فعنده عن ابن عباس مناكير يخالف عليها ولا يقبلها أهل العلم منها أنه: روي عن ابن عباس، أنه قال في رجل قال لامرأته أنت طالق ثلاثا إنما يلزمه واحدة ولا يعرف هذا عن ابن عباس إلا من روايته والصحيح عنه وعن علي بن أبي طالب رضي الله عنهما أنها ثلاث كما قال الله جل وعز {فإن طلقها فلا تحل له من بعد} [البقرة: 230] أي الثالثة فأما العلة التي رويت عن ابن عباس في المختلعة فإنه روي عنه أنه قال: وقع الخلع بين طلاقين، قال جل وعز: {الطلاق مرتان} [البقرة: 229] ثم ذكر المختلعة فقال جل وعز: {فإن طلقها} [البقرة: 230]","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:150","bookId":"nasikh-nahhas","type":"section","seq":150,"chapter":"ص: 48","title":"ص: 231","page":"ج1 ص230","text":"قال أبو جعفر: الذي عليه أهل العلم أن قوله جل وعز {الطلاق مرتان فإمساك بمعروف أو تسريح بإحسان} [البقرة: 229] كلام قائم بنفسه ثم قال جل وعز ولا يحل لكم أن تأخذوا مما آتيتموهن شيئا فكان هذا حكما مستأنفا ثم قال جل وعز: {فإن طلقها} [البقرة: 230] فرجع إلى الأول ولو كان على ما روي عن ابن عباس لم تكن المختلعة إلا من طلقت تطليقتين فهذا ما لا يقول به أحد ومثل هذا في التقديم والتأخير {وامسحوا برءوسكم وأرجلكم} قال أبو جعفر: وهذا بين في النحو وفي الآية من اللغة وقد ذكره مالك رحمه الله نصا فقال المختلعة التي اختلعت من كل مالها والمفتدية التي افتدت ببعض مالها والمبارئة التي بارأت زوجها من قبل أن يدخل بها، فقالت: قد أبرأتك فبارئني قال: وكل هذا سواء وهذا صحيح في اللغة وقد يدخل بعضه في بعض فيقال مختلعة وإن دفعت بعض مالها فيكون تقديره أنها اختلعت نفسها من زوجها وكذا المفتدية وإن افتدت بكل مالها","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:151","bookId":"nasikh-nahhas","type":"section","seq":151,"chapter":"ص: 48","title":"ص: 232","page":"ج1 ص230","text":"فأما قول من قال لا يجوز أن تختلع بأكثر مما ساق إليها من الصداق فشيء لا توجبه الآية لأن الله تبارك وتعالى قال: {فلا جناح عليهما فيما افتدت به} [البقرة: 229] وليس في التلاوة {فيما افتدت به} [البقرة: 229] من ذلك ولا منه فيصح ما قالوا على أن سعيد بن المسيب يروى عنه أنه قال «لا يجوز الخلع إلا بأقل من الصداق» وقال ميمون بن مهران «من أخذ الصداق كله فلم يسرح بإحسان» وقد أدخلت الآية الرابعة والعشرون في الناسخ والمنسوخ قال ذلك مالك بن أنس رحمه الله","bab":"باب ذكر الآية الثالثة والعشرين قال الله جل وعز {الطلاق مرتان} [البقرة: 229] الآية فمن العلماء من يقول هي ناسخة لما كانوا عليه لأنهم كانوا في الجاهلية مدة، وفي أ"},{"id":"nasikh-nahhas:152","bookId":"nasikh-nahhas","type":"section","seq":152,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة والعشرين قال الله جل وعز: {وعلى الوارث مثل ذلك} [البقرة: 233] في هذه الآية للعلماء أقوال فمنهم من قال هي منسوخة ومنهم","page":"ج1 ص230","text":"عصبة الأب عليهم النفقة والكسوة ومنهم من قال على وارث المرضع النفقة والكسوة ومنهم من قال وعلى الوارث أي الصبي نفسه، ومنهم من قال الوارث الباقي من الأبوين ومنهم من قال الوارث كل ذي رحم محرم قال أبو جعفر: ونحن ننسب هذه الأقوال إلى قائليها من الصحابة والتابعين والفقهاء ونشرحها لتكمل الفائدة في ذلك حكى عبد الرحمن بن القاسم في الأسدية عن مالك بن أنس رحمه الله أنه قال: لا يلزم الرجل نفقة أخ ولا ذي قرابة ولا ذي رحم منه قال: وقول الله جل وعز {وعلى الوارث مثل ذلك} [البقرة: 233] هو منسوخ قال أبو جعفر: هذا لفظ مالك رحمه الله ولم يبين ما الناسخ لها ولا عبد الرحمن بن القاسم\nومذهب ابن عباس، ومجاهد، والشعبي أن المعنى {وعلى الوارث} [البقرة: 233] أن لا يضار والذين قالوا على وارث الأب النفقة والكسوة عمر بن الخطاب رضي الله عنه والحسن بن أبي الحسن\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال حدثنا قبيصة، قال حدثنا سفيان، عن ابن جريج، عن عمرو بن شعيب، عن سعيد بن المسيب: أن عمر، «أجبر بني عم على منفوس» وفي رواية ابن عيينة: الرجال دون النساء وقال الحسن «إذا خلف أمه وعمه الأم موسرة والعم معسر فالنفقة على العم»","bab":"باب ذكر الآية الرابعة والعشرين قال الله جل وعز: {وعلى الوارث مثل ذلك} [البقرة: 233] في هذه الآية للعلماء أقوال فمنهم من قال هي منسوخة ومنهم من قال إنها محكمة وا"},{"id":"nasikh-nahhas:153","bookId":"nasikh-nahhas","type":"section","seq":153,"chapter":"ص: 48","title":"ص: 235","page":"ج1 ص234","text":"والذين قالوا: وعلى وارث المولود النفقة والكسوة زيد بن ثابت قال: إذا خلف أما وعما فعلى كل واحد منهما على قدر ميراثهما وهو قول عطاء وقال قتادة «على وارث الصبي على قدر ميراثهم» وقال قبيصة بن ذؤيب الوارث الصبي\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال حدثنا أبو عبد الرحمن المقرئ، قال أخبرنا حيوة، قال حدثنا جعفر بن ربيعة، عن قبيصة بن ذؤيب، {وعلى الوارث مثل ذلك} [البقرة: 233] قال: «الوارث الصبي» وروى ابن المبارك عن سفيان الثوري قال: «إذا كان للصبي أم وعم أجبرت الأم على رضاعة ولم يطالب العم بشيء» وأما الذين قالوا على كل ذي رحم محرم فهم أبو حنيفة وأبو يوسف، ومحمد\nقال أبو جعفر: فهذه جميع الأقوال التي وصفناها من أقوال الصحابة والتابعين والفقهاء، فأما قول مالك إنها منسوخة فلم يبينه ولا علمت أن أحدا من أصحابه بين ذلك والذي يشبه أن يكون الناسخ لها عنده والله جل وعز: أعلم أنه لما أوجب الله تبارك وتعالى للمتوفى عنها زوجها من مال المتوفى نفقة حول والسكنى ثم نسخ ذلك ورفعه نسخ ذلك أيضا عن الوارث، وأما قول من قال: {وعلى الوارث مثل ذلك} [البقرة: 233] أن لا يضار فقول حسن لأن أموال الناس محظورة فلا يخرج منها شيء إلا بدليل قاطع، وأما قول من قال على ورثة الأب فالحجة له أن النفقة كانت على الأب فورثته أولى من ورثة الابن\nوأما حجة من قال على ورثة الابن فيقول: كما يرثونه يقومون به قال أبو جعفر: وكان محمد بن جرير يختار قول من قال الوارث هاهنا الابن وهو وإن كان قولا غريبا فالإسناد به صحيح والحجة به ظاهرة؛ لأن ماله أولى به وقد أجمع الفقهاء إلا من شذ منهم أن رجلا لو كان له ولد طفل وللولد مال والأب موسر أنه لا يجب على الأب نفقة ولا رضاع وأن ذلك من مال الصبي فإن قيل قد قال الله جل وعز {وعلى المولود له رزقهن وكسوتهن} [البقرة: 233] قيل هذا الضمير للمؤنث ومع هذا فإن الإجماع حذا للآية مبين لها لا يسع مسلما الخروج عنه وأما قول من قال ذلك على من بقي من الأبوين فحجته أنه لا يجوز للأم تضييع ولدها وقد مات من كان ينفق عليها وعليه وأما قول من قال النفقة والكسوة على كل ذي رحم محرم فحجته أن على الرجل أن ينفق على كل ذي رحم محرم إذا كان فقيرا قال أبو جعفر: وقد عورض هذا القول بأنه لم يؤخذ من كتاب الله جل وعز ولا من إجماع ولا من سنة صحيحة بل لا يعرف من قول سوى من ذكرناه، فأما القرآن فقال جل وعز {وعلى الوارث مثل ذلك} [البقرة: 233] فتكلم الصحابة والتابعون فيه بما تقدم ذكره فإن كان على الوارث النفقة والكسوة فقد خالفوا ذلك، فقالوا: إذا ترك خاله وابن عمه فالنفقة على خاله وليس على ابن عمه شيء فهذا مخالفة نص القرآن لأن الخال لا يرث مع ابن\nالعم في قول أحد ولا يرث وحده في قول كثير من العلماء، والذي احتجوا به من النفقة على كل ذي رحم محرم أكثر أهل العلم على خلافه وأما الآية الخامسة والعشرون فقد تكلم العلماء أيضا فيها فقال أكثرهم: هي ناسخة وقال بعضهم فيها ما نسخ","bab":"باب ذكر الآية الرابعة والعشرين قال الله جل وعز: {وعلى الوارث مثل ذلك} [البقرة: 233] في هذه الآية للعلماء أقوال فمنهم من قال هي منسوخة ومنهم من قال إنها محكمة وا"},{"id":"nasikh-nahhas:154","bookId":"nasikh-nahhas","type":"section","seq":154,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلم","page":"ج1 ص238","text":"أقاموا برهة من الإسلام إذا توفي الرجل، وخلف امرأته حاملا أوصى لها زوجها بنفقة سنة وبالسكنى ما لم تخرج فتتزوج ثم نسخ ذلك بأربعة أشهر وعشر وبالميراث واختلف الذين قالوا هذا القول قال بعضهم نسخ من الأربعة الأشهر والعشر المتوفى عنها زوجها وهي حامل، فانقضاء عدتها إذا ولدت وقال قوم: آخر الأجلين وقال قوم هو عام بمعنى الخاص أي {والذين يتوفون منكم ويذرون أزواجا} [البقرة: 234] لسن حوامل يتربصن بأنفسهن أربعة أشهر وعشرا وقال قوم ليس في هذا نسخ وإنما هو نقصان من الحول وقال قوم هما محكمتان واستدلوا بأنها منهية عن المبيت في غير منزل زوجها قال أبو جعفر: ونحن نشرح هذه الأقوال ونذكر قائلي من نعرف منهم\nفممن قال: إن الآية ناسخة وصح ذلك عنه عثمان بن عفان وعبد الله بن الزبير حتى قال عبد الله بن الزبير: قلت لعثمان: لم أثبت في المصحف {والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج} [البقرة: 240] وقد نسختها {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] فقال يا ابن أخي إني لا أغير شيئا عن مكانه فبين عثمان رضي الله عنه أنه إنما أثبت في المصحف ما أخذه عن النبي صلى الله عليه وسلم وأخذه النبي عليه السلام عن جبريل على ذلك التأليف لم يغير منه شيئا\nوأخبرنا أبو جعفر، قال حدثنا أحمد بن محمد بن نافع، قال حدثنا سلمة، قال حدثنا عبد الرزاق، قال أخبرنا معمر، عن قتادة، {والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم} [البقرة: 240] قال: \" نسخها {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] قال {متاعا إلى الحول} [البقرة: 240] غير إخراج نسختها الربع أو الثمن ونسخ الحول العدة أربعة أشهر وعشر \"\nقال أبو جعفر وحدثنا بكر بن سهل، قال حدثنا أبو صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله عز وجل: {والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم} [البقرة: 240] الآية \" كانت المرأة إذا مات زوجها وتركها اعتدت منه سنة وينفق عليها من ماله ثم أنزل الله جل وعز بعد ذلك {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234]","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:155","bookId":"nasikh-nahhas","type":"section","seq":155,"chapter":"ص: 48","title":"ص: 241","page":"ج1 ص240","text":"إلا أن تكون حاملا فانقضاء عدتها أن تضع ما في بطنها، ونزل {ولهن الربع مما تركتم إن لم يكن لكم ولد فإن كان لكم ولد فلهن الثمن مما تركتم} [النساء: 12] فبين الله جل وعز الميراث وترك النفقة والوصية \" قال أبو جعفر: وأما قول من قال إنه عام بمعنى الخاص فقول حسن لأنه قد تبين ذلك بالقرآن والحديث وسنذكر ذينك وأما قول من قال نسخ منها الحوامل فيحتج بقول ابن مسعود: من شاء لاعنته أن سورة النساء القصرى نزلت بعد الطولى يعني أن قوله جل وعز {وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق: 4] نزلت بعد التي في البقرة وهذا القول أعني أن {وأولات الأحمال} [الطلاق: 4] ناسخة للتي في البقرة أو مبينة لها قول أكثر الصحابة والتابعين والفقهاء فمنهم عمر، وابن عمر، وابن مسعود وأبو مسعود البدري، وأبو هريرة وسعيد بن المسيب، والزهري، ومالك، والأوزاعي، والثوري وأصحاب الرأي، والشافعي وأبو ثور","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:156","bookId":"nasikh-nahhas","type":"section","seq":156,"chapter":"ص: 48","title":"ص: 242","page":"ج1 ص240","text":"وأما قول من قال آخر الأجلين فحجته أنه جمع بين الآيتين، وممن قال به بلا اختلاف عنه علي بن أبي طالب رضي الله عنه وكان بينه وبين الصحابة فيه منازعة شديدة من أجل الخلاف فيه\nكما حدثنا أحمد بن محمد الأزدي، قال حدثنا إبراهيم بن مرزوق، قال حدثنا أبو داود الطيالسي، عن شعبة، قال حدثنا عبيد بن الحسن، قال حدثنا ابن معقل، قال: \" شهدت علي بن أبي طالب، رضي الله عنه وقد سئل عن رجل توفي وامرأته حامل فقال: تعتد آخر الأجلين فقيل له يا أمير المؤمنين إن أبا مسعود البدري يقول لتبتغ لنفسها فقال: إن فروخا لا يعلم شيئا فبلغ ذلك أبا مسعود فقال: بلى وأنا أعلم \" وذكر الحديث وممن صح عنه أنه قال تعتد آخر الأجلين عبد الله بن عباس قال أبو جعفر: وقد ذكرنا من قال بغير هذا من الصحابة حتى قال عمر","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:157","bookId":"nasikh-nahhas","type":"section","seq":157,"chapter":"ص: 48","title":"ص: 243","page":"ج1 ص240","text":": إن وضعت حملها وزوجها على السرير حلت وعلى القول الآخر لا تحل حتى تمضي أربعة أشهر وعشرا ثم جاء التوقيف عن النبي صلى الله عليه وسلم بأنها تحل إذا توفي زوجها وهي حامل ثم ولدت قبل انقضاء أربعة أشهر وعشر، وصح ذلك عنه\nكما حدثنا بكر بن سهل، قال حدثنا عبد الله بن يوسف، قال أخبرنا مالك، عن يحيى بن سعيد، عن سليمان بن يسار، أن عبد الله بن عباس، وأبا سلمة بن عبد الرحمن سئلا عن المرأة يتوفى عنها زوجها وهي حامل، فقال ابن عباس: «آخر الأجلين» وقال أبو سلمة: «إذا ولدت فقد حلت» فقال أبو هريرة \" أنا مع ابن أخي. يعني أبا سلمة فأرسلوا كريبا مولى ابن عباس إلى أم سلمة زوج النبي صلى الله عليه وسلم فجاء فأخبرهم أن أم سلمة قالت ولدت سبيعة الأسلمية بعد وفاة زوجها بليال فذكرت ذلك","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:158","bookId":"nasikh-nahhas","type":"section","seq":158,"chapter":"ص: 48","title":"ص: 244","page":"ج1 ص242","text":"لرسول صلى الله عليه وسلم الله فقال: «قد حللت» . وقال الحسن، والشعبي: «لا تتزوج حتى تخرج من دم النفاس» وكذا قال حماد بن أبي سليمان قال أبو جعفر: وإذا قال الرسول صلى الله عليه وسلم شيئا لم يلتفت إلى قول غيره ولا سيما ونص القرآن {وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق: 4] وقد أجمع الجميع بلا خلاف بينهم أن رجلا لو توفي وترك امرأته حاملا فانقضت أربعة أشهر وعشر أنها لا تحل حتى تلد فعلم أن المقصود الولادة وأما قول من قال: ليس في هذا نسخ وإنما هو نقصان من الحول فحجته أن هذا مثل صلاة المسافر لما نقصت من الأربع إلى اثنتين لم يكن هذا نسخا وهذا غلط بين لأنه إذا كان حكمها أن تعتد سنة إذا لم تخرج فإن خرجت لم تمنع ثم أزيل هذا ولزمتها العدة أربعة أشهر وعشر فهذا هو النسخ وليس صلاة المسافر من هذا في شيء","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:159","bookId":"nasikh-nahhas","type":"section","seq":159,"chapter":"ص: 48","title":"ص: 245","page":"ج1 ص242","text":"والدليل على ذلك أن عائشة رضي الله عنها قالت: فرضت الصلاة ركعتين ركعتين فزيد في صلاة الحضر وأقرت صلاة المسافر بحالها، وهكذا يقول جماعة من الفقهاء إن فرض المسافر ركعتان قال أبو جعفر: وقد عورضوا في هذا بأن عائشة رضي الله عنها كانت تتم في السفر فكيف تتم في السفر وهي تقول فرض المسافر ركعتان فهذا متناقض فأجابوا عن ذلك بأن هذا ليس بمتناقض لأنه قد صح عنها ما ذكرناه وهي أم المؤمنين فحيث حلت فهي مع أولادها فليست بمسافرة وحكمها حكم من كان حاضرا فلذلك كانت تتم الصلاة إن صح عنها الإتمام، ومما يدلك على أن الآية منسوخة\nإن بكر بن سهل حدثنا، قال: حدثنا عبد الله بن يوسف، قال أخبرنا مالك، عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم، عن حميد بن نافع، عن زينب بنت أبي سلمة، أنها أخبرته هذه الأحاديث الثلاثة قالت زينب: «دخلت على أم حبيبة زوج النبي صلى الله عليه وسلم حين توفي أبوها","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:160","bookId":"nasikh-nahhas","type":"section","seq":160,"chapter":"ص: 48","title":"ص: 246","page":"ج1 ص243","text":"أبو سفيان بن حرب فدعت أم حبيبة، بطيب فيه صفرة خلوق أو غيره فدهنت منه جارية ثم مست بعارضيها ثم قالت والله مالي بالطيب من حاجة غير أني سمعت رسول الله صلى الله عليه وسلم يقول» لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث ليال إلا على زوج أربعة أشهر وعشرا \"\nقالت زينب: \" ودخلت على زينب بنت جحش، حين توفي أخوها فدعت بطيب فمست منه ثم قالت: أما والله ما لي بالطيب من حاجة غير أني سمعت رسول الله صلى الله عليه وسلم على المنبر يقول: «لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث ليال إلا على زوج أربعة أشهر وعشرا»\nقالت زينب وسمعت أم سلمة، تقول: \" جاءت امرأة إلى رسول الله صلى الله عليه وسلم فقالت يا رسول الله إن ابنتي توفي عنها زوجها قد اشتكت عينيها أفأكحلها؟ فقال رسول الله صلى الله عليه وسلم: «لا» مرتين أو ثلاثا، كل ذلك يقول: «لا» ثم قال رسول الله صلى الله عليه وسلم: «إنما هي أربعة أشهر وعشر، وقد كانت إحداكن في الجاهلية ترمي بالبعرة على رأس الحول» قال حميد: فقلت لزينب وما ترمي بالبعرة على رأس الحول قال","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:161","bookId":"nasikh-nahhas","type":"section","seq":161,"chapter":"ص: 48","title":"ص: 247","page":"ج1 ص246","text":"حميد: فقالت زينب: «كانت المرأة إذا توفي عنها زوجها دخلت حفشا ولبست شر ثيابها ولم تمس طيبا ولا شيئا حتى تمر بها سنة ثم تؤتى بدابة حمار أو شاة أو طائر فتفتض به فقل ما تفتض بشيء إلا مات ثم تخرج فتعطى بعرة فترمي بها ثم تراجع بعد ما شاءت من طيب أو غيره» وفي هذا الحديث من الفقه والمعاني واللغة شيء كثير فمن ذلك إيجاب الإحداد والامتناع من الزينة والكحل على المتوفى عنها زوجها على خلاف ما روى إسماعيل ابن علية عن يونس عن الحسن: أنه كان لا يرى بأسا بالزينة للمتوفى عنها زوجها ولا يرى الإحداد شيئا وفيه قوله صلى الله عليه وسلم: «لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث إلا على زوج» فأوجب هذا على كل امرأة بالغة كانت أو غير بالغة مدخولا بها أو غير مدخول بها أمة كانت تحت حر أو حرة كانت تحت عبد أو مطلقة واحدة أو اثنتين لأنها بمنزلة من لم يطلق","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:162","bookId":"nasikh-nahhas","type":"section","seq":162,"chapter":"ص: 48","title":"ص: 248","page":"ج1 ص246","text":"ودل هذا على أنه لا إحداد على المبتوتة وإنما هو على المتوفى عنها زوجها ودل ظاهر الحديث على أنه لا إحداد على كافرة لقول النبي صلى الله عليه وسلم: «تؤمن بالله واليوم الآخر» ودل أيضا ظاهره أنه لا إحداد على الحامل لذكره عليه السلام أربعة أشهر وعشرا فأما معنى ترمي بالبعرة فقال فيه أهل اللغة والعلماء بمعاني العرب: إنهن كن يفعلن ذلك ليرين أن مقامهن حولا أهون عليهن من تلك البعرة المرمية وفيه من اللغة والغريب قوله تفتض وقد رواه بعض الفقهاء الجلة تقبص وقال معناه تجعل أصابعها على الطائر كما قرئ: فقبصت قبصة، فخالفه أصحاب مالك أجمعون فقالوا: تفتض وهو على تفسير مالك كذا يجب\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: سمعت مالكا، وسئل ما تفتض به قال: «تمسح به جلدها»\nقال أبو جعفر: هذا مشتق من انفض القوم إذا تفرقوا وزال بعضهم عن بعض قال جل وعز: {حتى ينفضوا} [المنافقون: 7] فمعنى تفتض به تزول به لأنها لا تزول من مكانها إلا بهذا فقد صارت تفتض به وأما قول من قال الآيتان محكمتان واحتج بأن على المتوفى عنها\nزوجها ألا تبيت إلا في منزلها فليس بشيء؛ لأنه لو كان كما قال وجب عليها أن تقيم سنة كما في الآية المنسوخة وأيضا فليس مقامها في منزلها إجماعا بل قد اختلف فيه الصدر الأول ومن بعدهم فمن قال إن عليها المقام عمر، وعثمان، وأم سلمة، وابن مسعود، وابن عمر وتابعهم على ذلك أكثر فقهاء الأمصار فقال مالك: «تزور وتقيم بعد العشاء إلى أن يهدأ الناس ولا تبيت إلا في منزلها» وهذا قول الليث، وسفيان الثوري وأبي حنيفة، والشافعي وقال محمد بن الحسن «لا تخرج المتوفى عنها زوجها ولا المبتوتة من منزلها البتة»\nوممن قال غير هذا وقال لها أن تخرج وتحج إن شاءت ولا تقيم في منزلها علي بن أبي طالب رضي الله عنه، وعلى هذا صح عنه أنه أخرج ابنته أم كلثوم زوجة عمر بن الخطاب لما قتل عمر فضمها إلى منزله قبل أن تنقضي عدتها وصح عن ابن عباس مثل هذا\nروى الثوري، عن ابن جريج، عن عطاء، عن ابن عباس، قال: \" ليس على المتوفى عنها زوجها ولا على المبتوتة إقامة في بيتها إنما قال الله جل وعز {يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] فإنما عليها العدة وليس عليها مقام ولا نفقة لها «وممن قال بهذا القول أعني أنه ليس على المتوفى عنها زوجها إقامة عائشة وجابر بن عبد الله هؤلاء أربعة من الصحابة لم يوجبوا الإقامة ومنهم من احتج بالآية والحجة لمخالفهم قوله جل وعز يتربصن بأنفسهن فعليهن أن يحبسن أنفسهن عن كل الأشياء إلا ما خرج بدليل ومن الحجة أيضا توقيف الرسول صلى الله عليه وسلم وقوله للفريعة حين توفي عنها زوجها» أقيمي في منزلك حتى يبلغ الكتاب أجله \" وقد قال قوم: إن قوله جل وعز {والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم} [البقرة: 240] منسوخ بالحديث: «لا وصية لوارث» وأكثر\nالعلماء على أنها منسوخة بالآية التي ذكرناها ومما يبين لك أنها منسوخة اختلاف العلماء في النفقة على المتوفى عنها زوجها وهي حامل فأكثر العلماء يقول لا نفقة لها ولا سكنى فمن الصحابة عبد الله بن عباس وابن الزبير، وجابر ومن التابعين سعيد بن المسيب، والحسن، وعطاء بن أبي رباح وممن دونهم مالك بن أنس وأبو حنيفة وزفر وأبو يوسف ومحمد وهو الصحيح من قول الشافعي. وممن قال للمتوفى عنها زوجها وهي حامل النفقة من رأس المال علي بن أبي طالب رضي الله عنه وابن مسعود وابن عمر وهو قول شريح وخلاس بن عمرو، والشعبي، والنخعي وأيوب السختياني، وحماد بن أبي سليمان والثوري، وأبي عبيد وفيه قول ثالث عن قبيصة بن ذؤيب قال: «لو كنت فاعلا لجعلتها من مال ذي بطنها»\nوحجة من قال لا نفقة للمتوفى عنها زوجها إجماع المسلمين أنه لا نفقة لمن كانت تجب له النفقة على الرجل قبل موته من أطفاله وأزواجه وآبائه الذين تجب عليه نفقتهم بإجماع إذا كانوا زمنى فقراء فكذا تجب أيضا في الحامل المتوفى عنها زوجها. قال أبو جعفر: واختلفوا أيضا في الآية السادسة والعشرين فمنهم من قال هي محكمة واجبة ومنهم من قال هي مندوب إليها ومنهم من قال قد أخرج منها شيء ومنهم من قال هي منسوخة","bab":"باب ذكر الآية الخامسة والعشرين قال جل وعز {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] الآية، أكثر العلماء على أن هذه الآية "},{"id":"nasikh-nahhas:163","bookId":"nasikh-nahhas","type":"section","seq":163,"chapter":"ص: 48","title":"باب ذكر الآية السادسة والعشرين قال جل وعز: {لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المق","page":"ج1 ص253","text":"وعز {ومتعوهن} [البقرة: 236] من الصحابة علي بن أبي طالب رضي الله عنه ومن التابعين الحسن قال الحسن وأبو العالية: لكل مطلقة متعة مدخول بها أو غير مدخول بها مفروض لها أو غير مفروض لها، وهذا قول سعيد بن جبير والضحاك وهو قول أبي ثور\nقال أبو جعفر وحدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن ابن شهاب، أنه كان يقول: «لكل مطلقة متعة» وأما من قال قد أخرج منها شيء فعبد الله بن عمر\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال أخبرنا مالك، عن نافع، عن ابن عمر، قال: «لكل مطلقة متاع إلا التي لم يسم لها صداق ولم تمس فحسبها نصف ما فرض لها»","bab":"باب ذكر الآية السادسة والعشرين قال جل وعز: {لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعر"},{"id":"nasikh-nahhas:164","bookId":"nasikh-nahhas","type":"section","seq":164,"chapter":"ص: 48","title":"ص: 255","page":"ج1 ص254","text":"وأما قول من قال ومتعوهن على الندب لا على الحتم والإيجاب فهو قول شريح قال: «متع إن كنت من المحسنين ألا تحب أن تكون من المتقين» فهذا قول مالك بن أنس أنه لا يجبر على المتعة لامرأة من المطلقات كلهن، وأما قول أبي حنيفة وأصحابه وهو يروى عن الشافعي أنه لا يجبر على المتعة إلا أن يتزوج امرأة ولا يسمي لها صداقا فيطلقها قبل أن يمسها فإنه يجبر على تمتيعها وأما قول من قال بالنسخ فيها فهو قول سعيد بن المسيب\nكما حدثنا أحمد بن محمد الأزدي، قال حدثنا أحمد بن الحسن الكوفي، قال حدثنا أسباط بن محمد، قال حدثنا سعيد بن أبي عروبة، عن قتادة، عن سعيد بن المسيب، قال: «كانت المتعة واجبة لمن لم يدخل بها من النساء في سورة الأحزاب ثم نسختها الآية التي في البقرة»","bab":"باب ذكر الآية السادسة والعشرين قال جل وعز: {لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعر"},{"id":"nasikh-nahhas:165","bookId":"nasikh-nahhas","type":"section","seq":165,"chapter":"ص: 48","title":"ص: 256","page":"ج1 ص254","text":"قال أبو جعفر: يجب أن تكون التي في سورة الأحزاب {يا أيها الذين آمنوا إذا نكحتم المؤمنات ثم طلقتموهن من قبل أن تمسوهن فما لكم عليهن من عدة تعتدونها فمتعوهن} [الأحزاب: 49] فهذا إيجاب المتعة، والناسخة لها عنده التي في البقرة {وإن طلقتموهن من قبل أن تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم} [البقرة: 237] الآية وهذا لا يجب فيه ناسخ ولا منسوخ لأنه ليس في الآية لا تمتعوهن ولكن القول الصحيح البين أنه اجتزئ بذكر المتعة ثم فلم تذكرها هنا ولا سيما وبعده {وللمطلقات متاع بالمعروف} [البقرة: 241]","bab":"باب ذكر الآية السادسة والعشرين قال جل وعز: {لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعر"},{"id":"nasikh-nahhas:166","bookId":"nasikh-nahhas","type":"section","seq":166,"chapter":"ص: 48","title":"ص: 257","page":"ج1 ص254","text":"فهذا أوكد من متعوهن؛ لأن متعوهن قد يقع على الندب وذكره التمتيع في القرآن مؤكد قال الله جل وعز {على الموسع قدره وعلى المقتر قدره متاعا بالمعروف} [البقرة: 236] وكذا ظاهر القرآن وهو قول علي بن أبي طالب رضي الله عنه ومن ذكرناه وهو أحد قولي الشافعي: إن على كل مطلق متعة إذا كان الطلاق من قبله فأما تفرضوا لهن فريضة ففيه أن علي بن أبي طلحة روى عن ابن عباس قال: «الفريضة الصداق» قال أبو جعفر: الفرض في اللغة الإيجاب ومنه فرض الحاكم على فلان كذا كما قال:\n[البحر الكامل]\nكانت فريضة ما تقول كما ... كان الزناء فريضة الرجم\nوقد احتج قوم في أن التمتيع ليس بواجب لقول الله تبارك وتعالى {حقا على المحسنين} [البقرة: 236] وكذا {حقا على المتقين} [البقرة: 180] وهذا لا يلزم لأنه إذا كان واجبا على المحسنين فهو على غيرهم أوجب وأيضا فإن الناس جميعا مأمورون بأن يكونوا محسنين متقين لأن معنى يجب أن تكون محسنا يجب أن تحسن إلى نفسك بأن تؤدي فرائض الله جل وعز وتجتنب معاصيه فتكون محسنا إلى نفسك حتى لا تدخل النار ويجب أن تتقي الله بترك معاصيه والانتهاء إلى ما كلفكه من فرائضه فوجب على الخلق أن يكونوا محسنين متقين واختلف العلماء في الآية السابعة والعشرين فقال بعضهم هي منسوخة وقال بعضهم هي مخصوصة","bab":"باب ذكر الآية السادسة والعشرين قال جل وعز: {لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعر"},{"id":"nasikh-nahhas:167","bookId":"nasikh-nahhas","type":"section","seq":167,"chapter":"ص: 48","title":"باب ذكر الآية السابعة والعشرين قال جل وعز: {لا إكراه في الدين} [البقرة: 256] فمن العلماء من قال: هي منسوخة لأن رسول الله صلى الله عليه وسلم","page":"ج1 ص255","text":"ما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال أخبرنا سفيان بن عيينة، عن زيد بن أسلم، عن أبيه، قال سمعت عمر بن الخطاب، رضي الله عنه يقول لعجوز نصرانية: \" أسلمي أيتها العجوز تسلمي، إن الله جل وعز بعث محمدا صلى الله عليه وسلم بالحق، فقالت: أنا عجوز كبيرة وأموت إلى قريب، فقال عمر اللهم اشهد، ثم تلا {لا إكراه في الدين} [البقرة: 256] \" وممن قال إنها مخصوصة ابن عباس\nكما قرئ على أحمد بن شعيب، عن محمد بن بشار، عن ابن أبي عدي، في حديثه عن شعبة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس، قال: \" كانت المرأة تجعل على نفسها إن عاش لها ولد أن تهوده فلما أجليت بنو النضير كان فيهم من أبناء الأنصار، فقالت الأنصار: لا ندع أبناءنا فأنزل الله جل وعز {لا إكراه في الدين قد تبين الرشد من الغي} [البقرة: 256] \" قول ابن عباس في هذه الآية أولى الأقوال لصحة إسناده وأن مثله لا يؤخذ بالرأي فلما خبر أن الآية نزلت في هذا وجب أن يكون أولى الأقوال وأن تكون الآية مخصوصة نزلت في هذا، وحكم أهل الكتاب كحكمهم","bab":"باب ذكر الآية السابعة والعشرين قال جل وعز: {لا إكراه في الدين} [البقرة: 256] فمن العلماء من قال: هي منسوخة لأن رسول الله صلى الله عليه وسلم قد أكره العرب على دي"},{"id":"nasikh-nahhas:168","bookId":"nasikh-nahhas","type":"section","seq":168,"chapter":"ص: 48","title":"ص: 260","page":"ج1 ص259","text":"فأما دخول الألف واللام في الدين فللتعريف لأن المعنى لا إكراه في الإسلام وفي ذلك قول آخر يكون التقدير لا إكراه في دين الإسلام والألف واللام عوض من المضاف إليه مثل {يصهر به ما في بطونهم والجلود} [الحج: 20] أي وجلودهم واختلف العلماء أيضا في الآية الثامنة والعشرين، فقال بعضهم هي ناسخة وقال بعضهم نزلت في شيء بعينه غير ناسخة وقال بعضهم هي عامة","bab":"باب ذكر الآية السابعة والعشرين قال جل وعز: {لا إكراه في الدين} [البقرة: 256] فمن العلماء من قال: هي منسوخة لأن رسول الله صلى الله عليه وسلم قد أكره العرب على دي"},{"id":"nasikh-nahhas:169","bookId":"nasikh-nahhas","type":"section","seq":169,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام","page":"ج1 ص259","text":"على هذا القول\nأن أحمد بن محمد الأزدي حدثنا، قال حدثنا إبراهيم بن أبي داود، قال حدثنا يحيى بن صالح الوحاظي، قال حدثنا مسلم بن خالد الزنجي، عن زيد بن أسلم، عن عبد الرحمن بن البيلماني، قال: \" كنت بمصر فقال لي رجل ألا أدلك على رجل من أصحاب رسول الله صلى الله عليه وسلم فقلت بلى فأشار إلى رجل فجئته فقلت من","bab":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام كان إذا أعسر من دين"},{"id":"nasikh-nahhas:170","bookId":"nasikh-nahhas","type":"section","seq":170,"chapter":"ص: 48","title":"ص: 262","page":"ج1 ص261","text":"أنت رحمك الله؟ فقال: أنا سرق فقلت: سبحان الله ما ينبغي لك أن تسمى بهذا الاسم وأنت رجل من أصحاب النبي صلى الله عليه وسلم فقال إن رسول الله صلى الله عليه وسلم سماني سرقا فلن أدع ذلك أبدا قلت: ولم سماك سرقا؟ قال لقيت رجلا من أهل البادية ببعيرين له يبيعهما فابتعتهما منه وقلت انطلق معي حتى أعطيك فدخلت بيتي ثم خرجت من خلف خرج لي وقضيت بثمن البعيرين حاجتي وتغيبت حتى ظننت أن الأعرابي قد خرج فخرجت والأعرابي مقيم فأخذني فقدمني إلى رسول الله صلى الله عليه وسلم فأخبرته الخبر فقال رسول الله صلى الله عليه وسلم ما حملك على ما صنعت قلت قضيت بثمنها حاجتي يا رسول الله قال: «فاقضه» قال: قلت ليس عندي قال: «أنت سرق، اذهب به يا أعرابي فبعه حتى تستوفي حقك» قال فجعل الناس يسومونه بي ويلتفت إليهم فيقول ما تريدون؟ فيقولون نريد أن نبتاعه منك قال، فوالله إن منكم أحدا أحوج إليه مني اذهب فقد أعتقتك \" قال أحمد بن محمد الأزدي ففي هذا الحديث بيع الحر في الدين وقد كان ذلك في أول الإسلام يباع من عليه دين فيما عليه من الدين إذا لم يكن له مال يقضيه عن نفسه حتى نسخ الله جل وعز ذلك فقال عز وجل {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فذهب قوم إلى أن هذه الآية إنما أنزلت في الربا وأنه إذا كان لرجل على رجل دين ولم يكن عنده ما يقضيه إياه حبس أبدا حتى يوفيه","bab":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام كان إذا أعسر من دين"},{"id":"nasikh-nahhas:171","bookId":"nasikh-nahhas","type":"section","seq":171,"chapter":"ص: 48","title":"ص: 263","page":"ج1 ص261","text":"واحتجوا بقول الله جل وعز: {إن الله يأمركم أن تؤدوا الأمانات إلى أهلها} [النساء: 58] هذا قول شريح، وإبراهيم النخعي\nكما حدثنا أحمد بن محمد بن نافع، قال حدثنا سلمة، قال حدثنا عبد الرزاق، قال أخبرنا معمر، عن أيوب، عن محمد بن سيرين، في قول الله جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] قال: \" خاصم رجل إلى شريح في دين له فقال آخر يعذر صاحبه إنه معسر وقد قال الله تعالى {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فقال شريح كان هذا في الربا وإنما كان في الأنصار وإن الله تعالى قال: {إن الله يأمركم أن تؤدوا الأمانات إلى أهلها وإذا حكمتم بين الناس أن تحكموا بالعدل} [النساء: 58] ولا يأمرنا الله جل وعز بشيء ثم نخالفه احبسوه إلى جنب السارية حتى يوفيه\" وقال جماعة من أهل العلم فنظرة إلى ميسرة عامة في جميع الناس وكل من أعسر أنظر وهذا قول أبي هريرة، والحسن وجماعة من الفقهاء","bab":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام كان إذا أعسر من دين"},{"id":"nasikh-nahhas:172","bookId":"nasikh-nahhas","type":"section","seq":172,"chapter":"ص: 48","title":"ص: 264","page":"ج1 ص261","text":"وعارض في هذه الأقوال بعض الفقهاء بأشياء من النظر والنحو واحتج بأنه لا يجوز أن يكون هذا في الربا قال لأن الربا قد أبطل فكيف يقال فيه {وإن كان ذو عسرة فنظرة إلى ميسرة وأن تصدقوا خير لكم} [البقرة: 280] واحتج من النحو بأنه لو كان في الربا لكان وإن كان ذا عسرة لأنه قد تقدم ذكره فلما كان في السواد وإن كان ذو عسرة علم أنه منقطع من الأول عام لكل من كان ذا عسرة وكانت كان بمعنى وقع وحدث كما قال\n[البحر الطويل]\nفدى لبني ذهل بن شيبان ناقتي ... إذا كان يوم ذو كواكب أشهب\nقال أبو جعفر: وهذا الاحتجاج ظاهره حسن فإذا فتشت عنه لم يلزم وذلك أن قوله الربا قد أبطله الله تعالى فالأمر في قوله قد أبطله الله تعالى صحيح إن كان يريد ألا يعمل به وإلا فقد قال {فلكم رءوس أموالكم} فما الذي يمنع أن يكون الإعسار في مثل هذا وأما احتجاجه بالنحو فلا يلزم قد يجوز أن يكون التقدير وإن كان منهم ذو عسرة وقد حكى النحويون المرء مقتول بما قتل به إن خنجر فخنجر وإن كان يجوز فيه غير هذا وأحسن ما قيل في الآية قول عطاء والضحاك قالا: «هي في","bab":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام كان إذا أعسر من دين"},{"id":"nasikh-nahhas:173","bookId":"nasikh-nahhas","type":"section","seq":173,"chapter":"ص: 48","title":"ص: 265","page":"ج1 ص261","text":"الربا والدين في كله» فهذا قول يجمع الأقوال لأنه يجوز أن تكون ناسخة عامة نزلت في الربا ثم صار حكم غيره كحكمه ولا سيما وقد روى يزيد بن أبي زياد عن مجاهد عن ابن عباس قال: نزلت في الربا وهذا توقيف من ابن عباس بحقيقة الأمر مما لا يجوز أن يؤخذ بقياس ولا رأي لأنه خبر أنها نزلت فيه فأما {وأن تصدقوا خير لكم} [البقرة: 280] فجعله قتادة على الموسر والمعسر، وقال السدي على المعسر وهذا أولى لأنه يليه واختلفوا في الآية التاسعة والعشرين فجاء الاختلاف فيها عن الصدر الأول والثاني","bab":"باب ذكر الآية الثامنة والعشرين قال جل وعز {وإن كان ذو عسرة فنظرة إلى ميسرة} [البقرة: 280] فمن قال إنها ناسخة احتج بأن الإنسان في أول الإسلام كان إذا أعسر من دين"},{"id":"nasikh-nahhas:174","bookId":"nasikh-nahhas","type":"section","seq":174,"chapter":"ص: 48","title":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء في","page":"ج1 ص263","text":"إذا اشترى شيئا أو باعه إلا أن يشهد ولا يكتب إذا لم يكن إلى أجل واحتجوا بظاهر القرآن وقال بعضهم: هذا على الندب والإرشاد لا على الحتم وقال بعضهم هو منسوخ فممن قال هو واجب من الصحابة ابن عمر وأبو موسى الأشعري ومن التابعين محمد بن سيرين، وأبو قلابة، والضحاك، وجابر بن زيد، ومجاهد ومن أشدهم في ذلك عطاء قال: \" أشهد إذا بعت وإذا اشتريت بدرهم أو نصف درهم أو ثلث درهم أو أقل من ذلك فإن الله تعالى يقول: {وأشهدوا إذا تبايعتم} [البقرة: 282] \"\nوحدثنا جعفر بن مجاشع، قال حدثنا إبراهيم بن إسحاق، قال حدثنا شجاع، قال حدثنا هشيم، عن مغيرة، عن إبراهيم، قال: «أشهد إذا بعت وإذا اشتريت ولو دستجة بقل» وممن كان يذهب إلى هذا محمد بن جرير وأنه لا يحل لمسلم إذا باع أو اشترى إلا أن يشهد وإلا كان مخالفا كتاب الله جل وعز وكذا إن كان إلى أجل فعليه أن يكتب ويشهد إن وجد كاتبا واحتج بحجج سنذكرها في آخر الأقوال في الآية فممن قال إنها منسوخة من الصحابة أبو سعيد الخدري\nكما حدثنا محمد بن جعفر بالأنبار، قال حدثنا إبراهيم بن ديسم الخراساني، قال حدثنا عبيد الله بن عمر، قال حدثنا محمد بن مروان، قال حدثنا عبد الملك بن أبي نضرة، عن أبيه، عن أبي","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:175","bookId":"nasikh-nahhas","type":"section","seq":175,"chapter":"ص: 48","title":"ص: 268","page":"ج1 ص267","text":"سعيد الخدري، \" أنه تلا: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] إلى {فإن أمن بعضكم بعضا فليؤد الذي اؤتمن أمانته} [البقرة: 283] ، قال: «نسخت هذه ما قبلها» قال أبو جعفر: وهذا قول الحسن، والحكم، وعبد الرحمن بن زيد وممن قال إنها على الندب والإرشاد لا على الحتم الشعبي ويحكى أن هذا قول مالك والشافعي وأصحاب الرأي واحتج محمد بن جرير في أنها أمر لازم وأنه واجب على كل من اشترى شيئا إلى أجل أن يكتب ويشهد وإن اشتراه بغير أجل أن يشهد بظاهر الآية وأنه فرض لا يسع تضييعه لأن الله تبارك وتعالى أمر به وأمر الله سبحانه لازم لا يحمل على الندب والإرشاد إلا بدليل، ولا دليل يدل","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:176","bookId":"nasikh-nahhas","type":"section","seq":176,"chapter":"ص: 48","title":"ص: 269","page":"ج1 ص267","text":"على ذلك ولا يجوز عنده أن يكون هذا نسخا؛ لأن معنى الناسخ أن ينفي حكم المنسوخ ولم تأت آية فيها لا تكتبوا ولا تشهدوا فيكون هذا ناسخا واحتج بأنه لا معنى لقول من قال: {فإن أمن بعضكم بعضا فليؤد الذي اؤتمن أمانته} [البقرة: 283] ناسخ للأول، لا معنى له لأن هذا حكم غير ذاك وإنما هذا حكم من لم يجد كاتبا أو كتابا قال جل وعز: {ولم تجدوا كاتبا فرهان مقبوضة فإن أمن بعضكم بعضا} [البقرة: 283] أي فلم يطالبه برهن فليؤد الذي اؤتمن أمانته، قال: ولو جاز أن يكون هذا ناسخا للأول لجاز أن يكون قوله تعالى: {وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط} [النساء: 43] الآية ناسخا لقوله تعالى: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة} [المائدة: 6] الآية ولجاز أن يكون قوله: {فمن لم يجد فصيام شهرين متتابعين} [النساء: 92] ناسخا لقوله تعالى: {فتحرير رقبة مؤمنة} [النساء: 92] قال أبو جعفر: فهذا كلام بين غير أن الفقهاء الذين تدور عليهم الفتيا وأكثر الناس على أن هذا ليس بواجب ومما يحتجون فيه أن المسلمين مجمعون على أن رجلا لو خاصم رجلا إلى الحاكم فقال باعني كذا فقال ما بعته ولم تكن بينة أن الحاكم يستحلفه ويحتجون أيضا\nبحديث الزهري عن عمارة بن خزيمة بن ثابت عن","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:177","bookId":"nasikh-nahhas","type":"section","seq":177,"chapter":"ص: 48","title":"ص: 270","page":"ج1 ص267","text":"عمه وكان من أصحاب النبي صلى الله عليه وسلم: \" أن رسول الله صلى الله عليه وسلم ابتاع فرسا من أعرابي ثم استتبعه ليدفع إليه ثمنه فأسرع النبي صلى الله عليه وسلم المشي فساوم قوم الأعرابي بالفرس ولم يعلموا فصاح الأعرابي بالنبي صلى الله عليه وسلم أتبتاعه مني أم أبيعه فقال: «أليس قد ابتعته منك؟» قال: لا والله ما ابتعته مني فأقبل الناس يقولون له ويحك إن رسول الله صلى الله عليه وسلم لا يقول إلا حقا، فقال: هل من شاهد فقال: خزيمة أنا أشهد فقال النبي صلى الله عليه وسلم: «بم تشهد؟» قال: أشهد بتصديقك، فجعل النبي صلى الله عليه وسلم شهادة خزيمة شهادة رجلين \" فاحتجوا بهذا الحديث أن النبي صلى الله عليه وسلم ابتاع بغير إشهاد، فأما ما احتج به محمد بن جرير فصحيح غير أن ثم وجها يخرج منه لم يذكره وهو: أن علي بن أبي طلحة روى عن، ابن عباس، في قوله تعالى {ما ننسخ من آية أو ننسها} [البقرة: 106] قال ننسها نتركها، هكذا يقول المحدثون والصواب نتركها قال أبو جعفر: وفي هذا معنى لطيف شرحه سهل بن محمد على مذهب ابن عباس وبين معنى ذلك قال ننسخها نزيل حكمها بآية غيرها و {ننسها} [البقرة: 106] نزيل حكمها بأن نطلق لكم تركها كما قال تعالى: {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا ولا يسرقن ولا يزنين} [الممتحنة: 12] الآية ثم أطلق للمسلمين ترك ذلك من","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:178","bookId":"nasikh-nahhas","type":"section","seq":178,"chapter":"ص: 48","title":"ص: 271","page":"ج1 ص267","text":"غير آية نسختها، فكذا {إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] وكذا {وأشهدوا إذا تبايعتم} [البقرة: 282] قال أبو جعفر: فأما النسخ فكما قال محمد بن جرير، وأما الندب فلا يحمل عليه الأمر إلا بدليل قاطع وأما قول مجاهد: لا يجوز الرهن إلا في السفر لأنه في الآية كذلك، فقول شاذ، الجماعة على خلافه\nقال أبو جعفر وقرئ على أحمد بن شعيب، عن يوسف بن حماد، قال: حدثنا سفيان بن حبيب، عن هشام، عن عكرمة، عن ابن عباس، قال «توفي رسول الله صلى الله عليه وسلم ودرعه مرهونة عند يهودي بثلاثين صاعا من شعير لأهله» قال أبو جعفر: وليس كون الرهن في الآية في السفر مما يحظر غيره وأما {إذا تداينتم بدين} [البقرة: 282] والفائدة في {بدين} [البقرة: 282] وقد تقدم","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:179","bookId":"nasikh-nahhas","type":"section","seq":179,"chapter":"ص: 48","title":"ص: 272","page":"ج1 ص269","text":"{تداينتم} [البقرة: 282] فالجواب عنه أن العرب تقول تداينا أي تجازينا وتعاطينا الأخذ بيننا فأبان الله جل وعز بقوله {بدين} [البقرة: 282] المعنى الذي قصد له واختلف العلماء في الآية التي هي تتمة ثلاثين آية من هذه السورة فمنهم من قال: هي منسوخة ومنهم من قال: هي محكمة عامة ومنهم من قال: هي محكمة خاصة","bab":"باب ذكر الآية التاسعة والعشرين قال جل وعز: {يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه} [البقرة: 282] الآية فافترق العلماء فيها على ثلاثة أقوال ف"},{"id":"nasikh-nahhas:180","bookId":"nasikh-nahhas","type":"section","seq":180,"chapter":"ص: 48","title":"باب ذكر الآية التي هي تتمة ثلاثين آية قال جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] الآية فعن ابن عباس فيها ثلا","page":"ج1 ص271","text":"أنها غير منسوخة وأنها عامة يحاسب المؤمن والكافر والمنافق بما أبدى وأخفى فيغفر للمؤمنين ويعاقب الكافرون والمنافقون والثالث: أنها مخصوصة وأنها في كتمان الشهادة وإظهارها كذا روى يزيد بن أبي زياد عن مقسم عن ابن عباس فأما الرواية عن، عائشة، فإنها قالت «ما هم به العبد من خطيئة عوقب على ذلك بما يلحقه من الهم والحزن في الدنيا» فهذه أربعة أقوال\nوقرئ على أحمد بن محمد بن الحجاج عن يحيى بن سليمان، قال: حدثنا إسماعيل ابن علية، قال: حدثنا ابن أبي نجيح، عن مجاهد، في قول الله تعالى {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] فقال: «هذا في الشك واليقين» وهذه الأقوال الخمسة يقرب بعضها من بعض فقول مجاهد في الشك واليقين قريب من قول ابن عباس إنها لم تنسخ وإنها عامة، وقول ابن عباس الذي رواه عنه مقسم إنها في الشهادة يصح على أن غير الشهادة بمنزلتها وقول عائشة إنها ما يلحق الإنسان في الدنيا على أن تكون عامة أيضا فأما أن تكون منسوخة فيصح من جهة ويبطل من جهة فأما الجهة التي تبطل منها فإن الأخبار لا يكون فيها ناسخ ولا منسوخ ومن زعم أن في الأخبار ناسخا ومنسوخا فقد ألحد أو جهل فأخبر الله تعالى أنه يحاسب من أبدى شيئا أو أخفاه فمحال أن يخبر بضده وأيضا فإن الحكم","bab":"باب ذكر الآية التي هي تتمة ثلاثين آية قال جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] الآية فعن ابن عباس فيها ثلاثة أقوال: إحداهن: أن"},{"id":"nasikh-nahhas:181","bookId":"nasikh-nahhas","type":"section","seq":181,"chapter":"ص: 48","title":"ص: 275","page":"ج1 ص273","text":"إذا كان منسوخا فإنما ينسخ بنفيه وبآخر ناسخ له ناف له من كل جهاته فلو كان {لا يكلف الله نفسا إلا وسعها} [البقرة: 286] ناسخا لنسخ تكليف ما لا طاقة به وهذا منفي عن الله عز وجل أن يتعبد به كما قال تعالى {لا يكلف الله نفسا إلا ما آتاها} [الطلاق: 7] وصح عن النبي صلى الله عليه وسلم، أنه كان يلقن أصحابه إذا بايعوا «فيما استطعتم» فأما الوجه الذي يصح منه وهو الذي ينبغي أن يتبين ويوقف عليه لأن المعاند ربما عارض بقول الصحابة والتابعين في أشياء من الأخبار ناسخة ومنسوخة فالجاهل باللغة إما أن يحير فيها وإما أن يلحد فيقول في الأخبار ناسخ ومنسوخ وهو يعلم أن الإنسان إذا قال قام فلان ثم نسخ هذا فقال لم يقم فقد كذب وفي حديث ابن عباس تبيين ما أراد\nكما حدثنا محمد بن جعفر الأنباري، قال: حدثنا صالح بن زياد الرقي، قال: حدثنا يزيد، قال","bab":"باب ذكر الآية التي هي تتمة ثلاثين آية قال جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] الآية فعن ابن عباس فيها ثلاثة أقوال: إحداهن: أن"},{"id":"nasikh-nahhas:182","bookId":"nasikh-nahhas","type":"section","seq":182,"chapter":"ص: 48","title":"ص: 276","page":"ج1 ص274","text":": أخبرنا سفيان بن حسين، عن الزهري، عن سالم، أن عبد الله بن عمر، تلا {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] فدمعت عيناه فبلغ صنيعه ابن عباس فقال: \" يرحم الله أبا عبد الرحمن صنع كما صنع أصحاب محمد صلى الله عليه وسلم حين أنزلت ونسختها الآية التي بعدها {لا يكلف الله نفسا إلا وسعها لها ما كسبت وعليها ما اكتسبت} [البقرة: 286] معنى نسختها نزلت بنسختها سواء وليس هذا من الناسخ والمنسوخ في شيء \"\nقرئ على عبد الله بن الصقر بن نصر، عن زياد بن أيوب، قال: أخبرنا هشيم، قال: أخبرنا شيبان، عن الشعبي، قال: لما نزلت {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] لحقتهم منها شدة حتى نسخها ما بعدها \" وفي هذا معنى لطيف وهو أن يكون معنى نسختها نسخت الشدة التي لحقتهم أي أزالتها كما يقال نسخت الشمس الظل أي أزالته ومن حسن ما قيل في الآية وأشبهه بالظاهر قول ابن عباس إنها عامة يدلك على ذلك\nما حدثناه أحمد بن علي بن سهل، قال: حدثنا","bab":"باب ذكر الآية التي هي تتمة ثلاثين آية قال جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] الآية فعن ابن عباس فيها ثلاثة أقوال: إحداهن: أن"},{"id":"nasikh-nahhas:183","bookId":"nasikh-nahhas","type":"section","seq":183,"chapter":"ص: 48","title":"ص: 277","page":"ج1 ص276","text":"زهير وهو ابن حرب، قال: أخبرنا إسماعيل وهو ابن علية عن هشام وهو الدستوائي، عن قتادة، عن صفوان بن محرز، قال: قال رجل لابن عمر: كيف سمعت رسول الله صلى الله عليه وسلم يقول في النجوى؟ قال: سمعته يقول: \" يدني المؤمن من ربه تعالى حتى يضع عليه كنفه فيقرره بذنوبه فيقول: هل تعرف؟ فيقول: رب أعرف، قال: فإني سترتها عليك في الدنيا وإني أغفرها لك اليوم، فيعطى صحيفة حسناته، فأما الكفار والمنافقون فينادى بهم على رءوس الخلائق هؤلاء الذين كذبوا على الله جل وعز \" ففي هذا الحديث حقيقة معنى الآية وأنه لا نسخ فيها وإسناده إسناد لا يدخل القلب منه لبس وهو من أحاديث أهل السنة والجماعة","bab":"باب ذكر الآية التي هي تتمة ثلاثين آية قال جل وعز {وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله} [البقرة: 284] الآية فعن ابن عباس فيها ثلاثة أقوال: إحداهن: أن"},{"id":"nasikh-nahhas:184","bookId":"nasikh-nahhas","type":"section","seq":184,"chapter":"ص: 48","title":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {قال آيتك ألا تكلم الناس ثلاثة أيام إلا رمزا} [آل عمران: 41] فزعم بعض أهل العلم أن هذا منسوخ","page":"ج1 ص279","text":"كما قرئ على أحمد بن حماد، عن سعيد بن أبي مريم، قال: أخبرنا عبد العزيز الدراوردي، قال: أخبرنا حرام بن","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {قال آيتك ألا تكلم الناس ثلاثة أيام إلا رمزا} [آل عمران: 41] فزعم بعض أهل العلم أن هذا منسوخ وذلك أن هذه شريعة قد"},{"id":"nasikh-nahhas:185","bookId":"nasikh-nahhas","type":"section","seq":185,"chapter":"ص: 48","title":"ص: 280","page":"ج1 ص279","text":"عثمان، عن عبد الرحمن، ومحمد ابني جابر بن عبد الله، عن أبيهما، قال: قال رسول الله صلى الله عليه وسلم «لا صمت يوما إلى الليل» قال فنسخ إباحة الصمت وقد قال تعالى إخبارا عن مريم {فلن أكلم اليوم إنسيا} [مريم: 26] ليس في هذا ناسخ ولا منسوخ لأن الحديث عن النبي صلى الله عليه وسلم \" لا صمت يوما أنه لا يحل لأحد أن يصمت يوما إلى الليل فلا يذكر الله جل وعز ولا يسبح وهذا محظور في كل شريعة والدليل على هذا أن بعد قوله جل وعز {ألا تكلم الناس ثلاثة أيام إلا رمزا} [آل عمران: 41] الأمر بالتسبيح عشيا وبكرا وزعم بعض العلماء أن الآية الثانية منسوخة وقال بعضهم هي محكمة","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {قال آيتك ألا تكلم الناس ثلاثة أيام إلا رمزا} [آل عمران: 41] فزعم بعض أهل العلم أن هذا منسوخ وذلك أن هذه شريعة قد"},{"id":"nasikh-nahhas:186","bookId":"nasikh-nahhas","type":"section","seq":186,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] فمن أجل ما روي في تفسيرها وأصحه","page":"ج1 ص279","text":"ما حدثناه علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا عمرو بن الهيثم، قال: حدثنا المسعودي، عن زبيد، عن مرة، عن عبد الله بن مسعود، في قول الله جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] قال: «أن يطاع فلا يعصى ويذكر فلا ينسى وأن يشكر فلا يكفر»\nوحدثنا محمد بن جعفر بن محمد الأنباري، قال","bab":"باب ذكر الآية الثانية قال جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] فمن أجل ما روي في تفسيرها وأصحه"},{"id":"nasikh-nahhas:187","bookId":"nasikh-nahhas","type":"section","seq":187,"chapter":"ص: 48","title":"ص: 282","page":"ج1 ص281","text":": حدثنا موسى بن هارون الطوسي، قال: حدثنا الحسين وهو ابن محمد المروزي، قال: أخبرنا شيبان، عن قتادة، في قوله تعالى: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] قال: «أن يطاع فلا يعصى ثم أنزل جل وعز التخفيف فاتقوا الله ما استطعتم فنسخت هذه التي في آل عمران» قال أبو جعفر: محال أن يقع في هذا ناسخ ولا منسوخ إلا على حيلة وذلك أن معنى نسخ الشيء إزالته والمجيء بضده، فمحال أن يقال اتقوا الله منسوخ ولا سيما مع قول الرسول صلى الله عليه وسلم مما فيه بيان الآية\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا أبو الأحوص، قال: حدثنا أبو إسحاق، عن عمرو بن","bab":"باب ذكر الآية الثانية قال جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] فمن أجل ما روي في تفسيرها وأصحه"},{"id":"nasikh-nahhas:188","bookId":"nasikh-nahhas","type":"section","seq":188,"chapter":"ص: 48","title":"ص: 283","page":"ج1 ص281","text":"ميمون، عن معاذ بن جبل، قال: قال لي رسول الله صلى الله عليه وسلم: \" يا معاذ أتدري ما حق الله جل وعز على العباد؟ قلت: الله ورسوله أعلم قال: «أن يعبدوه فلا يشركوا به شيئا» أفلا ترى أنه محال أن يقع في هذا نسخ؟ والذي قلناه قول ابن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] قال: «لم تنسخ ولكن حق تقاته أن تجاهدوا في الله حق جهاده ولا تأخذكم في الله لومة لائم وتقوموا بالقسط ولو على آبائكم وأبنائكم» قال أبو جعفر: فكل ما ذكر في الآية واجب على المسلمين أن يستعملوه ولا يقع فيه نسخ وهو قول النبي صلى الله عليه وسلم أن يعبدوا الله ولا يشركوا به شيئا وكذا على المسلمين كما قال ابن مسعود «أن يطيعوا الله فلا يعصوه ويذكروه فلا ينسوه وأن يشكروه فلا يكفروه وأن يجاهدوا فيه حق جهاده»","bab":"باب ذكر الآية الثانية قال جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] فمن أجل ما روي في تفسيرها وأصحه"},{"id":"nasikh-nahhas:189","bookId":"nasikh-nahhas","type":"section","seq":189,"chapter":"ص: 48","title":"ص: 284","page":"ج1 ص282","text":"فأما قول قتادة مع محله من العلم إنها نسخت فيجوز أن يكون معناه نزلت فاتقوا الله ما استطعتم بنسخة {اتقوا الله حق تقاته} [آل عمران: 102] وأنها مثلها لأنه لا يكلف أحدا إلا طاقته وزعم قوم من العلماء الكوفيين أن الآية الثالثة ناسخة وقال غيرهم هي محكمة وليست بناسخة","bab":"باب ذكر الآية الثانية قال جل وعز: {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] فمن أجل ما روي في تفسيرها وأصحه"},{"id":"nasikh-nahhas:190","bookId":"nasikh-nahhas","type":"section","seq":190,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية","page":"ج1 ص283","text":"حدثناه أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن الزهري، عن سالم، عن ابن عمر، \" أن النبي صلى الله عليه وسلم لعن في صلاة الفجر بعد الركوع في الركعة الآخرة فقال: اللهم العن فلانا وفلانا «ناسا من المنافقين» فأنزل الله عز وجل {ليس لك من الأمر شيء أو يتوب عليهم} [آل عمران: 128] الآية قال أبو جعفر: فهذا إسناد مستقيم وليس فيه دليل على ناسخ ولا منسوخ وإنما نبهه الله جل وعز على أن الأمر إليه ولو كان هذا ناسخا لما جاز أن يلعن المنافقون\nواحتج أيضا بما حدثناه علي بن الحسين، عن الحسن بن محمد، قال: حدثنا شبابة، قال: أخبرنا إبراهيم بن سعد، عن الزهري، عن أبي سلمة، وابن المسيب، عن أبي هريرة، قال: «كان رسول الله صلى الله عليه وسلم إذا أراد أن يدعو لأحد أو يدعو على أحد قنت بعد الركوع فربما قال إذا قال سمع الله لمن","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:191","bookId":"nasikh-nahhas","type":"section","seq":191,"chapter":"ص: 48","title":"ص: 286","page":"ج1 ص285","text":"حمده ربنا ولك الحمد اللهم أنج الوليد بن الوليد وسلمة بن هشام، وعياش بن أبي ربيعة والمستضعفين من المؤمنين اللهم اشدد وطأتك على مضر واجعلها سنين كسني يوسف» حتى أنزلت {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128]","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:192","bookId":"nasikh-nahhas","type":"section","seq":192,"chapter":"ص: 48","title":"ص: 287","page":"ج1 ص285","text":"وهذا أيضا نظير الحديث الأول وفيه حجة على الكوفيين لأنهم يقولون لا يجوز أن يدعى في الصلاة إلا بما كان في القرآن أو ما أشبهه وليس في القرآن من هذا شيء؛ ولذلك عارض هذا المحتج بأن جعله في الناسخ والمنسوخ بلا حجة قاطعة ولا دليل واضح لما صح عن النبي صلى الله عليه وسلم الدعاء في الصلاة بغير ما في القرآن وعن الصحابة والتابعين وأيضا فإن العرب إنما كانت تعرف الصلاة في كلامها الدعاء كما قال\n[البحر البسيط]\nتقول بنتي وقد قربت مرتحلا ... يا رب جنب أبي الأوصاب والوجعا\nعليك مثل الذي صليت فاغتمضي ... نوما فإن لجنب المرء مضطجعا\nفسميت الصلاة صلاة لأن الدعاء فيها وهذا قول المدنيين إن للإنسان أن يدعو في صلاته بما شاء من الطاعة وعلى أنه قد روي مما صح سنده في نزول الآية غير هذا من ذلك\nما حدثناه علي بن الحسين، عن الحسن بن محمد، قال: حدثنا يزيد بن هارون، قال: أخبرنا حميد الطويل، عن أنس بن مالك، قال: \" شج النبي صلى الله عليه وسلم في وجهه وكسرت رباعيته ورمي رمية على كتفه فجعل يمسح الدم عن وجهه ويقول: كيف تفلح أمة فعلوا هذا بنبيهم \" فأنزل الله تبارك وتعالى {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128]","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:193","bookId":"nasikh-nahhas","type":"section","seq":193,"chapter":"ص: 48","title":"ص: 288","page":"ج1 ص285","text":"\" وهذا الحديث ليس بناقض لما تقدم يكون الأمران جميعا كانا فنزلت الآية\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثني يونس بن بكير، عن محمد بن إسحاق، قال حدثني يعقوب بن عتبة، عن سالم بن عبد الله بن عمر، قال: \" جاء رجل من قريش إلى النبي صلى الله عليه وسلم فقال: إنك تنهى عن السبي تقول قد سبي العرب ثم تحول فحول قفاه إلى النبي صلى الله عليه وسلم وكشف استه في وجه النبي صلى الله عليه وسلم فلعنه ودعا عليه \" فأنزل الله جل وعز {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] ثم أسلم الرجل فحسن إسلامه\nوهذا الحديث وإن كان منقطعا فإنما ذكرناه لأن سالما هو الذي وصله عن أبيه وفي هذا زيادة أن الرجل أسلم فعلم أن النبي صلى الله عليه وسلم نبه على أنه لا يعلم من الغيب شيئا وأن الأمر كله لله جل وعز يتوب على من يشاء ويعجل العقوبة لمن يشاء والتقدير ليس لك من الأمر شيء ولله ما في السموات وما في الأرض دونك ودونهم يغفر لمن يشاء ويتوب على من يشاء ويعذب من يشاء فتبين بهذا كله أن لا ناسخ ولا منسوخ في هذا\nأخبرنا أبو جعفر، قال: حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن الزهري، وعن عثمان الجزري، عن مقسم، قال دعا رسول الله صلى الله عليه وسلم على عتبة بن أبي وقاص حين كسر رباعيته ودمي وجهه فقال: «اللهم لا يبلغ الحول حتى يموت كافرا» قال فما بلغ الحول حتى مات كافرا إلى النار","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:194","bookId":"nasikh-nahhas","type":"section","seq":194,"chapter":"ص: 48","title":"سورة النساء قال جل وعز: {وإن خفتم ألا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فإن خفتم ألا تعدلوا فواحدة أو ما ملكت","page":"ج1 ص289","text":"من الفقهاء ناسخة وذلك أن الناس كانوا في الجاهلية وبرهة من الإسلام يتزوج الرجل ما شاء من الحرائر فنسخ الله جل وعز ذلك بالقرآن والسنة والعمل وأنه لا يحل لأحد أن يتزوج فوق أربع ونسخ ما كانوا عليه قال الحسن والضحاك كان الرجل يسلم وعنده عشرة نسوة منهن من قد تزوجه في الجاهلية ومنهن من قد تزوجه في الإسلام أو أكثر أو أقل حتى سألوا النبي صلى الله عليه وسلم عن اليتامى فنزلت {وإن خفتم ألا تقسطوا في اليتامى} [النساء: 3] أي تعدلوا {فانكحوا ما طاب لكم من النساء} [النساء: 3] أي فكما خفتم في اليتامى فخافوا في نكاح النساء قال محمد بن الحسن في رجل أسلم وعنده عشر نسوة قال: يخلي منهن ستا ويمسك أربعا من اللواتي تزوج بدءا فبدءا وليس له أن يختار منهن أربعا فإن احتج بالحديث عن النبي صلى الله عليه وسلم أنه خير غيلان فقال: «اختر أربعا» قيل للمحتج بهذا إن غيلان تزوج عشرا وذلك مباح فكان\nالعشر مباحات فلما رفع ذلك قيل له اختر قال أبو جعفر: وهذا كلام لطيف حسن غير أن مالكا والشافعي وأبا حنيفة يخيرونه على ظاهر الحديث ولم يزل المسلمون من لدن رسول الله صلى الله عليه وسلم إلى هذا الوقت يحرمون ما فوق الأربع بالقرآن والسنة\nقرئ على أحمد بن شعيب عن الحسين بن حريث، قال: أخبرنا","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:195","bookId":"nasikh-nahhas","type":"section","seq":195,"chapter":"ص: 48","title":"ص: 293","page":"ج1 ص292","text":"الفضل بن موسى، قال: أخبرنا معمر، عن الزهري، عن سالم، عن ابن عمر، قال: أسلم غيلان بن سلمة وعنده عشر نسوة فقال له رسول الله صلى الله عليه وسلم «أمسك أربعا وفارق سائرهن»\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا عبد الرحمن بن زياد، عن أبي جعفر الرازي، عن محمد بن السائب، عن حميضة بن الشمردل، عن قيس بن الحارث، قال: أسلمت وكان تحتي في الجاهلية ثماني نسوة فأتيت رسول الله صلى الله عليه وسلم فأخبرته فقال: «اختر منهن أربعا وخل سائرهن» ففعلت قال أبو جعفر: ومعنى مثنى في اللغة اثنتين اثنتين وثلاث ثلاثا","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:196","bookId":"nasikh-nahhas","type":"section","seq":196,"chapter":"ص: 48","title":"ص: 294","page":"ج1 ص292","text":"ثلاثا هذا قول الخليل، وسيبويه، والكسائي، وغيرهم ولهذا لم يصرف، وقيل معدول وليس معناه اثنتين فقط فيعارض معارض بأن يقول اثنتان وثلاث وأربع تسع وأيضا فليس من كلام الفصحاء اشتر اثنتين وثلاثا وأربعا وأيضا فلو كان معناه تسعا لكان المعنى انكحوا تسعا أو واحدة وكان محظورا ما بين ذينك قال أبو جعفر: وهذه احتجاجات قاطعة وإن كان في توقيف الرسول صلى الله عليه وسلم كفاية مع الإجماع من الذين لا يجتمعون على غلط ولا خطأ واختلف العلماء في الآية الثانية فمنهم من قال: هي منسوخة ومنهم من قال: هي محكمة","bab":"باب ذكر الآية الثالثة قال جل وعز: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] فزعم بعض الكوفيين أن هذه الآية ناسخة للقنوت الذي كا"},{"id":"nasikh-nahhas:197","bookId":"nasikh-nahhas","type":"section","seq":197,"chapter":"ص: 48","title":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النسا","page":"ج1 ص293","text":"بقوله جل وعز {يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم} [النساء: 29] وقال أبو يوسف: لا يحل له أن يأخذ من مال اليتيم شيئا إذا كان مقيما معه في المصر فإن احتاج أن يسافر من أجله فله أن يأخذ ما يحتاج إليه ولا يقتني شيئا وهو قول أبي حنيفة ومحمد\nوحدثنا أبو جعفر قال حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا إبراهيم بن عبد الله، قال: حدثنا حجاج، عن ابن جريج، عن عطاء الخراساني، عن ابن عباس، {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] ، قال نسخ: الظلم والاعتداء ونسختها {إن الذين يأكلون أموال اليتامى ظلما إنما يأكلون في بطونهم نارا وسيصلون سعيرا} [النساء: 10]","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:198","bookId":"nasikh-nahhas","type":"section","seq":198,"chapter":"ص: 48","title":"ص: 296","page":"ج1 ص295","text":"\" ثم افترق الذين قالوا إن الآية محكمة فرقا فقال بعضهم إن احتاج الوصي فله أن يقترض من مال اليتيم فإذا أيسر قضاه وهذا قول عمر بن الخطاب رضي الله عنه وعبيدة، وأبي العالية، وسعيد بن جبير واستشهد عبيدة وأبو العالية بأن بعده {فإذا دفعتم إليهم أموالهم فأشهدوا عليهم} [النساء: 6]\nكما قرئ على الحسن بن غليب بن سعيد، عن يوسف بن عدي، قال: حدثنا أبو الأحوص، قال: حدثنا أبو إسحاق، عن يرفأ مولى عمر بن الخطاب قال: قال لي عمر بن الخطاب رضي الله عنه: «يا يرفأ إني أنزلت مال الله مني بمنزلة مال اليتيم، إن احتجت أخذت منه، فإذا أيسرت قضيته، وإني إن استغنيت استعففت، فإني قد وليت من أمر المسلمين أمرا عظيما»","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:199","bookId":"nasikh-nahhas","type":"section","seq":199,"chapter":"ص: 48","title":"ص: 297","page":"ج1 ص295","text":"قال أبو جعفر: وهذا قول جماعة من التابعين وغيرهم منهم عبيدة قال: لا يحل للوصي أن يأخذ من مال اليتيم إلا قرضا واستشهد بأن بعد هذا {فإذا دفعتم إليهم أموالهم فأشهدوا عليهم} [النساء: 6] وكذا قال أبو العالية، ومجاهد\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح بن عبادة، قال: أخبرنا ابن عيينة، قال: حدثنا ابن أبي نجيح، عن مجاهد، قال: «يستلف والي اليتيم من ماله فإذا أيسر رده»\nقال روح وحدثنا شعبة، عن حماد، عن سعيد، {ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] قال: «قرضا» ، وفقهاء الكوفيين على هذا القول وقال أبو قلابة: فليأكل بالمعروف مما يجني من الغلة فأما المال الناض فليس له أن يأخذ منه شيئا قرضا ولا غيره وذهب جماعة من العلماء إلى ظاهر الآية فقالوا: له أن يأخذ منه مقدار قوته منهم الحسن\nكما قرئ على عبد الله بن أحمد بن عبد السلام عن أبي الأزهر، قال: حدثنا روح، عن أشعث، عن الحسن، قال","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:200","bookId":"nasikh-nahhas","type":"section","seq":200,"chapter":"ص: 48","title":"ص: 298","page":"ج1 ص297","text":": «إذا احتاج ولي اليتيم أكل بالمعروف وليس عليه إذا أيسر قضاؤه والمعروف قوته» قال أبو جعفر: وهذا قول قتادة والنخعي\nكما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا الثوري، عن مغيرة، عن إبراهيم، في قوله جل وعز: {ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] قال: «ما سد الجوعة ووارى العورة وليس يلبس الكتان ولا الحلل» واختلف عن ابن عباس في تفسير الآية اختلافا كثيرا على أن الأسانيد عنه صحاح مع اختلاف المتون فمن ذلك أنه\nقرئ على عبد الله بن أحمد بن عبد السلام عن أحمد بن الأزهر، قال: حدثنا روح، قال: حدثنا شعبة، ومالك بن أنس، عن يحيى بن سعيد، عن القاسم بن محمد، قال جاء أعرابي إلى ابن عباس فقال: إن لي إبلا أفقر ظهورها وأحمل عليها ولي يتيم له إبل فما يحل لي منها؟ قال: إذا كنت تهنأ جرباها وتلوط حوضها وتنشد ضالتها وتسقي وردها فاحلبها غير ناهك لها في الحلب ولا مضر بنسلها \"\nقال أبو جعفر: وهذا إسناد صحيح غير أنه لو كان هذا على هذا التأويل وأن الوصي إنما يأخذ مقدار عمله كان الغني والفقير في ذلك واحدا وقد فرق الله جل وعز بينهما في الآية بعينها وروى، عكرمة، عن ابن عباس، \" {ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] قال إذا احتاج واضطر \" وقال الشعبي كذلك إذا كان منه بمنزلة الدم ولحم الخنزير أخذ فإذا وجد أوفى وهذا لا معنى له لأنه إذا اضطر هذا الاضطرار كان له أخذ ما يقيمه من مال يتيمه أو غيره من قريب أو بعيد وعن ابن عباس رواية ثالثة\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا قبيصة، قال: حدثنا سفيان، عن الأعمش، عن الحكم، عن مقسم، عن ابن عباس، في قول الله جل وعز {ومن كان غنيا فليستعفف} [النساء: 6] قال: \" بغناه ولا يأكل مال اليتيم {ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] قال يقوت على نفسه حتى لا يحتاج إلى مال اليتيم \"","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:201","bookId":"nasikh-nahhas","type":"section","seq":201,"chapter":"ص: 48","title":"ص: 300","page":"ج1 ص299","text":"قال أبو جعفر: وهذا من أحسن ما روي في تفسير الآية لأن أموال الناس محظورة لا يطلق منها شيء إلا بحجة قاطعة وقد تنازع العلماء معنى الآية واحتملت غير تأويل فعدلنا إلى هذا لما قلنا، وهو قول محكي معناه عن الشافعي وقد ذكرنا قول أهل الكوفة وأنهم يجعلونه على القرض فأما مذهب أهل المدينة أو بعضهم فما ذكرناه من قول الحسن واحتج لهم محتج بما روي عن النبي صلى الله عليه وسلم\nكما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا ابن عيينة، عن عمرو بن دينار، عن الحسن العرني، قال قال رجل للنبي صلى الله عليه وسلم: \" إن في حجري يتيما أفأضربه؟ قال: \" مما تضرب منه ولدك قال: أفأصيب من ماله قال: غير متأثل مالا ولا واق مالك بماله \"\nوقرئ على عبد الله بن أحمد بن عبد السلام النيسابوري، عن أبي الأزهر، قال: حدثنا روح، قال: حدثنا حسين المعلم، عن عمرو بن شعيب، عن أبيه، عن جده، قال: جاء رجل إلى النبي صلى الله عليه وسلم فقال: \" إني لا أجد شيئا أوليس لي شيء وليتيمي مال، قال: كل منه غير مسرف","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:202","bookId":"nasikh-nahhas","type":"section","seq":202,"chapter":"ص: 48","title":"ص: 301","page":"ج1 ص300","text":"ولا متأثل مالا \" قال: وأحسبه قال: ولا تفد مالك بماله قال أبو جعفر: والذين ذهبوا إلى هذا من أهل المدينة إنما يجيزون أخذ القوت وما لا يضر باليتيم والذي روي في ذلك عن النبي صلى الله عليه وسلم هو من أحاديث المشايخ وليس هو مما يقطع به في مثل هذا واختلف العلماء أيضا في الآية الثالثة من هذه السورة فقال بعضهم: هي منسوخة وقال بعضهم هي محكمة","bab":"باب ذكر الآية الثانية من هذه السورة قال جل وعز مخاطبا للأوصياء في أموال اليتامى {ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف} [النساء: 6] فمنع جماعة من "},{"id":"nasikh-nahhas:203","bookId":"nasikh-nahhas","type":"section","seq":203,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز: {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا} للعلماء فيها ثلاثة أق","page":"ج1 ص300","text":"روي عنه أنها منسوخة ابن عباس، وسعيد بن المسيب\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا سلمة بن الفضل، قال: حدثنا إسماعيل بن مسلم، عن حميد الأعرج، عن مجاهد، عن ابن عباس، في قوله تعالى: {وإذا حضر القسمة أولوا القربى واليتامى والمساكين فارزقوهم منه} [النساء: 8] قال: \" نسخها {يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين} [النساء: 11] \"\nوحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: أخبرنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، أن ابن المسيب، قال في قول الله جل وعز {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه} قال: «نسخها الميراث والوصية»","bab":"باب ذكر الآية الثالثة قال جل وعز: {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا} للعلماء فيها ثلاثة أقوال فمنهم من قال إنه"},{"id":"nasikh-nahhas:204","bookId":"nasikh-nahhas","type":"section","seq":204,"chapter":"ص: 48","title":"ص: 303","page":"ج1 ص302","text":"وقال بأنها منسوخة أبو مالك، وعكرمة، والضحاك وممن قال إنها محكمة وتؤول قوله على الندب عبيدة، وعروة، وسعيد بن جبير، ومجاهد، وعطاء، والحسن، والزهري، والشعبي، ويحيى بن يعمر وهو مروي عن ابن عباس\nقال أبو جعفر كما حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال حدثنا معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {وإذا حضر القسمة أولو القربى واليتامى والمساكين} قال: «أمر الله جل وعز المؤمنين عند قسمة مواريثهم أن يصلوا أرحامهم وأيتامهم ومساكينهم من الوصية فإن لم تكن وصية وصل لهم من الميراث» قال أبو جعفر: فهذا أحسن ما قيل في الآية أن تكون على الندب والترغيب في فعل الخير والشكر لله تعالى فأمر الله جل وعز الذين فرض لهم الميراث إذا حضروا القسمة وحضر معهم من لا يرث من الأقرباء واليتامى والمساكين أن يرزقوهم شكرا لله تعالى على ما فرض لهم","bab":"باب ذكر الآية الثالثة قال جل وعز: {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا} للعلماء فيها ثلاثة أقوال فمنهم من قال إنه"},{"id":"nasikh-nahhas:205","bookId":"nasikh-nahhas","type":"section","seq":205,"chapter":"ص: 48","title":"ص: 304","page":"ج1 ص302","text":"وقد زعم بعض أهل النظر أنه لا يجوز أن يكون هاهنا نسخ لأن الذي يقول إنها منسوخة لا يخلو أمره من إحدى جهتين إما أن تكون كانت ندبا ثم نسخت وهذا محال لأن الندب إلى الخير لا ينسخ لأن نسخه لا تفعلوا الخير وهذا محال أو تكون كانت واجبة فنسخت وهذا أيضا لا يكون لأن قائله يقول إنه كان إذا حضر أولو القربى واليتامى والمساكين أعطوهم ولم يعطوا العصبة فنسخ ذلك بالفرض وهذا لم يعرف قط في جاهلية ولا إسلام وأيضا فإن الآية إذا ثبتت فلا يقال فيها منسوخة إلا أن ينفى حكمها على أنه قد روي عن، ابن عباس، رواه عنه القاسم بن محمد أنه قال هذا مخاطبة للموصي نفسه وكذا قال ابن زيد قيل للموصي أوص لذوي القربى واليتامى والمساكين واستدل على هذا بأن بعده {وقولوا لهم قولا معروفا} [النساء: 5] أي إن لم توصوا لهم فقولوا لهم خيرا وهذا القول اختيار محمد بن جرير فأما القول الثالث وهو أن تكون محكمة واجبة\nكما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال","bab":"باب ذكر الآية الثالثة قال جل وعز: {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا} للعلماء فيها ثلاثة أقوال فمنهم من قال إنه"},{"id":"nasikh-nahhas:206","bookId":"nasikh-nahhas","type":"section","seq":206,"chapter":"ص: 48","title":"ص: 305","page":"ج1 ص303","text":"حدثنا عبد الرحمن بن مهدي، قال: حدثنا سفيان، عن ابن أبي نجيح، عن مجاهد، {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه} قال: «هي واجبة عند قسمة الميراث ما طابت به أنفسهم» قال أبو جعفر: فهذا مجاهد يقول بإيجابها بالإسناد الذي لا تدفع صحته وهذا خلاف ما روي عنه عن ابن عباس غير أن هذا الإسناد أصح\nأخبرنا أبو جعفر، قال حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: أخبرنا عبد الرزاق، قال: أخبرنا معمر، عن الحسن، والزهري، {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه} قالا: «هي محكمة ما طابت به أنفسهم عند أهل الميراث» وأكثر العلماء على هذا القول وقد بينا صحته والصحيح في الآية الرابعة والخامسة أنهما منسوختان","bab":"باب ذكر الآية الثالثة قال جل وعز: {وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا} للعلماء فيها ثلاثة أقوال فمنهم من قال إنه"},{"id":"nasikh-nahhas:207","bookId":"nasikh-nahhas","type":"section","seq":207,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوف","page":"ج1 ص305","text":"أخبرنا أبو جعفر، قال: حدثنا أحمد بن محمد بن نافع قال: حدثنا سلمة قال: حدثنا عبد الرزاق قال: أخبرنا معمر، عن قتادة، في قوله تعالى {فأمسكوهن في البيوت حتى يتوفاهن الموت} [النساء: 15] قال: نسختها الحدود \" وفي قوله جل وعز {واللذان يأتيانها منكم فآذوهما} [النساء: 16] قال نسختها الحدود قال أبو جعفر: وفي الآيتين ثلاثة أقوال للعلماء الذين اتفقوا على نسخهما فمنهم من قال كان حكم الزاني والزانية إذا زنيا وكانا ثيبين أو بكرين أن يحبس كل واحد منهما في بيت حتى يموت ثم نسخ هذا بالآية الأخرى وهي {واللذان يأتيانها منكم فآذوهما} [النساء: 16] فصار حكمهما أن يؤذيا بالسب والتعيير ثم نسخ ذلك فصار حكم البكر من الرجال والنساء إذا زنا أن يجلد مائة جلدة وينفى عاما وحكم الثيب من الرجال والنساء أن يجلد مائة ويرجم حتى يموت وهذا القول مذهب عكرمة وهو مروي عن الحسن","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:208","bookId":"nasikh-nahhas","type":"section","seq":208,"chapter":"ص: 48","title":"ص: 307","page":"ج1 ص306","text":"عن حطان بن عبد الله الرقاشي عن عبادة بن الصامت فهذا قول والقول الثاني إنه كان حكم الزاني والزانية الثيبين إذا زنيا أن يحبسا حتى يموتا وحكم البكرين أن يؤذيا وهذا قول قتادة وإليه كان يذهب محمد بن جرير واحتج بأن الآية الثانية {واللذان يأتيانها منكم} [النساء: 16] فدل هذا على أنه يراد الرجل والمرأة البكران قال: ولو كان لجميع الزناة لكان والذين كما أن الذي قبله واللاتي يأتين الفاحشة قال ولأن العرب لا توعد اثنين إلا أن يكونا شخصين مختلفين والقول الثالث أن يكون قوله تعالى: {واللاتي يأتين الفاحشة من نسائكم} [النساء: 15] عاما لكل من زنت من ثيب وبكر وأن يكون {واللذان يأتيانها منكم} [النساء: 16] عاما لكل من زنى من الرجال ثيبا كان أو بكرا","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:209","bookId":"nasikh-nahhas","type":"section","seq":209,"chapter":"ص: 48","title":"ص: 308","page":"ج1 ص306","text":"، وهذا قول مجاهد وهو مروي عن ابن عباس وهو أصح الأقوال لحجج بينة سنذكرها فأما قول من قال إن الآية الثانية ناسخة للأولى وإن كان يحتمل ذلك فالحديث عن رسول الله صلى الله عليه وسلم يدل على غير ذلك\nكما قرئ على علي بن سعيد بن بشير، عن عمرو بن رافع، قال: حدثنا هشيم، قال: أخبرنا منصور، عن الحسن، عن حطان بن عبد الله الرقاشي، عن عبادة بن الصامت، عن، رسول الله صلى الله عليه وسلم قال: «خذوا عني قد جعل الله لهن سبيلا البكر بالبكر جلد مائة ونفي سنة، والثيب بالثيب جلد مائة والرجم» فتبين بقول رسول الله صلى الله عليه وسلم قد جعل الله لهن سبيلا أن الآية لم تنسخ قبل هذا قال أبو جعفر: وهذا الحديث أصل من أصول الفقه وإن كان قد تؤول فيه شيء سنذكره في موضعه\nومما يدل أيضا على ما قلنا إن أحمد بن محمد الأزدي حدثنا، قال: حدثنا أبو شريح محمد بن زكريا، وابن أبي مريم، قالا: حدثنا محمد بن يوسف، قال: حدثنا قيس بن الربيع، قال: حدثنا مسلم عن مجاهد عن ابن عباس في قوله تعالى {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت} [النساء: 15] قال: «فكانت المرأة إذا زنت حبست ماتت أو عاشت حتى نزلت في سورة النور {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة} ونزلت سورة الحدود فكان من عمل سوءا جلد وأرسل» قال أبو جعفر: ودل هذا على أن ابن عباس لم يكن يقول بنفي الزاني فأما القول الثاني الذي اختاره محمد بن جرير ففيه شيء وذلك أنه جعل {واللذان يأتيانها منكم} [النساء: 16] للرجل والمرأة وهذا إنما يجوز في العربية على مجاز ولا يحمل الشيء على مجاز ومعناه صحيح في الحقيقة والذي عارض به من قوله إن العرب لا توعد اثنين إلا أن يكونا شخصين مختلفين فهذا إن صح فهما شخصان مختلفان لأنه إذا كان واللذان للرجلين الثيبين والبكرين فهما مختلفان ومعارضته أنه لو كان هكذا لوجب أن يكون والذين لا يلزم لأن العرب تحمل على اللفظ وعلى المعنى كما قال جل وعز {وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما} [الحجرات: 9] ومثل هذا كثير","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:210","bookId":"nasikh-nahhas","type":"section","seq":210,"chapter":"ص: 48","title":"ص: 310","page":"ج1 ص308","text":"والقول الذي اخترناه هو قول ابن عباس\nحدثنا أبو جعفر قال: كما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: \" وقوله جل وعز {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم} [النساء: 15] وكانت المرأة إذا زنت تحبس في البيت حتى تموت ثم أنزل الله جل وعز بعد ذلك {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة} فإن كانا محصنين رجما فهذا السبيل الذي جعله الله جل وعز لهما \" قال وقوله: {واللذان يأتيانها منكم فآذوهما} [النساء: 16] كان الرجل إذا زنى أوذي بالتعيير وضرب النعال فأنزل الله عز وجل بعد هذا {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة} فإن كانا محصنين رجما في سنة رسول الله صلى الله عليه وسلم قال أبو جعفر: هذا نص كلام ابن عباس فتبين أن قوله جل وعز {واللاتي يأتين الفاحشة من نسائكم} [النساء: 15] عام لكل من زنى من النساء وأن قوله تعالى {واللذان يأتيانها منكم} [النساء: 16] عام لكل من زنى من الرجال ونسخ الله جل وعز الآيتين في كتابه وعلى لسان رسوله صلى الله عليه وسلم بحديث عبادة الذي ذكرناه","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:211","bookId":"nasikh-nahhas","type":"section","seq":211,"chapter":"ص: 48","title":"ص: 311","page":"ج1 ص309","text":"فمر بعض العلماء على استعمال حديث عبادة وأنه يجب على الزاني والزانية البكرين جلد مائة وتغريب عام وأنه يجب على الثيبين جلد مائة والرجم هذا قول علي بن أبي طالب رضي الله عنه لا اختلاف عنه في ذلك أنه جلد شراحة مائة ورجمها بعد ذلك وقال: جلدتها بكتاب الله سبحانه ورجمتها بسنة رسول الله صلى الله عليه وسلم وقال بهذا القول من الفقهاء الحسن بن صالح بن حي وهو قول الحسن بن أبي الحسن وإسحاق بن راهويه","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:212","bookId":"nasikh-nahhas","type":"section","seq":212,"chapter":"ص: 48","title":"ص: 312","page":"ج1 ص309","text":"والحجة فيه قول الله تعالى {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة} فثبت الجلد بالقرآن والرجم بالسنة ومع هذا فقول الرسول صلى الله عليه وسلم والثيب بالثيب جلد مائة والرجم وقال جماعة من العلماء بل على الثيب الرجم بلا جلد وهذا يروى عن عمر وهو قول الزهري والنخعي، ومالك والثوري، والأوزاعي، والشافعي، وأصحاب الرأي، وأحمد وأبي ثور فمنهم من احتج بأن الجلد منسوخ عن المحصن بالرجم ومنهم من قال آية الجلد مخصوصة ومنهم من قال حديث عبادة منسوخ منه الجلد الذي على الثيب واحتجوا بأحاديث سنذكر منها ما فيه كفاية\nفمنها ما قرئ على أحمد بن شعيب، عن محمد بن المثنى، قال: حدثنا محمد، قال: حدثنا شعبة، عن قتادة، عن يونس بن جبير، عن كثير بن الصلت، قال قال زيد بن ثابت سمعت رسول الله صلى الله عليه وسلم يقول: «الشيخ والشيخة إذا زنيا فارجموهما البتة»\nوقرئ على أحمد، عن قتيبة، قال: حدثنا أبو عوانة، عن سماك بن حرب، عن سعيد بن جبير، عن ابن عباس، قال: قال رسول الله صلى الله عليه وسلم لماعز بن مالك: \" أحق ما بلغني عنك؟ قال: ما بلغك عني؟ قال","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:213","bookId":"nasikh-nahhas","type":"section","seq":213,"chapter":"ص: 48","title":"ص: 313","page":"ج1 ص312","text":": «بلغني عنك أنك وقعت على جارية آل بني فلان» قال: نعم، فشهد أربع شهادات ثم أمر به فرجم \" قالوا فليس في هذين الحديثين ذكر الجلد مع الرجم، وكذا قوله صلى الله عليه وسلم: «اغد يا أنيس على امرأة هذا فإن اعترفت بالزنا فارجمها» ولم يذكر الجلد فدل هذا على نسخه وقال المخالف لهم: لا حجة لكم في هذه الأحاديث لأنه ليس في واحد منها أنه لم يجلد وقد ثبت الجلد بكتاب الله تعالى فليس يمتنع أن يسكت عنه لشهرته وقد تكلم العلماء منهم الشافعي في نظير هذا فقالوا قد يحفظ البعض ما لا يحفظ الكل وقد يروى بعض الحديث ويحذف بعضه واختلفوا في موضع آخر من أحكام الزنا فقال قوم في البكر يجلد وينفى وقال قوم يجلد ولا ينفى وقال قوم النفي إلى الإمام على حسب ما يرى فممن قال يجلد وينفى الخلفاء الراشدون المهديون أبو بكر، وعمر، وعثمان، وعلي وهو قول ابن عمر","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:214","bookId":"nasikh-nahhas","type":"section","seq":214,"chapter":"ص: 48","title":"ص: 314","page":"ج1 ص312","text":"، وقال به من الفقهاء عطاء، وطاوس، وسفيان، ومالك، وابن أبي ليلى والشافعي، وأحمد، وإسحاق، وأبو ثور وقال بترك النفي حماد بن أبي سليمان، وأبو حنيفة، ومحمد بن الحسن قال أبو جعفر: وحجة من قال بالنفي الحديث المسند بدءا ثم كثرة من قال به وجلالتهم\nكما قرئ على أحمد بن شعيب، عن قتيبة، قال: حدثنا ابن عيينة، عن الزهري، عن عبيد الله بن عبد الله، عن أبي هريرة، وزيد بن خالد، وشبل، قالوا: كنا عند النبي صلى الله عليه وسلم فقام رجل فقال: أنشدك بالله إلا قضيت بيننا بكتاب الله جل وعز فقام خصمه وكان أفقه منه فقال: صدق اقض بيننا بكتاب الله جل وعز وائذن لي أن أتكلم، قال: قل، قال: إن ابني كان عسيفا على هذا فزنى بامرأته فافتديت بمائة شاة وخادم كأنه أخبر أن على ابنه الرجم فافتدى منه بمائة شاة وخادم، قال رسول الله صلى الله عليه وسلم: «والذي نفسي بيده لأقضين بينكما بكتاب الله جل وعز أما مائة الشاة والخادم فرد عليك وعلى ابنك جلد مائة وتغريب عام اغد يا","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:215","bookId":"nasikh-nahhas","type":"section","seq":215,"chapter":"ص: 48","title":"ص: 315","page":"ج1 ص312","text":"أنيس على امرأة هذا فإن اعترفت بالزنا فارجمها» فغدا عليها فاعترفت بالزنا فرجمها قال أبو جعفر: فثبت التغريب بلفظ رسول الله صلى الله عليه وسلم فمن ادعى نسخه فعليه أن يأتي بالتوقيف بذلك فأما المعارضة بأن العبد لا ينفى بالزنا فغير لازمة وقد صح عن عبد الله بن عمر أنه ضرب أمته في الزنا ونفاها ولو وجب ألا ينفي الأمة والعبد لما وجب ذلك في الأحرار، وكان هذا مخرجا من الحديث وكذا القول في النساء على أن المزني قد حكى أن الأولى بقول الشافعي أن تنفى الأمة نصف سنة لقول الله جل وعز فعليهن نصف ما على المحصنات من العذاب ومن قال النفي إلى الإمام احتج بأن في حديث مالك عن الزهري عن عبيد الله عن أبي هريرة، وزيد بن خالد: أن رسول الله صلى الله عليه وسلم جلد وغرب وليس فيه كما في حديث ابن عيينة وفي الآية السادسة موضعان قد أدخلا في الناسخ والمنسوخ","bab":"باب ذكر الآية الرابعة والخامسة قال جل وعز: {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل ال"},{"id":"nasikh-nahhas:216","bookId":"nasikh-nahhas","type":"section","seq":216,"chapter":"ص: 48","title":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله ج","page":"ج1 ص314","text":"يذكر في الآية\nحدثنا أبو جعفر قال: كما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن أبي الزناد، عن الأعرج، عن أبي هريرة، أن رسول الله صلى الله عليه وسلم قال: «لا يجمع بين المرأة وعمتها ولا بين المرأة وخالتها»\nقال أبو جعفر قرئ على أحمد بن شعيب، عن إبراهيم بن الحسن، قال: حدثنا حجاج، عن ابن جريج، عن أبي الزبير، عن جابر، قال: «نهى رسول الله صلى الله عليه وسلم أن تنكح المرأة على عمتها أو على خالتها»","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:217","bookId":"nasikh-nahhas","type":"section","seq":217,"chapter":"ص: 48","title":"ص: 317","page":"ج1 ص316","text":"قال أبو جعفر: ولهذا الحديث طرق غير هذين الطريقين فاجتزأنا بهما لصحتهما واستقامة طريقهما\nقال حدثنا أحمد بن محمد الأزدي، قال: حدثنا عبيد الله بن محمد المؤدب، قال: حدثنا علي بن معبد بن شداد العبدي، قال: حدثنا مروان بن شجاع، عن خصيف، عن عكرمة، عن ابن عباس، أن رسول الله صلى الله عليه وسلم: «نهى أن يجمع بين العمة والخالة وبين الخالتين وبين العمتين» قال أبو جعفر: وقد أشكل هذا الحديث على بعض أهل العلم وتحير في معناه حتى حمله على ما يبعد أو لا يجوز فقال معنى بين العمتين على المجاز أي بين العمة وبنت أخيها فقيل لهما عمتان كما قيل سنة العمرين يعنون أبا بكر، وعمر رضي الله عنهما قال وبين الخالتين مثله على المجاز قال وفي الأول حذف أي بين العمة وبنت أخيها وهذا من التعسف الذي لا يكاد يسمع بمثله وفيه أيضا مع التعسف أنه يكون كلاما مكررا لغير فائدة لأنه إذا كان المعنى نهي أن يجمع بين العمة وبنت أخيها وبين العمتين يعني به العمة وبنت أخيها صار الكلام مكررا بغير فائدة وأيضا فلو كان كما قال: وجب أن يكون وبين الخالة وليس كذا الحديث لأن الحديث نهى أن يجمع بين العمة والخالة فالواجب على لفظ الحديث أنه نهى أن يجمع بين امرأتين إحداهما عمة الأخرى والأخرى خالة الأخرى وهذا يخرج على معنى صحيح يكون رجل وابنه تزوجا امرأة وابنتها تزوج الرجل البنت وتزوج الابن الأم فولد لكل واحد منهما ابنة من هاتين الزوجتين، فابنة الأب عمة ابنة","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:218","bookId":"nasikh-nahhas","type":"section","seq":218,"chapter":"ص: 48","title":"ص: 318","page":"ج1 ص316","text":"الابن وابنة الابن خالة ابنة الأب وأما الجمع بين الخالتين فهذا يوجب أن يكونا امرأتين كل واحدة منهما خالة صاحبتها وذلك أن يكون رجل تزوج ابنة رجل وتزوج الآخر ابنته فولد لكل واحد منهما ابنة فابنة كل واحد منهما خالة الأخرى وأما الجمع بين العمتين فيوجب ألا يجمع بين امرأتين كل واحدة منهما عمة الأخرى وذلك أن يتزوج رجل أم رجل ويتزوج الآخر أم الآخر فيولد لكل واحد منهما ابنة فابنة كل واحد منهما عمة الأخرى","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:219","bookId":"nasikh-nahhas","type":"section","seq":219,"chapter":"ص: 48","title":"ص: 319","page":"ج1 ص316","text":"فهذا مما حرمه الله سبحانه على لسان رسوله صلى الله عليه وسلم مما ليس في القرآن وقد قال الله جل وعز: {واذكرن ما يتلى في بيوتكن من آيات الله والحكمة} [الأحزاب: 34] فقيل الحكمة السنة ثم قاس الفقهاء على هذا فقالوا: كل امرأتين لو كانت إحداهما رجلا لم يجز أن يتزوج الأخرى لا يجوز الجمع بينهما، ثم حرم الله سبحانه على لسان رسوله صلى الله عليه وسلم مما ليس في الآية\nما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن عبد الله بن دينار، عن سليمان بن يسار، عن عروة بن الزبير، عن عائشة، أن رسول الله صلى الله عليه وسلم قال: «تحرم الرضاعة ما تحرم الولادة» ولهذا الحديث طرق اجتزأنا بهذا منها لأنه لا مطعن فيه وليس في القرآن إلا تحريم الأمهات والأخوات من الرضاعة فقط","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:220","bookId":"nasikh-nahhas","type":"section","seq":220,"chapter":"ص: 48","title":"ص: 320","page":"ج1 ص317","text":"ثم اختلف العلماء في الرضاع بعد الحولين فقال أكثرهم: لا رضاع بعد حولين فممن قال هذا أزواج رسول الله صلى الله عليه وسلم إلا عائشة وهو أحد قولي مالك، والقول الآخر عنه بعد الحولين بيسير نحو الشهر وقال أبو حنيفة بعد الحولين بستة أشهر وقال زفر بعد الحولين بسنة وقالت طائفة أخرى الرضاع للصغير والكبير بمعنى واحد فممن صح هذا عنه عائشة وأبو موسى الأشعري وقال به من الفقهاء الليث بن سعد وكان يفتي به قال","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:221","bookId":"nasikh-nahhas","type":"section","seq":221,"chapter":"ص: 48","title":"ص: 321","page":"ج1 ص317","text":"عبد الله بن صالح سألته امرأة تريد الحج وليس لها ذو محرم فقال امضي إلى امرأة رجل فترضعك فيكون زوجها أباك فتحجي معه والحجة لهذا القول أنه \"\nقرئ على أحمد بن شعيب، عن عبد الله بن محمد بن عبد الرحمن، قال: حدثنا ابن عيينة، قال سمعناه من عبد الرحمن بن القاسم بن محمد، عن أبيه، عن عائشة، قالت جاءت سهلة بنت سهيل إلى رسول الله صلى الله عليه وسلم فقالت: إني أرى في وجه أبي حذيفة علي إذا دخل سالم قال النبي صلى الله عليه وسلم: «فأرضعيه» قالت: كيف أرضعه وهو رجل كبير؟ قال: ألست أعلم أنه رجل؟ \" ثم جاءت بعد فقالت: والله يا رسول الله ما أرى في وجه أبي حذيفة بعد شيئا أكرهه \" قال أبو جعفر: واحتج من قال الرضاع في الحولين لا غير بقول الله جل وعز {والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة} [البقرة: 233] فعارضهم الآخرون فقالوا: ليس في هذا دليل على نفي ما بعد الحولين واحتج الآخرون أيضا بأن الحديث المسند إنما فيه إزالة كراهة فعارضهم الآخرون فقالوا: لم تزل عائشة رضي الله عنها تقوم برضاع","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:222","bookId":"nasikh-nahhas","type":"section","seq":222,"chapter":"ص: 48","title":"ص: 322","page":"ج1 ص319","text":"الكبير معروفا ذلك غير أن ربيعة بن أبي عبد الرحمن كان يقول: هذا الحديث مخصوص في سالم وحده وقال غيره: وهو منسوخ، واستدل على ذلك بأن مسروقا روى عن عائشة: كن عشر رضعات نزلن في الشيخ الكبير ثم نسخن وروى أيضا، مسروق عن عائشة، عن رسول الله صلى الله عليه وسلم أنه قال: «إنما الرضاعة من المجاعة» قال أهل اللغة معنى هذا إنما الرضاعة للصبي الذي إذا جاع أشبعه اللبن ونفعه من الجوع فأما الكبير فلا رضاعة له\nقرئ على أحمد بن شعيب، عن قتيبة، قال: حدثنا أبو عوانة، عن هشام بن عروة، عن فاطمة بنت المنذر، عن أم سلمة، عن، رسول الله صلى الله عليه وسلم أنه قال: «لا رضاع إلا ما فتق الأمعاء في الثدي وكان قبل الفطام»","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:223","bookId":"nasikh-nahhas","type":"section","seq":223,"chapter":"ص: 48","title":"ص: 323","page":"ج1 ص321","text":"وأما قوله تعالى: {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقد اختلف العلماء فيها بعد اجتماع من تقوم به","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:224","bookId":"nasikh-nahhas","type":"section","seq":224,"chapter":"ص: 48","title":"ص: 324","page":"ج1 ص321","text":"الحجة أن المتعة حرام بكتاب الله تعالى وسنة رسول الله صلى الله عليه وسلم وقول الخلفاء الراشدين المهديين وتوقيف علي بن أبي طالب ابن عباس وقوله له إنك رجل تائه وإن رسول الله صلى الله عليه وسلم قد حرم المتعة \" ولا اختلاف بين العلماء في صحة الإسناد عن علي بن أبي طالب واستقامة طريقه بروايته عن رسول الله صلى الله عليه وسلم تحريم المتعة وسنذكر","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:225","bookId":"nasikh-nahhas","type":"section","seq":225,"chapter":"ص: 48","title":"ص: 325","page":"ج1 ص321","text":"ذلك بإسناده في موضعه إن شاء الله فقال قوم فما استمتعتم به منهن فآتوهن أجورهن فريضة هو النكاح بعينه وما أحل الله جل وعز المتعة قط في كتابه فممن قال هذا من العلماء الحسن، ومجاهد\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا ابن أبي مريم، قال: حدثنا الفريابي، عن ورقاء، عن ابن أبي نجيح، عن مجاهد، {فما استمتعتم به منهن} [النساء: 24] قال: «النكاح»\nقال أبو جعفر حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: أخبرنا عبد الرزاق، قال: أخبرنا معمر، عن الحسن، {فما استمتعتم به منهن} [النساء: 24] قال: «النكاح» وكذا يروى عن ابن عباس قال أبو جعفر: وسنذكره بإسناده وشرحه وقال جماعة من العلماء: كانت المتعة حلالا ثم نسخ الله تعالى ذلك بالقرآن وممن قال هذا سعيد بن المسيب وهو يروي عن ابن عباس وعائشة وهو قول القاسم، وسالم وعروة\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا علي بن هاشم","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:226","bookId":"nasikh-nahhas","type":"section","seq":226,"chapter":"ص: 48","title":"ص: 326","page":"ج1 ص325","text":"، عن عثمان بن عطاء الخراساني، عن أبيه، عن ابن عباس، في قول الله تعالى: {فما استمتعتم به منهن فآتوهن أجورهن} [النساء: 24] قال: \" نسختها {يا أيها النبي إذا طلقتم النساء فطلقوهن لعدتهن} [الطلاق: 1] يقول: الطلاق للطهر الذي لم يجامعها فيه \"\nحدثنا أبو جعفر قال: قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا وكيع، عن سفيان، عن داود بن أبي هند، عن سعيد بن المسيب، قال: «نسخت المتعة آية الميراث يعني ولكم نصف ما ترك أزواجكم» قال أبو جعفر: وذلك أن المتعة لا ميراث فيها فلهذا قال بالنسخ وإنما المتعة أن يقول لها: أتزوجك يوما أو ما أشبهه على أنه لا عدة عليك ولا ميراث بيننا ولا طلاق ولا شاهد يشهد على ذلك وهذا هو الزنا بعينه ولذلك قال عمر رضي الله عنه: لا أوتى برجل تزوج متعة إلا غيبته تحت الحجارة\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن عبد الله بن بكير، قال: حدثني الليث، عن عقيل، عن ابن شهاب، قال: قال لي سالم بن عبد الله وهو يذاكرني: «يقولون بالمتعة هؤلاء فهل رأيت نكاحا لا","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:227","bookId":"nasikh-nahhas","type":"section","seq":227,"chapter":"ص: 48","title":"ص: 327","page":"ج1 ص326","text":"طلاق فيه ولا عدة له ولا ميراث فيه؟» قال: وقال لي القاسم بن محمد بن أبي بكر، \" كيف يجترئون على الفتيا بالمتعة وقد قال الله جل وعز: {والذين هم لفروجهم حافظون إلا على أزواجهم أو ما ملكت أيمانهم فإنهم غير ملومين فمن ابتغى وراء ذلك فأولئك هم العادون} [المؤمنون: 6] \" قال أبو جعفر: وهذا قول بين لأنه إذا لم تكن تطلق ولا تعتد ولا ترث فليست بزوجة وقال قوم من العلماء الناسخ للمتعة الحديث عن رسول الله صلى الله عليه وسلم\nكما قرئ على أحمد بن محمد الأزدي، عن إبراهيم بن أبي داود، قال: حدثنا عبد الله بن محمد بن أسماء، قال: حدثنا جويرية، عن مالك بن أنس، عن الزهري، أن عبد الله بن محمد بن علي بن أبي طالب، والحسن بن محمد، حدثاه، عن أبيهما، أنه سمع علي بن أبي طالب، رضي الله عنه يقول لابن","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:228","bookId":"nasikh-nahhas","type":"section","seq":228,"chapter":"ص: 48","title":"ص: 328","page":"ج1 ص326","text":"عباس إنك رجل تائه إن رسول الله صلى الله عليه وسلم: «نهى عن المتعة» قال أبو جعفر: ولهذا الحديث طرق فاجتزأنا بهذا لصحته ولجلالة جويرية بن أسماء ولأن ابن عباس لما خاطبه علي بن أبي طالب رضي الله عنه بهذا لم يحاججه فصار تحريم المتعة إجماعا لأن الذين يحلونها اعتمادهم على ابن عباس وقال قوم نسخت المتعة بالقرآن والسنة جميعا وهذا قول أبي عبيد وقد روى، الربيع بن سبرة، عن، أبيه، أن النبي صلى الله عليه وسلم «حرم المتعة يوم الفتح» فقد صح من الكتاب والسنة التحريم ولم يصح التحليل من الكتاب لما ذكرنا من قول من قال إن الاستمتاع النكاح على أن الربيع بن سبرة قد روى عن، أبيه، أن رسول الله صلى الله عليه وسلم قال لهم «استمتعوا من هذه النساء» قال: «والاستمتاع عندنا يومئذ التزوج»\nقال أبو جعفر","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:229","bookId":"nasikh-nahhas","type":"section","seq":229,"chapter":"ص: 48","title":"ص: 329","page":"ج1 ص327","text":"حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال: أخبرني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] يقول: \" إذا تزوج الرجل المرأة فنكحها مرة واحدة وجب لها الصداق كله والاستمتاع النكاح قال وهو قوله جل وعز: {وآتوا النساء صدقاتهن نحلة} [النساء: 4] \" فبين ابن عباس أن الاستمتاع هو النكاح بأحسن بيان، فالتقدير في العربية فما استمتعتم به ممن قد تزوجتموه بالنكاح مرة أو أكثر من ذلك فأعطوها الصداق كاملا إلا أن تهبه أو تهب منه وقيل التقدير فمن استمتعتم به، وما بمعنى من وقيل التقدير فما استمتعتم به من دخول بالمرأة فلها الصداق كاملا أو النصف إن لم يدخل بها قال أبو جعفر أما قوله {ولا جناح عليكم فيما تراضيتم به من بعد الفريضة} [النساء: 24] فتأوله قوم من الجهال المجترئين على كتاب الله جل وعز أن المتمتع إن أراد الزيادة بغير استبراء ورضيت بذلك زادته وزادها، وهذا الكذب على الله جل وعز قال أبو جعفر: ومن أصح ما قيل فيه أنه لا جناح على الزوج والمرأة أن يتراضيا بعدما انقطع بينهما من الصداق أن تهبه له أو تنقصه منه أو يزيدها فيه","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:230","bookId":"nasikh-nahhas","type":"section","seq":230,"chapter":"ص: 48","title":"ص: 330","page":"ج1 ص327","text":"، واختلف العلماء في الآية السابعة فمنهم من قال: هي منسوخة ومنهم من قال: هي ناسخة ومنهم من قال: هي محكمة غير ناسخة ولا منسوخة","bab":"باب ذكر الآية السادسة قال جل وعز: {وأحل لكم ما وراء ذلكم} [النساء: 24] وفيها {فما استمتعتم به منهن فآتوهن أجورهن فريضة} [النساء: 24] فقوله جل وعز: {وأحل لكم ما "},{"id":"nasikh-nahhas:231","bookId":"nasikh-nahhas","type":"section","seq":231,"chapter":"ص: 48","title":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا","page":"ج1 ص328","text":"ما حدثناه أحمد بن شعيب، قال أخبرني هارون بن عبد الله، قال: حدثنا أبو أسامة، قال حدثني إدريس بن يزيد، قال: حدثنا طلحة بن مصرف، عن سعيد بن جبير، عن ابن عباس، في قوله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] قال: \" كان المهاجرون حين قدموا المدينة تورث الأنصار دون رحمه للأخوة التي آخى النبي صلى الله عليه وسلم بينهم حتى نزلت الآية {ولكل جعلنا موالي مما ترك الوالدان والأقربون} [النساء: 33] قال: نسختها {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] قال من النصر والنصح والرفادة ويوصي له وهو لا يرث \"","bab":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا"},{"id":"nasikh-nahhas:232","bookId":"nasikh-nahhas","type":"section","seq":232,"chapter":"ص: 48","title":"ص: 332","page":"ج1 ص331","text":"قال أبو عبد الرحمن: إسناده صحيح قال أبو جعفر: فحمل هذا الحديث وأدخل في المسند على أن الآية ناسخة وليس الأمر عندي كذلك والذي يجب أن يحمل عليه الحديث أن يكون {ولكل جعلنا موالي} [النساء: 33] ناسخا لما كانوا يفعلونه وأن يكون {والذين عقدت أيمانكم} [النساء: 33] غير ناسخ ولا منسوخ ولكن فسره ابن عباس، وسنبين العلة في ذلك عند آخر هذا الباب ولكن ممن قال: الآية ناسخة سعيد بن المسيب\nكما حدثناه جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا داود بن رشيد، قال: حدثنا الوليد، قال: حدثنا مروان بن أبي الهذيل، سمع الزهري، يقول: أخبرني سعيد، في قول الله جل وعز {والذين عقدت أيمانكم} [النساء: 33] قال: \" الحلفاء في الجاهلية والذين كانوا يتبنون فكانوا يتوارثون على ذلك حتى نزلت {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فنزع الله جل وعز ميراثهم وأثبت لهم الوصية \" وقال الشعبي: كانوا يتوارثون حتى أزيل ذلك","bab":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا"},{"id":"nasikh-nahhas:233","bookId":"nasikh-nahhas","type":"section","seq":233,"chapter":"ص: 48","title":"ص: 333","page":"ج1 ص331","text":"وممن قال إنها منسوخة الحسن، وقتادة\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح، عن أشعث، عن الحسن، {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] قال: «كان الرجل يعاقد الرجل على أنهما إذا مات أحدهما ورثه الآخر فنسختها آية المواريث» وقال قتادة \" كان يقول ترثني وأرثك وتعقل عني وأعقل عنك فنسخها {وأولو الأرحام بعضهم أولى ببعض} [الأحزاب: 6] \" وقال الضحاك: «كانوا يتحالفون ويتعاقدون على النصرة والوراثة فإذا مات أحدهم قبل صاحبه كان له مثل نصيب ابنه فنسخ ذلك بالمواريث» ومثل هذا أيضا مروي عن ابن عباس مشروحا\nكما حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] \" كان الرجل يعاقد الرجل أيهما مات قبل صاحبه ورثه الآخر فأنزل الله جل وعز {وأولو الأرحام بعضهم أولى ببعض في كتاب الله من المؤمنين والمهاجرين إلا أن تفعلوا إلى أوليائكم معروفا} [الأحزاب: 6]","bab":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا"},{"id":"nasikh-nahhas:234","bookId":"nasikh-nahhas","type":"section","seq":234,"chapter":"ص: 48","title":"ص: 334","page":"ج1 ص333","text":"قال يقول: «يوصي له وصية فهي جائزة من ثلث مال الميت فذلك المعروف» وممن قال إنها محكمة مجاهد، وسعيد بن جبير\nكما قرئ على إبراهيم بن موسى الجوزي، عن يعقوب بن إبراهيم، قال: حدثنا وكيع، عن سفيان، عن منصور، عن مجاهد، في قوله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] قال: «من العقل والمشورة والرفد» وقال سعيد بن جبير \" {فآتوهم نصيبهم} [النساء: 33] من العون والنصرة \" قال أبو جعفر: وهذا أولى ما قيل في الآية إنها محكمة لعلتين: إحداهما أنه إنما يحمل النسخ على ما لا يصح المعنى إلا به وما كان منافيا فأما ما صح معناه وهو متلو فبعيد من الناسخ والمنسوخ والعلة الأخرى الحديث عن النبي صلى الله عليه وسلم الصحيح الإسناد\nحدثنا أبو جعفر قال: كما حدثنا أحمد بن شعيب، قال: أخبرنا عبد الرحمن بن محمد، قال","bab":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا"},{"id":"nasikh-nahhas:235","bookId":"nasikh-nahhas","type":"section","seq":235,"chapter":"ص: 48","title":"ص: 335","page":"ج1 ص334","text":": حدثنا إسحاق الأزرق، عن زكريا بن أبي زائدة، عن سعد بن إبراهيم، عن محمد بن جبير بن مطعم، عن أبيه، أن رسول الله صلى الله عليه وسلم قال: «لا حلف في الإسلام وأيما حلف كان في الجاهلية فإن الإسلام لم يزده إلا شدة» فتبين بهذا الحديث أن الحلف غير منسوخ وتبين من الحديث الأول وقول مجاهد، وسعيد بن جبير أنه في النصر والنصيحة والعون والرفد ويكون ما في الحديث الأول من قول ابن عباس نسختها يعني {ولكل جعلنا موالي} [النساء: 33] لأن الناس كانوا يتوارثون في الجاهلية بالتبني وتوارثوا في أول الإسلام بالإخاء ثم نسخ هذا كله فرائض الله بالمواريث واختلف العلماء أيضا في الآية الثامنة","bab":"باب ذكر الآية السابعة قال الله جل وعز {والذين عقدت أيمانكم فآتوهم نصيبهم} [النساء: 33] فمن أصح ما روي في هذه الآية إسنادا وأجله قائلا"},{"id":"nasikh-nahhas:236","bookId":"nasikh-nahhas","type":"section","seq":236,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة قال جل وعز {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] أكثر العلماء على أنها","page":"ج1 ص334","text":"فمن ذلك ما قرئ على أحمد بن شعيب، عن إسحاق بن إبراهيم، قال أخبرنا أبو داود، قال: حدثنا سفيان، عن علي بن بذيمة، عن عكرمة، عن ابن عباس في قول الله جل وعز {لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] قال: \" نسختها {إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] \" الآية قال أبو جعفر: فيكون على هذا قد نسخت الآية على الحقيقة يكونون أمروا بألا يصلوا إذا سكروا ثم أمروا بالصلاة على كل حال فإن","bab":"باب ذكر الآية الثامنة قال جل وعز {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] أكثر العلماء على أنها منسوخة غير أنهم يختل"},{"id":"nasikh-nahhas:237","bookId":"nasikh-nahhas","type":"section","seq":237,"chapter":"ص: 48","title":"ص: 337","page":"ج1 ص336","text":"كانوا لا يعقلون ما يقرءون وما يفعلون فعليهم الإعادة وإن كانوا يعقلون ذلك فعليهم أن يصلوا وهذا قبل التحريم، فأما بعد التحريم فينبغي ألا يفعلوا ذلك أعني من الشرب فإن فعلوا فقد أساءوا والحكم في الصلاة واحد إلا الزيادة في المضمضة من المسكر لأنه لما حرم صار نجسا فهذا قول\nوقد روى عثمان بن عطاء، عن أبيه، عن ابن عباس، {لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] قال: «في المساجد» وتقدير هذا في العربية لا تقربوا موضع الصلاة مثل {واسأل القرية} [يوسف: 82]\nأخبرنا أبو جعفر، قال: حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال أخبرنا معمر، عن قتادة، {لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] قال: «فكانوا يجتنبون السكر عند حضور الصلوات ثم نسخت في تحريم الخمر» وقال مجاهد: «نسخت بتحريم","bab":"باب ذكر الآية الثامنة قال جل وعز {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] أكثر العلماء على أنها منسوخة غير أنهم يختل"},{"id":"nasikh-nahhas:238","bookId":"nasikh-nahhas","type":"section","seq":238,"chapter":"ص: 48","title":"ص: 338","page":"ج1 ص337","text":"الخمر» وممن قال إنها محكمة غير منسوخة الضحاك قال: {وأنتم سكارى} [النساء: 43] من النوم والقول الأول أولى لتواتر الآثار بصحته\nكما قرئ على إبراهيم بن موسى الجوزي، عن يعقوب بن إبراهيم، قال: حدثنا وكيع، قال: حدثنا سفيان، عن عطاء بن السائب، عن أبي عبد الرحمن السلمي، عن علي بن أبي طالب، رضي الله عنه قال: \" دعانا رجل من الأنصار قبل تحريم الخمر فحضرت الصلاة فتقدم عبد الرحمن بن عوف فصلى بنا المغرب فقرأ {قل يا أيها الكافرون} [الكافرون: 1] فلبس عليه فنزلت {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] \" قال أبو جعفر: فهذا ليس من النوم في شيء مع التوقيف في نزول الآية","bab":"باب ذكر الآية الثامنة قال جل وعز {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] أكثر العلماء على أنها منسوخة غير أنهم يختل"},{"id":"nasikh-nahhas:239","bookId":"nasikh-nahhas","type":"section","seq":239,"chapter":"ص: 48","title":"ص: 339","page":"ج1 ص337","text":"وقد عارض معارض فقال: كيف يتعبد السكران بألا يقرب الصلاة في تلك الحال وهو لا يفهم وهذا لا يلزم، وفيه جوابان أحدهما أنه تعبد ألا يسكر عند حضور الصلاة والجواب الآخر وهو أصحهما أن السكران هاهنا هو الذي لم يزل فهمه، وإنما خدر جسمه من الشرب وفهمه قائم فهو مأمور منهي فأما من لا يفهم فقد خرج إلى الخبل وحال المجانين فهذا لم يزل مكروها في الجاهلية ثم زاده الإسلام توكيدا كما روي، عن عثمان، قال: \" ما سكرت في جاهلية ولا إسلام ولا تغيبت ولا تمنيت ولا مسست ذكري بيميني منذ بايعت بها رسول الله صلى الله عليه وسلم قيل له فالإسلام حجزك فما بال الجاهلية قال: كرهت أن أكون لعبة لأهلي \" فيكون المنسوخ من الآية التحريم في أوقات الصلاة وغيرها والبين في الآية التاسعة أنها منسوخة","bab":"باب ذكر الآية الثامنة قال جل وعز {يا أيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون} [النساء: 43] أكثر العلماء على أنها منسوخة غير أنهم يختل"},{"id":"nasikh-nahhas:240","bookId":"nasikh-nahhas","type":"section","seq":240,"chapter":"ص: 48","title":"باب ذكر الآية التاسعة قال جل وعز: {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الل","page":"ج1 ص338","text":"أن هذه الآية منسوخة بالأمر بالقتال\nقال أبو جعفر: كما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا إبراهيم بن عبد الله، قال: حدثنا حجاج، عن ابن جريج، عن عطاء الخراساني، عن ابن عباس، في قوله تعالى {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق} [النساء: 90] الآية قال: \" نسختها براءة {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \"\nحدثنا أبو جعفر، قال: حدثنا جعفر قال: حدثنا إبراهيم، قال: حدثنا عبيد الله، قال: حدثنا يزيد، عن سعيد، عن قتادة، {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق} [النساء: 90] قال: \" ثم نسخ بعد ذلك فنبذ إلى كل ذي عهد عهده ثم أمر الله جل وعز أن نقاتل المشركين حتى يقولوا لا إله إلا الله فقال: {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \"\nقال أبو جعفر وحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة","bab":"باب ذكر الآية التاسعة قال جل وعز: {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقات"},{"id":"nasikh-nahhas:241","bookId":"nasikh-nahhas","type":"section","seq":241,"chapter":"ص: 48","title":"ص: 341","page":"ج1 ص340","text":"، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، {فإن اعتزلوكم فلم يقاتلوكم وألقوا إليكم السلم} [النساء: 90] قال: \" نسختها براءة {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" قال أبو جعفر: هذا قول مجاهد وقال ابن زيد نسخها الجهاد وزعم بعض أهل اللغة أن معنى {إلا الذين يصلون} [النساء: 90] أي يتصلون أي ينتمون إلى قوم بينكم وبينهم ميثاق أي ينتسبون إليهم كما قال الأعشى:\n[البحر الطويل]\nإذا اتصلت قالت أبكر بن وائل ... وبكر سبتها والأنوف رواغم\n. قال أبو جعفر: وهذا غلط عظيم لأنه يذهب إلى أن الله تعالى حظر أن يقاتل أحد بينه وبين المسلمين نسب والمشركون قد كان بينهم وبين السابقين الأولين أنساب وأشد من هذا الجهل الاحتجاج بأن ذلك كان ثم نسخ لأن أهل التأويل مجمعون أن الناسخ له براءة وإنما نزلت براءة بعد الفتح وبعد أن انقطعت الحروب وإنما يؤتى هذا من الجهل بقول أهل التفسير","bab":"باب ذكر الآية التاسعة قال جل وعز: {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقات"},{"id":"nasikh-nahhas:242","bookId":"nasikh-nahhas","type":"section","seq":242,"chapter":"ص: 48","title":"ص: 342","page":"ج1 ص340","text":"والاجتراء على كتاب الله جل وعز وحمله على المعقول من غير علم بأقوال المتقدمين والتقدير على قول أهل التأويل: فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق، وأولئك القوم خزاعة صالحهم رسول الله صلى الله عليه وسلم على أنهم لا يقاتلون، وأعطاهم الأمان ومن وصل إليهم فدخل في الصلح معهم كان حكمه حكمهم {أو جاءوكم حصرت صدورهم} أي وإلا الذين جاءوكم حصرت صدورهم وهم بنو مدلج وبنو خزيمة ضاقت صدورهم أن يقاتلوا المسلمين أو يقاتلوا قومهم بني مدلج وحصرت خبر بعد خبر وقيل حذفت منه قد فأما أن يكون دعاء فمخالف لقول أهل التأويل لأنه قد أمر ألا يقاتلوا فكيف يدعي عليهم وقيل المعنى: أو يصلون إلى قوم جاءوكم حصرت صدورهم ثم قال تعالى: {ولو شاء الله لسلطهم عليكم} [النساء: 90] أي لسلط هؤلاء الذين يصلون إلى قوم بينكم وبينهم ميثاق والذين جاءوكم حصرت","bab":"باب ذكر الآية التاسعة قال جل وعز: {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقات"},{"id":"nasikh-nahhas:243","bookId":"nasikh-nahhas","type":"section","seq":243,"chapter":"ص: 48","title":"ص: 343","page":"ج1 ص340","text":"صدورهم، أي واشكروا نعمة الله عليكم واقبلوا أمره ولا تقاتلوهم {فإن اعتزلوكم فلم يقاتلوكم وألقوا إليكم السلم} [النساء: 90] أي الصلح {فما جعل الله لكم عليهم سبيلا} [النساء: 90] أي طريقا إلى قتلهم وسبي ذراريهم، ثم نسخ هذا كله كما قال أهل التأويل فنبذ إلى كل ذي عهد عهده فقيل لهم: {فسيحوا في الأرض أربعة أشهر} [التوبة: 2] ثم ليس بعد ذلك إلا الإسلام أو القتل لغير أهل الكتاب واختلف العلماء في الآية العاشرة فقالوا فيها خمسة أقوال","bab":"باب ذكر الآية التاسعة قال جل وعز: {إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقات"},{"id":"nasikh-nahhas:244","bookId":"nasikh-nahhas","type":"section","seq":244,"chapter":"ص: 48","title":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن ا","page":"ج1 ص340","text":"العلماء من قال: له توبة لأن هذا مما لا يقع فيه ناسخ ولا منسوخ لأنه خبر ووعيد ومن العلماء من قال الله جل وعز متول عقابه تاب أو لم يتب إن شاء عذبه وإن شاء عفا عنه وإن شاء أدخله النار وأخرجه منها ومن العلماء من قال المعنى فجزاؤه جهنم إن جازاه ومن العلماء من قال التقدير ومن يقتل مؤمنا متعمدا مستحلا لقتله فهذا جزاؤه لأنه كافر قال أبو جعفر: فهذه خمسة أقوال فالقول الأول أنه لا توبة للقاتل مروي عن زيد بن ثابت وابن\nعباس\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن عبد الله بن بكير، قال: حدثني الليث بن سعد، قال أخبرني خالد، وهو ابن يزيد، عن سعيد بن أبي هلال، عن جهم بن أبي الجهم، أن أبا الزناد، أخبره، أن، خارجة بن زيد أخبره، عن، أبيه، زيد بن ثابت قال: \" لما نزلت الآية التي في الفرقان {والذين لا يدعون مع الله إلها آخر ولا يقتلون النفس التي حرم الله إلا بالحق ولا يزنون} [الفرقان: 68] عجبنا للينها فنزلت التي في النساء {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] حتى فرغ\nوقرئ على أبي عبد الرحمن أحمد بن شعيب، عن عمرو بن علي، قال: حدثنا يحيى، قال حدثنا ابن جريج، قال أخبرني القاسم بن أبي بزة، عن سعيد بن جبير، قال سألت ابن عباس: \" هل لمن قتل مؤمنا متعمدا من توبة؟ قال: لا وقرأت عليه الآية التي في الفرقان {والذين لا يدعون مع الله إلها آخر} [الفرقان: 68] فقال هذه آية مكية نسختها آية مدنية {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه} [النساء: 93]\nقال أبو عبد الرحمن، وأخبرنا قتيبة، قال: حدثنا سفيان، عن عمار الدهني، عن سالم بن أبي الجعد، أن ابن عباس، سئل عمن قتل مؤمنا متعمدا ثم تاب وآمن وعمل صالحا ثم اهتدى فقال: \" وأنى له بالتوبة وقد سمعت نبيكم صلى الله عليه وسلم يقول: «يجيء متعلقا بالقاتل تشخب أوداجه دما يقول أي رب سل هذا فيم قتلني» ثم قال ابن عباس: والله لقد أنزلها الله تعالى ثم ما نسخها\nقال أبو عبد الرحمن، وأخبرنا يحيى بن حكيم، قال: حدثنا ابن أبي عدي، قال: حدثنا شعبة، عن يعلى بن عطاء، عن أبيه، عن عبد الله بن عمرو، عن رسول الله صلى الله عليه وسلم قال: «لزوال الدنيا أهون على الله تعالى من قتل رجل مسلم»\nقال أبو عبد الرحمن، وأخبرنا أحمد بن فضالة، قال حدثنا عبد الرزاق، قال: أخبرنا معمر، عن أيوب، عن الحسن، عن الأحنف بن قيس، عن أبي بكرة، قال: سمعت رسول الله صلى الله عليه وسلم يقول","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:245","bookId":"nasikh-nahhas","type":"section","seq":245,"chapter":"ص: 48","title":"ص: 348","page":"ج1 ص347","text":": «إذا التقى المسلمان بسيفيهما فقتل أحدهما صاحبه فالقاتل والمقتول في النار» قيل: يا رسول الله هذا القاتل فما بال المقتول؟ قال: «إنه أراد أن يقتل صاحبه» قال أبو جعفر: فهذه أحاديث صحاح يحتج بها أصحاب هذا القول مع ما روى عبد الله بن مسعود عن النبي صلى الله عليه وسلم: «سباب المسلم فسوق وقتاله كفر» وعنه عليه السلام: «لا ترجعوا بعدي كفارا يضرب بعضكم رقاب بعض» ومن أعان على قتل مسلم بشطر كلمة جاء يوم القيامة مكتوب بين عينيه يائس من رحمة الله \" جل وعز قال أبو جعفر: والقول الثاني أن له توبة قول جماعة من العلماء منهم عبد الله بن عمر وهو أيضا مروي عن زيد بن ثابت، وابن عباس\nكما قرئ على بكر بن سهل، عن عبد الله بن صالح، قال حدثني معاوية بن صالح، عن عبد الوهاب بن بخت، عن نافع، أو سالم، أن رجلا سأل عبد الله بن عمر فقال: يا أبا عبد الرحمن كيف ترى في رجل قتل رجلا عمدا؟ قال: «أأنت قتلته؟» قال: نعم، قال: «تب إلى الله جل وعز يتب عليك»\nوحدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا يزيد بن هارون، قال: أنبأنا أبو مالك الأشجعي، عن سعد بن عبيدة، قال: جاء رجل إلى ابن عباس فقال: «ألمن قتل مؤمنا متعمدا توبة؟» قال: «لا إلا النار» قال: فلما ذهب قال له جلساؤه أهكذا كنت تفتينا كنت تفتينا أن لمن قتل توبة مقبولة قال: «إني لأحسبه رجلا مغضبا يريد أن يقتل مؤمنا قال فبعثوا في أثره فوجدوه كذلك» قال أبو جعفر: وأصحاب هذا القول حججهم ظاهرة منها قول الله جل وعز: {وإني لغفار لمن تاب وآمن} [طه: 82] {وهو الذي يقبل التوبة عن عباده} [الشورى: 25] وقد بينا في أول هذا الكتاب أن الأخبار لا يقع فيها نسخ وقد اختلف عن، ابن عباس، أيضا فروي عنه، أنه قال: نزلت في أهل الشرك يعني التي في الفرقان وعنه نسختها التي في النساء فقال بعض العلماء: معنى نسختها نزلت بنسختها","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:246","bookId":"nasikh-nahhas","type":"section","seq":246,"chapter":"ص: 48","title":"ص: 350","page":"ج1 ص349","text":"قال أبو جعفر: وليس يخلو أن تكون الآية التي في النساء نزلت بعد التي في الفرقان كما روي عن زيد، وابن عباس على أنه قد روي عن زيد أن التي في الفرقان نزلت بعدها أو يكون هذا وتكون التي في الفرقان نزلت بعدها أو تكونا نزلتا معا وليس ثم قسم رابع فإن كانت التي في النساء نزلت بعد التي في الفرقان فهي مبينة عليها كما أن قوله {إنه من يشرك بالله فقد حرم الله عليه الجنة} [المائدة: 72] مبني على: {قل للذين كفروا إن ينتهوا يغفر لهم ما قد سلف} [الأنفال: 38] وإن كانت التي في الفرقان نزلت بعد التي في النساء فهي مبينة لها فإن كانتا نزلتا معا فإحداهما محمولة على الأخرى وهذا باب من النظر إذا تدبرته علمت أنه لا مدفع له مع ما يقوي ذلك من المحكم الذي لا ينازع فيه وهو قوله {وإني لغفار لمن تاب وآمن} [طه: 82] وأما القول الثالث أن أمره إلى الله جل وعز تاب أو لم يتب فعليه الفقهاء أبو حنيفة وأصحابه والشافعي أيضا يقول في كثير من هذا إلا أن يعفو الله عنه أو معنى هذا","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:247","bookId":"nasikh-nahhas","type":"section","seq":247,"chapter":"ص: 48","title":"ص: 351","page":"ج1 ص349","text":"وأما القول الرابع وهو قول أبي مجلز إن المعنى إن جازاه فالغلط فيه بين وقد قال الله تعالى: {ذلك جزاؤهم جهنم بما كفروا} [الكهف: 106] ولم يقل أحد معناه إن جازاهم وهو خطأ في العربية لأن بعده {وغضب الله عليه} [النساء: 93] وهو محمول على معنى جازاه وأما القول الخامس إن المعنى {ومن يقتل مؤمنا متعمدا} [النساء: 93] مستحلا لقتله فغلط لأن من عام لا يخص إلا بتوقيف أو دليل قاطع، وهذا القول يقال إنه قول عكرمة لأنه ذكر أن الآية نزلت في رجل قتل مؤمنا متعمدا ثم ارتد","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:248","bookId":"nasikh-nahhas","type":"section","seq":248,"chapter":"ص: 48","title":"ص: 352","page":"ج1 ص349","text":"قال أبو جعفر: فهذه عشر آيات قد ذكرناها في سورة النساء ورأيت بعض المتأخرين قد ذكر آية سوى هذه العشر وهي قوله عز وجل {وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا} [النساء: 101] قال أبو جعفر: وإنما لم أفرد لها بابا لأنه لم يصح عندي أنها ناسخة ولا منسوخة ولا ذكرها أحد من المتقدمين بشيء من ذينك فنذكر قوله وليس يخلو أمرها من إحدى ثلاث جهات ليس في واحدة منهن نسخ وذلك أن الذي قال: هي منسوخة يحتج بأن الله جل وعز قال: {وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا} [النساء: 101] قال فكان في هذا منع من قصر الصلاة إلا في الخوف ثم صح عن النبي صلى الله عليه وسلم أنه قصر في غير الخوف آمن ما كان الناس في السفر، فجعل فعل النبي صلى الله عليه وسلم ناسخا للآية وهذا غلط بين لأنه ليس في الآية منع للقصر في الأمن وإنما فيها إباحة القصر في الخوف فقط والجهات التي فيها عن العلماء المتقدمين منهن أن يكون معنى أن تقصروا من الصلاة أن تقصروا من حدودها في حال الخوف وذلك ترك إقامة ركوعها وسجودها وأداؤها كيف أمكن، مستقبل القبلة ومستدبرها وماشيا وراكبا في حال الحرب وهي حال الخوف كما قال تعالى: {فإن خفتم فرجالا أو ركبانا} [البقرة: 239] وهكذا يروى عن ابن عباس وهذا قول وهو اختيار محمد بن جرير واستدل على صحته","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:249","bookId":"nasikh-nahhas","type":"section","seq":249,"chapter":"ص: 48","title":"ص: 353","page":"ج1 ص349","text":"بأن بعده {فإذا اطمأننتم فأقيموا الصلاة} [النساء: 103] فإقامتها إتمام ركوعها وسجودها وسائر فرائضها وترك إقامتها في غير الطمأنينة هو ترك إقامة هذه الأشياء ومن الجهات في تأويل الآية أن جماعة من الصحابة والتابعين قالوا: قصر صلاة الخوف أن يصلي ركعة واحدة لأن صلاة المسافر ركعتين ليس بقصر لأن فرضها ركعتان وممن صح عنه: فرضت الصلاة ركعتين ثم أتمت صلاة المقيم وأقرت صلاة المسافر بحالها عائشة رضي الله عنها","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:250","bookId":"nasikh-nahhas","type":"section","seq":250,"chapter":"ص: 48","title":"ص: 354","page":"ج1 ص349","text":"، وممن قال صلاة الخوف ركعة واحدة حذيفة، وجابر بن عبد الله، وسعيد بن جبير وهو قول ابن عباس\nكما قرئ على محمد بن جعفر بن حفص، عن خلف بن هشام المقرئ، قال: حدثنا أبو عوانة، عن بكير بن الأخنس، عن مجاهد، عن ابن عباس، قال: «فرض الله جل وعز الصلاة على لسان نبيكم صلى الله عليه وسلم للمقيم أربعا وللمسافر ركعتين وفي الخوف ركعة» قال أبو جعفر: وفي الآية قول ثالث عليه أكثر الفقهاء وذلك أن تكون صلاة الخوف ركعتين مقصورة من أربع في كتاب الله جل وعز وصلاة السفر في الأمن ركعتان مقصورة في سنة رسول الله صلى الله عليه وسلم لا بالقرآن ولا بنسخ للقرآن\nويدلك على صحة هذا ما قرئ على يحيى بن أيوب، عن ابن أبي مريم، قال: حدثنا يحيى بن أيوب قال: أخبرني ابن جريج، أن عبد الرحمن بن عبد الله بن أبي عمار حدثه، عن عبد الله بن بابيه عن يعلى بن أمية أنه قال: سألت عمر بن الخطاب رضي الله عنه قلت: أرأيت قول الله عز وجل {فليس عليكم جناح أن تقصروا} [النساء: 101] من الصلاة إن خفتم أن يفتنكم الذين كفروا، فقد زال الخوف فما بال","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:251","bookId":"nasikh-nahhas","type":"section","seq":251,"chapter":"ص: 48","title":"ص: 355","page":"ج1 ص354","text":"القصر؟ فقال: عجبت مما عجبت منه فسألت رسول الله صلى الله عليه وسلم فقال: «هي صدقة تصدق الله بها عليكم فاقبلوها» قال أبو جعفر: فلم يقل عليه السلام قد نسخ ذلك وإنما نسبه عليه السلام إلى الرخصة فصح قول من قال قصر صلاة السفر بالسنة وقصر صلاة الخوف بالقرآن، ولا يقال منسوخ لما ثبت في التنزيل وصح فيه التأويل إلا بتوقيف أو بدليل قاطع","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:252","bookId":"nasikh-nahhas","type":"section","seq":252,"chapter":"ص: 48","title":"سورة المائدة اختلف العلماء في هذه السورة فمنهم من قال لم ينسخ منها شيء ومنهم من احتج بأنها آخر سورة نزلت فلا يجوز أن يكون فيها منسوخ","page":"ج1 ص354","text":"قال أبو جعفر: كما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال: حدثنا عبد الرحمن بن مهدي، قال: حدثنا الثوري، عن أبي إسحاق، عن أبي ميسرة، قال: «لم ينسخ من المائدة شيء»\nوقرئ على إسحاق بن إبراهيم بن يونس، عن الوليد بن شجاع، قال: حدثنا عبد الله بن وهب، قال أخبرني معاوية بن صالح، عن أبي الزاهرية، عن جبير بن نفير، قال: \" حججت فدخلت على عائشة فقالت: هل تقرأ سورة المائدة؟ قلت: نعم، قالت: أما إنها آخر سورة نزلت فما وجدتم فيها حلالا فاستحلوه وما وجدتم فيها حراما فحرموه \"","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:253","bookId":"nasikh-nahhas","type":"section","seq":253,"chapter":"ص: 48","title":"ص: 358","page":"ج1 ص357","text":"قال أبو جعفر: ومما يحتج به في هذا حديث عمر رضي الله عنه حين قرأ {اليوم أكملت لكم دينكم} [المائدة: 3] فقال بعض اليهود: لو نزلت هذه علينا في يوم لاتخذناه عيدا فقال عمر «كان في اليوم الذي نزلت فيه عيدان نزلت يوم الجمعة يوم عرفات يعني في حجة الوداع» قال أبو جعفر: فأما البراء فإنه قال: آخر سورة نزلت براءة وآخر آية نزلت {يستفتونك قل الله يفتيكم في الكلالة} [النساء: 176] وهذا ليس بمتناقض لأنهما جميعا من آخر ما نزل ولو لم يكن في المائدة منسوخ لاحتجنا إلى ذكرها لأن فيها ناسخا وهذا الكتاب يشتمل على الناسخ والمنسوخ على أن كثيرا من العلماء قد ذكروا فيها آيات منسوخة وقال بعضهم فيها آية واحدة منسوخة\nكما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا الثوري، عن بيان، عن الشعبي، قال: \" ليس في المائدة منسوخ إلا قوله جل وعز {يا أيها الذين آمنوا لا تحلوا شعائر الله} [المائدة: 2] الآية \" قال أبو جعفر: وهذه الآية الأولى مما نذكره منها","bab":"باب ذكر الآية العاشرة قال جل وعز: {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما} [النساء: 93] فمن العلماء من قال: لا تو"},{"id":"nasikh-nahhas:254","bookId":"nasikh-nahhas","type":"section","seq":254,"chapter":"ص: 48","title":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البي","page":"ج1 ص358","text":"محكمة فممن ذهب إلى أنها منسوخة قتادة وروي ذلك عن ابن عباس\nقال أبو جعفر: حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قوله جل وعز {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي} [المائدة: 2] ولا القلائد ولا آمين البيت الحرام قال: \" منسوخ كان الرجل في الجاهلية إذا خرج يريد الحج تقلد من السمر فلا يعرض له أحد وإذا تقلد قلادة شعر لم يعرض له أحد وكان المشرك يومئذ لا يصد عن البيت فأمر الله جل وعز أن لا يقاتل المشركون في الشهر الحرام ولا عند البيت ثم نسختها قوله جل وعز: {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5]\nقال أبو جعفر: حدثنا بكر بن سهل، قال: حدثنا أبو صالح عن معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله: جل وعز {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام} [المائدة: "},{"id":"nasikh-nahhas:255","bookId":"nasikh-nahhas","type":"section","seq":255,"chapter":"ص: 48","title":"ص: 360","page":"ج1 ص359","text":"ولا آمين البيت الحرام} [المائدة: 2] \" فكان المؤمنون والمشركون يحجون إلى البيت جميعا فنهى أن يمنع أحد من الحج إلى البيت من مؤمن وكافر ثم أنزل الله جل وعز بعد هذا {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28] وقال جل ذكره: {إنما يعمر مساجد الله من آمن بالله واليوم الآخر} [التوبة: 18] وقال تعالى {ما كان للمشركين أن يعمروا مساجد الله} [التوبة: 17] فنفى المشركين من المسجد الحرام \"\nوبهذا الإسناد {لا تحلوا شعائر الله} [المائدة: 2] \" كان المشركون يعظمون أمر الحج ويهدون الهدايا إلى البيت ويعظمون حرمته فأراد المسلمون أن يغيروا ذلك فأنزل الله جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله} [المائدة: 2] \" فهذا على تأويل النسخ في الأحكام الخمسة بإباحة قتال المشركين على كل حال ومنعهم من المسجد الحرام فأما مجاهد فقال لم ينسخ منها إلا القلائد كان الرجل يتقلد بشيء من لحا الحرم فلا يقرب فنسخ ذلك قال أبو جعفر: وعلى مذهب أبي ميسرة أنها محكمة","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام} [المائدة: "},{"id":"nasikh-nahhas:256","bookId":"nasikh-nahhas","type":"section","seq":256,"chapter":"ص: 48","title":"ص: 361","page":"ج1 ص359","text":"وأما عطاء فقال: {لا تحلوا شعائر الله} [المائدة: 2] أي لا تتعرضوا ما يسخطه واتبعوا طاعته واجتنبوا معاصيه، فهذا لا نسخ فيه وهو قول حسن لأن واحد الشعائر شعيرة من شعرت به أي علمت به فيكون المعنى لا تحلوا معالم الله وهي أمره ونهيه وما أعلمه الناس فلا تخالفوه وقد روي عن، ابن عباس الهدي، ما لم يقلد وقد عزم صاحبه على أن يهديه والقلائد ما قلد، فأما الربيع بن أنس فتأول معنى ولا القلائد أنه لا يحل لهم أن يأخذوا من شجر الحرم فيتقلدوه وهذا قول شاذ بعيد وقول أهل التأويل إنهم نهوا أن يحلوا ما قلد فيأخذوه ويغصبوه فمن قال منسوخ فحجته بينة أن المشرك حلال الدم وإن تقلد من شجر الحرم وهذا بين جدا وفي هذه الآية مما ذكر أنه منسوخ قوله جل وعز: {ولا يجرمنكم شنآن قوم أن صدوكم عن المسجد الحرام أن تعتدوا} [المائدة: 2] قال","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام} [المائدة: "},{"id":"nasikh-nahhas:257","bookId":"nasikh-nahhas","type":"section","seq":257,"chapter":"ص: 48","title":"ص: 362","page":"ج1 ص359","text":"عبد الرحمن بن زيد «هذا كله منسوخ نسخه الجهاد» قال أبو جعفر: ذهب ابن زيد إلى أنه لما جاز قتالهم لأنهم كفار جاز أن يعتدي عليهم ويبدءوا بالقتال وأما غيره من أهل التأويل فذهب إلى أنها ليست منسوخة فممن قال ذلك مجاهد واحتج بقول النبي صلى الله عليه وسلم: لعن الله من قتل بذحل في الجاهلية، وأهل التأويل أو أكثرهم متفقون على أن المعنى لا يحملنكم إبغاض قوم لأن صدوكم عن المسجد الحرام يوم الحديبية على أن تعتدوا لأن سورة المائدة نزلت بعد يوم الحديبية والبين علىهذا أن تقرأ {أن صدوكم} [المائدة: 2] بفتح الهمزة لأنه شيء قد تقدم واختلف العلماء في الآية الثانية","bab":"باب ذكر الآية الأولى من هذه السورة قال جل وعز: {يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام} [المائدة: "},{"id":"nasikh-nahhas:258","bookId":"nasikh-nahhas","type":"section","seq":258,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال الله جل وعز: {اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم} [المائدة: 5] فقالوا فيها ثلاثة","page":"ج1 ص360","text":"وهو قول ربيعة، والشعبي ويروى عن صحابيين أبي الدرداء، وعبادة بن الصامت وأصحاب القول الثاني يقولون هذا استثناء وحلال أكله وأصحاب القول الثالث يقولون إذا سمعت الكتابي يسمي غير الله فلا تأكل وقال بهذا من الصحابة علي بن أبي طالب وعائشة، وابن عمر رضي الله عنهم وهو قول طاوس، والحسن وقال مالك بن أنس أكره ذلك","bab":"باب ذكر الآية الثانية قال الله جل وعز: {اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم} [المائدة: 5] فقالوا فيها ثلاثة أقوال فمنهم من قال:"},{"id":"nasikh-nahhas:259","bookId":"nasikh-nahhas","type":"section","seq":259,"chapter":"ص: 48","title":"ص: 365","page":"ج1 ص363","text":"ولم يحرمه واختلفوا أيضا في ذبائح نصارى بني تغلب فأكثر العلماء يقول هم بمنزلة النصارى تؤكل ذبائحهم وتتزوج المحصنات من نسائهم فممن قال هذا ابن عباس بلا اختلاف عنه وقال آخرون لا تؤكل ذبائحهم ولا يتزوج فيهم لأنهم عرب وإنما دخلوا في النصرانية، فممن روي عنه هذا علي بن أبي طالب رضي الله عنه\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا حفص بن غياث، قال: حدثنا أشعث بن عبد الملك، عن الحسن، قال: «ما علمت أحدا من أصحاب محمد صلى الله عليه وسلم حرم ذبائح بني تغلب إلا علي بن أبي طالب رضي الله عنه»\nقال أبو جعفر: وهذا قول الشافعي وعارضه محمد بن جرير بأن الحديث المروي عن علي بن أبي طالب رضي الله عنه الصحيح أنه قال: لا تأكلوا ذبائح بني تغلب ولا تتزوجوا فيهم فإنهم لم يتعلقوا من النصرانية إلا بشرب الخمر، قال: فدل هذا أنهم لو كانوا على ملة النصارى في كل أمورهم لأكلت ذبائحهم وتزوج فيهم قال وقد قامت الحجة على أكل ذبائح النصارى والتزوج فيهم وهم من النصارى وقد احتج ابن عباس في ذلك فقال: قال الله جل وعز {ومن يتولهم منكم فإنه منهم} [المائدة: 51] فلو لم تكن بنو تغلب من النصارى إلا بتوليتهم إياهم لأكلت ذبائحهم فأما المجوس فالعلماء مجمعون إلا من شذ منهم على أن ذبائحهم لا تؤكل ولا يتزوج فيهم لأنهم ليسوا أهل كتاب وقد بين ذلك رسول الله صلى الله عليه وسلم في كتابه إلى كسرى فلم يخاطبهم بأنهم أهل كتاب وخاطب\nقيصر بغير ذلك فقال: {يا أهل الكتاب تعالوا إلى كلمة سواء بيننا وبينكم} [آل عمران: 64] الآية، وقد عارض معارض بالحديث المروي عن عبد الرحمن بن عوف أنه قال لعمر بن الخطاب رضي الله عنه في المجوس: سمعت رسول الله صلى الله عليه وسلم يقول أنزلوهم منزلة أهل الكتاب قال أبو جعفر: وهذا الحديث لا حجة فيه من جهات إحداها أنه قد غلط في متنه وأن إسناده غير متصل فلا تقوم به حجة، وهذا الحديث\nحدثناه بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن جعفر بن محمد، عن، أبيه، قال: قال عمر بن الخطاب رضي الله عنه ما أدري كيف أعمل في أمر المجوس فشهد عنده عبد الرحمن بن عوف أنه سمع رسول الله صلى الله عليه وسلم يقول: «سنوا بهم سنة أهل الكتاب» قال أبو جعفر: فالإسناد منقطع لأن محمد بن علي لم يولد في وقت عمر وأما المتن فيقال إنه على غير هذا\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا أحمد بن بشر الكوفي، قال سمعت سفيان بن","bab":"باب ذكر الآية الثانية قال الله جل وعز: {اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم} [المائدة: 5] فقالوا فيها ثلاثة أقوال فمنهم من قال:"},{"id":"nasikh-nahhas:260","bookId":"nasikh-nahhas","type":"section","seq":260,"chapter":"ص: 48","title":"ص: 368","page":"ج1 ص367","text":"عيينة، يقول عمرو بن دينار، سمع بجالة، يقول: «إن عمر لم يكن أخذ من المجوس الجزية حتى شهد عبد الرحمن بن عوف أن رسول الله صلى الله عليه وسلم أخذها من مجوس هجر» فهذا إسناده متصل صحيح ولو صح الحديث الأول ما كان فيه دليل على أكل ذبائح المجوس ولا تزوج نسائهم لأن قوله سنوا بهم سنة أهل الكتاب يدل على أنهم ليسوا من أهل الكتاب، وأيضا فإنما نقل الحديث على أنه في الجزية خاصة وأيضا فسنوا بهم ليس من الذبائح في شيء لأنه لم يقل استنوا أنتم في أمرهم بشيء فأما الاحتجاج بأن حذيفة تزوج مجوسية فغلط والصحيح أنه تزوج يهودية وفي هذه الآية {والمحصنات من الذين أوتوا الكتاب من قبلكم} [المائدة: 5] وقد ذكرناه في قوله {ولا تنكحوا المشركات} [البقرة: 221] وقول من قال إن هذه الآية ناسخة لتلك واختلفوا في الآية الثالثة فقالوا فيها سبعة أقوال","bab":"باب ذكر الآية الثانية قال الله جل وعز: {اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم} [المائدة: 5] فقالوا فيها ثلاثة أقوال فمنهم من قال:"},{"id":"nasikh-nahhas:261","bookId":"nasikh-nahhas","type":"section","seq":261,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة","page":"ج1 ص367","text":"النبي صلى الله عليه وسلم كان إذا أحدث لم يكلم أحدا حتى يتوضأ وضوءه للصلاة فنسخ هذا وأمر بالطهارة عند القيام إلى الصلاة ومنهم من قال: هي منسوخة لأنه لو لم تنسخ لوجب على كل قائم إلى الصلاة الطهارة وإن كان متطهرا والناسخ لها فعل النبي صلى الله عليه وسلم وسنذكره بإسناده ومن العلماء من قال: يجب على كل من قام إلى الصلاة أن يتوضأ للصلاة بظاهر الآية وإن كان طاهرا فهذا قول عكرمة، وابن سيرين، واحتج عكرمة، بعلي بن أبي طالب رضي الله عنه\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا إبراهيم بن مرزوق، قال: حدثنا بشر بن عمر","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:262","bookId":"nasikh-nahhas","type":"section","seq":262,"chapter":"ص: 48","title":"ص: 370","page":"ج1 ص369","text":"، وعبد الصمد بن عبد الوارث، قالا: حدثنا شعبة، عن مسعود بن علي، قال: كان علي بن أبي طالب رضي الله عنه يتوضأ لكل صلاة ويتلو: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم} [المائدة: 6] الآية ومن العلماء من يقول ينبغي لكل من قام إلى الصلاة أن يتوضأ لها طلبا للفضل، وحمل الآية على الندب، ومنهم من قال الآية مخصوصة لمن قام من النوم والقول السابع: أن الآية يراد بها من لم يكن على طهارة فهذه سبعة أقوال، فأما القول الأول إنها ناسخة لقول الله جل وعز {لا تقربوا الصلاة وأنتم سكارى} [النساء: 43] فقد ذكرناه بإسناده في سورة النساء ولا يبين في هذا نسخ يكون التقدير إذا قمتم إلى الصلاة غير سكارى والقول الثاني: يحتج من قاله بحديث علقمة بن","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:263","bookId":"nasikh-nahhas","type":"section","seq":263,"chapter":"ص: 48","title":"ص: 371","page":"ج1 ص369","text":"الفغواء عن أبيه قال: كان النبي صلى الله عليه وسلم إذا بال لم يكلم أحدا حتى يتوضأ للصلاة حتى نزلت آية الرخصة {يا أيها الذين آمنوا إذا قمتم إلى الصلاة} [المائدة: 6]\nوقرئ على أحمد بن شعيب، عن محمد بن بشار، عن ابن معاذ، قال: حدثنا سعيد، عن قتادة، عن الحسن، عن حصين بن المنذر أبي ساسان، عن المهاجر بن قنفذ، أنه: «سلم على النبي صلى الله عليه وسلم وهو يبول فلم يرد عليه حتى توضأ فلما توضأ رد عليه» قال أبو جعفر: وهذا أيضا لا يتبين فيه نسخ لأنه مباح فعله ومن قال: الآية منسوخة بفعل النبي صلى الله عليه وسلم فاحتج\nبما حدثناه عبد الله بن محمد بن جعفر، قال: حدثنا أحمد بن منصور، قال حدثنا عبد الرزاق، قال: أخبرنا سفيان، عن علقمة بن مرثد، عن سليمان بن بريدة، عن أبيه، أن رسول الله صلى الله عليه وسلم: «كان يتوضأ وضوءه لكل صلاة فلما كان يوم الفتح صلى الصلوات بوضوء واحد ومسح على خفيه» فقال عمر: لقد فعلت شيئا ما كنت تفعله فقال: «عمدا فعلته» ومن منع أن ينسخ القرآن بالسنة قال هذا تبيين وليس بنسخ ومن قال على كل قائم إلى الصلاة أن يتوضأ لها احتج بظاهر الآية وبما روي عن علي بن أبي طالب رضي الله عنه","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:264","bookId":"nasikh-nahhas","type":"section","seq":264,"chapter":"ص: 48","title":"ص: 373","page":"ج1 ص371","text":"ومن قال: هي على الندب احتج بفعل النبي صلى الله عليه وسلم وبأن علي بن أبي طالب رضي الله عنه لم يقل هذا واجب فيتأول أنه يفعل هذا إرادة الفضل والدليل على هذا أنه قد صح عن علي بن أبي طالب رضي الله عنه أنه توضأ وضوءا خفيفا ثم قال: هذا وضوء من لم يحدث وكذا عن عمر أيضا ويحتج بحديث غطيف عن ابن عمر عن النبي صلى الله عليه وسلم: من توضأ على طهارة كتبت له عشر حسنات وأما من قال المعنى إذا قمتم من النوم فيحتج بأن في القرآن الوضوء على النائم، وهذا قول أهل المدينة\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن زيد بن أسلم، أن تفسير، هذه الآية {يا أيها الذين آمنوا إذا قمتم إلى الصلاة} [المائدة: 6] الآية أن: «ذلك إذا قام من المضجع يعني النوم» والقول السابع: قول الشافعي قال: \" لو وكلنا إلى الآية لكان على كل قائم إلى الصلاة الطهارة. فلما صلى رسول الله صلى الله عليه وسلم الصلوات بطهر واحد بينها ومعنى هذا على هذا القول {يا أيها الذين آمنوا إذا قمتم إلى الصلاة} [المائدة: 6] وقد أحدثتم {فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برءوسكم وأرجلكم إلى الكعبين} وقد زعم قوم أن هذا ناسخ للمسح على الخفين، وسنبين ما في ذلك وأنه ليس بناسخ له إن شاء الله وقال قوم في قراءة من قرأ: وأرجلكم بالخفض إنه منسوخ بفعل النبي صلى الله عليه وسلم وقوله لأن الجماعة الذين تقوم بهم الحجة رووا أن النبي صلى الله عليه وسلم غسل قدميه وفي ألفاظه عليه السلام إذا غسل قدميه خرجت الخطايا من قدميه ولم يقل أحد عنه عليه السلام إنه قال فإذا مسح قدميه، وصح عنه","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:265","bookId":"nasikh-nahhas","type":"section","seq":265,"chapter":"ص: 48","title":"ص: 375","page":"ج1 ص372","text":": «ويل للعراقيب من النار ويل للأعقاب من النار» وأنه أمر بتخليل الأصابع ولو كان المسح جائزا ما كان لهذا معنى وقال قوم قد صح الغسل بنص كتاب الله جل وعز في القراءة بالنصب وبفعل رسول الله صلى الله عليه وسلم وقوله ومن ادعى أن المسح جائز فقد تعلق بشذوذ وقال قوم الغسل والمسح جميعا واجبان بكتاب الله جل وعز لأن القراءة بالنصب والخفض مستفيضة قد قرأ بها الجماعة فممن قال إن مسح الرجلين منسوخ الشعبي\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا إبراهيم بن مرزرق، قال: حدثنا يعقوب بن","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:266","bookId":"nasikh-nahhas","type":"section","seq":266,"chapter":"ص: 48","title":"ص: 376","page":"ج1 ص374","text":"إسحاق، قال: حدثنا حماد بن سلمة، عن عاصم، عن الشعبي، قال: «نزل القرآن بالمسح والسنة بالغسل» ومن قال قد صح الغسل بالكتاب والسنة احتج بالقراءة بالنصب وبما صح عن النبي صلى الله عليه وسلم ومن قال: هما واجبان قال هما بمنزلة آيتين لصحة كل واحدة منهما عن جماعة تقوم بهم الحجة\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا إبراهيم، قال: حدثنا أبو داود، قال: حدثنا قيس، عن عاصم، عن زر، عن عبد الله، أنه: قرأ «وأرجلكم» بالنصب\nقال وحدثنا أحمد، قال: حدثنا محمد بن خزيمة، قال: حدثنا سعيد بن منصور، قال سمعت هشيما، يقول أخبرنا خالد، عن عكرمة، عن ابن عباس، أنه: قرأ «وأرجلكم وقال عاد إلى الغسل»","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:267","bookId":"nasikh-nahhas","type":"section","seq":267,"chapter":"ص: 48","title":"ص: 377","page":"ج1 ص376","text":"قال أبو جعفر: وهذه قراءة عروة بن الزبير، ونافع، والكسائي، وقرأ أنس بن مالك وأرجلكم بالخفض وهي قراءة أبى جعفر، وأبي عمرو، وعاصم، والأعمش، وحمزة على أنه يقال تمسحت بمعنى تطهرت للصلاة فيكون على هذا الخفض كالنصب وسمعت علي بن سليمان يقول التقدير وأرجلكم غسلا ثم حذف هذا لعلم السامع وممن قال إن المسح على الخفين منسوخ بسورة المائدة ابن عباس وقال: ما مسح رسول الله صلى الله عليه وسلم على الخفين بعد نزول المائدة","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:268","bookId":"nasikh-nahhas","type":"section","seq":268,"chapter":"ص: 48","title":"ص: 378","page":"ج1 ص376","text":"وممن رد المسح أيضا عائشة وأبو هريرة قال أبو جعفر: من نفى شيئا وأثبته غيره فلا حجة للنافي وهذا موجود في الأحكام والمعقول وقد أثبت المسح على الخفين من أصحاب رسول الله صلى الله عليه وسلم جماعة كثيرة ومنهم من قال بعد المائدة فممن أثبت المسح علي بن أبي طالب، وسعد بن أبي وقاص، وبلال، وعمرو بن أمية الضمري، وصفوان بن عسال، وحذيفة، وبريدة، وخزيمة بن ثابت، وأبو بكر، وسهل بن سعد، وأسامة بن زيد، وسلمان، وجرير البجلي، والمغيرة بن شعبة، وعن عمر بن الخطاب غير مسند صحيح\nفمن ذلك ما حدثنا أحمد بن شعيب، أبوعبد الرحمن، قال: أخبرنا إسحاق بن إبراهيم، وهو ابن راهويه، قال: أخبرنا عبد الرزاق، قال: أخبرنا سفيان الثوري، عن عمرو بن قيس الملائي، عن الحكم بن عتيبة، عن القاسم بن مخيمرة، عن شريح بن هانئ، عن علي بن أبي طالب","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:269","bookId":"nasikh-nahhas","type":"section","seq":269,"chapter":"ص: 48","title":"ص: 379","page":"ج1 ص376","text":"، رضي الله عنه قال: «جعل رسول الله صلى الله عليه وسلم للمسافر ثلاثة أيام ولياليهن، ويوما وليلة للمقيم يعني في المسح»\nقال أبو عبد الرحمن، وأخبرنا هناد بن السري، عن أبي معاوية، عن الأعمش، عن الحكم بن عتيبة، عن القاسم بن مخيمرة، عن شريح بن هانئ، قال: سألت عائشة عن المسح على الخفين قالت: ائت عليا فإنه أعلم بذلك مني فأتيت عليا فسألته عن المسح فقال: «أمرنا رسول الله صلى الله عليه وسلم أن نجعل للمقيم يوما وليلة وللمسافر ثلاثا»\nقال أبو عبد الرحمن، وأخبرنا قتيبة، قال: حدثنا حفص، عن الأعمش، عن إبراهيم، عن همام، أن، جرير بن عبد الله البجلي: \" توضأ ومسح على خفيه فقيل له أتمسح؟ فقال: قد رأيت رسول صلى الله عليه وسلم يمسح \" فكان أصحاب عبد الله يعجبهم قول جرير لأن إسلامه كان قبل موت رسول الله صلى الله عليه وسلم بيسير قال أبو جعفر: وكذا قال أحمد بن حنبل أنا أستحسن حديث جرير في المسح على الخفين لأن إسلامه كان بعد نزول المائدة","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:270","bookId":"nasikh-nahhas","type":"section","seq":270,"chapter":"ص: 48","title":"ص: 380","page":"ج1 ص379","text":"وقد عارض قوم من الذين يمنعون المسح على الخفين بأن الواقدي روى عن عبد الحميد بن جعفر عن أبيه: أن جريرا البجلي أسلم في سنة عشر في شهر رمضان وأن المائدة نزلت في ذي الحجة يوم عرفات قالوا: فإسلام جرير على هذا قبل نزول المائدة قال أبو جعفر: والذي احتج بهذا جاهل بمعرفة الحديث لأن هذا الحديث لا تقوم به حجة لوهائه وضعف إسناده، وأيضا فإن قوله نزلت المائدة يوم عرفات في ذي الحجة جهل أيضا لأن الرواية أنه نزل منها في ذلك اليوم آية واحدة وهي {اليوم أكملت لكم دينكم وأتممت عليكم نعمتي} [المائدة: 3] ولو صح ما قال إن المسح كان قبل نزول المائدة لما كانت له فيه حجة ولكان المسح ثابتا ويكون القرآن نزل بالغسل لمن لم يكن عليه خفان ويقال له أيضا ما معنى المسح قبل نزول المائدة وهل كان التوضؤ للصلاة واجبا قبل نزول المائدة فإن كان واجبا فقد صح أن المسح على الخف بدل من الغسل وإن قال كان غير واجب قيل له فما معنى المسح والغسل غير واجب وكذا المسح وهذا بين في تثبيت المسح على الخفين وهو قول الفقهاء الذين تقوم بهم الحجة واختلفوا في الآية الرابعة فمنهم من قال: هي منسوخة ومنهم من قال: هي محكمة","bab":"باب ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق} [المائدة: 6] الآية فيها سبعة أقوال: فمن العلماء م"},{"id":"nasikh-nahhas:271","bookId":"nasikh-nahhas","type":"section","seq":271,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال الله جل وعز: {فاعف عنهم واصفح} [المائدة: 13] من العلماء من قال إنما كان العفو والصفح قبل الأمر بالقتال ثم نسخ ذلك","page":"ج1 ص379","text":"كما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قول الله تعالى {ولا تزال تطلع على خائنة منهم إلا قليلا منهم فاعف عنهم واصفح} [المائدة: 13] ، قال: \" نسخها {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية \"","bab":"باب ذكر الآية الرابعة قال الله جل وعز: {فاعف عنهم واصفح} [المائدة: 13] من العلماء من قال إنما كان العفو والصفح قبل الأمر بالقتال ثم نسخ ذلك بالأمر بالقتال"},{"id":"nasikh-nahhas:272","bookId":"nasikh-nahhas","type":"section","seq":272,"chapter":"ص: 48","title":"ص: 382","page":"ج1 ص381","text":"وقال غيره: ليست بمنسوخة لأنها نزلت في يهود غدروا برسول الله صلى الله عليه وسلم غدرة وأرادوا قتله فأمره الله جل وعز بالصفح عنهم قال أبو جعفر: وهذا لا يمتنع أن يكون أمر بالصفح عنهم بعد أن لحقتهم الذلة والصغار فصفح عنهم في شيء بعينه واختلفوا أيضا في الآية الخامسة فقال بعضهم هي ناسخة وقال بعضهم هي محكمة غير ناسخة","bab":"باب ذكر الآية الرابعة قال الله جل وعز: {فاعف عنهم واصفح} [المائدة: 13] من العلماء من قال إنما كان العفو والصفح قبل الأمر بالقتال ثم نسخ ذلك بالأمر بالقتال"},{"id":"nasikh-nahhas:273","bookId":"nasikh-nahhas","type":"section","seq":273,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خ","page":"ج1 ص381","text":"بهم وسمل أعينهم وتركهم حتى ماتوا فممن قال هذا محمد بن سيرين قال: «لما فعل النبي صلى الله عليه وسلم ذلك وعظ ونسخ هذا الحكم» ، واستدل على ذلك بأحاديث صحاح فمن ذلك\nما حدثناه أحمد بن شعيب أبو عبد الرحمن، قال أخبرني عمرو بن عثمان بن سعيد بن كثير، عن الوليد، عن الأوزاعي، عن يحيى، عن أبي قلابة عن أنس،: \" أن نفرا من عكل قدموا على النبي صلى الله عليه وسلم فأسلموا فاجتووا المدينة فأمرهم النبي صلى الله عليه وسلم أن يخرجوا إلى إبل الصدقة فيشربوا من أبوالها وألبانها ففعلوا فقتلوا راعيها واستاقوها فبعث النبي صلى الله عليه وسلم في طلبهم قافة فأتي بهم فقطع أيديهم وأرجلهم ولم","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:274","bookId":"nasikh-nahhas","type":"section","seq":274,"chapter":"ص: 48","title":"ص: 384","page":"ج1 ص383","text":"يحسمهم وسمل أعينهم وتركهم حتى ماتوا، فأنزل الله جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا} [المائدة: 33] الآية \"\nقال أبو عبد الرحمن، وأخبرني الفضل بن سهل، قال حدثني يحيى بن غيلان، ثقة مأمونا قال حدثني يزيد بن زريع، عن سليمان التيمي، عن أنس، قال: «إنما سمل رسول الله صلى الله عليه وسلم أعين أولئك لأنهم سملوا أعين الرعاء» قال أبو جعفر: وهذا من أحسن حديث يروى في هذا الباب وأغربه وأصحه وفيه حجة للشافعي في القصاص","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:275","bookId":"nasikh-nahhas","type":"section","seq":275,"chapter":"ص: 48","title":"ص: 385","page":"ج1 ص383","text":"، فأما الحديث الأول فيحتج به من جعل الآية ناسخة وفيه من الغريب قوله: فاجتووا المدينة قال أبو زيد يقال اجتويت البلاد إذا كرهتها وإن كانت موافقة لك في بدنك، واستوبلتها إذا لم تكن توافقك في بدنك وإن كنت محبا لها وفيه، وسمل أعينهم، قال أبو عبيد: السمل أن تفقأ العين بحديدة محماة أو بغير ذلك يقال: سملتها أسملها سملا وقد يكون السمل بالشوك كما قال أبو ذؤيب يرثي بنين له ماتوا:\n[البحر الكامل]\nفالعين بعدهم كأن حداقها ... سملت بشوك فهي عور تدمع\nوبعض من يقول إنها محكمة غير ناسخة يقول الحكمان قائمان جميعا ويحتج بالحديث أن السمل كان قصاصا وهو أحسن ما قيل فيه وقال أبو الزناد لما فعل ذلك صلى الله عليه وسلم وعظ ونهى عن المثلة فلم يعد، وقال غيره: إنما فعل ذلك على الاجتهاد كما فعل في الغنائم حتى نزلت {لولا كتاب من الله سبق} [الأنفال: 68] الآية وقال آخر لا يجوز أن يفعل النبي صلى الله عليه وسلم شيئا من هذا وما أشبهه إلا بوحي منزل أو إلهام من الله جل وعز لقوله جل وعز: {وما ينطق عن الهوى} [النجم: 3] ولفرضه طاعته وقال السدي: إنما أراد أن يفعل فنهي عن ذلك وأمر بالحدود","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:276","bookId":"nasikh-nahhas","type":"section","seq":276,"chapter":"ص: 48","title":"ص: 386","page":"ج1 ص383","text":"قال أبو جعفر: وقد ذكرنا الحديث بغير ما قال فأما ما في الآية من قوله جل وعز أو؛ ومن اختلاف العلماء في تخيير الإمام أن يفعل أي هذه شاء ومن قول بعضهم بل ذلك على الترتيب فنذكر منه ما تكمل به الفائدة في علم الآية إن شاء الله واختلف العلماء في من يلزمه اسم محاربة الله جل وعز ورسوله صلى الله عليه وسلم على خمسة أقوال: فمنهم من قال المحارب لله جل وعز ورسوله هو المشرك المعاند دين الله فأما من كان مسلما وخرج متلصصا فلا يلزمه هذا الاسم وهذا القول مروي عن ابن عباس وهو يروى عن الحسن، وعطاء ومن العلماء من قال المحارب لله جل وعز ورسوله المرتد وهذا قول عروة بن الزبير\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح بن عبادة، عن ابن جريج، قال: أخبرني هشام بن عروة، عن أبيه، قال: «إذا خرج المسلم فشهر سلاحه ثم تلصص ثم جاء تائبا أقيم عليه الحد، ولو ترك لبطلت العقوبات إلا أن يلحق ببلاد الشرك ثم يأتي تائبا فيقبل منه»","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:277","bookId":"nasikh-nahhas","type":"section","seq":277,"chapter":"ص: 48","title":"ص: 387","page":"ج1 ص384","text":"وقال قوم: المحارب لله ولرسوله من المسلمين من فسق فشهر سلاحه وخرج على المسلمين يحاربهم وردوا على من قال لا يكون المحارب لله جل وعز ورسوله إلا مشركا بحديث معاذ عن النبي صلى الله عليه وسلم: «من عادى وليا من أولياء الله جل وعز فقد نادى الله جل وعز بالمحاربة»\nقال أبو جعفر حدثنا أحمد بن محمد الأزدي، قال: حدثنا الحسين بن الحكم الحبري، قال: حدثنا أبو غسان، مالك بن إسماعيل، عن السدي، عن صبيح، مولى أم سلمة، عن زيد بن أرقم، «أن رسول الله صلى الله عليه وسلم قال لعلي بن أبي طالب رضي الله عنه وفاطمة والحسن، والحسين رضي الله عنهم أنا سلم لمن سالمتم، وحرب لمن حاربتم» أفلا ترى قول رسول الله صلى الله عليه وسلم لمن ليس بكافر وتسميته إياه محاربا وقد رد أبو ثور وغيره على من قال إن الآية في المشركين بأشياء بينة","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:278","bookId":"nasikh-nahhas","type":"section","seq":278,"chapter":"ص: 48","title":"ص: 388","page":"ج1 ص386","text":"قال قد أجمع العلماء على أن المشرك إذا فعل هذه الأشياء ثم أسلم قبل أن يتوب منها أنه لا يقام عليه شيء من حدودها لقول الله جل وعز {قل للذين كفروا إن ينتهوا يغفر لهم ما قد سلف} [الأنفال: 38] فهذا كلام بين حسن وقال غيره لو كانت الآية في المشركين لوجب في أسرى المشركين أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأرض، وهذا لا يقوله أحد وقال بعض العلماء الآية عامة في المشركين والمسلمين فهذه أربعة أقوال، والقول الخامس: أن تكون الآية عامة على ظاهرها إلا أن يدل دليل على خارج منها فيخرج بالدليل فقد دل ما ذكرناه على أن أهل الحرب من المشركين خارجون منها فهذا أحسن ما قيل فيها، وهو قول أكثر الفقهاء ثم اختلفوا فيمن لزمه اسم المحاربة أيكون الإمام مخيرا فيه أم تكون عقوبته على قدر جنايته فقال قوم: الإمام مخير فيه على أنه يجتهد وينظر للمسلمين، فممن قال هذا من الفقهاء مالك بن أنس وهو مروي عن ابن عباس وهو","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:279","bookId":"nasikh-nahhas","type":"section","seq":279,"chapter":"ص: 48","title":"ص: 389","page":"ج1 ص386","text":"قول سعيد بن المسيب، وعمر بن عبد العزيز، ومجاهد، والضحاك وممن قال العقوبة على قدر الجناية وليس إلى الإمام في ذلك خيار الحسن، وعطاء، وسعيد بن جبير وأبو مجلز وهو مروي أيضا عن ابن عباس إلا أنه من رواية الحجاج بن أرطأة عن عطية عن ابن عباس، والحجاج وعطية ليسا بذاك عند أهل الحديث وقال بهذا من الفقهاء الأوزاعي والشافعي","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:280","bookId":"nasikh-nahhas","type":"section","seq":280,"chapter":"ص: 48","title":"ص: 390","page":"ج1 ص386","text":"وهو قول أصحاب الرأي، سفيان، وأبي حنيفة وأبي يوسف غير أنهم اختلفوا في الترتيب في أكثر الآية فما علمت أنهم اتفقوا إلا فيمن خرج فقتل فإن أصحاب الترتيب أجمعوا على قتله وسنذكر اختلافهم فأما أصحاب التخيير الذين قالوا ذلك إلى الإمام فحجتهم ظاهر الآية وأن أو في العربية كذا معناها إذا قلت خذ دينارا أو درهما ورأيت زيدا، أو عمرا واحتجوا بقول الله جل وعز {فكفارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم أو كسوتهم أو تحرير رقبة} [المائدة: 89] وكذا {ففدية من صيام أو صدقة أو نسك} [البقرة: 196] أنه لا اختلاف أن هذا على التخيير وكذا ما اختلفوا فيه مردود إلى ما أجمعوا عليه وإلى لغة الذين نزل القرآن بلغتهم فعارضهم من يقول بالترتيب بحديث عثمان وابن مسعود وعائشة عن النبي صلى الله عليه وسلم: «لا يحل دم امرئ مسلم إلا بإحدى ثلاث كفر بعد إيمان أو زنا بعد إحصان أو قتل نفس بغير نفس» فعارضهم الآخرون بأشياء منها أن المحارب مضموم إلى هذه الثلاثة كما ضممتم إليها أشياء ليست كفرا وكما قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه} [الأنعام: 145] الآية، فضممتم إليها تحريم كل ذي ناب من السباع وكل ذي مخلب من الطير","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:281","bookId":"nasikh-nahhas","type":"section","seq":281,"chapter":"ص: 48","title":"ص: 391","page":"ج1 ص386","text":"واحتج بعضهم بأن لآية المحاربة حكما آخر واستدل على ذلك بأن الأمر للمحارب ليس إلى الولي وإنما هو إلى الإمام واحتج بأن عائشة رضي الله عنها قد روت عن النبي صلى الله عليه وسلم ذكر المحارب\nكما قرئ على أحمد بن شعيب، عن العباس بن محمد، قال: حدثنا أبو عامر، عن إبراهيم بن طهمان، عن عبد العزيز بن رفيع، عن عبيد بن عمير، عن عائشة، رضي الله عنها أن رسول الله صلى الله عليه وسلم قال: \" لا يحل دم امرئ مسلم إلا بإحدى ثلاث خصال: زان محصن يرجم، أو رجل قتل متعمدا فيقتل، أو رجل خرج من الإسلام فيحارب فيقتل أو يصلب أو ينفى من الأرض \" واحتجوا أيضا بأن أكثر التابعين على أن الإمام مخير وكذا ظاهر الآية\nكما قرئ على إبراهيم بن موسى الجوزي بمدينة السلام عن يعقوب الدورقي، قال: حدثنا وكيع، عن سفيان، عن عاصم الأحول، عن الحسن، وعن ابن جريج، عن عطاء، في قول الله تعالى {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا} [المائدة: 33] الآية قالا: «الإمام مخير فيه»\nوحدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله تعالى: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأرض} [المائدة: 33] قال: \" من شهر السلاح في فئة الإسلام وأفسد السبيل فظهر عليه وقدر فإمام المسلمين مخير فيه إن شاء قتله وإن شاء صلبه وإن شاء قطع يده ورجله قال: أو ينفوا من الأرض قال: يهربوا ويخرجوا من دار الإسلام إلى دار الحرب فإن تابوا من قبل أن يقدر عليهم فاعلموا أن الله غفور رحيم \" ثم قال بهذا من التابعين سعيد بن المسيب، ومجاهد والضحاك وهو قول إبراهيم النخعي، وعمر بن عبد العزيز فأما الرواية الأخرى عن ابن عباس فأن ذلك على قدر جناياتهم فقد ذكرنا أنها\nمن رواية الحجاج، عن عطية، عن ابن عباس في قول الله تعالى {إنما جزاء الذين يحاربون الله ورسوله} [المائدة: 33] ، قال: «إذا خرج وأظهر السلاح وقتل قتل وإن أخذ المال ولم يقتل قطعت يده ورجله وإن أخذ المال وقتل قتل ثم صلب» وهذا قول قتادة وعطاء الخراساني وزعم إسماعيل بن إسحاق أنه لم يصح إلا عنهما يعني من المتقدمين لأن الرواية عن ابن عباس ضعيفة عنده وعند أهل الحديث","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:282","bookId":"nasikh-nahhas","type":"section","seq":282,"chapter":"ص: 48","title":"ص: 393","page":"ج1 ص392","text":"وقال الأوزاعي إذا خرج وقتل قتل فإن أخذ المال وقتل صلب وقتل مصلوبا وإن أخذ المال ولم يقتل قطعت يده ورجله وقال الليث بن سعد إذا أخذ المال وقتل صلب وقتل بالحربة مصلوبا وقال أبو يوسف إذا أخذ المال وقتل صلب وقتل على الخشبة وقال أبو حنيفة إذا قتل قتل وإذا أخذ المال ولم يقتل قطعت يده ورجله من خلاف وإذا أخذ المال وقتل فالسلطان مخير فيه إن شاء قطع يده ورجله وقتله وإن شاء لم يقطع يده ورجله وقتله وصلبه، قال أبو يوسف: القتل يأتي على كل شيء وقال الشافعي: «إذا أخذ المال قطعت يده اليمنى وحسمت، ثم قطعت رجله اليسرى وحسمت وخلي وإذا قتل قتل وإذا أخذ المال وقتل قتل وصلب وروي عنه أنه قال يصلب ثلاثة أيام قال وإن حضر وكثر وهيب فكان رداء للعدو عزر وحبس» قال أبو جعفر: اختلف الذين قالوا بالترتيب واختلف عن بعضهم حتى وقع في ذلك اضطراب كثير فممن اختلف عنه ابن عباس كما ذكرناه والحسن فروي عنه التخيير والترتيب وأنه قال إذا خرج وقتل قتل فإن أخذ المال ولم يقتل قطعت يده ورجله ونفي وإن أخذ المال وقتل قتل","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:283","bookId":"nasikh-nahhas","type":"section","seq":283,"chapter":"ص: 48","title":"ص: 394","page":"ج1 ص392","text":"وقال أحمد بن محمد بن حنبل: «إن قتل قتل وإن أخذ المال ولم يقتل قطعت يده ورجله» وقال قوم لا ينبغي أن يصلب قبل القتل فيحال بينه وبين الصلاة والأكل والشرب، وحكي عن الشافعي أنه قال أكره أن يقتل مصلوبا لنهي النبي صلى الله عليه وسلم عن المثلة وقال أبو ثور: «الإمام مخير على ظاهر الآية» واحتج غيره بأن الذين قالوا بالتخيير معهم ظاهر الآية وأن الذين قالوا بالترتيب وإن اختلفوا فإنك تجد في أقوالهم أنهم يجمعون عليه حدين فيقولون يقتل ويصلب ويقول بعضهم يصلب ويقتل، ويقول بعضهم تقطع يده ورجله وينفى، وليس كذا الآية، ولا كذا معنى أو في اللغة فأما معنى أو ينفوا من الأرض ففيه أقوال منها عن ابن عباس ما ذكرناه أنهم يهربون حتى يخرجوا من دار الإسلام إلى دار الحرب، وهذا أيضا محكي معناه عن الشافعي أنهم يخرجون من بلد إلى بلد ويحاربون، وكذا قال الزهري محمد بن مسلم وقال سعيد بن","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:284","bookId":"nasikh-nahhas","type":"section","seq":284,"chapter":"ص: 48","title":"ص: 395","page":"ج1 ص392","text":"جبير «ينفون من بلد إلى بلد وكلما أقاموا في بلد نفوا منه» وقال الشعبي «ينفيه السلطان الذي أحدث هذا في عمله عن عمله» وقال مالك بن أنس رحمه الله «ينفى من البلد الذي أحدث فيه هذا إلى غيره ثم يحبس فيه» ويحتج لمالك بأن الزاني كذا ينفى وقال الكوفيون لما قال الله جل وعز {أو ينفوا من الأرض} [المائدة: 33] وقد علم أنه لا بد أن يستقروا في الأرض لم يكن شيء أولى بهم من الحبس لأنه إذا حبس فقد نفي من الأرض إلا من موضع استقراره واختلف العلماء أيضا في الآية السادسة فمنهم من قال إنها منسوخة ومنهم من قال: هي محكمة","bab":"باب ذكر الآية الخامسة قال جل وعز: {إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فسادا أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأر"},{"id":"nasikh-nahhas:285","bookId":"nasikh-nahhas","type":"section","seq":285,"chapter":"ص: 48","title":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الك","page":"ج1 ص392","text":"كما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا وكيع، قال: حدثنا سفيان، عن مغيرة، عن إبراهيم، وعامر الشعبي، في قول الله تعالى {فإن جاءوك فاحكم بينهم أو أعرض عنهم} قال: «إن شاء حكم وإن شاء لم يحكم» وقال بهذا من الفقهاء عطاء بن أبي رباح، ومالك بن أنس","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:286","bookId":"nasikh-nahhas","type":"section","seq":286,"chapter":"ص: 48","title":"ص: 397","page":"ج1 ص396","text":"ومن العلماء من قال إذا تحاكم أهل الكتاب إلى الإمام فعليه أن يحكم بينهم بكتاب الله جل وعز وسنة رسوله صلى الله عليه وسلم ولا يحل له أن يردهم إلى حكامهم، وقائلوا هذا القول يقولون إن الآية منسوخة لأنها إنما نزلت أول ما قدم النبي صلى الله عليه وسلم المدينة واليهود فيها يومئذ كثير فكان الأدعى لهم والأصلح أن يردوا إلى حكامهم فلما قوي الإسلام أنزل الله تعالى {وأن احكم بينهم بما أنزل الله} [المائدة: 49] فممن قال بهذا القول من الصحابة ابن عباس وجماعة من التابعين والفقهاء\nقال أبو جعفر كما حدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا سعيد بن سليمان، قال: حدثنا عباد، عن سفيان، عن الحكم، عن مجاهد، عن ابن عباس، قال: \" نسخت من هذه السورة يعني المائدة آيتان آية القلائد وقوله تعالى: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} فكان رسول الله صلى الله عليه وسلم مخيرا إن شاء حكم بينهم وإن شاء أعرض عنهم فردهم إلى حكامهم فنزلت {وأن احكم بينهم بما أنزل الله} [المائدة: 49] فأمر رسول الله صلى الله عليه وسلم بأن يحكم بينهم بما في كتابنا \" وهذا إسناد مستقيم وأهل الحديث يدخلونه في المسند وهو مع هذا قول جماعة من العلماء\nكما قرئ على عبد الله بن الصقر، عن زياد بن أيوب، قال: حدثنا هشيم، قال: أخبرنا أصحابنا، منصور، وغيره عن الحكم، عن مجاهد، في قول الله تعالى {وأن احكم بينهم بما أنزل الله} [المائدة: 49] قال: \" نسخت هذه الآية التي قبلها {فإن جاءوك فاحكم بينهم أو أعرض عنهم} وهذا أيضا إسناد صحيح والقول بأنها منسوخة قول عكرمة، والزهري، وعمر بن عبد العزيز والسدي وهو الصحيح من قول الشافعي قال في كتاب الجزية ولا خيار له إذا تحاكموا إليه لقول الله جل وعز {حتى يعطوا الجزية عن يد وهم صاغرون} [التوبة: 29] وهذا من أصح الاحتجاجات لأنه إذا كان معنى {وهم صاغرون} [التوبة: 29] أن تجري عليهم أحكام المسلمين وجب ألا يردوا إلى حكامهم فإذا وجب هذا فالآية منسوخة وهو أيضا قول الكوفيين أبي حنيفة وزفر وأبي يوسف ومحمد لا اختلاف بينهم إذا تحاكم أهل الكتاب إلى الإمام، أنه ليس له أن يعرض عنهم غير أن أبا حنيفة قال إذا جاءت المرأة والزوج فعليه أن يحكم بينهما بالعدل فإن جاءت المرأة وحدها ولم يرض الزوج لم يحكم وقال الباقون: بل يحكم","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:287","bookId":"nasikh-nahhas","type":"section","seq":287,"chapter":"ص: 48","title":"ص: 399","page":"ج1 ص397","text":"فثبت أن قول أكثر العلماء أن الآية منسوخة مع ما صح فيها من توقيف ابن عباس، ولو لم يأت الحديث عن ابن عباس لكان النظر يوجب أنها منسوخة لأنهم قد أجمعوا جميعا أن أهل الكتاب إذا تحاكموا إلى الإمام فله أن ينظر بينهم وأنه إذا نظر بينهم مصيب ثم اختلفوا في الإعراض عنهم على ما ذكرنا فالواجب أن ينظر بينهم لأنه مصيب عند الجماعة وألا يعرض عنهم فيكون عند بعض العلماء تاركا فرضا فاعلا ما لا يحل له ولا يسعه ولمن قال بأنها منسوخة من الكوفيين قول آخر منهم من يقول على الإمام إذا علم من أهل الكتاب حدا من حدود الله جل وعز أن يقيمه وإن لم","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:288","bookId":"nasikh-nahhas","type":"section","seq":288,"chapter":"ص: 48","title":"ص: 400","page":"ج1 ص397","text":"يتحاكموا إليه، ويحتج بأن قول الله تعالى {وأن احكم بينهم} [المائدة: 49] يحتمل أمرين: أحدهما وأن احكم بينهم إذا تحاكموا إليك، والآخر وأن احكم بينهم وإن لم يتحاكموا إليك إذا علمت ذلك منهم، قالوا: فوجدنا في كتاب الله تعالى وسنة رسول الله صلى الله عليه وسلم ما يوجب إقامة الحد عليهم وإن لم يتحاكموا إلينا فأما ما في كتاب الله جل وعز فقوله: {يا أيها الذين آمنوا كونوا قوامين بالقسط شهداء لله} [النساء: 135] وأما ما في السنة فحديث البراء\nقال أبو جعفر حدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا أبو معاوية، قال، حدثنا الأعمش، عن عبد الله بن مرة، عن البراء، قال: \" مر على النبي صلى الله عليه وسلم بيهودي قد جلد وحمم قال: «أهكذا حد الزاني عندكم؟» فقالوا: نعم فدعا رجلا من علمائهم فقال: «سألتك بالله أهذا حد الزاني فيكم؟» فقال: لولا أنك سألتني بهذا ما أخبرتك كان الحد عندنا الرجم فكان الشريف إذا زنى تركناه وكان الوضيع إذا زنى رجمناه فقلنا تعالوا نجتمع على شيء يكون للشريف والوضيع فاجتمعنا على الجلد والتحميم، فأنزل الله جل وعز: {يا أيها الرسول لا يحزنك الذين يسارعون في الكفر} [المائدة: 41] إلى: {يقولون إن أوتيتم هذا فخذوه} [المائدة: 41] أي ائتوا محمدا فإن أفتاكم بالجلد والتحميم فاقبلوه وإن لم تؤتوه فاحذروا أي فإن أفتاكم بالرجم فلا تقبلوا إلى {ومن لم يحكم بما أنزل الله فأولئك هم الكافرون} [المائدة: 44] ، قال في اليهود {ومن لم يحكم بما أنزل الله فأولئك هم الفاسقون} [المائدة: 47]","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:289","bookId":"nasikh-nahhas","type":"section","seq":289,"chapter":"ص: 48","title":"ص: 401","page":"ج1 ص398","text":"قال في اليهود {ومن لم يحكم بما أنزل الله فأولئك هم الظالمون} [المائدة: 45] قال في الكفار خاصة فأمر رسول الله صلى الله عليه وسلم باليهودي فرجم، وقال: «أنا أول من أحيا أمرك» فاحتجوا بأن النبي صلى الله عليه وسلم حكم بينهم ولم يتحاكموا إليه في هذا الحديث فإن قال قائل ففي حديث مالك، عن نافع، عن ابن عمر،: أن اليهود، أتوا النبي صلى الله عليه وسلم قيل له ليس في حديث مالك أيضا أن اللذين زنيا رضيا بالحكم وقد رجمهما النبي صلى الله عليه وسلم","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:290","bookId":"nasikh-nahhas","type":"section","seq":290,"chapter":"ص: 48","title":"ص: 402","page":"ج1 ص398","text":"فأما ما في الحديث من أن معنى {ومن لم يحكم بما أنزل الله فأولئك هم الكافرون} [المائدة: 44] أنه في اليهود ففي ذلك اختلاف قد ذكرناه وهذا أولى ما قيل فيه لأنه عن صحابي مشاهد للتنزيل يخبر أن بذلك السبب نزلت هذه الآية على أن غير الحسن بن محمد يقول فيه: عن النبي صلى الله عليه وسلم، في قوله {جل وعز ومن لم يحكم بما أنزل الله فأولئك هم الكافرون} قال اليهود غير أن حكم غيرهم كحكمهم فكل من حكم بغير ما أنزل الله جل وعز جاحدا له كما جحدت اليهود فهو كافر ظالم فاسق واختلفوا في الآية السابعة فمنهم من قال: هي منسوخة ومنهم من قال: هي محكمة وهي من أشكل ما في الناسخ والمنسوخ","bab":"باب ذكر الآية السادسة قال جل وعز: {فإن جاءوك فاحكم بينهم أو أعرض عنهم} من العلماء من قال هذه الآية محكمة والإمام مخير إذا تحاكم إليه أهل الكتاب إن شاء حكم بينهم"},{"id":"nasikh-nahhas:291","bookId":"nasikh-nahhas","type":"section","seq":291,"chapter":"ص: 48","title":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إ","page":"ج1 ص400","text":"في السفر إذا كانت وصية وقال قوم كان هذا هكذا ثم نسخ ولا تجوز شهادة كافر بحال وقال قوم الآية كلها في المسلمين إذا شهدوا فهذه ثلاثة أقوال والقول الرابع: أن هذا ليس في الشهادة التي تؤدى وإنما الشهادة هاهنا بمعنى الحضور والقول الخامس: أن الشهادة هاهنا بمعنى اليمين فالقول الأول: عن رجلين من الصحابة عبد الله بن قيس","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:292","bookId":"nasikh-nahhas","type":"section","seq":292,"chapter":"ص: 48","title":"ص: 404","page":"ج1 ص400","text":"، وعبد الله بن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة عن ابن عباس، قال: وقوله جل وعز: {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم} [المائدة: 106] \" فهذا لمن مات وعنده المسلمون فأمره الله تعالى أن يشهد على وصيته عدلين من المسلمين، ثم قال تعالى: {أو آخران من غيركم إن أنتم ضربتم في الأرض فأصابتكم مصيبة الموت} [المائدة: 106] فهذا لمن مات وليس عنده أحد من المسلمين فأمره الله تعالى بشهادة رجلين من غير المسلمين فإن ارتيب بشهادتهما استحلفا بعد الصلاة بالله تعالى لم نشتر بشهادتنا ثمنا قليلا، فإن اطلع الأولياء على أن الكافرين كذبا حلفا بالله جل وعز أن شهادة الكافرين باطلة وأنا لم نعتد فذلك قوله جل وعز {فإن عثر على أنهما استحقا إثما فآخران يقومان مقامهما من الذين استحق عليهم الأوليان} [المائدة: 107] يقول إذا اطلع على أنهما كذبا قام الأوليان فحلفا أنهما كذبا يقول الله تعالى {ذلك أدنى} [المائدة: 108] أن يأتي الكافران {بالشهادة على وجهها أو يخافوا أن ترد أيمان بعد أيمانهم} [المائدة: 108] فتترك شهادة الكافرين ويحكم بشهادة الأولياء","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:293","bookId":"nasikh-nahhas","type":"section","seq":293,"chapter":"ص: 48","title":"ص: 405","page":"ج1 ص403","text":"وليس على شهود المسلمين إقسام إنما الإقسام إذا كانا كافرين \" فهذا قول ابن عباس مشروحا مبينا لا يحتاج إلى زيادة شرح، وقال به من التابعين جماعة منهم شريح قال تجوز شهادة أهل الكتاب على المسلمين في السفر إذا كانت وصية وهو قول سعيد بن المسيب، وسعيد بن جبير، وعبيدة ومحمد بن سيرين، والشعبي، ويحيى بن يعمر، وقتادة، والسدي، وقال به من الفقهاء سفيان الثوري ومال إليه أبو عبيدة لكثرة من قال به والقول الثاني إن الآية منسوخة وإنه لا تجوز شهادة كافر بحال كما لا تجوز شهادة فاسق قول زيد بن أسلم، ومالك بن أنس، والشافعي وقول أبي حنيفة أيضا أنها منسوخة ولا تجوز عنده شهادة","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:294","bookId":"nasikh-nahhas","type":"section","seq":294,"chapter":"ص: 48","title":"ص: 406","page":"ج1 ص403","text":"الكفار على المسلمين غير أنه خالف من تقدم ذكره بأنه أجاز شهادة الكفار بعضهم على بعض والقول الثالث: إن الآية كلها في المسلمين لا منسوخ فيها قول الحسن، والزهري\nكما قرئ على عبد الله بن الصقر، عن زياد بن أيوب، عن هشيم، قال: أخبرنا منصور، وغيره، عن الحسن، في قول الله تعالى {أو آخران من غيركم} [المائدة: 106] ، قال: «من غير عشيرتكم» والقول الرابع إن الشهادة هاهنا بمعنى الحضور يحتج قائله بما يعارض به تلك الأقوال مما سنذكره وكذا القول الخامس إن الشهادة بمعنى اليمين كما قال الله تعالى {فشهادة أحدهم أربع شهادات بالله} [النور: 6] فأما المعارضة في القول الأول فنص كتاب الله تعالى قال جل ثناؤه {ممن ترضون من الشهداء} [البقرة: 282] وقال تعالى: {وأشهدوا ذوي عدل منكم} [الطلاق: 2] ولا يرضى الكفار ولا يكونون ذوي عدل ويعارض بالإجماع لأنه قد أجمع المسلمون أن شهادة الفساق لا تجوز والكفار فساق وأجمعوا أيضا أن شهادة الكفار لا تجوز على المسلمين في غير هذا الموضع الذي قد اختلف فيه فيرد ما اختلف فيه إلى ما أجمع عليه وهذه احتجاجات بينة","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:295","bookId":"nasikh-nahhas","type":"section","seq":295,"chapter":"ص: 48","title":"ص: 407","page":"ج1 ص404","text":"واحتج من خالفها بكثرة من قال ذلك القول وأنه قد قاله صحابيان وليس ذلك في غيره ومخالفة الصحابة إلى غيرهم ينفر منه أهل العلم قال فيجعل هذا على الضرورة كما تقصر الصلاة في السفر وكما يكون التيمم فيه والإفطار في شهر رمضان قيل له هذه الضرورات إنما تكون في الحال وليس كذا الشهادة وعورض من قال بنسخ الآية أنه لم يأت هذا عن أحد ممن شهد التنزيل وأيضا فإن في القولين جميعا شيئا من العربية غامضا وذلك أن معنى آخر في العربية آخر من جنس الأول تقول مررت بكريم وكريم آخر فقولك آخر يدل على أنه من جنس الأول ولا يجوز عند أهل العربية مررت بكريم وخسيس آخر ولا مررت برجل وحمار آخر فوجب من هذا أن يكون معنى اثنان ذوا عدل منكم أو آخران عدلان والكفار لا يكونون عدولا فيصح على هذا قول من قال من غيركم من غير عشيرتكم من المسلمين على أنه قد عورض لأن في أول الآية {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت} [المائدة: 106] فخوطب الجماعة من المؤمنين فيقال لمن عارض بهذا: هذا موجود في اللغة كثير يستغني عن الاحتجاج والقول الرابع: إن الشهادة بمعنى الحضور معروف في اللغة، وقد احتج قائله بأن الشاهد لا يكون عليه يمين في شيء من الأحكام غير هذا","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:296","bookId":"nasikh-nahhas","type":"section","seq":296,"chapter":"ص: 48","title":"ص: 408","page":"ج1 ص404","text":"المختلف فيه فيرد ما اختلف فيه إلى ما اجتمع عليه لأنه يقال شهدت وصية فلان أي حضرت والقول الخامس: أن الشهادة بمعنى اليمين معروف يكون التقدير فيه شهادة أحدكم أي يمين أحدكم أن يحلف اثنان وحقيقته في العربية: يمين اثنين مثل {واسأل القرية} [يوسف: 82]\nقرئ على علي بن سعيد بن بشير الرازي، عن صالح بن عبد الله الترمذي، قال حدثنا يحيى بن أبي زائدة، عن محمد بن أبي القاسم، عن عبد الملك بن سعيد بن جبير، عن أبيه، عن ابن عباس، قال: \" كان تميم الداري، وعدي بن بداء يختلفان إلى مكة للتجارة فخرج معهم رجل من بني سهم فتوفي بأرض ليس بها مسلم فأوصى إليهما فدفعا تركته إلى أهله وحبسا جاما من فضة مخوصا بالذهب ففقده أولياء السهمي من تركته فأتوا رسول الله صلى الله عليه وسلم فاستحلفهما رسول الله صلى الله عليه وسلم ما كتمنا ولا اطلعنا ثم عرف الجام بمكة فقالوا: اشتريناه من تميم، وعدي فقام رجلان من أولياء السهمي فحلفا بالله تعالى: إن هذا لجام السهمي ولشهادتنا أحق من شهادتهما وما اعتدينا أنا إذا لمن الظالمين فأخذ الجام وفيهم نزلت هذه الآية \"\nوقرئ على علي بن سعيد بن بشير، عن أبي مسلم الحسن بن أحمد بن أبي شعيب الحراني، قال: حدثنا محمد بن سلمة، قال: حدثنا محمد بن إسحاق، عن أبي النضر، عن زاذان، مولى أم هانئ بنت أبى طالب، عن ابن عباس، عن تميم الداري، في قوله تعالى {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت} [المائدة: 106] قال: \" برئ الناس منها غيري وغير عدي بن بداء وكانا نصرانيين يختلفان إلى الشام قبل الإسلام فأتيا الشام لتجارتهما وقدم عليهما مولى لبني سهم يقال له برير بن أبي مريم لتجارة ومعه جام من فضة يريد به الملك وهو عظم تجارته فمرض فأوصى إليهما وأمرهما أن يبلغا ما ترك أهله، قال تميم: فلما مات أخذنا ذلك الجام فبعناه بألف درهم ثم اقتسمناه أنا وعدي بن بداء فلما قدمنا إلى أهله دفعنا إليهم ما كان معنا، وفقدوا الجام فسألوا عنه فقلنا ما ترك غير هذا وما دفع إلينا غيره قال: فلما أسلمت بعد قدوم رسول الله صلى الله عليه وسلم المدينة تأثمت من ذلك فأتيت أهله فأخبرتهم الخبر وأديت إليهم خمسمائة درهم وأخبرتهم أن عند صاحبي مثلها فوثبوا إليه فأتوا به رسول الله صلى الله عليه وسلم فسألهم البينة فلم يجدوا فأمرهم أن يستحلفوه بما يعظم به على أهل دينه فحلف فأنزل الله تعالى {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية} [المائدة: 106]","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:297","bookId":"nasikh-nahhas","type":"section","seq":297,"chapter":"ص: 48","title":"ص: 410","page":"ج1 ص408","text":"قرأ إلى قوله تعالى {أن ترد أيمان بعد أيمانهم} [المائدة: 108] فقام عمرو بن العاص ورجل آخر منهم فحلفا فنزعت الخمسمائة درهم من عدي بن بداء \" قال أبو جعفر: فهذا ما في الآية وما بعدها من القصة من الآثار واختلاف العلماء والنظر ثم نبينهما على ما هو أصح من ذلك الذي ذكرناه قال أبو جعفر: الأبين في هذا أن تكون شهادة بينكم قسم بينكم إذا حضر أحدكم الموت حين الوصية أن يقسم اثنان ذوا عدل منكم أو آخران من غيركم وللعلماء في أو هنا قولان فمنهم من قال أو هاهنا للتعقيب وأنه إذا وجد اثنين ذوي عدل من المسلمين لم يجز له أن يشهد كافرين وهذا القول يروى عن سعيد بن المسيب، وسعيد بن جبير، والشعبي، وإبراهيم، وقتادة","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:298","bookId":"nasikh-nahhas","type":"section","seq":298,"chapter":"ص: 48","title":"ص: 411","page":"ج1 ص408","text":"ومنهم من قال أو هاهنا للتخيير لأنها إنما هي وصية وقد يكون الموصي يرى أو يسند وصيته إلى كافرين أو أجنبيين وهذا القول أن أو للتخيير هو القول البين الظاهر {إن أنتم ضربتم في الأرض} [المائدة: 106] قال ابن زيد: «أي سافرتم وكذا هو في اللغة وفي الكلام حذف مستدل عليه أي إن أنتم سافرتم فأصابتكم مصيبة الموت وقد أسندتم وصيتكم إلى اثنين ذوي عدل منكم أو آخرين من غيركم فإن ارتبتم أي اتهمتم الوصيين والتقدير أو آخرين من غيركم إن ارتبتم تحبسونهما من بعد الصلاة» واختلف العلماء في هذه الصلاة فقال أكثرهم هي العصر فممن قال هذا عبد الله بن قيس الأشعري واستعمله وقضى به وهو قول سعيد بن المسيب، وسعيد بن جبير، وإبراهيم، وقتادة ومنهم من قال: هي صلاة من صلواتهم في دينهم وهذا قول السدي وهو يروى عن ابن عباس، والقول الأول أولى لقوله تعالى من بعد الصلاة فجاءت","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:299","bookId":"nasikh-nahhas","type":"section","seq":299,"chapter":"ص: 48","title":"ص: 412","page":"ج1 ص408","text":"معرفة بالألف واللام وإذا كان بعد صلاة من صلواتهم كانت نكرة، وقد صح عن النبي صلى الله عليه وسلم أنه لاعن بين العجلانيين بعد العصر فخصها بهذا ويقال إن أهل الكتاب أيضا يعظمون ذلك الوقت فيقسمان بالله وهما الوصيان ولا نشتري به ثمنا أي لا نشتري بقسمنا شيئا نأخذه مما أوصى به ولا ندفعه إلى أحد لو كان ذا قربى، ولا نكتم شهادة الله أي ولا نكتم شهادة الله عندنا إنا إذا لمن الآثمين أي إن فعلنا ذلك {فإن عثر على أنهما استحقا إثما} [المائدة: 107] أصله من عثرت بالشيء أي وقعت عليه أي فإن وقع على أنهما استوجبا إثما بكذبهما في أيمانهما وأخذهما ما ليس لهما فآخران يقومان مقامهما أي في الأيمان من الذين استحق عليهم الأوليان تقدير هذا في العربية مختلف عند جماعة من العلماء فمنهم من قال التقدير من الذين استحق منهم الأوليان وعليهم بمعنى منهم مثل: {إذا اكتالوا على الناس يستوفون} [المطففين: 2] ومنهم من قال عليهم بمعنى فيهم أي من الذين استحق فيهم إثم الأوليين ثم حذف إثم مثل: {واسأل القرية} [يوسف: 82] وهذا قول محمد بن جرير وقال إبراهيم بن السري التقدير من الذين استحق عليهم الإيصاء والأوليان بدل من قوله جل وعز: {فآخران} [المائدة: 107]","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:300","bookId":"nasikh-nahhas","type":"section","seq":300,"chapter":"ص: 48","title":"ص: 413","page":"ج1 ص408","text":"قال أبو جعفر: وهذا من أحسن ما قيل فيه لأنه لا يجعل حرفا بدلا من حرف وأيضا فإن التفسير عليه لأن المعنى عند أهل التفسير من الذين استحقت عليهم الوصية والأوليان قراءة علي بن أبي طالب رضي الله عنه وكثير من القراء وقراءة يحيى بن وثاب، والأعمش، وحمزة الإولين وفيها من البعد ما لا خفاء به والأولين بدل من الذين فيقسمان بالله لشهادتنا أحق من شهادتهما أي لقسمنا، فصح أن معنى الشهادة هاهنا القسم وما اعتدينا أي وما تجاوزنا الحق في قسمنا إنا إذا لمن الظالمين أي إن كنا حلفنا على باطل وأخذنا ما ليس لنا وصح من هذا كله أن الآية غير منسوخة ودل الحديث على ذلك لأنه إذا أوصى رجل إلى آخر فاتهم الورثة الموصى إليه حلف الموصى إليه وبرئ فإن اطلع على أن الموصى إليه خان وذلك أن يشهد شاهد أو يوجد شيء يعلم أنه للميت فيقول الموصى إليه قد اشتريته منه فيحلف الوارث ويستحقه فقد بين الحديث أن المعنى على هذا وإن كان العلماء قد تكلموا في استحلاف الشاهدين هاهنا لمن وجب فمنهم من قال: لأنهما ادعيا وصية من الميت وهو قول يحيى بن يعمر","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:301","bookId":"nasikh-nahhas","type":"section","seq":301,"chapter":"ص: 48","title":"ص: 414","page":"ج1 ص408","text":"وهذا لا يعرف في حكم الإسلام أن يدعي رجل وصية فيحلف ويأخذها ومنهم من قال إنما يحلفان إذا شهدا أن الميت أوصى بما لا يجوز أو بماله كله أو لبعض الورثة وهذا أيضا لا يعرف في الأحكام أن يحلف الشاهد إذا شهد أن الموصى أوصى بما لا يجوز ومنهم من قال إنما يحلفان إذا اتهما ثم تنقل اليمين عنهما إذا اطلع على الخيانة كما ذكرنا ثم قال تعالى: {ذلك أدنى} [المائدة: 108] أي أقرب {أن يأتوا بالشهادة على وجهها} [المائدة: 108] وهما الموصى إليهما أو يخافوا {أن ترد أيمان بعد أيمانهم} [المائدة: 108] وهي أيمان الأوليين أي الأوليين باليمين لما ظهرت خيانة الموصى إليهما، وقيل هما الأوليان بالميت {واتقوا الله واسمعوا والله لا يهدي القوم الفاسقين} [المائدة: 108] أي اسمعوا ما يقال لكم قابلين له متبعين أمرالله تعالى فيه {والله لا يهدي القوم الفاسقين} [المائدة: 108] أي الخارجين عن طاعة الله جل وعز وقال ابن زيد «كل فاسق مذكور في القرآن فمعناه الكاذب»","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:302","bookId":"nasikh-nahhas","type":"section","seq":302,"chapter":"ص: 48","title":"سورة الأنعام","page":"ج1 ص409","text":"قال أبو جعفر حدثني يموت بن المزرع، قال: حدثنا أبو حاتم سهل بن محمد السجستاني، قال: حدثنا أبو عبيدة معمر بن المثنى التيمي، قال: حدثنا يونس بن حبيب، قال سمعت أبا عمرو بن العلاء، يقول سألت مجاهدا عن تلخيص آي القرآن المدني من المكي فقال سألت ابن عباس عن ذلك فقال: \" سورة الأنعام نزلت بمكة جملة واحدة فهي مكية إلا ثلاث آيات منها نزلت بالمدينة فهي مدنية {قل تعالوا أتل ما حرم ربكم عليكم} [الأنعام: 151] إلى تمام الآيات الثلاث \" قال أبو جعفر: وإذا كانت سورة الأنعام مكية لم يصح قول من قال معنى {وآتوا حقه يوم حصاده} [الأنعام: 141] للزكاة المفروضة لأن الزكاة إنما فرضت بالمدينة وهذا يشرح في موضعه وإذا كانت السورة مكية فلا يكاد يكون فيها آية ناسخة","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:303","bookId":"nasikh-nahhas","type":"section","seq":303,"chapter":"ص: 48","title":"ص: 416","page":"ج1 ص415","text":"وما تقدم من السور فهن مدنيات أعني سورة البقرة وآل عمران والنساء والمائدة حدثني يموت بذلك الإسناد بعينه وفي سورة الأنعام آيات قد ذكرت في الناسخ والمنسوخ فالآية الأولى: منها قوله تعالى {قل لست عليكم بوكيل} [الأنعام: 66]\nقال أبو جعفر حدثنا أبو الحسن عليل بن أحمد، قال: حدثنا محمد بن هشام بن أبي خيرة، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، في قوله تعالى {قل لست عليكم بوكيل} [الأنعام: 66] قال: \" نسخ هذا آية السيف {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" قال أبو جعفر: هذا خبر لا يجوز أن ينسخ ومعنى: وكيل حفيظ ورقيب والنبي صلى الله عليه وسلم ليس هو عليهم بحفيظ إنما عليه أن ينذرهم وعقابهم إلى الله عز وجل، والآية الثانية نظيرها","bab":"باب ذكر الآية السابعة قال الله جل وعز {يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم} [المائ"},{"id":"nasikh-nahhas:304","bookId":"nasikh-nahhas","type":"section","seq":304,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال الله عز وجل {وما على الذين يتقون من حسابهم من شيء}","page":"ج1 ص416","text":"[الأنعام: 69]\nحدثنا أبو الحسن عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، في قول الله تعالى {وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون} [الأنعام: 69] قال:: \" هذه مكية نسخت بالمدينة بقوله تعالى {وقد نزل عليكم في الكتاب أن إذا سمعتم آيات الله يكفر بها ويستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره} [النساء: 140] فنسخ هذا ما قبله وأمر المؤمنون أن لا يقعدوا مع من يكفر بالقرآن ويستهزئ به \" قال أبو جعفر: {وما على الذين يتقون من حسابهم من شيء} [الأنعام: 69] خبر ومحال نسخه والمعنى فيه بين ليس على من اتقى الله تعالى إذا نهى إنسانا عن منكر من حسابه شيء الله مطالبه ومعاقبه وعليه أن ينهاه ولا يقعد معه راضيا بقوله وفعله وإلا كان مثله، وهذان الحديثان وإن كانا عن ابن عباس فإنهما من حديث جويبر، والآية الثالثة قريبة منهما","bab":"باب ذكر الآية الثانية قال الله عز وجل {وما على الذين يتقون من حسابهم من شيء}"},{"id":"nasikh-nahhas:305","bookId":"nasikh-nahhas","type":"section","seq":305,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز: {وذر الذين اتخذوا دينهم لعبا ولهوا}","page":"ج1 ص417","text":"[الأنعام: 70]\nقال أبو جعفر حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة: {وذر الذين اتخذوا دينهم لعبا ولهوا} [الأنعام: 70] قال: \" نسخها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" قال أبو جعفر: هذا ليس بخبر وهو يحتمل النسخ غير أن البين فيه أنه ليس بمنسوخ وأنه على معنى التهديد لمن فعل هذا أي: ذره فإن الله تعالى مطالبه ومعاقبه ومثله {ذرهم في خوضهم يلعبون} [الأنعام: 91] والصحيح في الآية الرابعة أنها منسوخة","bab":"باب ذكر الآية الثالثة قال جل وعز: {وذر الذين اتخذوا دينهم لعبا ولهوا}"},{"id":"nasikh-nahhas:306","bookId":"nasikh-nahhas","type":"section","seq":306,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كل","page":"ج1 ص418","text":"خمسة أقوال: منهم من قال: هي منسوخة بالزكاة المفروضة ومنهم من قال: هي منسوخة بالسنة العشر ونصف العشر، ومنهم من قال يعني بهذا الزكاة المفروضة ومنهم من قال: هي محكمة واجبة يراد بها غير الزكاة ومنهم من قال: هي على الندب فممن قال: إنها منسوخة بالزكاة المفروضة سعيد بن جبير\nحدثنا أبو جعفر قال: كما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا الوليد بن صالح، قال: أخبرنا شريك، عن سالم، عن سعيد بن جبير، في قول الله تعالى {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «كان هذا قبل أن تنزل الزكاة كان الرجل يبدأ بعلف الدابة وبالشيء»","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:307","bookId":"nasikh-nahhas","type":"section","seq":307,"chapter":"ص: 48","title":"ص: 420","page":"ج1 ص419","text":"وهذا قول أبي جعفر محمد بن علي، وعكرمة وقال الضحاك نسخت الزكاة كل صدقة في القرآن وممن قال نسخت الآية بقول النبي عليه السلام بالعشر ونصف العشر ابن عباس فيما روي عنه\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا فهد، قال: حدثنا محمد بن سعيد، قال: حدثنا الحجاج، عن الحكم، عن مقسم، عن ابن عباس، في قوله تعالى: {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «نسختها العشر ونصف العشر»\nوقرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح، قال: أخبرنا الثوري، عن مغيرة، عن شباك، عن","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:308","bookId":"nasikh-nahhas","type":"section","seq":308,"chapter":"ص: 48","title":"ص: 421","page":"ج1 ص420","text":"إبراهيم، {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «نسختها العشر ونصف العشر» وهذا قول محمد بن الحنفية، والسدي وممن قال: إنها الزكاة المفروضة أنس بن مالك\nكما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أبو حفص، قال: حدثنا عبد الصمد، قال: حدثنا يزيد بن درهم، عن أنس بن مالك، {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «الزكاة»\nوقرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح بن عبادة قال: أخبرنا شعبة، عن أبي رجاء، قال سألت الحسن عن قول الله، تعالى {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «الزكاة المفروضة»","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:309","bookId":"nasikh-nahhas","type":"section","seq":309,"chapter":"ص: 48","title":"ص: 422","page":"ج1 ص421","text":"قال أبو جعفر: وهذا قول سعيد بن المسيب، وجابر بن زيد، وعطاء، وقتادة، وزيد بن أسلم\nقال: وحدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، في قول الله تعالى {وآتوا حقه يوم حصاده} [الأنعام: 141] : «أن ذلك الزكاة والله تعالى أعلم» وقد سمعت من يقول ذلك قال أبو جعفر: وقد قيل إن هذا أيضا قول الشافعي على التأويل لأنه لا يقول في معنى {وآتوا حقه يوم حصاده} [الأنعام: 141] لا يخلو من أن يكون ذلك في وقت الحصاد أو بعده وبينت السنة أنه بعده وقد قيل بل يجب على قول للشافعي أن تكون منسوخة لأنه يقول ليس في الرمان زكاة ولا في شيء من الثمار إلا في النخل، والكرم وفي نص الآية ذكر الرمان والزيتون وقد قال بمصر ليس في الزيتون زكاة لأنه أدم فهذه ثلاثة أقوال والقول الرابع أن في المال حقا سوى الزكاة وإن معنى {وآتوا حقه يوم حصاده} [الأنعام: 141] أن يعطي منه شيئا سوى الزكاة وأن يخلي بين المساكين وبين ما سقط\nكما حدثنا محمد بن جعفر الأنباري، قال: حدثنا الحسن بن عفان، قال: حدثنا يحيى بن اليمان، عن سفيان، قال: «يدع المساكين يتبعون أثر الحصاد فما سقط عن المنجل أخذوه» وهذا قول جماعة من أهل العلم منهم جعفر بن محمد وقد روي وصح عن علي بن الحسين رضي الله عنه أنه أنكر حصاد الليل من أجل هذا\nوقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا حفص، قال: أخبرنا أشعث، عن نافع، عن ابن عمر، {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «كانوا يعطون من اعتر بهم» وهذا أيضا قول","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:310","bookId":"nasikh-nahhas","type":"section","seq":310,"chapter":"ص: 48","title":"ص: 424","page":"ج1 ص423","text":"مجاهد ومحمد بن كعب وعطية وهو قول أبي عبيد واحتج بحديث النبي صلى الله عليه وسلم: «أنه نهى عن حصاد الليل» والقول الخامس: أن يكون معنى، {وآتوا حقه يوم حصاده} [الأنعام: 141] على الندب وهذا القول لا يعرف أحدا من المتقدمين قاله وإذا تكلم أحد من المتأخرين في معنى آية من القرآن قد تقدم كلام المتقدمين فيها فخرج عن قولهم لم يلتفت إلى قوله ولم يعد خلافا فبطل هذا، وأما القول بأنها الصدقة المفروضة فيعارض بأشياء منها أن هذه السورة مكية والزكاة فرضت بالمدينة لا تنازع بين أهل العلم في ذلك، ومنها أن قوله تعالى {يوم حصاده} [الأنعام: 141] لو كان للزكاة المفروضة وجب أن تعطى وقت الحصاد وقد جاءت السنة وصحت أن الزكاة لا تعطى إلا بعد الكيل وأيضا فإن في الآية {ولا تسرفوا إنه لا يحب المسرفين} [الأنعام: 141] فكيف يكون هذا في الزكاة وهي معلومة وأيضا فلو كان هذا في الزكاة لوجب أن تكون الزكاة في كل الثمر وفي كل ما أنبتت الأرض وهذا لا يقوله أحد نعلمه من الصحابة ولا التابعين ولا الفقهاء إلا بعض المتأخرين ممن خرج عن الإجماع","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:311","bookId":"nasikh-nahhas","type":"section","seq":311,"chapter":"ص: 48","title":"ص: 425","page":"ج1 ص423","text":"وأكثر ما قيل في هذا من قول من يحتج بقوله قول أبي حنيفة أن في كل هذا الزكاة إلا في الحطب والحشيش والقصب وقد أخرج شيئا مما في الآية ولم يختلف العلماء أن في أربعة أشياء منها الزكاة: الحنطة، والشعير، والتمر، والزبيب فهذا إجماع وجماعة من العلماء يقولون لا تجب الزكاة فيما أخرجت الأرض إلا في أربعة أشياء: الحنطة، والشعير، والتمر والزبيب فممن قال هذا الحسن ومحمد بن سيرين والشعبي وابن أبي ليلى","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:312","bookId":"nasikh-nahhas","type":"section","seq":312,"chapter":"ص: 48","title":"ص: 426","page":"ج1 ص423","text":"، وسفيان الثوري، والحسن بن صالح، وعبد الله بن المبارك، ويحيى بن آدم وأبو عبيد واحتج أبو عبيد بحديث الثوري عن طلحة بن يحيى عن أبي بردة إن معاذا وأبا موسى لما بعثا ليعلما الناس أمر دينهم لم يأخذا الزكاة فيما أخرجت الأرض إلا من هذه الأربعة واحتج غيره أن أموال المسلمين محظورة، فلما أجمع على هذه الأشياء وجبت بالإجماع ولما وقع الاختلاف في غيرها لم يجب فيها شيء وزاد ابن عباس على هذه الأربعة السلت والزيتون وزاد الزهري على هذه الأربعة الأشياء الزيتون والحبوب كلها وهذا قول عطاء، وعمر بن عبد العزيز، ومكحول، ومالك بن أنس وهو قول الأوزاعي، والليث في الزيتون الزكاة قال أبو جعفر: وهذا القول كان قول الشافعي بالعراق ثم قال بمصر في الزيتون لا أرى أن تجب فيه الزكاة لأنه أدم لا أنه يؤكل بنفسه وقال يعقوب، ومحمد فيما بعد الأربعة كل ما يؤكل ويبقى ففيه","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:313","bookId":"nasikh-nahhas","type":"section","seq":313,"chapter":"ص: 48","title":"ص: 427","page":"ج1 ص423","text":"الزكاة فهذه الأقوال كلها تدل على أن الآية منسوخة لأنه ليس أحد منهم أوجب الزكاة في كل ما ذكر في الآية وأكثرهم اعتماده على الأشياء الأربعة فمن ضم إليها الحبوب وما يقتات به فإنما قاسه عليها ومن ضم إليها الزيتون فإنما قاسه على النخل والعنب هكذا قول الشافعي بالعراق قال أبو جعفر: وقد احتج من يذهب إلى أن الآية محكمة وأن ذلك حق في المال سوى الزكاة\nبما حدثنا أبو علي الحسن بن غليب، قال: حدثنا عمران بن أبي عمران، قال: حدثنا ابن لهيعة، عن دراج، عن أبي الهيثم، عن أبي سعيد الخدري، عن النبي صلى الله عليه وسلم في قول الله تعالى {وآتوا حقه يوم حصاده} [الأنعام: 141] قال: «ما سقط من السنبل»","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:314","bookId":"nasikh-nahhas","type":"section","seq":314,"chapter":"ص: 48","title":"ص: 428","page":"ج1 ص423","text":"قال أبو جعفر: وهذا الحديث لو كان مما تقوم به حجة لجاز أن يكون منسوخا كالآية وقد قامت الحجة بأنه لا فرض في المال سوى الزكاة إلا لمن تجب نفقته وثبت ذلك عن رسول الله صلى الله عليه وسلم\nكما حدثنا بكر بن سهل، قال حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن عمه أبي سهيل بن مالك، عن أبيه، أنه سمع طلحة بن عبيد الله، يقول: \" جاء رجل إلى رسول الله صلى الله عليه وسلم من أهل نجد ثائر الرأس نسمع لصوته دويا ولا نفقه ما يقول حتى دنا فإذا هو يسأل عن الإسلام فقال رسول الله صلى الله عليه وسلم: «خمس صلوات في اليوم والليلة» قال: هل علي غيرها؟ قال: «لا إلا أن تطوع» ، قال رسول الله صلى الله عليه وسلم: «وصيام رمضان» قال هل علي غيره؟ قال: «لا إلا أن تطوع» ، وذكر له رسول الله صلى الله عليه وسلم الزكاة فقال: هل علي غيرها؟ قال: «لا إلا أن تطوع» فأدبر الرجل وهو يقول: والله لا أزيد على هذا ولا أنقص منه فقال رسول الله صلى الله عليه وسلم: «أفلح إن صدق» فتبين بهذا الحديث مع صحة إسناده واستقامة طريقه أنه لا فرض على المسلمين من الصلاة إلا الخمس ولا من الصدقة إلا الزكاة فلما ثبت أنه لا يجب بالآية فرض سوى الزكاة وأنها ليست الزكاة وأنها ليست","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:315","bookId":"nasikh-nahhas","type":"section","seq":315,"chapter":"ص: 48","title":"ص: 429","page":"ج1 ص427","text":"ندبا لم يبق إلا أن تكون منسوخة فأما {ولا تسرفوا} [الأنعام: 141] فقد تكلم العلماء في معناه فقال سعيد بن المسيب معنى: \" {ولا تسرفوا} [الأنعام: 141] لا تمنعوا من الزكاة الواجبة\" وقال أبو العالية: \" كانوا إذا حصدوا أعطوا ثم تباروا في ذلك حتى أجحفوا فأنزل الله تعالى {ولا تسرفوا} [الأنعام: 141] \" وقال السدي: «لا تعطوا أموالكم فتقعدوا","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:316","bookId":"nasikh-nahhas","type":"section","seq":316,"chapter":"ص: 48","title":"ص: 430","page":"ج1 ص427","text":"فقراء» وقال ابن جريج: \" نزلت في ثابت بن قيس جد نخلا له فحلف أن لا يأتيه أحد ألا أعطاه فأمسى ليست له تمرة فأنزل الله عز وجل: {ولا تسرفوا إنه لا يحب المسرفين} [الأنعام: 141] \" وقال ابن زيد ولا تسرفوا للولاة أي ولا تأخذوا ما لا يجب على الناس قال أبو جعفر: وهذه الأقوال كلها غير متناقضة لأن الإسراف في اللغة فعل ما لا ينبغي فهذا كله داخل في أصل اللغة فواجب اجتنابه ومعنى {إنه لا يحب المسرفين} [الأنعام: 141] لا يثيبهم ولا يقبل أعمالهم مجازا، وتقدير {والزيتون والرمان} [الأنعام: 141] وشجر الزيتون والرمان مثل واسأل القرية قال قتادة «متشابها وغير متشابه يتشابه ورقه ويختلف ثمره» وقال غيره: يتشابه لونه ويختلف طعمه وقرأ يحيى بن وثاب {انظروا إلى ثمره} [الأنعام: 99] وهي قراءة حسنة لأنه قد ذكرت أشياء كثيرة فثمر جمع ثمار وثمار جمع ثمرة","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:317","bookId":"nasikh-nahhas","type":"section","seq":317,"chapter":"ص: 48","title":"ص: 431","page":"ج1 ص427","text":"قال محمد بن جرير أصل الإسراف في كلام العرب الإخطاء في إصابة غير الحق إما بزيادة وإما بنقصان من الحد الواجب، وأنشد\n[البحر البسيط]\nأعطوا هنيدة يحدوها ثمانية ... ما في عطائهم من ولا سرف\nأي خطأ واختلفوا في الآية الخامسة اختلافا كثيرا","bab":"باب ذكر الآية الرابعة قال جل وعز: {وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر "},{"id":"nasikh-nahhas:318","bookId":"nasikh-nahhas","type":"section","seq":318,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسق","page":"ج1 ص428","text":"الله صلى الله عليه وسلم الحمر الأهلية وكل ذي ناب من السباع وكل ذي مخلب من الطير نسخت هذه الأشياء منها وقالت طائفة: الآية محكمة ولا حرام من الحيوان إلا ما فيها وأحلوا ما ذكرنا وغيره من الحيوان وقالت طائفة: الآية محكمة وكل ما حرمه رسول الله صلى الله عليه وسلم داخل فيها وقالت طائفة هي محكمة وكل ما حرمه رسول الله صلى الله عليه وسلم مضموم إليها داخل في الاستثناء والقول الخامس: إن هذه الآية جواب لما سألوا عنه فأجيبوا عما سألوا، وقد حرم الله تعالى ورسوله صلى الله عليه وسلم غير ما في الآية قال أبو جعفر: القول الأول إنها منسوخة غير جائز لأن الأخبار لا تنسخ والقول الثاني: إنها جامعة لكل ما حرم وإحلال الحمر الإنسية وغيرها قول جماعة من العلماء منهم سعيد بن جبير، والشعبي ويقال إنه قول عائشة وابن عباس وثم أحاديث مسندة نبدأ بها\nفمن ذلك\nما حدثناه أحمد بن محمد الأزدي، قال: حدثنا فهد، قال: حدثنا أبو نعيم، قال: حدثنا شعبة، عن عبيد بن حسن، عن عبد الرحمن بن معقل، عن عبد الرحمن بن بشر، عن، رجال، من مزينة من أصحاب النبي صلى الله عليه وسلم من الظاهرة عن أبجر أو ابن أبجر أنه قال: يا رسول الله لم يبق لي شيء أستطيع أن أطعمه أهلي إلا حمر لي، قال: أطعم أهلك من سمين مالك فإنما كرهت لكم جوال القرية \" فاحتجوا بهذا الحديث في إحلال الحمر الأهلية وقالوا: إنما كرهها رسول الله صلى الله عليه وسلم لأنها كانت تأكل القذر كما كره الجلالة\nوحدثنا أحمد بن محمد الأزدي، قال حدثنا إسماعيل بن يحيى المزني، قال: حدثنا الشافعي، قال: أخبرنا عبد الوهاب بن عبد المجيد، عن أيوب السختياني، عن محمد بن سيرين، عن أنس بن مالك، أن رسول الله صلى الله عليه وسلم جاءه جاء","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:319","bookId":"nasikh-nahhas","type":"section","seq":319,"chapter":"ص: 48","title":"ص: 434","page":"ج1 ص433","text":"فقال: أكلت الحمر ثم جاءه جاء فقال: أكلت الحمر ثم جاءه جاء فقال: أفنيت الحمر فأمر رسول الله صلى الله عليه وسلم مناديا فنادى: إن الله جل وعز ورسوله صلى الله عليه وسلم ينهيانكم عن لحوم الحمر الأهلية فإنها رجس فكفئت القدور وإنها لتفور \" فهذا ما فيه من المسند، وأما ما جاء عن الصحابة\nفحدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا يزيد بن هارون، قال: أخبرنا يحيى بن سعيد، عن القاسم بن محمد، قال: كانت عائشة رحمها الله \" إذ ذكر لها النهي عن كل ذي ناب من السباع قالت: إن الله يقول: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة} [الأنعام: 145] الآية \" قال أبو جعفر: وهذا إسناد صحيح لا مطعن فيه\nقال: وحدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا شبابة، عن ورقاء، عن عمرو بن دينار، قال: «كان جابر بن عبد الله ينهى عن لحوم الحمر ويأمر بلحوم الخيل» وأبى ذلك ابن عباس وتلا {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه} [الأنعام: 145] \" حكى ذلك عمرو عن طاوس عن ابن عباس، وأما ما فيه عن التابعين\nفحدثنا أحمد بن محمد الأزدي، قال: حدثنا المزني، قال: حدثنا الشافعي، قال: أخبرنا سفيان، عن أبي","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:320","bookId":"nasikh-nahhas","type":"section","seq":320,"chapter":"ص: 48","title":"ص: 435","page":"ج1 ص434","text":"إسحاق، قال: ذكرت لسعيد بن جبير حديث ابن أبي أوفى في النهي عن لحوم الحمر فقال: «إنما كانت تلك الحمر تأكل القذر»\nوحدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا يحيى بن عباد، عن يونس، قال قلت للشعبي ما تقول في لحم الفيل؟ فقال: \" قال الله: {قل لا أجد فيما أوحي إلي محرما} الآية \" قال أبو جعفر: فهذه الأحاديث كلها تعارض بسنة رسول الله صلى الله عليه وسلم الثابتة عنه فأما معارضتها فإن الحديث المسند الذي فيه قول الرجل للنبي صلى الله عليه وسلم لم يبق لي شيء أطعمه أهلي إلا حمر لي قد يجوز أن تكون الحمر وحشية ويكون أكلها جائزا وقد يجوز أن يكون أحلها له على الضرورة كالميتة وأما الحديث الثاني حديث أنس الذي فيه من أمر النبي صلى الله عليه وسلم مناديا ينادي بما نادى به ففيه دليل على تحريمها وهو قوله فإنها رجس، فالرجس بالحرام أشبه منه بالحلال وفيه فكفئت القدور والحلال لا ينبغي أن يقلب والذي تأوله سعيد بن جبير يخالف فيه والذي روي عن عائشة وابن عباس يقال إن ابن عباس رجع عنه لما قال له","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:321","bookId":"nasikh-nahhas","type":"section","seq":321,"chapter":"ص: 48","title":"ص: 436","page":"ج1 ص434","text":"علي بن أبي طالب رضي الله عنه: إنك امرؤ تائه قد حرم رسول الله صلى الله عليه وسلم المتعة ولحوم الحمر الأهلية فرجع عن قوله، وقال بتحريم المتعة وأكل الحمر الأهلية ومع هذا فليس لأحد مع الرسول عليه السلام حجة ومع هذا فإن ابن عباس يقول: «لا يحل أكل لحوم الخيل فقد أخرج الخيل من الآية والحمر أولى» وقوله في الخيل قول مالك","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:322","bookId":"nasikh-nahhas","type":"section","seq":322,"chapter":"ص: 48","title":"ص: 437","page":"ج1 ص434","text":"، وأبي حنيفة والقول الثالث بأن الآية محكمة وأن المحرمات داخلة فيها قول نظري لأن التذكية إنما تؤخذ توقيفا فكل ما لم تؤخذ تذكيته بالتوقيف فهو ميتة داخل في الآية والقول الرابع: أن يضم إلى الآية ما صح عن النبي صلى الله عليه وسلم قول حسن فيكون داخلا في الاستثناء إلا أن يكون ميتة أو دما مسفوحا أو كذا أو كذا وهذا قول الزهري، ومالك بن أنس ألا ترى أن الزهري كان يقول بتحليل كل ذي ناب من السباع حتى قدم الشام فلقي أبا إدريس الخولاني فحدثه عن، أبي ثعلبة الخشني، عن النبي صلى الله عليه وسلم أنه حرم كل ذي ناب من السباع فرجع إلى قوله وكذا قال مالك لما سئل عن كل ذي مخلب من الطير فقال: ما أعلم فيه نهيا وهو عندي حلال","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:323","bookId":"nasikh-nahhas","type":"section","seq":323,"chapter":"ص: 48","title":"ص: 438","page":"ج1 ص434","text":"وقد صح عن النبي صلى الله عليه وسلم تحريم كل ذي مخلب من الطير غير أن الحديث لم يقع إلى مالك فعذر بذلك والقول الخامس: أن الآية جواب قول حسن صحيح وهو قريب من القول الذي قبله لأنها إذا كانت جوابا فقد أجيبوا عما سألوا عنه وثم محرمات لم يسألوا عنها فهي محرمة بحالها والدليل على أنها جواب أن قبلها {قل آلذكرين حرم أم الأنثيين} [الأنعام: 143] وما معه من الاحتجاج عليهم وهذا القول الخامس مذهب الشافعي وفي هذه السورة شيء قد ذكره قوم هو من الناسخ والمنسوخ بمعزل ولكنا نذكره ليكون الكتاب عام الفائدة قال جل وعز: {ولا تأكلوا مما لم يذكر اسم الله عليه وإنه لفسق} [الأنعام: 121] ففي هذه أربعة أقوال فمن الناس من قال: هي منسوخة بقوله","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:324","bookId":"nasikh-nahhas","type":"section","seq":324,"chapter":"ص: 48","title":"ص: 439","page":"ج1 ص434","text":"تعالى: {وطعام الذين أوتوا الكتاب حل لكم} [المائدة: 5] ، وهم يذكرون غير اسم الله على ذبائحهم ومنهم من قال: هي محكمة لا يحل أكل ذبيحة إلا أن يذكر اسم الله عليها فإن تركه تارك عامدا أو ناسيا لم تؤكل ذبيحته، والقول الثالث أن تؤكل إذا نسي أن يسمي والقول الرابع: أن تؤكل ذبيحة المسلم وإن ترك التسمية عامدا أو ناسيا فالقول الأول قول عكرمة قال في قول الله تعالى: {ولا تأكلوا مما لم يذكر اسم الله عليه} [الأنعام: 121] قال: فنسخ ذلك واستثنى منه فقال تعالى {اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم} [المائدة: 5] واحتج بعضهم لهذا القول: بأن القاسم بن مخيمرة سئل عن ذبيحة النصارى، هل تؤكل إذا سموا عليها بغير اسم الله تعالى فقال: نعم تؤكل ولو قالوا عليها باسم جرجس قال أبو جعفر: وهو قول مكحول، وعطاء قال: قد علم الله تعالى ذلك منهم وأباح ذبائحهم وهو قول ربيعة وهو يروى عن أبي الدرداء، وعبادة بن الصامت وهذا القول لو كان إجماعا لما وجب أن يكون فيه دليل على نسخ الآية ولكان استثناء على أنه قد صح عن جماعة من الصحابة كراهة ذلك منهم علي بن أبي طالب قال: إذا سمعته يقول باسم المسيح فلا تأكله فإنه مما أهل لغير الله به","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:325","bookId":"nasikh-nahhas","type":"section","seq":325,"chapter":"ص: 48","title":"ص: 440","page":"ج1 ص434","text":"، وإذا لم تسمع فكل لأنه قد أحل لك ذلك وهو قول عائشة وابن عمر وكره مالك ذلك ولم يحرمه والقول الثاني: إنه لا يحل أكل ما لم يذكر عليه اسم الله تعالى في العمد والنسيان قول الحسن، وابن سيرين، والشعبي وعارضه محمد بن جرير، وقال لو لم يكن من فساده إلا أن العلماء على غيره والجماعة لكان ذلك كافيا من فساده قال أبو جعفر: وقد ذكرنا من قال به من العلماء\nحدثنا أحمد بن محمد الأزدي، قال: حدثنا محمد بن خزيمة، قال حدثنا حجاج، قال: حدثنا حماد، عن داود، عن الشعبي، قال: {لا تأكلوا مما لم يذكر اسم الله عليه} [الأنعام: 121] \" وهذا أيضا مذهب أبي ثور والقول الثالث: إنه إذا ذبح فنسي التسمية أكلت ذبيحته، قول سعيد بن جبير، والنخعي، ومالك، وأبي حنيفة، ويعقوب، ومحمد والحجة لهم أن ظاهر الآية يوجب أن لا تؤكل ذبيحة من ترك ذكر اسم الله تعالى عامدا ولا ناسيا ألا ترى أن فيها {وإنه لفسق} [الأنعام: 121] فخرج بهذا النسيان لأنه لا يقال لمن نسي فسق","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:326","bookId":"nasikh-nahhas","type":"section","seq":326,"chapter":"ص: 48","title":"ص: 441","page":"ج1 ص435","text":"والقول الرابع إنه تؤكل ذبيحة المسلم وإن ترك التسمية عامدا غير متهاون، قول ابن عباس\nكما قرئ على أحمد بن شعيب بن علي، عن عمرو بن علي، قال: حدثنا يحيى القطان، قال: حدثنا سفيان، قال: حدثنا هارون بن أبي وكيع، عن أبيه، عن ابن عباس، في قوله جل وعز: {ولا تأكلوا مما لم يذكر اسم الله عليه} [الأنعام: 121] قال: \" خاصمهم المشركون فقالوا: «ما ذبح الله فلا تأكلونه وما ذبحتم أكلتموه» فهذا من أصح ما مر وهو داخل في المسند وخبر ابن عباس بسبب نزول هذه الآية فوجب أن يكون ما لم يذكر اسم الله عليه يعني به الميتة وما ذبحه المشركون غير أهل الكتاب وما ذبحه المسلمون وأهل الكتاب مأكول وإن لم يذكر عليه اسم الله جل وعز، واحتج ابن عباس فقال اسم الله تعالى مع المسلم وهذا القول هو الصحيح من قول الشافعي وقد حكى حيوة بن شريح عن، عقبة بن مسلم، أنه قال: \" يؤكل ما ذبحوا لكنائسهم لأنه من طعامهم الذي","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:327","bookId":"nasikh-nahhas","type":"section","seq":327,"chapter":"ص: 48","title":"ص: 442","page":"ج1 ص440","text":"أحله الله جل وعز لنا قال: فقلت له فقد قال الله تعالى: {وما أهل لغير الله به} [المائدة: 3] فقال: إنما ذلك ذبائح أهل الأوثان والمجوس \" وفي هذه السورة {وأعرض عن المشركين} [الأنعام: 106] روي عن، ابن عباس، قال: نسخ هذا {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية وقال غيره ليس هذا بنسخ إنما هذا من قولهم أعرضت عنه أي لم أنبسط إليه واشتقاقه من أوليته عرض وجهي وهذا واجب أن يستعمل مع المشركين وأهل المعاصي، قال جل وعز: {أذلة على المؤمنين أعزة على الكافرين} [المائدة: 54] وفي هذه السورة {إن الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء} [الأنعام: 159]\nحدثنا أبو جعفر حدثنا أبو الحسن عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، قال: حدثنا جويبر، عن الضحاك، عن ابن عباس، في قوله جل وعز: {إن الذين فرقوا دينهم} [الأنعام: 159] قال: \" اليهود والنصارى تركوا الإسلام والدين الذي أمروا به وكانوا شيعا فرقا أحزابا مختلفة {لست منهم في شيء} [الأنعام: 159] نزلت بمكة ثم نسخها {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة\n: 29] \" قال أبو جعفر: وقال غيره ليس في هذا نسخ لأنه معروف في اللغة أن يقال لست من فلان ولا هو مني إذا كنت مخالفا له منكرا عليه ما هو فيه وحكى سيبويه أنت مني فرسخا أي مادمت أسير فرسخا على أنه روى، أبو غالب، عن، أبي أمامة، عن النبي صلى الله عليه وسلم، في قول الله عز وجل {إن الذين فرقوا دينهم وكانوا شيعا} [الأنعام: 159] قال هم الخوارج وإن بني إسرائيل افترقت على إحدى وسبعين فرقة وتزيد هذه الأمة واحدة كلها في النار إلا فرقة واحدة وهي الجماعة والسواد الأعظم فتبين بهذا الحديث وبظاهر الآية أن الذين فرقوا دينهم وكانوا شيعا هم أهل البدع لأنهم إذا ابتدعوا تجادلوا وتخاصموا وتفرقوا فليس النبي صلى الله عليه وسلم ولا الفرقة الناجية وهي الجماعة الظاهرة منهم في شيء لأنهم منكرون عليهم ما هم فيه مخالفون لهم فهذا من الناسخ والمنسوخ بمعزل","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:328","bookId":"nasikh-nahhas","type":"section","seq":328,"chapter":"ص: 48","title":"سورة الأعراف","page":"ج1 ص443","text":"حدثنا يموت بن المزرع، قال: حدثنا أبو حاتم، قال: حدثنا أبو عبيدة، قال: حدثنا يونس بن حبيب، عن أبي عمرو بن العلاء، عن مجاهد، عن ابن عباس، قال: «وسورة الأعراف نزلت بمكة فهي مكية»\nقال أبو جعفر: لم نجد فيها مما يدخل في الناسخ والمنسوخ إلا آية واحدة مختلفا فيها قال جل وعز: {خذ العفو} [الأعراف: 199] فيها خمسة أقوال، من العلماء من قال: إنها منسوخة بالزكاة المفروضة، ومنهم من قال: هي منسوخة بالأمر بالغلظة على الكفار، ومنهم من قال: {خذ العفو} [الأعراف: 199] أي الزكاة المفروضة، ومنهم من قال: هو حق في المال سوى الزكاة ومنهم من قال: هو أمر بالاحتمال وترك الغلظة والفظاظة غير منسوخ فممن روي عنه أنها منسوخة بالزكاة ابن عباس قال: {خذ العفو} [الأعراف: 199] يقول خذ ما عفا وما أتوك به، قال: وكان هذا قبل أن تنزل براءة بفرض الزكاة وتفصيلها وجعلها في مواضعها وقال الضحاك: «نسخت الزكاة كل صدقة في القرآن»\nوحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم الحربي، قال: حدثنا حسين\nالأسود، عن عمرو، عن أسباط، عن السدي، {خذ العفو} [الأعراف: 199] قال: «الفضل من المال نسخته الزكاة» والقول الثاني: إنها منسوخة بالغلظة قول ابن زيد قال: {خذ العفو} [الأعراف: 199] فأقام النبي صلى الله عليه وسلم بمكة عشر سنين لا يعرض عن أحد ولا يقاتله ثم أمره الله تعالى أن يقعد لهم كل مرصد وأن لا يقبل منهم إلا الإسلام وأنزل {يا أيها النبي جاهد الكفار والمنافقين واغلظ عليهم} [التوبة: 73] وقال تعالى: {قاتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظة} [التوبة: 123] فنسخ هذا العفو والقول الثالث: إن العفو الزكاة قول مجاهد وكان إبراهيم بن محمد بن عرفة يميل إلى هذا القول قال: لأن الزكاة يسير من كثير والقول الرابع: إن العفو شيء في المال سوى الزكاة قول القاسم، وسالم قالا: هو فضل المال ما كان عن ظهر غنى\nوالقول الخامس قول عبد الله، وعروة ابني الزبير\nكما قرئ على أحمد بن شعيب، عن هارون بن إسحاق، قال: حدثنا عبدة، عن هشام بن عروة، عن أبيه، عن ابن الزبير، قال: \" إنما أنزل الله تعالى {خذ العفو} [الأعراف: 199] من أخلاق الناس \" وهذا أولى ما قيل في الآية لصحة إسناده وأنه عن صحابي يخبر بنزول الآية وإذا جاء الشيء هذا المجيء لم يسع أحدا مخالفته والمعنى عليه {خذ العفو} [الأعراف: 199] أي السهل من أخلاق الناس ولا تغلظ عليهم ولا تعنف بهم، وكذا كانت أخلاقه صلى الله عليه وسلم أنه ما لقي أحدا قط بمكروه في وجهه ولا ضرب أحدا بيده وقيل لعائشة رضي الله عنها ما كان خلق رسول الله صلى الله عليه وسلم الذي مدحه الله تعالى به، فقال: {وإنك لعلى خلق عظيم} [القلم: 4] فقالت: كان خلقه القرآن وزعم محمد بن جرير \" أن هذا أمر النبي صلى الله عليه وسلم في الكفار أمره بالرفق بهم واستدل على أنه في المشركين أن ما قبله وما بعده فيهم قال لأن قبله احتجاجا عليهم {قل ادعوا شركاءكم ثم كيدون فلا تنظرون} [الأعراف: 195] وبعده {وإخوانهم يمدونهم في الغي} [الأعراف: 202] \" وخالفه غيره فقال أمر النبي صلى الله عليه وسلم بالأخلاق السهلة اللينة لجميع","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:329","bookId":"nasikh-nahhas","type":"section","seq":329,"chapter":"ص: 48","title":"ص: 449","page":"ج1 ص448","text":"الناس، بل هذا للمسلمين أولى، وقد قال ابن الزبير وهو الذي فسر الآية: والله لأستعملن الأخلاق السهلة ما بقيت كما أمر الله تعالى وفي الآية {وأمر بالعرف} [الأعراف: 199] قال عروة، والسدي: «العرف المعروف» قال أبو جعفر: والذي قالاه معروف في اللغة يقال أولاني فلان معروفا وعرفا وعارفة وفي الحديث «العرف أن تعفو عمن ظلمك وتعطي من حرمك وتصل من قطعك» وهذا من كلام العرب ومن اختصار القرآن المعجز لأنه قد اجتمع في قوله تعالى وأمر بالعرف هذه الخصال الثلاث، ويدخل فيه الأمر بالمعروف والقبول عن الله تعالى ما أمر به وما ندب إليه هذا كله من العرف وفيها {وأعرض عن الجاهلين} [الأعراف: 199] زعم ابن زيد أن هذا منسوخ بالأمر بالقتال وقال غيره ليست بمنسوخة وإنما أمر باحتمال من ظلم، وما بعد هذه الآية أيضا يدل على أن القول كما قال ابن الزبير وأنه صلى الله عليه وسلم أمر بالسهل من الأخلاق وترك الغلظة لأن بعدها {وإما ينزغنك من الشيطان نزغ} [الأعراف: 200] أي وإما يغضبنك من الشيطان وسوسة وتحميل على ترك الاحتمال {فاستعذ بالله} [الأعراف: 200] أي فاستجر به مما عرض لك {إنه سميع} [الأعراف: 200] لاستجارتك وغيرها {عليم} [الأعراف: 200] بما يزيل عنك ما عرض لك","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:330","bookId":"nasikh-nahhas","type":"section","seq":330,"chapter":"ص: 48","title":"ص: 450","page":"ج1 ص448","text":"، وبعدها أيضا ما يدل على ما قال قال الله تعالى: {إن الذين اتقوا} [الأعراف: 201] أي اتقوا الله تعالى بأداء فرائضه وترك معاصيه {إذا مسهم طائف من الشيطان} [الأعراف: 201] أي عارض ووسواس منه {تذكروا} [الأعراف: 201] وعد الله ووعيده وعقابه {فإذا هم مبصرون} [الأعراف: 201] الحق آخذون بما أمرهم الله تعالى به من التحامل عند الغضب والغلظة على من قد نهوا عن الغلظة عليه","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:331","bookId":"nasikh-nahhas","type":"section","seq":331,"chapter":"ص: 48","title":"سورة الأنفال","page":"ج1 ص448","text":"حدثنا أبو جعفر، قال: حدثنا يموت، بإسناده عن ابن عباس، قال: \" ونزلت سورة الأنفال بالمدينة فهي مدنية، قال جل وعز: {يسألونك عن الأنفال} [الأنفال: 1] الآية للعلماء في هذه الآية خمسة أقوال، فأكثرهم على أنها منسوخة بقوله تعالى {واعلموا أنما غنمتم من شيء فأن لله خمسه} [الأنفال: 41] واحتج بعضهم بأنها لما كانت من أول ما نزل بالمدينة من قبل أن يؤمر بتخميس الغنائم وكان الأمر في الغنائم كلها إلى النبي صلى الله عليه وسلم وجب أن تكون منسوخة بجعل الغنائم حيث جعلها الله تعالى وقائلو هذا القول يقولون: الأنفال هاهنا الغنائم ويجعل بعضهم اشتقاقه من النافلة وهي الزيادة قال: فالغنائم أنفال لأن الله تعالى نفلها أمة محمد صلىالله عليه وسلم خصهم بذلك\n، وقال بعضهم ليست بمنسوخة وهي محكمة، وللأئمة أن يعملوا بها فينفلوا من شاءوا إذا كان في ذلك صلاح للمسلمين واحتجوا أن هذه هي الأنفال على الحقيقة لا الغنائم لأنها زيادات يزادها الرجل على غنيمته أو يزيدها الإمام من رأى والقول الثالث: إن الأنفال ما شذ من العدو من عبد أو دابة فللإمام أن ينفل ذلك من شاء إذا كان صلاحا والقول الرابع: إن الأنفال أنفال السرايا خاصة والقول الخامس: إن الأنفال الخمس خاصة سألوا لمن هو فأجيبوا بهذا قال أبو جعفر: فمن روي عنه القول الأول ابن عباس من رواية ابن أبي طلحة قال: الأنفال الغنائم التي كانت خالصة للنبي صلى الله عليه وسلم ليس لأحد فيها شيء ثم أنزل الله تعالى: {واعلموا أنما غنمتم من شيء} [الأنفال: 41] الآية وهو قول مجاهد\nكما حدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا حجاج، عن ابن جريج، قال: أخبرني سليم، مولى أبي علي عن مجاهد، قال: \" نسخت نسختها {واعلموا أنما غنمتم من شيء فأن لله خمسه} [الأنفال: 41] \" وهو قول عكرمة\nكما قرئ على","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:332","bookId":"nasikh-nahhas","type":"section","seq":332,"chapter":"ص: 48","title":"ص: 453","page":"ج1 ص452","text":"إبراهيم بن موسى الجوزي، عن يعقوب بن إبراهيم، قال: حدثنا وكيع، قال: حدثنا إسرائيل، عن جابر، عن مجاهد، وعكرمة، قالا: \" كانت الأنفال لله تعالى وللرسول صلى الله عليه وسلم ثم نسخ ذلك قوله تعالى: {واعلموا أنما غنمتم من شيء فأن لله خمسه} [الأنفال: 41] \" وهو أيضا قول الضحاك، والشعبي، والسدي وأكثر الفقهاء لأن أكثرهم يقول: لا يجوز للإمام أن ينفل أحدا شيئا من الغنيمة إلا من سهم النبي صلى الله عليه وسلم لأن الأسهم الأربعة قد صارت لمن شهد من الجيش الحرب، وكذا قال الشافعي في السهم الخامس سهم النبي صلى الله عليه وسلم يكون للأئمة والمؤذنين أي لما فيه صلاح المسلمين وكذا التنفيل منه فالقول على هذا أن الآية منسوخة إذا صارت الأنفال تقسم خمسة أقسام وإذا كان بعض الفقهاء يقول إنما تقسم ثلاثة أقسام، وبعضهم يقول: إنما ذكرت الأصناف التي يجب أن يقسم السهم فيها فإن دفع إلى بعضها جاز فهذا كله يوجب أن الآية منسوخة لأنهم قد أجمعوا أن الأربعة","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:333","bookId":"nasikh-nahhas","type":"section","seq":333,"chapter":"ص: 48","title":"ص: 454","page":"ج1 ص452","text":"الأسهم لمن شهد الحرب وإنما الاختلاف في السهم الخامس ومما يحقق أنها نسختها حديث سعد بن أبي وقاص في سبب نزولها\nكما قرئ على محمد بن عمرو بن خالد، عن أبيه، قال: حدثنا زهير بن معاوية، قال: حدثنا سماك بن حرب، قال حدثني مصعب بن سعد، عن أبيه، قال: \" أنزل في آيات وذكر الحديث فقال فيه وأصاب رسول الله صلى الله عليه وسلم غنيمة عظيمة فإذا فيها سيف فأخذته فأتيت به الرسول صلى الله عليه وسلم فقلت: نفلنيه فأنا من قد علمته، قال رده من حيث أخذته فانطلقت به حتى إذا أردت أن ألقيه في القبض لامتني نفسي فرجعت إلى النبي صلى الله عليه وسلم فقلت: أعطنيه قال: فشد صوته وقال رده من حيث أخذته، فأنزل الله تعالى {يسألونك عن الأنفال قل الأنفال لله والرسول} [الأنفال: 1] الآية","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:334","bookId":"nasikh-nahhas","type":"section","seq":334,"chapter":"ص: 48","title":"ص: 455","page":"ج1 ص452","text":"وحكى أبو جعفر بن رشدين عن عمرو بن خالد قال: «القبض الموضع الذي يجمع الغزاة فيه ما غنموا»\nوقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال حدثني عبد الله بن وهب، قال: أخبرني أبو صخر، عن القرظي، قال أبو صخر، وحدثني أبو معاوية البجلي، عن سعيد بن جبير،: \" أن سعدا، ورجلا، من الأنصار خرجا يتنفلان فوجدا سيفا ملقى فخرا عليه جميعا فقال سعد: هو لي وقال الأنصاري: هو لي، قال لا أسلمه حتى آتي رسول الله صلى الله عليه وسلم فقصا عليه القصة فقال رسول الله صلى الله عليه وسلم ليس لك يا سعد ولا للأنصاري ولكنه لي، فنزلت","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:335","bookId":"nasikh-nahhas","type":"section","seq":335,"chapter":"ص: 48","title":"ص: 456","page":"ج1 ص454","text":"{يسألونك عن الأنفال قل الأنفال لله والرسول فاتقوا الله وأصلحوا ذات بينكم وأطيعوا الله ورسوله إن كنتم مؤمنين} [الأنفال: 1] \" يقول سلما السيف إلى رسول الله صلى الله عليه وسلم ثم نسخت هذه الآية فقال جل وعز {واعلموا أنما غنمتم من شيء فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل} [الأنفال: 41] إلى آخر الآية قال أبو جعفر: هذه الزيادة حسنة وإن كانت غير متصلة فإنها عن سعد في سبب نزول الآية ثم ذكر نسخها وقد سمعت أحمد بن محمد بن سلامة يقول: قال لي أحمد بن شعيب نظرت في حديث يحيى بن سليمان عن ابن وهب فما رأيت شيئا أنكره إلا حديثا واحدا ثم رفع يحيى في الحديث والقول الثاني: أنها غير منسوخة وأن للإمام أن يزيد من حضر الحرب على سهمه لبلاء أبلاه أو لعناء أتاه وأن له أن يرضخ لمن لم يقاتل إذا كان في ذلك صلاح للمسلمين يتأول قائل هذا ما صح عن ابن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن ابن شهاب، عن القاسم بن محمد، قال سمعت رجلا، يسأل عبد الله بن عباس عن الأنفال فقال","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:336","bookId":"nasikh-nahhas","type":"section","seq":336,"chapter":"ص: 48","title":"ص: 457","page":"ج1 ص455","text":": «الفرس من النفل والسلب من النفل» ثم عاد يسأله فقال ابن عباس: ذلك أيضا ثم عاد فقال: ما الأنفال التي قال الله جل وعز في كتابه فلم يزل يسأله حتى كاد يحرجه، فقال ابن عباس: ما مثل هذا؟ مثله مثل صبيغ الذي ضربه عمر بن الخطاب رضي الله عنه؟ \"\nحدثنا بكر بن سهل، قال: حدثنا عبد الله، قال: أخبرنا مالك، عن نافع، عن ابن عمر، «أن رسول الله صلى الله عليه وسلم بعث سرية قبل نجد فيها عبد الله بن عمر فغنموا إبلا كثيرة فطارت سهمانهم اثني عشر بعيرا أو أحد عشر بعيرا ونفلوا بعيرا بعيرا» قال أبو جعفر: ففي هذا التنفيل ولم يقل فيه من الخمس واحتج قائل هذا باللغة أيضا وأن معنى التنفيل في اللغة الزيادة وكان محمد بن جرير يميل إلى هذا القول والقول الثالث: إن الأنفال ما شذ من المشركين إلى المسلمين بغير قتال، قول عطاء، والحسن\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا ابن نمير، وأسباط، عن عبد الملك بن أبي سليمان، عن عطاء،: {قل","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:337","bookId":"nasikh-nahhas","type":"section","seq":337,"chapter":"ص: 48","title":"ص: 458","page":"ج1 ص457","text":"الأنفال لله والرسول} [الأنفال: 1] قال: «الأنفال ما شذ من المشركين إلى المسلمين من عبد أو أمة أو متاع أو دابة فهو النفل كان للنبي صلى الله عليه وسلم أن يصنع به ما شاء»\nقال يحيى بن سليمان، وحدثنا حفص بن غياث، عن عاصم بن سليمان، عن الحسن، قال: «فذلك إلى الإمام يصنع ما شاء به» والقول الرابع: إن الأنفال أنفال السرايا قول علي بن صالح بن حي والقول الخامس: إن الأنفال الخمس قول مجاهد رواه عنه ابن أبي نجيح قال: قال المهاجرون: لم يخرج منا هذا الخمس فقال الله جل وعز لله وللرسول فهذه خمسة أقوال وإن كان بعضها يدخل في بعض لأن قول من قال هو ما شذ من المشركين إلى المسلمين يدخل في قول من قال للإمام أن ينفل وكذا قول من قال: هي أنفال السرايا وقول مجاهد هي الخمس يرجع إلى قول من قال التنفيل من الخمس، واختلفوا أيضا في الآية الثانية من هذه السورة","bab":"باب ذكر الآية الخامسة قال جل وعز: {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به} "},{"id":"nasikh-nahhas:338","bookId":"nasikh-nahhas","type":"section","seq":338,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير}","page":"ج1 ص458","text":"من قال: هي محكمة وحكمها باق إلى يوم القيامة فممن قال: هي منسوخة عطاء بن أبي رباح قال: «نسخها {يا أيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين}","bab":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير} [الأنفال: 16] للعلم"},{"id":"nasikh-nahhas:339","bookId":"nasikh-nahhas","type":"section","seq":339,"chapter":"ص: 48","title":"ص: 460","page":"ج1 ص458","text":"إلى تمام الآيتين أي فنسخ بالتخفيف عنهم والإطلاق لهم أن يولوا ممن هو أكثر من هذا العدد» والقول الثاني: إنها مخصوصة قول الحسن\nكما حدثنا محمد بن جعفر، بالأنبار، قال: حدثنا حاجب بن سليمان، قال: حدثنا وكيع، عن الربيع بن صبيح، عن الحسن، قال: \" ليس الفرار من الزحف من الكبائر إنما كان في أهل بدر خاصة هذه الآية {ومن يولهم يومئذ دبره} [الأنفال: 16] \"\nوقرئ على أحمد بن شعيب، عن أبي داود، قال: حدثنا أبو زيد الهروي، قال: حدثنا شعبة، قال: حدثنا داود بن أبي هند، عن أبي نضرة، عن أبي سعيد الخدري، قال: \" نزلت {ومن يولهم يومئذ دبره} [الأنفال: 16]","bab":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير} [الأنفال: 16] للعلم"},{"id":"nasikh-nahhas:340","bookId":"nasikh-nahhas","type":"section","seq":340,"chapter":"ص: 48","title":"ص: 461","page":"ج1 ص460","text":"في أهل بدر \" والقول الثالث: إن حكمها باق إلى يوم القيامة قول ابن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، وذكر الكبائر، قال: \" والفرار من الزحف لأن الله جل وعز قال {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله} [الأنفال: 16] قال أبو جعفر: وهذا أولى ما قيل في الآية ولا يجوز أن تكون منسوخة لأنه خبر ووعيد ولا ينسخ الوعيد كما لا ينسخ الوعد فإن قيل فحديث أبي سعيد الخدري متصل الإسناد وقد خبر بنزول الآية في أهل بدر؟ فكيف يجوز خلافه؟ فالجواب أنه لعمري لا يجوز خلافه في مثل هذا والقول كما قال نزلت في أهل بدر وحكمها باق إلى يوم القيامة وأهل بدر كان رسول الله صلى الله عليه وسلم فئتهم فكان لهم أن ينحازوا إليه وكذا كل إمام والدليل على أن حكمها باق\nما حدثناه علي بن الحسين، قال حدثنا الحسن بن محمد، قال: حدثنا عفان، قال حدثنا أبو عوانة","bab":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير} [الأنفال: 16] للعلم"},{"id":"nasikh-nahhas:341","bookId":"nasikh-nahhas","type":"section","seq":341,"chapter":"ص: 48","title":"ص: 462","page":"ج1 ص461","text":"، قال: حدثنا يزيد بن أبي زياد، عن عبد الرحمن بن أبي ليلى، عن ابن عمر، قال: \" كنت في غزوة مسالح رسول الله صلى الله عليه وسلم فلقينا العدو فحاص الناس حيصة، ويقال جاض الناس جيضة فكنت فيمن حاص فرجعنا إلى أنفسنا فقلنا كيف يرانا المسلمون وقد بؤنا بالغضب ثم قرأ {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله} [الأنفال: 16] ، فقلنا نأتي المدينة فنبيت بها ثم نخرج فلا يرانا أحد فلما أتينا المدينة قلنا لو عرضنا أنفسنا على رسول الله صلى الله عليه وسلم فرصدناه حين خرج إلى صلاة الفجر فقلنا: يا رسول الله نحن الفرارون قال: لا بل أنتم العكارون قلنا: إنا قد هممنا بكذا وكذا قال: لا أنا فئة للمسلمين {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة} [الأنفال: 16] \" قال أبو جعفر: ففي هذا الحديث بيان معنى الآية لمن كان من أهل","bab":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير} [الأنفال: 16] للعلم"},{"id":"nasikh-nahhas:342","bookId":"nasikh-nahhas","type":"section","seq":342,"chapter":"ص: 48","title":"ص: 463","page":"ج1 ص461","text":"العلم وذلك أن ابن عمر لم يقبله رسول الله صلى الله عليه وسلم للحرب إلا بعد يوم بدر فتبين بهذا أن حكم الآية باق وتبين أن لمن حارب العدو إذا خاف على نفسه أن ينحاز إلى فئة يتقوى بها والعكارون الكرارون الراجعون يقال عكر وعكر واعتكر إذا كر ورجع فلما رجع ابن عمر ومن معه إلى النبي صلى الله عليه وسلم قابلين منه كانوا هم العكارين الراجعين إلى ما كانوا عليه من بذل أنفسهم إلى الجهاد والقبول من الرسول صلى الله عليه وسلم ما يأمرهم به، واختلفوا أيضا في الآية الثالثة اختلافا كثيرا لأنها مشكلة","bab":"باب ذكر الآية الثانية قال الله جل وعز {ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير} [الأنفال: 16] للعلم"},{"id":"nasikh-nahhas:343","bookId":"nasikh-nahhas","type":"section","seq":343,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز {وما كان الله ليعذبهم وأنت فيهم وما كان الله معذبهم وهم يستغفرون} [الأنفال: 33] للعلماء في هذه الآية خمسة أ","page":"ج1 ص461","text":"الله تعالى به ولا نعلم أحدا روي عنه هذا إلا الحسن وسائر العلماء على أنها محكمة وقالوا فيها أربعة أقوال فمن ذلك\nما حدثناه بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {وما كان الله ليعذبهم وأنت فيهم} [الأنفال: 33] قال: \" يقول سبحانه وما كان الله ليعذب قوما وأنبياؤهم بين أظهرهم حتى يخرجهم، وما كان الله معذبهم وهم يستغفرون قال: يقول وفيهم من قد سبق له منه الدخول في الإيمان وهو الاستغفار {وما لهم ألا يعذبهم الله} [الأنفال: 34] يوم بدر بالسيف \"","bab":"باب ذكر الآية الثالثة قال جل وعز {وما كان الله ليعذبهم وأنت فيهم وما كان الله معذبهم وهم يستغفرون} [الأنفال: 33] للعلماء في هذه الآية خمسة أقوال: قال الحسن: نسخ"},{"id":"nasikh-nahhas:344","bookId":"nasikh-nahhas","type":"section","seq":344,"chapter":"ص: 48","title":"ص: 465","page":"ج1 ص464","text":"قال أبو جعفر: شرح هذا {وما كان الله معذبهم} [الأنفال: 33] يعني الكفار جميعا وقد علم أن فيهم من يسلم فيكون وهم يراد بهم البعض مثل قول العرب قتلنا بني فلان وإنما قتلوا بعضهم {وما لهم ألا يعذبهم الله} [الأنفال: 34] إذا أسلم منهم من قد سبق في علمه أنه يسلم فهذا القول يجوز إلا أن فيه هذا التعسف وقال مجاهد «وهم يستغفرون أي يسلمون وهذا كالأول»\nوروي أبو زميل، عن ابن عباس، {وما كان الله معذبهم وهم يستغفرون} [الأنفال: 33] أي: «وما كان الله معذبهم في الدنيا وهم يستغفرون كانوا يقولون غفرانك غفرانك، وما لهم ألا يعذبهم الله تعالى في الآخرة» قال أبو جعفر: وهذا القول ظاهره حسن إلا أن فيه أنهم إنما استعجلوا بعذاب الدنيا لا بعذاب الآخرة وأيضا فقد علم أنهم يعذبون في الآخرة إن ماتوا على الكفر، فهذان قولان لمن قال إنها محكمة، والقول الثالث قول الضحاك\nكما قرئ على إبراهيم بن موسى الجوزي، عن يعقوب بن إبراهيم، قال حدثنا وكيع، قال: حدثنا سلمة بن نبيط، عن الضحاك، في قوله تعالى {وما كان الله معذبهم وهم يستغفرون} [الأنفال\n: 33] قال: \" المؤمنون من أهل مكة {وما لهم ألا يعذبهم الله} [الأنفال: 34] قال الكفار من أهل مكة \" قال أبو جعفر: جعل الضميرين مختلفين وهو قول حسن وإن كان محمد بن جرير قد أنكره لأنه زعم أنه لم يتقدم للمؤمنين ذكر فيكنى عنهم فهذا غلط بين لأنه قد تقدم ذكر المؤمنين في غير موضع من السورة فإن قيل لم يتقدم ذكرهم في هذا الموضع فالجواب أن في المعنى دليلا على ذكرهم في هذا الموضع وذلك أن من قال من الكفار: اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء إنما قال هذا مستهزئا ومتعنتا ولو قصد الحق لقال اللهم إن كان هذا هو الحق من عندك فاهدنا له ولكنه كفر وأنكر أن يكون الله تعالى يبعث رسولا يوحى إليه من السماء أي اللهم إن كان هذا هو الحق من عندك فأهلك الجماعة من الكفار والمسلمين فهذا معنى ذكر المسلمين فيكون المعنى كيف يهلك الله تعالى المسلمين فهذا معنى {وما كان الله معذبهم وهم يستغفرون} [الأنفال: 33] يعني المؤمنين {وما لهم ألا يعذبهم الله} [الأنفال: 34] يعني الكافرين وقول ابن أبزى كقول الضحاك قال \" {وما كان الله معذبهم وهم يستغفرون} [الأنفال\n: 33] يعني الفئة المسلمة التي كانت بمكة فلما خرجوا قال الله جل وعز {وما لهم ألا يعذبهم الله} [الأنفال: 34] يعني الكفار \" والقول الخامس: قول قتادة، والسدي، وابن زيد قالوا: \" {وهم يستغفرون} [الأنفال: 33] أي لو استغفروا \" قال أبو جعفر: فهذا أبين ما قيل في الآية ولا تعسف فيه كما تقول لا أسيء إليك وأنت تحسن إلي أي لو أحسنت إلي ما أسأت إليك فيكون المعنى {وما كان الله معذبهم} [الأنفال: 33] وهذه حالهم أي لو استغفروا من الكفر وتابوا {وما لهم ألا يعذبهم الله} [الأنفال: 34] أي وما شأنهم وما يمنعهم أن يعذبهم الله وهم مصرون على الكفر والمعاصي فقد استحقوا العذاب واختلفوا أيضا في الآية الرابعة","bab":"باب ذكر الآية الثالثة قال جل وعز {وما كان الله ليعذبهم وأنت فيهم وما كان الله معذبهم وهم يستغفرون} [الأنفال: 33] للعلماء في هذه الآية خمسة أقوال: قال الحسن: نسخ"},{"id":"nasikh-nahhas:345","bookId":"nasikh-nahhas","type":"section","seq":345,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال جل وعز {وإن جنحوا للسلم فاجنح لها}","page":"ج1 ص467","text":"[الأنفال: 61]\nحدثنا أبو جعفر قال حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، عن معمر، عن قتادة، {وإن جنحوا للسلم} [الأنفال: 61] قال: \" للصلح {فاجنح لها} [الأنفال: 61] قال: نسخها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] «وروي عن، ابن عباس،» أن الناسخ لها فلا تهنوا وتدعوا إلى السلم \" قال أبو جعفر: القول في أنها منسوخة لا يمتنع لأنه أمر بالإجابة إلى الصلح والهدنة بغير شرط فلما قال تعالى {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] حظر الصلح والهدنة مع قوة اليد والاستعلاء على المشركين","bab":"باب ذكر الآية الرابعة قال جل وعز {وإن جنحوا للسلم فاجنح لها}"},{"id":"nasikh-nahhas:346","bookId":"nasikh-nahhas","type":"section","seq":346,"chapter":"ص: 48","title":"ص: 469","page":"ج1 ص468","text":"والبين في باب النظر أن لا تكون منسوخة وأن تكون الثانية مبينة للأولى ومن العلماء من يقول في الآية الخامسة أنها منسوخة","bab":"باب ذكر الآية الرابعة قال جل وعز {وإن جنحوا للسلم فاجنح لها}"},{"id":"nasikh-nahhas:347","bookId":"nasikh-nahhas","type":"section","seq":347,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة قال جل وعز: {يا أيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألف","page":"ج1 ص468","text":"في رواية ابن جريج، وعثمان بن عطاء، عن عطاء، عن ابن عباس، قال: \" نسخها {الآن خفف الله عنكم} [الأنفال: 66] الآية \"\nوقرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا يزيد بن هارون، قال: أخبرنا جرير بن حازم، عن الزبير بن خريت، عن عكرمة، عن ابن عباس، قال: «كان فرض على المسلمين أن يقاتل الرجل منهم العشرة من المشركين، قال جل وعز {إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا} » فشق ذلك عليهم فأنزل الله تعالى التخفيف فجعل على الرجل أن يقاتل الرجلين فخفف عنهم ونقصوا من النصر بقدر ذلك \" قال أبو جعفر: وهذا شرح بين حسن أن يكون ذا تخفيفا لا نسخا؛ لأن معنى النسخ رفع حكم المنسوخ ولم يرفع حكم الأول لأنه لم يقل","bab":"باب ذكر الآية الخامسة قال جل وعز: {يا أيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا}"},{"id":"nasikh-nahhas:348","bookId":"nasikh-nahhas","type":"section","seq":348,"chapter":"ص: 48","title":"ص: 471","page":"ج1 ص470","text":"فيه لا يقاتل الرجل عشرة بل إن قدر على ذلك فهو الاختيار له ونظير هذا إفطار الصائم في السفر لا يقال إنه نسخ الصوم وإنما هو تخفيف ورخصة والصيام له أفضل قال ابن شبرمة «وكذا النهي عن المنكر، لا يحل له أن يفر، من اثنين إذا كان على منكر وله أن يفر من أكثر منهما» ومن العلماء من أدخل الآية السادسة في الناسخ والمنسوخ\nباب","bab":"باب ذكر الآية الخامسة قال جل وعز: {يا أيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا}"},{"id":"nasikh-nahhas:349","bookId":"nasikh-nahhas","type":"section","seq":349,"chapter":"ص: 48","title":"ص: 472","page":"ج1 ص470","text":"ذكر الآية السادسة قال جل وعز: {ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض} [الأنفال: 67]\nحدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض} [الأنفال: 67] قال: \" وذلك والمسلمون قليل يومئذ فلما كثروا واشتدت سلطانهم أنزل الله تعالى بعد هذا في الأسرى {فإما منا بعد وإما فداء} [محمد: 4] فجعل الله تعالى النبي والمؤمنين في أمر الأسرى بالخيار إن شاءوا قتلوهم وإن شاءوا استعبدوهم وإن شاءوا فادوهم \" قال أبو جعفر: وهذا كله من الناسخ والمنسوخ بمعزل لأنه قال تعالى {ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض} [الأنفال: 67] فأخبر بهذا فلما أثخن في الأرض كان له أسرى واختلف في الحكم فيهم وسنذكر ذلك في موضعه إن شاء الله وقد أدخلت الآية السابعة في الناسخ والمنسوخ","bab":"باب ذكر الآية الخامسة قال جل وعز: {يا أيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا}"},{"id":"nasikh-nahhas:350","bookId":"nasikh-nahhas","type":"section","seq":350,"chapter":"ص: 48","title":"باب ذكر الآية السابعة قال جل وعز: {فكلوا مما غنمتم حلالا طيبا} [الأنفال: 69] فكان هذا ناسخا لما تقدم من حكم الله جل وعز في حظر الغنائم لأنها","page":"ج1 ص472","text":"تحل الغنائم لأحد قبلنا» وفي الحديث أنهم لما أسرعوا إليها أنزل الله تعالى: {لولا كتاب من الله سبق لمسكم فيما أخذتم عذاب عظيم} [الأنفال: 68] قيل المعنى لولا أن الله تعالى سبق منه أنه لا يعذب أحدا إلا بعد التقدم إليه لعاقبكم قبل، وقيل لولا أنه سبق من الله تعالى أنه لا يعذب أحدا على صغيرة إذا اجتنب الكبائر لعاقبكم وفيه غير هذا قد ذكرته، وأكثر العلماء تقول في الآية الثامنة إنها منسوخة","bab":"باب ذكر الآية السابعة قال جل وعز: {فكلوا مما غنمتم حلالا طيبا} [الأنفال: 69] فكان هذا ناسخا لما تقدم من حكم الله جل وعز في حظر الغنائم لأنها لم تحل لأحد قبل أمة"},{"id":"nasikh-nahhas:351","bookId":"nasikh-nahhas","type":"section","seq":351,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}","page":"ج1 ص473","text":"[الأنفال: 72]\nحدثنا أبو جعفر، قال حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قوله جل وعز {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء} [الأنفال: 72] قال: \" كان المسلمون يتوارثون بالهجرة كان الرجل إذا أسلم فلم يهاجر لم يرث أخاه فنسخ ذلك قوله جل وعز {وأولو الأرحام بعضهم أولى ببعض في كتاب الله من المؤمنين والمهاجرين} [الأحزاب: 6] \"\nوقرئ على علي بن سعيد بن بشير، عن محمود بن غيلان، قال: حدثنا أبو داود، قال: حدثنا سليمان بن معاذ، عن سماك، عن عكرمة، عن ابن عباس،: \" أن رسول الله صلى الله عليه وسلم آخى بين أصحابه فكانوا يتوارثون","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:352","bookId":"nasikh-nahhas","type":"section","seq":352,"chapter":"ص: 48","title":"ص: 475","page":"ج1 ص474","text":"بذلك حتى نزلت {وأولو الأرحام بعضهم أولى ببعض} [الأحزاب: 6] فتوارثوا بالنسب \" قال أبو جعفر: فتكلم العلماء على أن هذه الآية ناسخة للتي قبلها وأن التوارث كان بالهجرة والمؤاخاة فنسخ ذلك قال عكرمة: «فأقام الناس برهة من الدهر لا يرث الأعرابي المهاجر ولا المهاجر الأعرابي حتى أنزل الله تعالى {وأولو الأرحام بعضهم أولى ببعض في كتاب الله من المؤمنين المهاجرين إلا أن تفعلوا إلى أوليائكم معروفا} » قال قتادة «أي بالوصية»","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:353","bookId":"nasikh-nahhas","type":"section","seq":353,"chapter":"ص: 48","title":"سورة براءة قال أبو جعفر: لا أعلم خلافا أنها من آخر ما نزل بالمدينة ولذلك قل المنسوخ فيها ويدلك على ذلك","page":"ج1 ص474","text":"ما حدثنا به، أحمد بن عمرو بن عبد الخالق، قال: حدثنا محمد بن المثنى، وعمرو بن علي، قالا حدثنا يحيى بن سعيد، قال: حدثنا عوف الأعرابي، عن يزيد الفارسي، قال: حدثنا ابن عباس، قال: قلنا لعثمان بن عفان رضي الله عنه ما حملكم على أن عمدتم إلى الأنفال وهي من المثاني وإلى براءة وهي من المئين فقرنتم بينهما ولم تكتبوا بينهما بسم الله الرحمن الرحيم","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:354","bookId":"nasikh-nahhas","type":"section","seq":354,"chapter":"ص: 48","title":"ص: 478","page":"ج1 ص477","text":"، ووضعتهما في السبع الطوال ما حملكم على هذا؟ فقال: «كان رسول الله صلى الله عليه وسلم تنزل عليه السور ذوات العدد فإذا نزلت عليه الآية قال اجعلوها في سورة كذا وكذا وكانت الأنفال من أول ما نزل بالمدينة وكانت براءة من آخر ما نزل وكانت قصتها تشبه قصتها ولم يبين لنا رسول الله صلى الله عليه وسلم في ذلك شيئا فلذلك قرنت بينهما ولم أكتب بينهما سطر بسم الله الرحمن الرحيم»\nقال وقرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا أبو أسامة، قال: حدثنا عوف، وذكر بإسناده نحوه غير أنه زاد فيه قال عثمان فظننت أنها منها قال: وكانتا تدعيان في زمان رسول الله صلى الله عليه وسلم القرينتين فلذلك جعلتهما في السبع الطوال \" قال أبو جعفر: ففي هذا الحديث ظن عثمان أن الأنفال من براءة وتحقيق ابن عباس أنها ليست منها وفيه البيان أن تأليف القرآن عن الله جل وعز ورسول الله صلى الله عليه وسلم لا مدخل لأحد فيه ولو لم يكن في ذلك إلا الأحاديث المتواترة أن رسول الله صلى الله عليه وسلم ذكر البقرة وآل عمران وسائر السور وأنه كان يقرأ في صلاة كذا بكذا وأنه قرأ في ركعة بالبقرة وآل عمران وأنه\nقال صلى الله عليه وسلم «تأتيان يوم القيامة كأنهما غمامتان أو غيايتان» وصح أن أربعة من أصحاب رسول الله صلى الله عليه وسلم كانوا يحفظون القرآن في وقته ولا يجوز أن يحفظوا ما ليس مؤلفا\nكما حدثنا أبو علي محمد بن جعفر بن محمد الأنباري، قال: حدثنا الحسن بن محمد، قال: حدثنا شبابة، قال: حدثنا شعبة، عن قتادة، عن أنس، قال: «جمع القرآن على عهد رسول الله صلى الله عليه وسلم أربعة أبي بن كعب، وزيد بن ثابت، وأبو زيد، ومعاذ بن جبل»","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:355","bookId":"nasikh-nahhas","type":"section","seq":355,"chapter":"ص: 48","title":"ص: 480","page":"ج1 ص479","text":"قال قتادة: قلت لأنس من أبو زيد؟ قال: أحد عمومتي قال أبو جعفر: وهؤلاء الأربعة من الأنصار هم الذين كانوا يقرءون وأبو زيد سعد بن عبيد من بني عمرو بن عوف من الأنصار وقال الشعبي، وأبو الدرداء: «حفظ القرآن على عهد رسول الله صلى الله عليه وسلم ومجمع بن جارية بقيت عليه سورتان أو ثلاث قال ولم يحفظ القرآن أحد من الخلفاء إلا عثمان، وسالم مولى أبي حذيفة بقي عليه منه شيء»","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:356","bookId":"nasikh-nahhas","type":"section","seq":356,"chapter":"ص: 48","title":"ص: 481","page":"ج1 ص479","text":"فإن قيل فقد أمر النبي صلى الله عليه وسلم بأخذ القرآن عنه قيل ليس في هذا دليل على حفظه إياه كله ولكن فيه دليل على أمانته ومما يدلك على أن القرآن كان مؤلفا في عهد رسول الله صلى الله عليه وسلم\nما حدثناه أحمد بن محمد الأزدي، قال: حدثنا يزيد بن سنان، قال: حدثنا أبو داود، قال: حدثنا عمران القطان، عن قتادة، عن أبي بكر الهذلي، عن أبي رافع، قال: قال رسول الله صلى الله عليه وسلم: «أعطيت السبع مكان التوراة وأعطيت المئين مكان الزبور وأعطيت المثاني مكان الإنجيل وفضلت بالمفصل»\nقال أبو جعفر: فهذا التأليف من لفظ رسول الله صلى الله عليه وسلم وهذا أصل من أصول المسلمين لا يسعهم جهله لأن تأليف القرآن من إعجازه ولو كان التأليف عن غير الله جل وعز ورسول الله صلى الله عليه وسلم لسوعد بعض الملحدين على طعنهم وقد أشكل على بعض أصحاب الحديث ما طعن به بعض أهل الأهواء بالحديث أن عثمان أمر زيد بن ثابت أن يجمع القرآن وضم إليه جماعة فتوهم أن هذا هو التأليف وهذا غلط عظيم وقد تكلم العلماء في معنى هذا بأجوبة فمنهم من قال إنما أمر بجمعه وإن كان مجموعا لأنهم كانوا يقرءونه على سبعة أحرف فوقع بينهم الشر والخلاف فأراد عثمان رحمه الله أن يختار من السبعة حرفا واحدا هو أفصحها ويزيل الستة وهذا من أصح ما قيل فيه لأنه مروي عن زيد بن ثابت أنه قال هذا ويدلك على صحته أن زيد بن ثابت كان يحفظ القرآن فلا معنى لجمعه إياه إلا على هذا أو ما أشبهه وقد قيل إنما جمعه وإن كان يحفظه لتقوم حجته عند أمير المؤمنين عثمان أنه لم يستبد برأيه\nوقد عارض بعض الناس في هذا فقال: لم خص زيد بن ثابت بهذا وفي الصحابة من هو أكبر منه منهم عبد الله بن مسعود، وأبو موسى الأشعري وغيرهما واحتج\nبما حدثناه إبراهيم بن محمد بن عرفة، قال: حدثنا شعيب بن أيوب، قال: حدثنا يحيى بن آدم، قال: حدثنا أبو بكر بن عياش، عن عاصم، عن زر، عن عبد الله، أن أبا بكر، وعمر، رضي الله عنهما بشراه بأن رسول الله صلى الله عليه وسلم قال: «من أراد أن يقرأ القرآن غضا كما أنزل فليقرأه بقراءة ابن أم عبد» قال أبو جعفر: والجواب عن هذا أن زيد بن ثابت قدم لأشياء لم تجتمع لغيره منها أنه كان يكتب الوحي لرسول الله صلى الله عليه وسلم ومنها أنه كان يحفظ","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:357","bookId":"nasikh-nahhas","type":"section","seq":357,"chapter":"ص: 48","title":"ص: 484","page":"ج1 ص483","text":"القرآن في عهد رسول الله صلى الله عليه وسلم ومنها أن قراءته كانت على آخر عرضة عرضها النبي صلى الله عليه وسلم على جبريل عليه السلام وقول النبي صلى الله عليه وسلم في عبد الله بن مسعود ما قال قد تأوله هذا المعارض على غير تأويله وليس التأويل على ما ذهب إليه ولو كان على ما ذهب إليه ما وسع أحدا أن يقرأ إلا بحرف عبد الله، والتأويل عند أهل العلم منهم الحسين بن علي الجعفي أن عبد الله بن مسعود كان يرتل القرآن فحض النبي صلى الله عليه وسلم على ترتيل مثل ترتيله لا غير ويدلك على ذلك الحديث، أنه سئل عن طسم، فقال: لا أحفظها سل خبابا عنها فإن قيل فقد حضر ابن مسعود العرضة الآخرة قيل قد ذكرنا ما لزيد بن ثابت سوى هذا على أن حرف عبد الله الصحيح أنه موافق لمصحفنا يدلك على ذلك أن أبا بكر بن عياش قال: قرأت على عاصم وقرأ عاصم على زر وقرأ زر على عبد الله\nوقرئ على أحمد بن شعيب بن علي، عن محمد بن بشار، قال: حدثنا محمد، قال: حدثنا شعبة، عن أبي إسحاق، قال","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:358","bookId":"nasikh-nahhas","type":"section","seq":358,"chapter":"ص: 48","title":"ص: 485","page":"ج1 ص483","text":": سمعت البراء بن عازب، يقول: «آخر آية نزلت آية الكلالة وآخر سورة نزلت براءة» قال أبو جعفر: وقد ذكرنا أنه لا يكاد يوجد فيها منسوخ لهذا فأما الناسخ فيها فكثير، وقد اختلف في الآية الأولى منها","bab":"باب ذكر الآية الثامنة قال جل وعز: {والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا}"},{"id":"nasikh-nahhas:359","bookId":"nasikh-nahhas","type":"section","seq":359,"chapter":"ص: 48","title":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في","page":"ج1 ص484","text":"منها ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، قال: \" كان لقوم عهود فأمر الله تعالى النبي عليه السلام بأن يؤجلهم أربعة أشهر يسيحون فيها فلا عهد لهم بعدها وأبطل ما بعدها وكان قوم لا عهود لهم فأجلهم خمسين يوما عشرين من ذي الحجة والمحرم كله، وذلك قوله تعالى {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" فهذا قول والقول الثاني رواه ابن أبي طلحة عن ابن عباس،: «أجل من له عهد أربعة أشهر» ، ولم يقل فيه أكثر وبهذه الرواية فيمن لا عهد له كالأولى والقول الثالث: إنهم صنفان صنف عاهده النبي صلى الله عليه وسلم أقل من أربعة أشهر وصنف عاهده إلى غير أجل فرد الجميع إلى أربعة أشهر","bab":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في هذه الآية سبعة أقوال"},{"id":"nasikh-nahhas:360","bookId":"nasikh-nahhas","type":"section","seq":360,"chapter":"ص: 48","title":"ص: 487","page":"ج1 ص486","text":"والقول الرابع: إنهما صنفان أيضا صنف عوهد إلى أقل من أربعة أشهر فأتمت له أربعة وصنف عوهد إلى أكثرمن أربعة أشهر فأمر بالوفاء له قال تعالى: {فأتموا إليهم عهدهم إلى مدتهم} [التوبة: 4] والقول الخامس: إنه رد الجميع إلى أربعة أشهر من عوهد إلى أقل منها أو أكثر قال أبو جعفر: وهذا قول مجاهد، والسدي قالا: «وأول هذه الأشهر التي هي أشهر السياحة يوم الحج الأكبر إلى عشر يخلون من شهر ربيع الآخر» وسميت الحرم لأن القتال كان فيها محرما\nقال أبو جعفر وحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن الزهري، {فسيحوا في الأرض أربعة أشهر} [التوبة: 2] قال: «شوال وذو القعدة وذو الحجة والمحرم» قال أبو جعفر: ولا أعلم أحدا قال هذا إلا الزهري والدليل على غير قوله صحة الرواية أن علي بن أبي طالب رضي الله عنه إنما قرأ عليهم هذا ونبذ العهد إليهم بأمر رسول الله صلى الله عليه وسلم في ذي الحجة يوم الحج الأكبر فيجب أن يكون هذا أول الشهور","bab":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في هذه الآية سبعة أقوال"},{"id":"nasikh-nahhas:361","bookId":"nasikh-nahhas","type":"section","seq":361,"chapter":"ص: 48","title":"ص: 488","page":"ج1 ص486","text":"وقال من احتج للزهري إنما حمل هذا على نزول براءة قال أبو جعفر: وهذا غلط كيف ينبذ العهد إليهم وهم لا يعلمون وأيضا فإن النبي صلى الله عليه وسلم وجه أبا بكر رضي الله عنه يحج بالناس سنة تسع ثم اتبعه علي بن أبي طالب رضي الله عنه بهذه الآيات ليقرأها في الموسم ودل هذا على أنه قد نسخ بها ما كان النبي صلى الله عليه وسلم أقر المشركين عليه من حجهم البيت وطوافهم به عراة وسنذكر الحديث بهذا والقول السابع إن الذين نبذ إليهم العهد وأجلوا أربعة أشهر هم الذين نقضوا العهد الذي كان بينهم وبين رسول الله صلى الله عليه وسلم فأمر بنبذ العهد إليهم وتأجيلهم أربعة أشهر فأما من لم ينقض العهد فكان مقيما على عهده وقال جل وعز فما استقاموا لكم فاستقيموا لهم ومن لم يكن له عهد أجل خمسين يوما كما قال ابن عباس وهذا أحسن ما قيل في الآية وهو معنى قول قتادة، والدليل على صحته\nما حدثناه أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن أبي إسحاق الهمداني، عن زيد بن يثيع، عن علي بن أبي طالب، رضي الله عنه قال أمرني رسول الله صلى الله عليه وسلم بأربع لا يحج البيت مشرك، ولا يطوف بالبيت عريان، ولا يدخل الجنة إلا نفس مؤمنة، وأن يتم لكل ذي عهد عهده \"","bab":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في هذه الآية سبعة أقوال"},{"id":"nasikh-nahhas:362","bookId":"nasikh-nahhas","type":"section","seq":362,"chapter":"ص: 48","title":"ص: 489","page":"ج1 ص487","text":"قال أبو جعفر: فإن قيل: فقد روي في الرابعة: «وأن ينبذ إلى كل ذي عهد عهده» فالجواب: أنه يجوز أن يكون هذا لمن نقض العهد، على أن الرواية الأولى أولى وأكثر وأشبه، والله تعالى أعلم\nوقد حدثنا عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، قال: «لم يعاهد رسول الله صلى الله عليه وسلم بعد هذه الآية أحدا» وقال السدي: «لم يعاهد النبي صلى الله عليه وسلم بعد هذا إلا من كان له عهد قبل» قال أبو جعفر: هذا وإن كان قد روي فالصحيح غيره قد عاهد النبي صلى الله عليه وسلم بعد الآية جماعة منهم أهل نجران قال الواقدي «عاهدهم وكتب لهم ستة عشر قبل وفاته صلى الله عليه وسلم بيسير» وقد اعترض قوم من أهل الأهواء فقالوا قد أجلى عمر بن الخطاب رضي الله عنه أهل نجران إلى الشام بعد أن أمنهم رسول الله صلى الله عليه وسلم وكتب لهم كتابا ألا يحشروا فأرادوا بهذا الطعن على عمر رضي الله عنه وهذا جهل ممن قاله أو عناد لأن الأعمش روى عن سالم بن أبي الجعد قال: أمن رسول الله صلى الله عليه وسلم أهل نجران وكتب لهم أن لا يحشروا ثم كتب\nلهم بذلك أبو بكر الصديق رضي الله عنه بعد رسول الله صلى الله عليه وسلم ثم كتب لهم بذلك عمر رضي الله عنه فكثروا حتى صاروا أربعين ألف مقاتل فكره عمر أن يميلوا على المسلمين فيفرقوا بينهم وقالوا لعمر نريد أن نتفرق ونخرج إلى الشام فاغتنم ذلك منهم وقال نعم ثم ندموا فلم يقلهم فلما ولي علي بن أبي طالب رضي الله عنه أتوه فقالوا كتابك بيمينك وشفاعتك بلسانك فقال: إن عمر رضي الله عنه كان رشيدا وفي غير رواية سالم فقال لهم علي إني ما قعدت هذا المقعد لأحل عقدا عقده عمر إن عمر كان رجلا موفقا\nوقرئ على عمران بن موسى يعرف بابن الطبيب، عن أبي يعقوب، إسحاق بن إبراهيم بن يزيد بن ميمون، قال: حدثنا أبو داود الحفري، قال: حدثنا سفيان الثوري، عن الأعمش، عن أبي وائل، قال قال عبد الله بن مسعود، «لو وضع علم عمر في كفة ووضع علم أحياء العرب في كفة لرجح علم عمر، ولقد كنا نقول ذهب عمر بتسعة أعشار العلم»\nوقرئ على عمران بن موسى، عن إسحاق، قال: حدثنا الهيثم بن جميل، قال: حدثنا عيسى بن يونس، عن عمر بن سعيد بن أبي حسين، عن عبد الله بن أبي مليكة، عن ابن عباس، قال: «كنت فيمن يزدحم على عمر رحمه الله حين وضع على سريره فجاء","bab":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في هذه الآية سبعة أقوال"},{"id":"nasikh-nahhas:363","bookId":"nasikh-nahhas","type":"section","seq":363,"chapter":"ص: 48","title":"ص: 492","page":"ج1 ص491","text":"رجل من خلفي فوضع يده على منكبي فترحم عليه وقال ما من أحد ألقى الله تعالى بعمله أحب إلي من هذا إن كنت أظن ليجمعنه الله مع صاحبيه كنت أسمع رسول الله صلى الله عليه وسلم يقول كنت أنا وأبو بكر، وعمر وقلت أنا وأبو بكر، وعمر وكنت أظن ليجمعنك الله جل وعز معهما فالتفت فإذا هوعلي بن أبي طالب رضي الله عنه» فهذا قول علي فيه بالأسانيد الصحاح فلا مطعن لمن طعن على شيء لم يغيره من ينتحل محبته\nوقد قرئ على أحمد بن شعيب، عن عمرو بن منصور، قال: حدثنا عبد الله بن مسلمة، قال: حدثنا نافع، عن نافع، عن ابن عمر، عن النبي صلى الله عليه وسلم قال: «إن الله تعالى جعل الحق على لسان عمر وقلبه» والروايات بمثل هذا كثيرة ولم نقصد جمعها وإنما قصدنا بعضها لأن فيه كفاية وبيانا عما أردناه وقد اختلف العلماء في الآية الثانية من هذه السورة","bab":"باب ذكر الآية الأولى منها قال جل وعز: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر} [التوبة: 2] للعلماء في هذه الآية سبعة أقوال"},{"id":"nasikh-nahhas:364","bookId":"nasikh-nahhas","type":"section","seq":364,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال جل وعز: {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية للعلماء في هذه الآية ثلاثة أقوال","page":"ج1 ص492","text":"قال هذا الحسن رواه عنه أشعث أنه: \" كان يكره قتل الأسير صبرا وقال {فإما منا بعد وإما فداء} [محمد: 4] \" وهذا قول الضحاك، والسدي قالا: \" نسخ {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] قوله {فإما منا بعد وإما فداء} [محمد: 4] \"\nوهو قول عطاء كما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان قال: حدثني ابن وهب قال: أخبرني ابن جريج عن عطاء في قوله {فإما منا بعد وإما فداء} [محمد: 4] قال: «هذا في الأسارى إما المن وإما الفداء وكان ينكر القتل صبرا»","bab":"باب ذكر الآية الثانية قال جل وعز: {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية للعلماء في هذه الآية ثلاثة أقوال فمنهم من قال: هي من"},{"id":"nasikh-nahhas:365","bookId":"nasikh-nahhas","type":"section","seq":365,"chapter":"ص: 48","title":"ص: 494","page":"ج1 ص493","text":"قال أبو جعفر: فهذا قول ومن العلماء من قال لا يجوز في الأسارى من المشركين إلا القتل ولا يجوز أن يؤخذ منهم فداء ولا يمن عليهم وجعلوا قوله تعالى {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] ناسخا لقوله تعالى {فإما منا بعد وإما فداء} [محمد: 4] وهذا قول قتادة ومروي عن مجاهد\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا عبد الله بن إدريس، قال سمعت ليثا، يحدث عن مجاهد، قال: \" نسخت هذه الآية {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] قوله تعالى {فإما منا بعد وإما فداء} [محمد: 4] فإما السيف والقتل وإما الإسلام \" والقول الثالث: إن الآيتين جميعا محكمتان وهو قول ابن زيد وهو قول صحيح بين لأن إحداهما لا تنفي الأخرى، قال جل وعز {فاقتلوا المشركين حيث وجدتموهم وخذوهم} [التوبة: 5] أي وخذوهم أسرى للقتل أو المن أو الفداء، فيكون الإمام ينظر في أمور الأسارى على ما فيه الصلاح من القتل أو المن أو الفداء وقد فعل هذا كله رسول الله صلى الله عليه وسلم في حروبه فقتل عقبة بن أبي معيط","bab":"باب ذكر الآية الثانية قال جل وعز: {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية للعلماء في هذه الآية ثلاثة أقوال فمنهم من قال: هي من"},{"id":"nasikh-nahhas:366","bookId":"nasikh-nahhas","type":"section","seq":366,"chapter":"ص: 48","title":"ص: 495","page":"ج1 ص493","text":"، والنضر بن الحارث أسيرين يوم بدر ومن على قوم وفادى بقوم قال\nوحدثنا أحمد بن شعيب، قال: أخبرنا قتيبة، قال: أخبرنا مالك بن أنس، عن ابن شهاب، عن أنس: \" أن رسول الله صلى الله عليه وسلم دخل مكة وعليه المغفر فقيل له إن ابن خطل متعلق بأستار الكعبة فقال: «اقتلوه» قال أبو جعفر: وهذا في عداد الأسارى وقد أمر النبي صلى الله عليه وسلم بقتله\nوحدثنا أحمد بن محمد الأزدي، قال: حدثنا فهد بن سليمان، قال: حدثنا يوسف بن بهلول قال حدثنا عبد الله بن إدريس قال حدثني محمد بن إسحاق، قال: قال الزهري: حدثني عبيد الله بن عبد الله بن عتبة، عن ابن عباس: أن العباس بن عبد المطلب، حمل أبا سفيان على عجز بغلته في الليلة التي كان في صبيحتها ما كان من دخول رسول الله صلى الله عليه وسلم مكة قال العباس: \" فكنت إذا مررت بنار من نيران المسلمين قالوا: من هذا؟ فإذا نظروا قالوا: عم رسول الله صلى الله عليه وسلم حتى مررت\nبنار عمر بن الخطاب رضي الله عنه فقال: من هذا؟ وقام إلي ورآه في عجز البغلة فقال أبو سفيان: عدو الله قد أمكن الله منك ومر يشتد إلى رسول الله صلى الله عليه وسلم فركضت البغلة فسبقت كما تسبق الدابة البطيء الرجل البطيء ثم اقتحمت فدخلت على رسول الله صلى الله عليه وسلم ثم جاء عمر فدخل فقال: يا رسول الله هذا أبو سفيان قد أمكن الله منه بلا عهد ولا ميثاق فدعني فأضرب عنقه فقلت: يا رسول الله إني قد أمنته \" قال أبو جعفر: فهذا عمر بن الخطاب أراد قتل أبي سفيان وهو أسير فلم يقل له رسول الله صلى الله عليه وسلم لا يجوز قتل الأسير ولا أنكر عليه ما قاله من همه بقتله ففي هذا بيان أن الآية محكمة وقد أدخلت الآية الثالثة في الناسخ والمنسوخ","bab":"باب ذكر الآية الثانية قال جل وعز: {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية للعلماء في هذه الآية ثلاثة أقوال فمنهم من قال: هي من"},{"id":"nasikh-nahhas:367","bookId":"nasikh-nahhas","type":"section","seq":367,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال تعالى: {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28] فكانت هذه الآية ناسخة لما كان رسول","page":"ج1 ص496","text":"كما حدثنا أحمد بن محمد الأزدي، قال: حدثنا عبد الملك بن مروان الرقي، قال: حدثنا حجاج بن محمد، عن ابن جريج، عن عطاء، قال: \" قوله تعالى {فلا يقربوا المسجد الحرام} [التوبة: 28] يريد الحرم كله \" قال أبو جعفر: {بعد عامهم هذا} [التوبة: 28] يعني سنة تسع {وإن خفتم عيلة} [التوبة: 28] قال ابن عباس: \" قالوا: إذا لم يحج الكفار خفنا الفقر إذا قل من نبايعه \" واختلف العلماء في حكم هذه الآية وفي دخول المشركين الحرم وسائر المساجد فقال عمر بن عبد العزيز، ومالك بن أنس يمنع المشركون كلهم","bab":"باب ذكر الآية الثالثة قال تعالى: {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28] فكانت هذه الآية ناسخة لما كان رسول الله صلى الله عليه و"},{"id":"nasikh-nahhas:368","bookId":"nasikh-nahhas","type":"section","seq":368,"chapter":"ص: 48","title":"ص: 498","page":"ج1 ص497","text":"من أهل الكتاب وغيرهم من دخول الحرم ومن دخول كل المساجد وهو قول قتادة قال: لأنهم نجس قال: «وقيل لهم نجس لأنهم لا يستحمون من جنابة وكذا لا يدخل المسجد جنب» فهذا قول وقال الشافعي: «يمنع المشركون جميعا من دخول الحرم ولا يمنعون من دخول سائر المساجد» وقال أبو حنيفة، ويعقوب، ومحمد، وزفر «لا يمنع اليهود ولا النصارى من دخول المسجد الحرام ولا من سائر المساجد؛ لأن المشركين هم أهل الأوثان» فجعلوا قول الله تعالى {إنما المشركون نجس} [التوبة: 28] مخصوصا به من لا كتاب له","bab":"باب ذكر الآية الثالثة قال تعالى: {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28] فكانت هذه الآية ناسخة لما كان رسول الله صلى الله عليه و"},{"id":"nasikh-nahhas:369","bookId":"nasikh-nahhas","type":"section","seq":369,"chapter":"ص: 48","title":"ص: 499","page":"ج1 ص497","text":"قال أبو جعفر: وهذا القول في كتاب الله تعالى نصا ما يدل على خلافه قال تعالى: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين أوتوا الكتاب حتى يعطوا الجزية عن يد. . .} [التوبة: 29] إلى قوله تعالى: {اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح ابن مريم وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو سبحانه عما يشركون} [التوبة: 31] فهذا شيء قاطع فإن أشكل على أحد أنهم لم يجعلوا لله شريكا فكيف يقال لهم مشركون؟ قيل له لهذا نظائر في أصول الدين يعرفها أهل اللغة ويحتاج الناس جميعا إلى معرفتها وهي الأسماء الديانية وذلك أنه يقال آمن بكذا إذا صدق ثم قيل مؤمن لمن صدق بمحمد رسول الله وهو اسم دياني وكذا منافق اسم وقع بعد الإسلام وكذا لكل ما أسكر كثيره خمر اسم إسلامي كما صح عن رسول الله صلى الله عليه وسلم: «كل مسكر خمر» وكذا كل من كفر بمحمد صلى الله عليه وسلم مشرك، وفي هذا قول آخر كان أبو إسحاق الزجاج يخرجه على أصول الاشتقاق المعروفة قال: لما كان محمد صلى الله عليه وسلم قد جاء من البراهين بما لا يكون إلا من عند الله تعالى وكان من كفر به قد نسب ما لا يكون إلا من عند الله تعالى إلى غير الله تعالى كان مشركا، وقد أدخلت الآية الرابعة في الناسخ والمنسوخ","bab":"باب ذكر الآية الثالثة قال تعالى: {إنما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا} [التوبة: 28] فكانت هذه الآية ناسخة لما كان رسول الله صلى الله عليه و"},{"id":"nasikh-nahhas:370","bookId":"nasikh-nahhas","type":"section","seq":370,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال جل ذكره: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية فمن العلماء من يقول هذه الآية ناسخة لل","page":"ج1 ص497","text":"كما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: \" وقوله تعالى: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] فنسخ بهذا العفو عن المشركين \" وقيل هذا ناسخ لقوله تعالى {فاقتلوا المشركين} [التوبة: 5] وقيل بل هو تبيين لما قال تعالى {فاقتلوا المشركين} [التوبة: 5] وأمر في أهل الكتاب بأخذ الجزية، علم أنه يراد بالمشركين غير أهل الكتاب وقيل لما قال تعالى: {فاقتلوا المشركين} [التوبة: 5] وجب قتل كل مشرك إلا من نص الله عليه من أهل الكتاب ومن قامت بترك قتله الحجة من النساء والصبيان ومن قامت بأخذ الجزية منه الحجة وهم المجوس وقائل هذا يقول يقتل الرهبان إذا لم يؤدوا الجزية لقول الله {فاقتلوا المشركين} [التوبة: 5] ولم تقم الحجة بتركهم إلا بعد أداء الجزية بالآية الأخرى","bab":"باب ذكر الآية الرابعة قال جل ذكره: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية فمن العلماء من يقول هذه الآية ناسخة للعفو عن المشركين لأنه"},{"id":"nasikh-nahhas:371","bookId":"nasikh-nahhas","type":"section","seq":371,"chapter":"ص: 48","title":"ص: 501","page":"ج1 ص500","text":"ومن الفقهاء من يقول لا يقتل الرهبان إن لم يؤدوا الجزية لأن في نص القرآن ما يدل على ذلك يعرفه أهل اللسان الذين نزل القرآن بلغتهم قال الله: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] وقاتلوا في اللغة لا تكون إلا من اثنين فخرج من هذا الرهبان والنساء والصبيان لأنهم ليست سبيلهم أن يقاتلوا ومعنى لا يؤمنون بالله لا يؤمنون بأنه لا معبود إلا الله وقال سيبويه: الأصل إله، وقال الفراء: الأصل الإله ثم ألقيت حركة الهمزة على اللام ثم أدغم فالتقدير قاتلوا الذين لا يؤمنون بالإله الذي لا تصلح الألوهة إلا له؛ لأنه ابتدع الأشياء {ولا باليوم الآخر} [النساء: 38] لأنهم لا يقرون بنعيم أهل الجنة ولا بالنار لمن أعدها الله له {حتى يعطوا الجزية} [التوبة: 29] وهي فعلة من جزى فلان فلانا يجزيه إذا قضاه أي لا يؤدون ما عليهم مما يحفظ رقابهم ويذلون به عن يد وقد تكلم العلماء في معناه فما حفظ فيه عن صحابي أن معنى {عن يد} [التوبة: 29] أن يؤديها وهو قائم والآخذ منه قاعد هذا عن المغيرة بن شعبة","bab":"باب ذكر الآية الرابعة قال جل ذكره: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية فمن العلماء من يقول هذه الآية ناسخة للعفو عن المشركين لأنه"},{"id":"nasikh-nahhas:372","bookId":"nasikh-nahhas","type":"section","seq":372,"chapter":"ص: 48","title":"ص: 502","page":"ج1 ص500","text":"وهو قول عكرمة وقيل عن يد عن إنعام عليهم وقيل عن يد أي يؤديها بيده ولا يوجه بها مع رسول قال أبو جعفر: ومعنى عن يد في كلام العرب وهو ذليل يقال أدى ذلك عن يده وعن يد وحكى سيبويه بايعته يدا بيد {وهم صاغرون} [التوبة: 29] قال عكرمة «إعطاؤه إياها صغار له» ، وقال غيره وأحكام المسلمين جارية عليهم وقد أدخلت الآية الخامسة في الناسخ والمنسوخ","bab":"باب ذكر الآية الرابعة قال جل ذكره: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية فمن العلماء من يقول هذه الآية ناسخة للعفو عن المشركين لأنه"},{"id":"nasikh-nahhas:373","bookId":"nasikh-nahhas","type":"section","seq":373,"chapter":"ص: 48","title":"باب ذكر الآية الخامسة قال جل وعز: {إلا تنفروا يعذبكم عذابا أليما}","page":"ج1 ص500","text":"[التوبة: 39]\nحدثنا عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، {إلا تنفروا يعذبكم عذابا أليما} [التوبة: 39] قال: \" نسختها {وما كان المؤمنون لينفروا كافة} [التوبة: 122] الآية \" وكذا قال الحسن، وعكرمة وقال","bab":"باب ذكر الآية الخامسة قال جل وعز: {إلا تنفروا يعذبكم عذابا أليما}"},{"id":"nasikh-nahhas:374","bookId":"nasikh-nahhas","type":"section","seq":374,"chapter":"ص: 48","title":"ص: 504","page":"ج1 ص503","text":"غيرهم الآيتان محكمتان لأن قوله تعالى: {إلا تنفروا يعذبكم عذابا أليما} [التوبة: 39] معناه إذا احتيج إليكم وإذا استنفرتم فهذا مما لا ينسخ لأنه خبر ووعيد، وقوله تعالى: {وما كان المؤمنون لينفروا كافة} [التوبة: 122] محكم لأنه لابد من أن يبقى بعض المؤمنين لئلا تخلو دار الإسلام من المؤمنين فتلحقهم مكيدة وهذا قول جماعة من الصحابة ومن التابعين وقد أدخلت الآية السادسة في الناسخ والمنسوخ","bab":"باب ذكر الآية الخامسة قال جل وعز: {إلا تنفروا يعذبكم عذابا أليما}"},{"id":"nasikh-nahhas:375","bookId":"nasikh-nahhas","type":"section","seq":375,"chapter":"ص: 48","title":"باب ذكر الآية السادسة من هذه السورة","page":"ج1 ص503","text":"قال أبو جعفر حدثنا عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس،: {عفا الله عنك لم أذنت لهم حتى يتبين لك الذين صدقوا وتعلم الكاذبين لا يستأذنك الذين يؤمنون بالله واليوم الأخر أن يجاهدوا بأموالهم وأنفسهم والله عليم بالمتقين إنما يستأذنك الذين لا يؤمنون بالله واليوم الآخر وارتابت قلوبهم فهم في ريبهم يترددون} : \" نسخ هذه الآيات الثلاث {فإذا استأذنوك لبعض شأنهم فأذن لمن شئت منهم} [النور: 62] «قال الحسن، وعكرمة» {لا يستأذنك الذين يؤمنون بالله واليوم الآخر} [التوبة: 44] نسخت الآية التي في سورة النور {فإذا استأذنوك لبعض شأنهم فأذن لمن شئت منهم} [النور: 62] \"\nقال أبو جعفر وحدثني جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال: حدثنا يزيد، عن سعيد، عن قتادة: {لا يستأذنك الذين يؤمنون بالله واليوم الآخر أن يجاهدوا بأموالهم وأنفسهم} [التوبة: 44] \" ثم نزل في النور {فأذن لمن شئت منهم} [النور: 62]","bab":"باب ذكر الآية السادسة من هذه السورة"},{"id":"nasikh-nahhas:376","bookId":"nasikh-nahhas","type":"section","seq":376,"chapter":"ص: 48","title":"ص: 506","page":"ج1 ص505","text":"\" ومن العلماء من يقول: هذه الآيات كلها محكمات قال\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، قال: وقوله {إنما يستأذنك الذين لا يؤمنون بالله واليوم الآخر} [التوبة: 45] \" فهذا تعيير للمنافقين حين استأذنوا في القعود عن الجهاد بغير عذر وعذر الله تعالى المؤمنين فقال: {فإذا استأذنوك لبعض شأنهم فأذن لمن شئت منهم} [النور: 62] \" قال أبو جعفر: وهذا من أحسن ما قيل في الآيات لأن قوله تعالى: {إنما يستأذنك الذين لا يؤمنون بالله واليوم الآخر} [التوبة: 45] صفات المنافقين لأنهم لا يؤمنون بوحدانية الله ولا بعقابه أهل معصيته ولا بثوابه أهل طاعته ثم قال تعالى: {وارتابت قلوبهم} [التوبة: 45] أي شككوا لأنهم على غير بصيرة من دينهم فهم في ريبهم يترددون متحيرين لا يعملون على حقيقة وقد أدخلت الآية السابعة في الناسخ والمنسوخ","bab":"باب ذكر الآية السادسة من هذه السورة"},{"id":"nasikh-nahhas:377","bookId":"nasikh-nahhas","type":"section","seq":377,"chapter":"ص: 48","title":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن","page":"ج1 ص506","text":"كما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق الحربي، قال: حدثنا علي بن مسلم، قال: حدثنا عبيد الله، عن سفيان، عن جابر، عن عكرمة،: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] قال: «نسخت هذه كل صدقة في القرآن» قال أبو جعفر: في هذه الآية الناسخة ما هو مختلف فيه وما هو مجتمع عليه فمما اختلف فيه منها الفرق بين الفقراء والمساكين اختلف في ذلك أهل التأويل والفقهاء وأهل اللغة وأهل النظر فقالوا في ذلك أحد عشر قولا\nفحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة،: {إنما الصدقات للفقراء والمساكين} [التوبة: 60]","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:378","bookId":"nasikh-nahhas","type":"section","seq":378,"chapter":"ص: 48","title":"ص: 508","page":"ج1 ص507","text":"قال: «الفقراء الذين بهم زمانة والمساكين الأصحاء المحتاجون» فهذا قول في الفرق بين الفقير والمسكين وقال الضحاك: «الفقراء فقراء المهاجرين والمساكين من لم يهاجر» وقال عكرمة: «الفقراء من اليهود والنصارى والمساكين من المسلمين» وقال عبيد الله بن الحسن: «المساكين الذين عليهم الذلة والخضوع والفقراء الذين يتجملون ويأخذون في السر» قال محمد بن مسلمة: «المسكين الذي لا شيء له والفقير الذي له المسكن والخادم» فهذه","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:379","bookId":"nasikh-nahhas","type":"section","seq":379,"chapter":"ص: 48","title":"ص: 509","page":"ج1 ص507","text":"خمسة أقوال وعن جماعة من الفقهاء قالوا: المسكين الذي له شيء والفقير الذي لا شيء له قال الشافعي: «الفقراء والله أعلم من لا مال لهم ولا حرفة تقع منه موقعا زمنا كان أو غير زمن سائلا كان أو متعففا، والمساكين من له مال أو حرفة لا تقع منه موقعا ولا تغنيه سائلا كان أو غير سائل» فهذه ستة أقوال، وقال: أبو ثور الفقير الذي له شيء والمسكين الذي لا يصيب من كسبه ما يقوته وقال أهل اللغة منهم يعقوب بن إسحاق في جماعة معه المسكين الذي لا شيء له والفقير الذي له شيء لا يكفيه، قال يونس: قلت لأعرابي أفقير أنت؟ فقال: لا بل مسكين وأنشد أهل اللغة:\n[البحر البسيط]\nأما الفقير الذي كانت حلوبته ... وفق العيال فلم يترك له سبد","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:380","bookId":"nasikh-nahhas","type":"section","seq":380,"chapter":"ص: 48","title":"ص: 510","page":"ج1 ص507","text":"ومن أجل ما روي فيه، ما رواه ابن أبي طلحة عن، ابن عباس، قال: «المساكين الطوافون والفقراء فقراء المسلمين» وأكثر أهل التأويل على هذا القول قال مجاهد، والحسن، والزهري، وجابر بن زيد، وعكرمة، والضحاك في اختلاف عنهما: المسكين السائل والفقير الذي لا يسأل فهذه تسعة أقوال، ومن أهل النظر من يقول الفقير هو الفقير إلى الشيء وإن كان يملك مالا فقد يكون غائبا عنه ويكون فقيرا إلى أخذ الصدقة والمسكين الذي عليه الخضوع والذلة والقول الحادي عشر: أن الفقير هو الذي يعطى لفقره فقط والمسكين الذي يكون عليه مع فقره خضوع وذلة السؤال، وكان محمد بن جرير يذهب إلى هذا القول وإن كان لم يذكر كثيرا مما ذكرناه وهو قول حسن وهو مستخرج من قول ابن عباس والجماعة الذين ذكرناهم معه لأن المسكين مشتق من المسكنة وهي الخضوع والذلة، قال الله تعالى: {وضربت عليهم الذلة والمسكنة} [البقرة: 61]","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:381","bookId":"nasikh-nahhas","type":"section","seq":381,"chapter":"ص: 48","title":"ص: 511","page":"ج1 ص507","text":"قال أبو جعفر: هذه الأقوال وإن كثرت فإذا جمعت بعضها إلى بعض ونظرت فيها قرب بعضها من بعض وذلك أن قول من قال المسكين كذا والفقير كذا لم يقل إنه لا يقال لغيره مسكين ولا فقير وقد قال الشافعي فيما روي عنه «إذا أوصى رجل بشيء للفقراء جاز أن يدفع إلى المساكين وإذا أوصى بشيء إلى المساكين جاز أن يدفع إلى الفقراء وإذا أوصى للفقراء والمساكين لم يجز أن يدفع إلى أحدهما» قال أبو جعفر: فلما اجتمعت هذه الأقوال وقد قلنا إن بعضها يقرب من بعض وجب أن يرجع إلى ما هو أجمعها وهو أن المسكين هو الذي يسأل الناس والفقير الذي لا يسأل ولا سيما وهذا قول ابن عباس ولا يعرف له مخالف من الصحابة فيه ثم تابعه على ذلك أهل التأويل الذين يرجع إلى قولهم في تفسير كتاب الله تعالى وأيضا فإن الأسماء إنما يرجع فيها إلى التعارف، والتعارف بين الناس إذا قيل ادفع هذا إلى المساكين أنهم الذين يسألون وإذا قيل ادفع هذا إلى الفقراء فهم الذين لا يسألون وقد دل على هذا كتاب الله قال الله عز وجل لا يسألون الناس إلحافا قال أبو جعفر: وسمعت علي بن سليمان يقول محتجا لأهل اللغة","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:382","bookId":"nasikh-nahhas","type":"section","seq":382,"chapter":"ص: 48","title":"ص: 512","page":"ج1 ص507","text":"لأنهم أعلم بالأسماء وبموضوعاتها، وقد أجمعوا على أن المسكين الذي لا شيء له قال وهو مشتق من السكون والسكون ذهاب الحركة حتى لا يبقى منها شيء وهذه صفة من لا يملك شيئا قال: والدليل على أن الفقير هو الذي يملك شيئا أنه مشتق من قولهم فقرته أي كسرت فقاره فهذا قد بقي له شيء قال أبو جعفر فأما قول الله تعالى {فكانت لمساكين يعملون في البحر} [الكهف: 79] فإذا صح أن المسكين هو الذي لا شيء له فالكلام على هذا سهل لأنه يجوز أن ينسب إليهم لأنهم كانوا يعملون فيها كما يقال قصدت فلانا في داره وإن كان مكتريا لها وكما يقال سرج الدابة وقد يجوز أن يكون نسبوا إلى المسكنة وهي الخضوع كما قال النبي صلى الله عليه وسلم: «يا مسكينة عليك السكينة» وقال عليه السلام: «مسكين مسكين من لا امرأة له ومسكينة مسكينة من لا زوج لها»","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:383","bookId":"nasikh-nahhas","type":"section","seq":383,"chapter":"ص: 48","title":"ص: 513","page":"ج1 ص507","text":"فإن قيل فما معنى حديث أبي هريرة\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن أبي الزناد، عن الأعرج، عن أبي هريرة، أن رسول الله صلى الله عليه وسلم قال: «ليس المسكين الذي ترده اللقمة واللقمتان والتمرة والتمرتان» قالوا: يا رسول الله فمن المسكين؟ قال: «الذي لا يجد غنى يغنيه ولا يفطن له فيعطى ولا يقوم فيسأل الناس» فقيل: معنى هذا أن الذي يسأل يجيئه الشيء بعد الشيء وقيل المعنى ليس المسكين الذي في نهاية المسكنة على أن هذا الحديث يدل على القول الذي اخترناه من أن المسكين السائل ويكون المعنى ليس المسكين الذي تعدونه فيكم مسكينا هذا كما قال عليه السلام: «ليس الغنى عن كثرة العرض إنما الغنى غنى النفس» ولهذا نظائر منها: قول النبي صلى الله عليه وسلم «إنما المحروب من حرب","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:384","bookId":"nasikh-nahhas","type":"section","seq":384,"chapter":"ص: 48","title":"ص: 514","page":"ج1 ص507","text":"دينه» أي المحروب على الحقيقة هو هذا وقال عليه السلام: «ما تعدون الرقوب فيكم؟» قالوا: الذي لا يعيش له ولد، قال: «بل الرقوب الذي لم يمت له ولد» أي هذا الذي لم يمت له ولد هو أولى بهذا الاسم أي أولى بأن يكون قد لحقته المصيبة واختلفوا من هذه الآية في قسم الزكوات فمنهم من قال: في أي صنف قسمتها من هذه الأصناف الثمانية جزى عنك ومنهم من قال: بل يقسم في الأصناف الثمانية كما سماها الله ومنهم من قال يقسم على ستة يسقط منها سهم المؤلفة قلوبهم لأنهم إنما كانوا في وقت النبي عليه السلام وسهم العاملين إذا فرق الإنسان زكاته قال أبو جعفر: فالقول الأول يروى عن ثلاثة من الصحابة عمر وحذيفة وابن عباس إن الصدقات جائز أن تدفع إلى بعض هذه الأصناف دون بعض","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:385","bookId":"nasikh-nahhas","type":"section","seq":385,"chapter":"ص: 48","title":"ص: 515","page":"ج1 ص507","text":"ولا يعرف عن أحد من الصحابة خلاف لهذا وهو مع ذلك قول سعيد بن جبير، وعطاء، وإبراهيم، وأبي العالية، وميمون بن مهران، ومالك بن أنس، وأبي حنيفة، وأبي يوسف، ومحمد والقول بأنها تقسم فيمن سمى الله تعالى قول الشافعي وحجته ظاهر الآية وأن ذلك بمنزلة الوصية إذا أوصى رجل لجماعة لم يخرج منهم أحد وحجة من ذكرنا غيره أن هذا مخالف للوصية لأن الوصية لا يجوز أن تقسم إلا فيمن سميت له فإن فقد بعضهم لم يرجع سهمه إلى من بقي، وقد","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:386","bookId":"nasikh-nahhas","type":"section","seq":386,"chapter":"ص: 48","title":"ص: 516","page":"ج1 ص507","text":"أجمع الجميع على أنه إذا فقد من ذكر في الآية رجع سهمه إلى من بقي وأيضا فإنه لا يجوز ولا يوصل إلى أن يعم كل من ذكر في الآية لأن الفقراء والمساكين لا يحاط بهم واحتجوا بحديث النبي عليه السلام حين قال لسلمة بن صخر حين وطئ في شهر رمضان نهارا: «أطعم ستين مسكينا، فقال ما بتنا ليلتنا إلا وحشا لا نصل إلى شيء، فقال امض إلى بني زريق فخذ صدقتهم فتصدق بوسق على ستين مسكينا وكل أنت وعيالك ما بقي» فأعطاه النبي صلى الله عليه وسلم صدقة هذه القبيلة ولم يقسمها على ثمانية \"، فلما احتمل قوله {إنما الصدقات للفقراء والمساكين} [التوبة: 60] الآية أن يقسم على هذا واحتمل أن يكون المعنى يقسم في هذا الجنس ولا يخرج عنهم ثم جاء عن ثلاثة من الصحابة أحد المعنيين كان أولى مع حجة من ذكرناه وأما {العاملين عليها} [التوبة: 60] قال الزهري: «هم السعاة» قال الحسن «يعطون بمقدار عملهم» وقال مجاهد، والضحاك «لهم الثمن»","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:387","bookId":"nasikh-nahhas","type":"section","seq":387,"chapter":"ص: 48","title":"ص: 517","page":"ج1 ص507","text":"فأما والمؤلفة قلوبهم فهم عند الشافعي على ضربين أحدهما أنهم قوم أسلموا ولم يكن إسلامهم قويا فللإمام أن يستميلهم ويعطيهم من الصدقات وإن كانوا أغنياء والضرب الآخر قوم في ناحيتهم عدو قد كفوا المسلمين مؤونته فيعانون على ذلك وإن كانوا أغنياء وأما {وفي الرقاب} [التوبة: 60] فأكثر العلماء على أنهم المكاتبون وهو قول أبي موسى الأشعري، والحسن، وابن زيد، والشافعي ومن العلماء من يقول يجوز أن يعتق من الزكاة لعموم الآية وهو قول مالك، وأما {والغارمين} [التوبة: 60] فهم على ضربين عند الشافعي أحدهما أن يدان الرجل في مصلحة نفسه من غير معصية فيقضى دينه والآخر أن يدان الرجل في حمالات وفي معروف وفيما فيه صلاح للمسلمين فيقضى دينه","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:388","bookId":"nasikh-nahhas","type":"section","seq":388,"chapter":"ص: 48","title":"ص: 518","page":"ج1 ص507","text":"، وأما وفي سبيل الله فأكثر الفقهاء يقول للغزاة ومنهم من يجيز أن يعطى في الحج وهو قول الكوفيين وأما {وابن السبيل} [البقرة: 177] فهو المنقطع به الذي ليس ببلده يعطى ما يتحمل به وإن كان له في بلده مال ولا قضاء عليه وفي هذه، الآية أيضا ما قد اختلفوا فيه وهو من سبيله أن يعطى من الزكاة\nفمن ذلك ما حدثنا الحسن بن غليب، قال: حدثنا مهدي بن جعفر، قال: حدثنا زيد بن أبي الزرقاء، عن سفيان الثوري، قال: «إذا كان لرجل خمسون درهما فلا يدفع إليه من الزكاة شيء ولا يدفع إلى أحد أكثر من خمسين درهما» قال أبو جعفر: فهذا القول يروى عن علي بن أبي طالب وابن مسعود وهو قول الحسن بن صالح، وعبد الله بن المبارك، وعبيد الله بن الحسن، وأحمد بن محمد بن حنبل، وإسحاق بن راهويه وأكثر أصحاب الحديث لأن فيه حديثا يروى عن النبي عليه السلام\nكما قرئ على أحمد بن شعيب، عن أحمد بن سليمان، قال: حدثنا يحيى بن آدم، قال: حدثنا سفيان الثوري، عن حكيم بن جبير، عن محمد بن عبد الرحمن بن يزيد، عن أبيه، عن عبد الله بن مسعود، قال: قال رسول الله صلى الله عليه وسلم: «من سأل وله ما يغنيه جاءت يعني مسألته في وجهه يوم القيامة خموشا، أو كدوحا» قالوا: يا رسول الله: وماذا يغنيه أو ماذا غناه؟ قال: «خمسون درهما أو حسابها من الذهب» قال يحيى بن أدم قال سفيان وحدثنا زبيد عن محمد بن عبد الرحمن بن يزيد قال أبو عبد الرحمن، حكيم بن جبير ضعيف في الحديث، وإنما ذكرناه لقول سفيان حدثنا زبيد هذا قول، وقال قوم: لا يحل لمن يملك أربعين درهما أن يأخذ من الزكاة شيئا واحتجوا بحديث عطاء بن يسار عن رجل من بني أسد سمع","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:389","bookId":"nasikh-nahhas","type":"section","seq":389,"chapter":"ص: 48","title":"ص: 520","page":"ج1 ص518","text":"النبي صلى الله عليه وسلم يقول: «من سأل وله أربعون درهما قد سأل إلحافا» وهذا قول الحسن «لا يحل لمن معه أربعون درهما أن يأخذ من الزكاة شيئا» وهو قول أبي عبيد القاسم بن سلام قال: «وهذان الحديثان أصلان فيمن يحل له أخذ الزكاة» وقد روي عن مالك بن أنس القول بهذا الحديث غير أن الصحيح عنه أنه لم يحد في ذلك حدا وقال على مقدار الحاجة ومذهب الشافعي قريب من هذا أنه قد يكون للرجل الجملة من الدنانير والدراهم وعليه عيال وهو محتاج إلى أكثر منها فله أن يأخذ من الزكاة","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:390","bookId":"nasikh-nahhas","type":"section","seq":390,"chapter":"ص: 48","title":"ص: 521","page":"ج1 ص518","text":"ومن الفقهاء من يقول من كانت معه عشرون دينارا أو مائتا درهم لم يحل له أن يأخذ من الزكاة شيئا وهذا قول أبي حنيفة، وأبي يوسف، ومحمد وحجتهم قول رسول الله صلى الله عليه وسلم لمعاذ: «عرفهم أن عليهم صدقة تؤخذ من أغنيائهم وتجعل في فقرائهم» فقد صار من تجب عليه الزكاة غنيا من المال على لسان رسول الله صلى الله عليه وسلم وفي الحديث الذي ذكرناه فيه الخموش تفسير ما فيه من الغريب وغيره، الخموش الخدوش واحدها خمش وقد خمش وجهه يخمشه ويخمشه خمشا وخموشا، والكدوح الآثار من الخدش والعض ومنه حمار مكدح أي معضض، وقال أبو عبد الرحمن: «لم يقل أحد عن سفيان حدثنا زبيد إلا يحيى بن آدم» وقال غيره لما قال سفيان حدثنا زبيد عن محمد بن عبد الرحمن لم يصل الحديث فقال من يرد عليه لم يحتج أن يصله لأنه قد ذكره بدءا وقد غمز يحيى بن معين على يحيى بن آدم فقال: قرأت على وكيع حديث يحيى بن آدم عن سفيان فقال ليس هذا ثورينا الذي نعرفه","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:391","bookId":"nasikh-nahhas","type":"section","seq":391,"chapter":"ص: 48","title":"ص: 522","page":"ج1 ص518","text":"فأما غير يحيى بن معين فمقدم ليحيى بن آدم حتى قال سفيان بن عيينة: «بلغني أنه يخرج في كل مائة سنة بعد موت رسول الله صلى الله عليه وسلم رجل من العلماء يقوي الله به الدين وإن يحيى بن آدم عندي منهم» واختلفوا في الآية الثامنة فقالوا فيها قولين","bab":"باب ذكر الآية السابعة قال جل وعز: {إنما الصدقات للفقراء والمساكين} [التوبة: 60] أدخلت في الناسخ والمنسوخ لأنها نسخت كل صدقة في القرآن"},{"id":"nasikh-nahhas:392","bookId":"nasikh-nahhas","type":"section","seq":392,"chapter":"ص: 48","title":"باب ذكر الآية الثامنة قال الله جل وعز: {استغفر لهم أو لا تستغفر لهم إن تستغفر لهم} [التوبة: 80] من العلماء من قال: هي منسوخة بقوله تعالى: {و","page":"ج1 ص519","text":"وفي رواية جويبر، عن الضحاك، عن ابن عباس، {استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم} [التوبة: 80] فقال: \" لأزيدن على السبعين فنسختها: {سواء عليهم أستغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم إن الله لا يهدي القوم الفاسقين} [المنافقون: 6] \" فهذا قول. ومن العلماء من قال: ليست بمنسوخة وإنما هذا على التهديد لهم أي لو استغفر لكم رسول الله صلى الله عليه وسلم ما غفر لكم فقال قائل: هذا القول لا يجوز أن يستغفر رسول الله صلى الله عليه وسلم لمنافق لأن المنافق كافر بنص كتاب الله قال جل ثناؤه: {إذا جاءك المنافقون} [المنافقون: 1] إلى قوله {ذلك بأنهم آمنوا ثم كفروا \"} [المنافقون: 3] ، وقال من احتج بأنها منسوخة الآثار تدل على ذلك\nكما روى الزهري، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس، عن عمر بن الخطاب، {ولا تصل على أحد منهم مات أبدا} [التوبة: 84] قال: \" لما مات عبد الله بن أبي ابن سلول أتى ابنه وقومه رسول الله صلى الله عليه وسلم فكلموه أن يصلي عليه ويقوم على قبره فجاء رسول الله صلى الله عليه وسلم ليصلي عليه قال عمر رضي الله عنه فقمت بينه وبين الجنازة فقلت: يا رسول الله تصلي عليه وهو الفاعل كذا وكذا يوم كذا وكذا وهو الراجع بثلث الناس","bab":"باب ذكر الآية الثامنة قال الله جل وعز: {استغفر لهم أو لا تستغفر لهم إن تستغفر لهم} [التوبة: 80] من العلماء من قال: هي منسوخة بقوله تعالى: {ولا تصل على أحد منهم "},{"id":"nasikh-nahhas:393","bookId":"nasikh-nahhas","type":"section","seq":393,"chapter":"ص: 48","title":"ص: 524","page":"ج1 ص523","text":"يوم أحد وهو القائل يوم كذا وكذا كذا وهو الذي يقول لا تنفقوا على من عند رسول الله حتى ينفضوا؟ فجعل رسول الله صلى الله عليه وسلم يقول: \" أخر عني يا عمر وجعل عمر يردد قوله فقال رسول الله صلى الله عليه وسلم: «أخر عني يا عمر فلو أني أعلم أني لو استغفرت لهم أكثر من سبعين مرة غفر لهم لاستغفرت لهم» فصلى عليه رسول الله صلى الله عليه وسلم ووقف على قبره حتى دفن فما لبثنا إلا ليالي حتى نزلت هذه الآية {ولا تصل على أحد منهم مات أبدا ولا تقم على قبره إنهم كفروا بالله ورسوله وماتوا وهم فاسقون ولا تعجبك أموالهم وأولادهم إنما يريد الله أن يعذبهم بها في الدنيا وتزهق أنفسهم وهم كافرون} [التوبة: 85] قال فكان عمر يعجب من جرأته على رسول الله صلى الله عليه وسلم في ذلك اليوم وما أنزل الله عز وجل في ذلك من القرآن قال أبو جعفر: فقالوا في هذا الحديث إنه صلى عليه بعد كلام عمر إياه وإن كان كلام عمر قد أحمد منه بعد ذلك حتى قال رسول الله صلى الله عليه وسلم: «ما بعث الله قط نبيا إلا وفي أمته محدث فإن يكن في أمتي فهو عمر رضي الله عنه» ، فقيل معنى محدث ينطق على لسانه بالحق\nوفي حديث عبيد الله بن عمر عن نافع، عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال لعمر ذلك اليوم إن الله تعالى لم ينهني عن الصلاة عليهم وإنما خيرني \" قال أبو جعفر: ففي هذا الحديث التوقيف من رسول الله صلى الله عليه وسلم أن أو هاهنا للتخيير أعني من قوله: {استغفر لهم أو لا تستغفر لهم} [التوبة: 80] فإن قيل فكيف يجوز أن يستغفر عليه السلام لمنافق؟ فالجواب عن هذا أن يستغفر له على ظاهره على أنه مسلم، وباطنه إلى الله تعالى وقد قيل ولا تصل على أحد منهم مات أبدا ناسخ لفعله عليه السلام لا للآية الأخرى وقد توهم بعض الناس أن قوله تعالى {ولا تصل على أحد منهم} [التوبة: 84] ناسخ لقوله تعالى {وصل عليهم إن صلاتك سكن لهم} [التوبة: 103] قال أبو جعفر: وهذا غلط عظيم ولهذا كره العلماء أن يجترئ أحد على تفسير كتاب الله تعالى حتى يكون عالما بأشياء منها الآثار ولا اختلاف بين أهل الآثار أن قوله تعالى {وصل عليهم} [التوبة: 103] ليس هم الذين قيل فيهم {ولا تصل على أحد منهم مات أبدا} [التوبة: 84]","bab":"باب ذكر الآية الثامنة قال الله جل وعز: {استغفر لهم أو لا تستغفر لهم إن تستغفر لهم} [التوبة: 80] من العلماء من قال: هي منسوخة بقوله تعالى: {ولا تصل على أحد منهم "},{"id":"nasikh-nahhas:394","bookId":"nasikh-nahhas","type":"section","seq":394,"chapter":"ص: 48","title":"ص: 526","page":"ج1 ص523","text":"ويدلك على ذلك أن بعد {وصل عليهم} [التوبة: 103] {ألم يعلموا أن الله هو يقبل التوبة عن عباده} [التوبة: 104] فكيف لا يصلي على من تاب؟ وأهل التأويل يقولون نزلت {وصل عليهم} [التوبة: 103] في أبي لبابة وجماعة معه ربطوا أنفسهم في السواري لأنهم تخلفوا عن غزوة تبوك إلى أن تاب الله جل وعز عليهم وقد ذكرت الآية التاسعة في الناسخ والمنسوخ","bab":"باب ذكر الآية الثامنة قال الله جل وعز: {استغفر لهم أو لا تستغفر لهم إن تستغفر لهم} [التوبة: 80] من العلماء من قال: هي منسوخة بقوله تعالى: {ولا تصل على أحد منهم "},{"id":"nasikh-nahhas:395","bookId":"nasikh-nahhas","type":"section","seq":395,"chapter":"ص: 48","title":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة","page":"ج1 ص525","text":"النبي صلى الله عليه وسلم أو احتيج إلى المسلمين فاستنفروا لم يسع أحدا التخلف وإذا بعث النبي صلى الله عليه وسلم سرية تخلفت طائفة، وهذا مذهب ابن عباس","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:396","bookId":"nasikh-nahhas","type":"section","seq":396,"chapter":"ص: 48","title":"ص: 528","page":"ج1 ص525","text":"، والضحاك، وقتادة","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:397","bookId":"nasikh-nahhas","type":"section","seq":397,"chapter":"ص: 48","title":"سورة يونس صلى الله عليه وسلم","page":"ج1 ص527","text":"حدثنا أبو جعفر قال حدثنا يموت بن المزرع، قال: حدثنا أبو حاتم، قال: حدثنا أبو عبيدة، قال: حدثنا يونس، عن أبي عمرو، عن مجاهد، عن ابن عباس، قال: «نزلت سورة يونس بمكة فهي مكية» قال أبو جعفر: لم نجد فيها مما يدخل في هذا الكتاب إلا موضعا واحدا قال الله عز وجل {واصبر حتى يحكم الله وهو خير الحاكمين} [يونس: 109] أي اصبر على أذاهم ومكروههم حتى يقضي الله تعالى فيهم وهو خير القاضين وأعدل الفاصلين، فمذهب ابن زيد أنها منسوخة وإنما نسخ منها الصبر عليهم قال: أنزل الله تعالى بعد هذا الأمر بالجهاد والغلظة عليهم","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:398","bookId":"nasikh-nahhas","type":"section","seq":398,"chapter":"ص: 48","title":"سورة هود","page":"ج1 ص529","text":"قال أبو جعفر حدثنا يموت بن المزرع، بإسناده عن ابن عباس، قال: «نزلت سورة هود بمكة فهي مكية» قال أبو جعفر: لم نجد فيها مما يدخل في هذا الكتاب إلا آية واحدة\nمن رواية جويبر، عن الضحاك، عن ابن عباس قال: قوله تعالى {من كان يريد الحياة الدنيا وزينتها} [هود: 15] \" قال: أي ثواب الحياة الدنيا قال: {وزينتها} [هود: 15] ما لها {نوف إليهم أعمالهم فيها} [هود: 15] قال: نوفر لهم ثواب أعمالهم بالصحة والسرور في الأهل والمال والولد وهم فيها لا يبخسون، قال لا ينقصون قال: ثم نسختها: {من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد} [الإسراء: 18] \" قال أبو جعفر: محال أن يكون هاهنا نسخ لأنه خبر والنسخ في الأخبار محال لو جاز النسخ فيها ما عرف حق من باطل ولا صدق من كذب، ولبطلت المعاني ولجاز لرجل أن يقول لقيت فلانا ثم يقول نسخته ما لقيته","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:399","bookId":"nasikh-nahhas","type":"section","seq":399,"chapter":"ص: 48","title":"سورة يوسف صلى الله عليه وسلم","page":"ج1 ص531","text":"قال أبو جعفر حدثنا يموت بن المزرع، بإسناده عن ابن عباس، قال: «نزلت سورة يوسف بمكة فهي مكية» قال أبو جعفر: رأيت بعض المتأخرين قد ذكر أن فيها آية منسوخة وهي قوله جل وعز إخبارا عن يوسف {توفني مسلما وألحقني بالصالحين} [يوسف: 101] قال نسخه قول النبي صلى الله عليه وسلم: «لا يتمنين أحدكم الموت لضر نزل به» قال أبو جعفر: وهذا قول لا معنى له ولولا أنا أردنا أن يكون كتابنا متقصا لما ذكرناه لأنه ليس معنى {توفني مسلما} [يوسف: 101] توفني الساعة وهذا بين جدا لا إشكال فيه ولو صح أن قول يوسف صلى الله عليه وسلم {توفني مسلما} [يوسف: 101] أنه يريد في ذلك الوقت لما كان منسوخا لأن النبي صلى الله عليه وسلم إنما قال: \" لا يتمنين أحدكم الموت لضر نزل به فإذا تمناه إنسان لغير ضر فليس بمخالف للنبي صلى الله عليه وسلم وقد يجوز أن يتمنى الموت من له عمل صالح متخلصا\nمن الكبائر فهذا عمر بن الخطاب رضي الله عنه لما استقامت أموره وفتح الله على يديه الفتوح وأسلم ببركته من لا يحصى عدده تمنى الموت فقال: «اللهم كبرت سني ورق عظمي وانتشرت رعيتي فاقبضني إليك غير مفرط ولا مضيع»\nوعن مالك، عن أبي الزناد، عن الأعرج، عن أبي هريرة، عن رسول الله صلى الله عليه وسلم: «من أحب لقاء الله أحب الله لقاءه ومن كره لقاء الله كره الله لقاءه» فظاهر هذا الحديث أن السليم من الذنوب محب للقاء الله تعالى في كل الأحوال وقد قيل هذا عند الموت","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:400","bookId":"nasikh-nahhas","type":"section","seq":400,"chapter":"ص: 48","title":"سورة الرعد","page":"ج1 ص534","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: «سورة الرعد نزلت بمكة فهي مكية»\nوروى حميد، عن مجاهد، قال: «سورة الرعد مكية ليس فيها ناسخ ولا منسوخ»\nوروى سعيد، عن قتادة، قال: \" سورة الرعد مدنية إلا آية واحدة، قوله تعالى: {ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة} [الرعد: 31] الآية \" والقول الأول أولى لأنه المتعارف\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا أحمد بن داود، قال: حدثنا مسدد، قال: حدثنا","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:401","bookId":"nasikh-nahhas","type":"section","seq":401,"chapter":"ص: 48","title":"ص: 536","page":"ج1 ص535","text":"أبو عوانة، عن أبي بشر، قال قلت لسعيد بن جبير: {ومن عنده علم الكتاب} [الرعد: 43] أهو عبد الله بن سلام، قال: \" كيف يكون عبد الله بن سلام والسورة مكية؟ قال: وكان سعيد بن جبير يقرأ {ومن عنده علم الكتاب} [الرعد: 43] قال أبو جعفر: أنكر هذا سعيد بن جبير لأن السورة مكية وعبد الله بن سلام إنما أسلم بالمدينة","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:402","bookId":"nasikh-nahhas","type":"section","seq":402,"chapter":"ص: 48","title":"سورة إبراهيم صلى الله عليه وسلم","page":"ج1 ص535","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: \" سورة إبراهيم نزلت بمكة فهي مكية سوى آيتين منها نزلتا بالمدينة وهما قوله: {ألم تر إلى الذين بدلوا نعمة الله كفرا} [إبراهيم: 28] إلى آخر الآيتين نزلتا في قتلى بدر من المشركين \" وروى، سعيد، عن قتادة، قال: \" سورة إبراهيم مكية إلا آيتين منها نزلتا بالمدينة قوله تعالى: {ألم تر إلى الذين بدلوا نعمة الله كفرا} [إبراهيم: 28] إلى {وبئس القرار} [إبراهيم: 29] قال أبو جعفر: والذي قاله قتادة لا يمتنع قد تكون السورة مكية ثم ينزل الشيء بالمدينة فيأمر رسول الله صلى الله عليه وسلم بجعله فيها ولا يكون هذا لأحد غير رسول الله صلى الله عليه وسلم لما يأتيه من الوحي بذلك إذ كان تأليف القرآن معجزا لا يؤخذ إلا عن الله تعالى وعن رسوله صلى الله عليه وسلم وعن الجماعة الذين لا يلحقهم الغلط ولا يتواطئون على الباطل","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:403","bookId":"nasikh-nahhas","type":"section","seq":403,"chapter":"ص: 48","title":"سورة الحجر","page":"ج1 ص537","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: «نزلت سورة الحجر بمكة فهي مكية» قال أبو جعفر: لم نجد فيها مما يدخل في هذا الكتاب إلا حرفين، قوله تعالى: {فاصفح الصفح الجميل} [الحجر: 85] قال سعيد عن، قتادة، \" نسخته: {واقتلوهم حيث ثقفتموهم} [البقرة: 191] والحرف الآخر {وأعرض عن المشركين} [الحجر: 94] \" روي، عن، ابن عباس: «نسخته براءة، والأمر بالقتال»","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:404","bookId":"nasikh-nahhas","type":"section","seq":404,"chapter":"ص: 48","title":"سورة النحل","page":"ج1 ص539","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: \" وسورة النحل نزلت بمكة فهي مكية سوى ثلاث آيات من آخرها فإنهن نزلن بين مكة والمدينة في منصرف رسول الله صلى الله عليه وسلم من أحد وذلك أنه قتل حمزة بن عبد المطلب ومثل به المشركون فقال رسول الله صلى الله عليه وسلم: «لئن أظفرني الله بهم لأمثلن بثلاثين منهم» فقال أصحاب رسول الله صلى الله عليه وسلم: والله يا رسول الله لئن أظفرنا الله بهم لنمثلن بهم تمثيلا لم يمثل به أحد من العرب، فأنزل الله تعالى بين مكة والمدينة ثلاث آيات وهن قوله تعالى {وإن عاقبتم فعاقبوا بمثل ما عوقبتم به} [النحل: 126] وما نزل بين مكة والمدينة فهو مدني \"","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:405","bookId":"nasikh-nahhas","type":"section","seq":405,"chapter":"ص: 48","title":"ص: 542","page":"ج1 ص541","text":"قال أبو جعفر: في هذه السورة موضعان يصلحان في هذا الكتاب أحدهما قوله تعالى: {ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا حسنا} [النحل: 67]\nقال أبو جعفر حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا الثوري، عن الأسود بن قيس، عن عمرو بن سفيان، عن ابن عباس، أنه سئل عن هذه الآية، {ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا حسنا} [النحل: 67] قال: «السكر ما حرم من ثمراتها والرزق الحسن ما حل من ثمراتها»\nقال عبد الرزاق، وأخبرنا معمر، عن قتادة، {تتخذون منه سكرا} [النحل: 67] قال: «خمور الأعاجم ونسخت في سورة المائدة» قال: «والرزق الحسن ما ينتبذون ويخللون ويأكلون» قال أبو جعفر: والقول في أنها منسوخة يروى عن سعيد بن جبير","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:406","bookId":"nasikh-nahhas","type":"section","seq":406,"chapter":"ص: 48","title":"ص: 543","page":"ج1 ص542","text":"، ومجاهد، والشعبي، وإبراهيم النخعي، وأبي رزين قال أبو جعفر: الحق في هذا أنه خبر لا يجوز فيه نسخ ولكن يتكلم العلماء بشيء فيتأول عليهم ما هو غلط لأن قول قتادة: «ونسخت يعني الخمر أي نسخت إباحتها والدليل على هذا» أن سعيدا روى عن قتادة، قال: نزلت هذه الآية: {ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا حسنا} [النحل: 67] والخمر يومئذ حلال ثم أنزل الله بعد تحريمها في سورة المائدة \" قال أبو جعفر: وهذا قول حسن صحيح أخبر الله تعالى أنهم يفعلون هذا ونزل قبل تحريم الخمر على أن جماعة من أهل العلم والنظر قالوا غير ما تقدم منهم أبو عبيدة قال السكر الطعم وقال غيره السكر ما سد الجوع مشتق من قولهم سكرت النهر أي سددته فتتخذون منه سكرا على هذا ما كان من العجوة والرطب وهو معنى قول أبي عبيدة إذا شرح والموضع الآخر قوله تعالى: {وجادلهم بالتي هي أحسن} [النحل: 125] من قال هو منسوخ قال نسخه الأمر بالقتال في","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:407","bookId":"nasikh-nahhas","type":"section","seq":407,"chapter":"ص: 48","title":"ص: 544","page":"ج1 ص542","text":"سورة براءة ومن قال ليس بمنسوخ قال المجادلة بالتي هي أحسن هي الانتهاء إلى ما أمر الله تعالى به، وهذا لا ينسخ","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:408","bookId":"nasikh-nahhas","type":"section","seq":408,"chapter":"ص: 48","title":"سورة بني إسرائيل","page":"ج1 ص542","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: «نزلت سورة بني إسرائيل بمكة فهي مكية» قال أبو جعفر: فيها ثلاث آيات مما يصلح أن تكون في هذا الكتاب الأولى منهن قال الله تعالى: {إما يبلغن عندك الكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما وقل لهما قولا كريما واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربياني صغيرا} [الإسراء: 24] في هذا ثلاثة أقوال: من العلماء من قال في قوله تعالى: {وقل رب ارحمهما كما ربياني صغيرا} [الإسراء: 24] هو منسوخ بأن هذا مجمل ولا يجوز إن كان أبواه مشركين أن يترحم عليهما\nومنهم من قال يجوز هذا إذا كانا حيين فإذا ماتا لم يجز ومنهم من قال: لا يجوز أن يترحم على كافر ولا يستغفر له حيا كان أو ميتا، والآية محكمة مستثنى منها الكفار\nقال أبو جعفر حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال: حدثنا يزيد، عن سعيد، عن قتادة: {وقل رب ارحمهما كما ربياني صغيرا} [الإسراء: 24] : \" نسخ منه حرف واحد لا يجوز لمسلم أن يستغفر لأبويه إذا كانا مشركين، لا يقول: رب ارحمهما كما ربياني صغيرا ولكن ليخفض لهما جناح الذل من الرحمة وليقل لهما قولا معروفا \" قال تعالى: {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى} [التوبة: 113] ، فنسخ هذا: {وقل رب ارحمهما كما ربياني صغيرا} [الإسراء: 24] \" والقول الثاني: قول جماعة من أصحاب الحديث واحتجوا بحديث سعيد بن جبير عن ابن عباس قال: «لم يزل إبراهيم عليه السلام يستغفر لأبيه حتى مات فلما مات تبين له أنه عدو لله فتبرأ منه» ، واحتجوا بحديث الزهري عن","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:409","bookId":"nasikh-nahhas","type":"section","seq":409,"chapter":"ص: 48","title":"ص: 547","page":"ج1 ص546","text":"سهل بن سعد أن رسول الله صلى الله عليه وسلم قال: «اللهم اغفر لقومي فإنهم لا يعلمون»","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:410","bookId":"nasikh-nahhas","type":"section","seq":410,"chapter":"ص: 48","title":"ص: 548","page":"ج1 ص546","text":"والقول الثالث: يدل على صحته، ظاهر القرآن قال تعالى: {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى} [التوبة: 113] وأيضا فإن النبي صلى الله عليه وسلم لم يزل من أول أمره يدعو إلى الله تعالى ويخبر أن الله تعالى لا يغفر الشرك ومع هذا فيقول صلى الله عليه وسلم في النصارى وهم أهل كتاب «لا تبدءوهم بالسلام وإذا لقيتموهم في طريق فاضطروهم إلى أضيقه» فكيف يستغفر لمن هذه حاله أو يبجل أو يعظم بالدعاء له بالرحمة وأيضا فإن الشرك أعظم الذنوب وأشدها فكيف يدعى لأهله بالمغفرة ولم يصح أن الله تعالى أباح الاستغفار للمشركين ولا فرضه ولا ينسخ إلا ما أبيح أو فرض فأما قول الله تعالى: {وما كان استغفار إبراهيم لأبيه إلا عن موعدة وعدها إياه} [التوبة: 114] فقد قيل إن أباه وعده أنه يظهر إسلامه واستغفر له فلما لم يظهر إسلامه ترك الاستغفار له فإن قيل فما معنى {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين} [التوبة: 113] فهل يكون هذا في العربية إلا بعد الاستغفار لهم؟ فقد أجاب عن هذا بعض أهل النظر فقال يجوز أن يكون بعض المسلمين ظن أن هذا جائز فاستغفر لأبويه وهما مشركان فنزل هذا قال أبو جعفر: هذا لا يحتاج أن يقال فيه يجوز لأن فيه حديثا قد غاب عن هذا المجيب\nحدثناه أحمد بن محمد الأزدي، قال: حدثنا يزيد بن","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:411","bookId":"nasikh-nahhas","type":"section","seq":411,"chapter":"ص: 48","title":"ص: 549","page":"ج1 ص546","text":"سنان، قال: حدثنا محمد بن كثير، قال: حدثنا سفيان الثوري، عن أبي إسحاق، عن أبي الخليل، عن علي بن أبي طالب، رضي الله عنه قال: سمعت رجلا، يستغفر لأبويه وهما مشركان فقلت له: \" أتستغفر لأبويك وهما مشركان؟ فقال: أليس قد استغفر إبراهيم عليه السلام لأبيه فذكرت ذلك للنبي صلى الله عليه وسلم فنزلت {وما كان استغفار إبراهيم لأبيه إلا عن موعدة وعدها إياه} [التوبة: 114] قال أبو جعفر: وهذا من أحسن ما روي في الآية، مع استقامة طريقه وصحة إسناده\nوعلى أن الزهري، قد روى عن سعيد بن المسيب، عن أبيه، قال: دخل رسول الله صلى الله عليه وسلم على أبي طالب عند موته وعنده أبو جهل، وعبد الله بن أبي أمية بن المغيرة فقال: «يا عم قل لا إله إلا الله كلمة أشهد لك بها يوم القيامة» ، فقال له أبو جهل، وعبد الله بن أبي أمية أترغب عن ملة عبد المطلب؟ وأقبل النبي صلى الله عليه وسلم يعرض عليه وهما يعارضانه فكان آخر كلمة قالها على ملة عبد المطلب وأبى أن يقول لا إله إلا الله، فقال رسول الله صلى الله عليه وسلم: «لأستغفرن لك ما لم أنه عنك» فأنزل الله تعالى: {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى} [التوبة: 113] وأنزل في أبي طالب {إنك لا تهدي من أحببت ولكن الله يهدي من يشاء} [القصص: 56]","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:412","bookId":"nasikh-nahhas","type":"section","seq":412,"chapter":"ص: 48","title":"ص: 550","page":"ج1 ص548","text":"\" وحديث مسروق عن عبد الله على غير هذا في نزول الآية قال: \" كنا مع النبي صلى الله عليه وسلم فجلس على قبر بين القبور فبكى حتى ارتفع نحيبه ففزعنا لذلك فلما قام قال له عمر مما بكيت يا رسول الله؟ قال: «على قبر آمنة بنت وهب استأذنت ربي جل وعز في الاستغفار لها فأنزل علي {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين» } [التوبة: 113] الآية فدخلني ما يدخل الولد لوالديه فبكيت \" قال أبو جعفر: وليست هذه الأحاديث بمتناقضة لأنه يجوز أن تكون الآية نزلت بعد هذا كله وليس في شيء من الأحاديث أن النبي صلى الله عليه وسلم استغفر لمشرك","bab":"باب ذكر الآية التاسعة قال الله جل وعز: {ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه} [التوبة: 120] مذهب ابن زيد "},{"id":"nasikh-nahhas:413","bookId":"nasikh-nahhas","type":"section","seq":413,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال الله جل وعز: {ولا تقربوا مال اليتيم إلا بالتي هي أحسن حتى يبلغ أشده}","page":"ج1 ص549","text":"[الأنعام: 152]\nحدثني جعفر بن مجاشع، قال: حدثنا إبراهيم الحربي، قال: حدثنا عبيد الله، قال: حدثنا يزيد، عن سعيد، عن قتادة، {ولا تقربوا مال اليتيم إلا بالتي هي أحسن} [الأنعام: 152] : \" فكانوا من هذا في جهد حتى نزلت {وإن تخالطوهم فإخوانكم} [البقرة: 220] \" قال أبو جعفر قال مجاهد أي: «لا تقربوا مال اليتيم فتستقرضوا منه إلا بالتي هي أحسن التجارة لهم» وقال ربيعة، وزيد بن أسلم، ومالك: «الأشد الحلم» قال أبو جعفر: وقد قال جماعة من أهل التفسير وبلغ أشده ثلاثا وثلاثين سنة وليس هذا بمتناقض يكون أول الأشد بلوغ الحلم فعلى هذا يصح القولان وقد ذكرنا أمر اليتامى في سورة البقرة بأكثر من هذا","bab":"باب ذكر الآية الثانية قال الله جل وعز: {ولا تقربوا مال اليتيم إلا بالتي هي أحسن حتى يبلغ أشده}"},{"id":"nasikh-nahhas:414","bookId":"nasikh-nahhas","type":"section","seq":414,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك","page":"ج1 ص551","text":"{بالغدو والآصال} [الأعراف: 205] ، قال: بالغداة والعشي {ولا تكن من الغافلين} [الأعراف: 205] ، قال عن القراءة في الصلاة \" وفي رواية سعيد بن جبير عن، ابن عباس: \" كان النبي صلى الله عليه وسلم يجهر بالقرآن فإذا جهر به سب المشركون القرآن ومن جاء به فخفض صوته حتى لا يسمعه أحد فنزلت {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] أي أسمعهم القرآن حتى يأخذوه عنك \"\nوالقول الثالث: إن المعنى في الدعاء وأن الصلاة هاهنا الدعاء هذا قول أبي هريرة، وأبي موسى وعائشة\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا فهد، قال حدثنا معلى بن أسد، قال: حدثنا سلام بن أبي مطيع، قال: حدثنا هشام بن عروة، عن أبيه، قال: قالت لي خالتي عائشة يا ابن أختي هل تدري فيم أنزلت هذه الآية {ولا تجهر بصلاتك ولا تخافت بها} [الإسراء: 110] قلت: لا: قالت: «أنزلت في الدعاء» قال أبو جعفر: وهذا من أحسن ما قيل في الآية لأن فيه هذا التوقيف عن عائشة، والمعروف في كلام العرب أن الصلاة الدعاء ولا يقال للقراءة صلاة إلا على مجاز وأيضا فإن العلماء مجمعون على كراهة رفع الصوت بالدعاء، وقد قال الله: {ادعوا ربكم تضرعا وخفية} [الأعراف: 55] وأما أن تكون الآية منسوخة بقوله تعالى: {واذكر ربك في نفسك تضرعا وخيفة} [الأعراف: 205] فبعيد لأن هذا عقيب قوله تعالى: {وإذا قرئ القرآن فاستمعوا له وأنصتوا لعلكم ترحمون} [الأعراف: 204] فإنما أمر الله تعالى إذا أنصت أن يذكر ربه في نفسه تضرعا وخيفة من عقابه ولهذا كان هاهنا","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:415","bookId":"nasikh-nahhas","type":"section","seq":415,"chapter":"ص: 48","title":"ص: 554","page":"ج1 ص553","text":"وخيفة وثم وخفية ومع هذا فقد روي عن النبي صلى الله عليه وسلم في كراهة رفع الصوت بالدعاء ما يقوي هذا وقد قال ابن جريج في قول الله تعالى: {إنه لا يحب المعتدين} [الأعراف: 55] قال: «من الاعتداء رفع الصوت بالدعاء والنداء والصياح به»\nقال أبو جعفر حدثنا أحمد بن محمد الأزدي، قال: حدثنا محمد بن عمرو بن يونس، قال: حدثنا أبو معاوية الضرير، عن عاصم، عن أبي عثمان، عن أبي موسى، قال: كنت مع النبي صلى الله عليه وسلم في سفر فنزلنا في وهدة من الأرض فرفع الناس أصواتهم بالتكبير فقال رسول الله صلى الله عليه وسلم: «يا أيها الناس اربعوا على أنفسكم إنكم لا تدعون أصم ولا غائبا إنكم تدعون سميعا قريبا» ثم دعاني وكنت قريبا منه فقال: «يا عبد الله بن قيس ألا أعلمك كلمة من كنز الجنة؟» فقلت: بلى يا رسول الله قال: «لا حول ولا قوة إلا بالله»","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:416","bookId":"nasikh-nahhas","type":"section","seq":416,"chapter":"ص: 48","title":"سورة الكهف، ومريم، وطه، والأنبياء عليهم السلام","page":"ج1 ص554","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس: «أنهن نزلن بمكة لم نجد فيهن مما يدخل في هذا الكتاب إلا موضعا واحدا مختلفا فيه»\nقال جل وعز: {وداود وسليمان إذ يحكمان في الحرث إذ نفشت فيه غنم القوم وكنا لحكمهم شاهدين ففهمناها سليمان وكلا آتينا حكما وعلما} قال أبو جعفر جماعة من الكوفيين يذهبون إلى أن هذا الحكم منسوخ وأن البهائم إذا أفسدت زرعا في ليل أو نهار أنه لا يلزم صاحبها شيء وإن كان رسول الله صلى الله عليه وسلم قد حكم بغير هذا فخالفوا حكمه وزعموا أنه منسوخ بقوله صلى الله عليه وسلم العجماء جبار \" ومنهم من يقول في الحديث العجماء جرحها جبار والعجماء\nالبهيمة وأصله أنه يقال رجل أعجم وامرأة عجماء إذا كانا لا يفصحان بالكلام ويقال إنه ما تقدم أبا حنيفة أحد بهذا القول حتى قال بعض العلماء هذا الحكم أصله من كتاب الله، وقد حكم به ثلاثة من الأنبياء فلا تجوز مخالفته بتأويل قال أبو جعفر: وسنبين ذلك من الآية ومن حكم الأنبياء عليهم السلام قال جل وعز: {وداود وسليمان} أي واذكر داود وسليمان {إذ يحكمان في الحرث} [الأنبياء: 78] قال قتادة: «كان نبتا» وعن ابن مسعود، «كان الحرث كرما قد أنبتت عنا قيده» {إذ نفشت فيه غنم القوم} [الأنبياء: 78] والنفش في كلام العرب لا يكون إلا بالليل أي دخلت الغنم بالليل في حرث القوم الذين ليسوا أصحابها فأفسدت العنب وأكلته \" {وكنا لحكمهم شاهدين} [الأنبياء: 78] أي لم يغب عنا ذلك {ففهمناها سليمان} [الأنبياء: 79] أي القضية قال ابن عباس دخلت الغنم فأفسدت الكرم فاختصموا إلى داود فقضى بالغنم لصاحب الكرم لأن ثمنها كان قريبا منه فمروا على سليمان فأخبروه فقال كان غير هذا الحكم أرفق بالجميع فدخل صاحب الغنم فأخبر داود فقال لسليمان كيف الحكم عندك قال يا نبي الله تدفع الغنم إلى صاحب الحرث فيصيب من ألبانها وأصوافها وأولادها وتدفع الكرم إلى صاحب الغنم فيقوم به حتى يرجع إلى حاله فإذا رجع إلى حاله\nسلمت الكرم إلى صاحبه والغنم إلى صاحبها، قال الله تعالى {ففهمناها سليمان} [الأنبياء: 79] قال أبو جعفر: ثم رجعنا إلى ما حكم به رسول الله صلى الله عليه وسلم\nكما قرئ على أبي عبد الرحمن أحمد بن شعيب، عن القاسم بن زكريا بن دينار، قال: حدثني معاوية بن هشام، عن سفيان، عن إسماعيل بن أمية، وعبد الله بن عيسى، عن الزهري، عن حرام بن محيصة، عن البراء،: «أن ناقة، لآل البراء أفسدت نبتا فقضى رسول الله صلى الله عليه وسلم أن على أهل الثمار حفظها بالنهار وضمن أصحاب الماشية ما أصابت ماشيتهم بالليل»\nقال أبو عبد الرحمن، وأخبرني عمرو بن عثمان، قال: حدثنا الوليد، عن الأوزاعي، عن الزهري، عن حرام بن محيصة،: أن البراء بن عازب","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:417","bookId":"nasikh-nahhas","type":"section","seq":417,"chapter":"ص: 48","title":"ص: 559","page":"ج1 ص558","text":"أخبره، أنه كانت له ناقة ضارية فدخلت حائطا فأفسدت فيه فكلم فيها رسول الله صلى الله عليه وسلم فقضى رسول الله صلى الله عليه وسلم أن على أهل الحوائط حفظها بالنهار وعلى أهل المواشي حفظها بالليل وأن على أهل الماشية ما أصابت بالليل \" فهذا حكم رسول الله صلى الله عليه وسلم بعد حكم نبيين قبله بالتضمين قال أبو حنيفة: «لا ضمان» والحديث صحيح عن النبي صلى الله عليه وسلم وإن كان مالك قد رواه عن الزهري، عن حرام بن محيصة، أن ناقة، لآل البراء فصار مقطوعا فقد رواه من تقوم به الحجة متصلا لأن إسماعيل بن أمية، وعبد الله بن عيسى نبيلان جليلا المقدار وقد تابعهما الأوزاعي فلا معنى لمعارضة الأئمة فيما رووا بغيره وقد قال الله تعالى: {إذ يحكمان في الحرث} [الأنبياء: 78] وعلى ذلك القول لا حكم فيه وقول رسول الله صلى الله عليه وسلم «العجماء جبار» ليس من هذا في شيء لأنه قد أجمع من تقوم به الحجة من العلماء أن على راكب الدابة ما أصابت بيديها فقد صح أن المعنى العجماء جبار إذا لم يكن على صاحبها حفظها فإذا كان عليه حفظها فليست بجبار وقد حكم رسول الله صلى الله عليه وسلم أن على أهل الماشية حفظها بالليل فليس ما أفسدته بالليل إذن جبارا والجبار الهدر الذي لا شيء فيه وقد حكم داود وسليمان بما ذكرنا فمدحهما الله تعالى فقال جل وعز: {وكلا آتينا حكما وعلما} [الأنبياء: 79]\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:418","bookId":"nasikh-nahhas","type":"section","seq":418,"chapter":"ص: 48","title":"ص: 560","page":"ج1 ص558","text":"، قال: حدثني عبد الله بن وهب، قال: أخبرني مالك بن أنس، عن زيد بن أسلم، في قول الله تعالى: {وكلا آتينا حكما وعلما} [الأنبياء: 79] قال زيد بن أسلم: «الحكم أو الحكمة العقل» قال مالك: «وإنه ليقع بقلبي أن الحكمة هو الفقه في دين الله عز وجل» قال أبو جعفر: والذي ذكرناه من تضمين أصحاب الماشية ما أصابت بالليل مع ما صح عن النبي صلى الله عليه وسلم قول أكثر الفقهاء منهم مالك والشافعي","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:419","bookId":"nasikh-nahhas","type":"section","seq":419,"chapter":"ص: 48","title":"سورة الحج","page":"ج1 ص559","text":"قال أبو جعفر حدثنا يموت، بإسناده عن ابن عباس، قال: \" وسورة الحج نزلت بمكة سوى ثلاث آيات منها فإنهن نزلن بالمدينة في ستة نفر من قريش، ثلاثة منهم مؤمنون وثلاثة كافرون فأما المؤمنون فهم عبيدة بن الحارث، وحمزة بن عبد المطلب، وعلي بن أبي طالب رضي الله عنهم دعاهم للبراز عتبة وشيبة ابنا ربيعة، والوليد بن عتبة فأنزل الله تعالى ثلاث آيات مدنيات وهن: {هذان خصمان اختصموا في ربهم} [الحج: 19] إلى تمام الآيات الثلاث \" قال أبو جعفر: وجدنا في هذه السورة أربعة مواضع تصلح في هذا الكتاب منهن قول الله تعالى: {فكلوا منها وأطعموا البائس الفقير}","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:420","bookId":"nasikh-nahhas","type":"section","seq":420,"chapter":"ص: 48","title":"ص: 562","page":"ج1 ص561","text":"[الحج: 28] ، وقال تعالى: {فكلوا منها وأطعموا القانع والمعتر} [الحج: 36] فمن العلماء من قال ذبح الضحايا ناسخ لكل ذبح كان قبله حتى قال محمد بن الحسن في إملائه كانت العقيقة تفعل في الجاهلية ثم فعلت في أول الإسلام ثم نسخت بذبح الضحية فمن شاء فعلها ومن شاء تركها واحتج بعض الكوفيين بقول محمد بن علي بن الحسين نسخ ذبح الضحية كل ما قبله","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:421","bookId":"nasikh-nahhas","type":"section","seq":421,"chapter":"ص: 48","title":"ص: 563","page":"ج1 ص561","text":"، وقد خولف محمد بن الحسن في هذا واحتج عليه بفعل رسول الله صلى الله عليه وسلم وقوله في العقيقة وسنذكر ذلك إن شاء الله وقال بعض العلماء {فكلوا منها} [الحج: 28] ناسخ لفعلهم لأنهم كانوا يحرمون لحوم الضحية على أنفسهم ولا يأكلون منها شيئا فنسخ ذلك بقوله تعالى {فكلوا منها} [الحج: 28] ويقول النبي صلى الله عليه وسلم: «من ضحى فليأكل من أضحيته» إلا أن العلماء على أن هذا الأمر ندب لا إيجاب وإن كانوا يستحبون الأكل منها كما قال مالك، والليث ويستحب أن يأكل من لحم أضحيته لقول الله تعالى: {فكلوا منها} [الحج: 28] وقال الزهري: «من السنة أن يأكل أول من الكبد» ، وأكثر العلماء منهم ابن مسعود، وابن عمر، وعطاء، والثوري يستحبون أن يتصدق بالثلث ويطعم الثلث ويأكل هو وأهله الثلث واختلف العلماء في الادخار منها على ثلاثة أقوال فمنهم من قال: لا يدخر منها بعد ثلاث ومنهم من قال يدخر إلى أي وقت أحب ومنهم من قال: إن كانت بالناس حاجة إليها فلا يدخر","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:422","bookId":"nasikh-nahhas","type":"section","seq":422,"chapter":"ص: 48","title":"ص: 564","page":"ج1 ص561","text":"فممن قال لا يدخر بعد ثلاث علي بن أبي طالب وابن عمر\nكما قرئ على أحمد بن محمد بن الحجاج عن يحيى بن عبد الله بن بكير، قال: حدثني الليث، قال حدثني عقيل، عن ابن شهاب، عن أبي عبيد، مولى ابن أزهر قال: شهدت علي بن أبي طالب صلى بنا العيد وعثمان رضي الله عنه محصور ثم خطبنا فقال: «لا تدخروا شيئا من لحم أضاحيكم بعد ثلاث فإن رسول الله صلى الله عليه وسلم أمر بذلك»\nحدثنا أبو إسحاق إبراهيم بن شريك، قال: حدثنا أحمد بن عبد الله بن يونس، قال: حدثنا ليث، عن نافع، عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال: «لا يأكل أحدكم من لحم أضحيته فوق ثلاثة أيام» قال أبو جعفر: وهذان الحديثان صحيحان من قول النبي صلى الله عليه وسلم إلا أنه قد تؤول حديث ابن عمر أنه منسوخ\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن أبي الزبير المكي، أن جابر بن عبد الله، أخبره أن رسول الله صلى الله عليه وسلم: «نهى أن تؤكل لحوم","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:423","bookId":"nasikh-nahhas","type":"section","seq":423,"chapter":"ص: 48","title":"ص: 565","page":"ج1 ص564","text":"الضحايا بعد ثلاث ثم قال بعد كلوا وتزودوا وادخروا» قال أبو جعفر: وهذا نسخ بين وبه قال أبو سعيد الخدري، وبريدة الأسلمي قالا قال رسول الله صلى الله عليه وسلم: «إني كنت نهيتكم عن لحوم الأضاحي بعد ثلاث ألا فكلوا وتزودوا» والقول الثالث: إن نهي النبي صلى الله عليه وسلم عن أكل لحوم الضحايا إنما كان لعلة بينتها عائشة قالت: \" دفت دافة من البادية بحضرة الأضحى فقال رسول الله صلى الله عليه وسلم: «كلوا وتصدقوا ولا تدخروا بعد ثلاث ثم قال إنما نهيتكم من أجل الدافة فكلوا وادخروا» قال أبو جعفر: وهذا من أحسن ما قيل في هذا حتى تتفق الأحاديث ولا تتضاد ويكون قول أمير المؤمنين علي بن أبي طالب وعثمان رضي الله عنه محصور لأن الناس كانوا في شدة محتاجين ففعل كما فعل رسول الله صلى الله عليه وسلم حين قدمت الدافة والدليل على هذا\nما حدثناه إبراهيم بن شريك، قال: حدثنا أحمد، قال: حدثنا ليث، قال حدثني الحارث بن يعقوب، عن يزيد بن أبي يزيد، عن امرأته، أنها سألت عائشة عن لحوم الأضاحي","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:424","bookId":"nasikh-nahhas","type":"section","seq":424,"chapter":"ص: 48","title":"ص: 566","page":"ج1 ص564","text":"فقالت قدم علينا علي بن أبي طالب من سفر فقدمنا إليه منه فأبى أن يأكله حتى يسأل رسول الله صلى الله عليه وسلم فسأله فقال: «كل من ذي الحجة إلى ذي الحجة» قال أبو جعفر: الدافة الجماعة بالدال غير معجمة ويقال ذففت على الجريج بالذال معجمة إذا أجهزت عليه مشتق مما حكاه أبو زيد قال عن العرب ذف الأمر واستذف إذا تهيأ ومنه يقال خفيف ذفيف وقول محمد بن الحسن إن الضحية نسخت العقيقة قول لا دليل معه فيه والذي روي عن محمد بن علي نسخت الضحية كل ذبح معناه كل ذبح مكروه، فأما العقيقة فذبح مندوب إليه كالضحية\nكما قرئ على أحمد بن شعيب، عن الحسين بن حريث، قال: حدثنا الفضل وهو ابن موسى، عن الحسين بن واقد، عن عبد الله بن بريدة، عن أبيه: «أن النبي صلى الله عليه وسلم عق عن الحسن، والحسين» وفي حديث ابن عباس «بكبشين كبشين»\nوقرئ على محمد بن عمرو بن خالد، عن أبيه، قال: حدثنا ابن","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:425","bookId":"nasikh-nahhas","type":"section","seq":425,"chapter":"ص: 48","title":"ص: 567","page":"ج1 ص566","text":"عيينة، عن عمرو، عن عطاء، عن حبيبة ابنة ميسرة، عن أم كرز، أن رسول الله صلى الله عليه وسلم قال: «عن الغلام، شاتان مكافئتان وعن الجارية شاة» قال أبو جعفر: فهذا فعل رسول الله صلى الله عليه وسلم وقوله ثم الصحابة والتابعين فمن الصحابة ابن عباس، وابن عمر، وعبد الله بن عمرو وسمرة وفاطمة وعائشة ومن التابعين القاسم، وعروة، ويحيى الأنصاري، وعطاء وقال مالك رحمه الله هو الأمر الذي لا اختلاف فيه عندنا وهو قول الشافعي، وأحمد، وإسحاق، وأبي ثور إلا أن مالكا يقول شاة عن الغلام وشاة عن الجارية والشافعي وأصحاب الحديث على حديث أم كرز والحجة لمالك الحديث: «أن فاطمة رضي الله عنها عقت","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:426","bookId":"nasikh-nahhas","type":"section","seq":426,"chapter":"ص: 48","title":"ص: 568","page":"ج1 ص566","text":"عن الحسن، والحسين بكبشين» وأما الحسن البصري فإنه قال «العقيقة واجبة على الرجل إن لم يعق عنه عق عن نفسه» وهي عند غيره بمنزلة الضحية مندوب إليها إلا أن أبا حنيفة قال الضحية واجبة على كل من وجد إليها سبيلا وعلى الرجل أن يضحي عن ولده، وخالفه أكثر أهل العلم واحتجوا بأن الله تعالى لم يوجبها في كتابه ولا أوجبها رسوله صلى الله عليه وسلم لأن حديث أبي بردة بن نيار يتأول فيه أنه أوجبها على نفسه","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:427","bookId":"nasikh-nahhas","type":"section","seq":427,"chapter":"ص: 48","title":"ص: 569","page":"ج1 ص566","text":"وقد احتج الشافعي بقول النبي صلى الله عليه وسلم: «من رأى هلال ذي الحجة فأراد أن يضحي فلا يحلق له شعرا ولا يقلم له ظفرا» فقوله صلى الله عليه وسلم فأراد يدل على أنه مخير إن شاء فعل وإن شاء لم يفعل وفي الحديث أن أبا بكر، وعمر رضي الله عنهما لم يكونا يضحيان مخافة أن يتوهم الناس أن ذلك واجب وكذا قول أبي مسعود، وبلال، وابن عمر خمسة من الصحابة لم يوجبوا الضحية قال زيد بن أسلم «متكافئتان مشتبهتان تذبحان جميعا» ، وقال أحمد: «مكافئتان متساويتان» وقال الأصمعي: «أصل العقيقة الشعر الذي يولد المولود وهو على رأسه وكذلك هو في البهائم فقيل عقيقة لأنها إذا ذبحت حلق ذلك الشعر» وأنكر أحمد هذا القول وقال: «الذبيحة العقيقة» قال أبو جعفر: والذي قال أحمد «لا يمتنع في اللغة لأنه يقال عق إذا قطع ومنه عق فلان والديه»","bab":"باب ذكر الآية الثالثة قال الله جل وعز: {ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا} [الإسراء: 110] ، فيها ثلاثة أقوال في رواية الضحاك عن ابن عباس: \" نسخت"},{"id":"nasikh-nahhas:428","bookId":"nasikh-nahhas","type":"section","seq":428,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال جل وعز: {أذن للذين يقاتلون بأنهم ظلموا}","page":"ج1 ص566","text":"[الحج: 39]\nحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا سفيان الثوري، عن مسلم البطين، عن سعيد بن جبير عن ابن عباس، أنه قرأ: {أذن للذين يقاتلون بأنهم ظلموا} [الحج: 39] قال: «وهي أول آية نزلت في القتال» قال أبو جعفر: فكانت هذه ناسخة للمنع من القتال وقال ابن زيد: نسخ قوله تعالى: {وذروا الذين يلحدون في أسمائه} [الأعراف: 180] الأمر بالقتال \" وخالفه غيره فقال: لا معنى هاهنا للناسخ والمنسوخ لأن قوله تعالى: {وذروا الذين يلحدون في أسمائه} [الأعراف: 180] تهديد لهم وهذا لا ينسخ","bab":"باب ذكر الآية الثانية قال جل وعز: {أذن للذين يقاتلون بأنهم ظلموا}"},{"id":"nasikh-nahhas:429","bookId":"nasikh-nahhas","type":"section","seq":429,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}","page":"ج1 ص570","text":"[الحج: 52]\nقال أبو جعفر حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {فينسخ الله ما يلقي الشيطان} [الحج: 52] قال: \" يبطل ما ألقاه الشيطان {ثم يحكم الله آياته} [الحج: 52] قال أبو جعفر: هذا من قول العرب نسخت الشمس الظل إذا أزالته وروي في هذا الذي نسخه الله تعالى مما ألقاه الشيطان أحاديث فمنها\nما رواه الزهري عن أبي بكر بن عبد الرحمن بن الحارث بن هشام، قال: قرأ رسول الله صلى الله عليه وسلم: {والنجم} [النجم: 1] فلما بلغ {أفرأيتم اللات والعزى} [النجم: 19] قال: \" فإن شفاعتهم ترتجى فسها فلقيه المشركون فسلموا عليه وفرحوا فأنزل الله تعالى: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته} [الحج: 52] ، الآية \"","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:430","bookId":"nasikh-nahhas","type":"section","seq":430,"chapter":"ص: 48","title":"ص: 572","page":"ج1 ص571","text":"قال أبو جعفر: وهذا حديث منقطع وفيه هذا الأمر العظيم وكذا حديث قتادة وزاد فيه «وإنهن لهن الغرانيق العلا» ولو صح هذا لكان له تأويل قد ذكرناه في أول هذا الكتاب وأفظع من هذا ما ذكره الواقدي عن كثير بن زيد عن المطلب بن عبد الله قال \" فسجد المشركون كلهم إلا الوليد بن المغيرة فإنه أخذ ترابا من الأرض فرفعه إلى وجهه ويقال إنه أبو أحيحة سعيد بن العاص حتى نزل جبريل عليه السلام فقرأ عليه النبي صلى الله عليه وسلم هذا فقال ما جئتك به وأنزل الله تعالى: {لقد كدت تركن إليهم شيئا قليلا إذا لأذقناك ضعف الحياة وضعف الممات ثم لا تجد لك علينا نصيرا} [الإسراء: 75] قال أبو جعفر: وهذا حديث منكر منقطع ولا سيما وهو من حديث الواقدي والدين والعقل يمنعان من هذا لأنه إن كان قال هذا","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:431","bookId":"nasikh-nahhas","type":"section","seq":431,"chapter":"ص: 48","title":"ص: 573","page":"ج1 ص571","text":"متعمدا ومعاذ الله أن يكون ذلك لأن فيه مساعدة لهم على دينهم لأن هذا قولهم، وإن كان ناسيا فكيف صبر ولم يبين ذلك حتى أتاه الوحي من الله تعالى، ثم رجعنا إلى الآية فوجدنا فيها قولين لمن يرجع إلى قوله وعلمه\nكما حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته} [الحج: 52] قال: «إذا حدث ألقى الشيطان في حديثه» قال أبو جعفر: فالتأويل على: ألقى الشيطان في سره وخاطره ما يوهمه به أنه الصواب ثم ينبهه الله تعالى على ذلك وقد صح عنه عليه السلام أنه قال: «إنه ليغان على قلبي فأستغفر الله تعالى في اليوم والليلة مائة مرة»","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:432","bookId":"nasikh-nahhas","type":"section","seq":432,"chapter":"ص: 48","title":"ص: 574","page":"ج1 ص571","text":"وفي السير أن كبراء قريش جاءوه فقالوا: يا محمد قد استغويت ضعفاءنا وسفهاءنا وذلك حين أظهر دعوته وتبينت براهينه فأمسك عنا حتى ننظر في أمرك فإن تبين لنا اتبعناك وإن لم يتبين لنا كنت على أمرك ونحن على أمرنا فوقع له صلى الله عليه وسلم أن هذا إنصاف ثم نبهه الله بالخاطر والتذكر لما أمره الله تعالى به من إظهار الدعوة وأن يصدع بما أمر به ثم نزل عليه الوحي {لقد كدت تركن إليهم شيئا قليلا} [الإسراء: 74] وما بعده فيكون على هذا ألقى الشيطان في أمنيته أي في سره والقول الآخر عليه أكثر أهل التأويل قال سعيد بن جبير «في أمنيته في قراءته» وقال مجاهد في قوله وقال الضحاك: «الأمنية التلاوة» قال أبو جعفر: وهذا معروف في اللغة منه {لا يعلمون الكتاب إلا أماني}","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:433","bookId":"nasikh-nahhas","type":"section","seq":433,"chapter":"ص: 48","title":"ص: 575","page":"ج1 ص571","text":"[البقرة: 78] فيكون التقدير على هذا ألقى الشيطان في تلاوة النبي صلى الله عليه وسلم إما شيطانا من الإنس وإما شيطانا من الجن ومتعارف في الآثار أن الشيطان كان يظهر كثيرا في وقت النبي صلى الله عليه وسلم قال تعالى {وإذ زين لهم الشيطان أعمالهم وقال لا غالب لكم اليوم من الناس وإني جار لكم فلما تراءت الفئتان نكص على عقبيه وقال إني بريء منكم إني أرى ما لا ترون إني أخاف الله والله شديد العقاب} [الأنفال: 48] فألقى الشيطان هذا في تلاوة النبي عليه السلام من غير أن ينطق به النبي صلى الله عليه وسلم والدليل على هذا أن ظاهر القرآن كذا وأن الثقات من أصحاب السير كذا يروون\nكما روى موسى بن عقبة، عن الزهري، «ألقى الشيطان في تلاوة النبي صلى الله عليه وسلم فإن شفاعتهم ترتجى فوقرت في مسامع المشركين، فاتبعوه جميعا وسجدوا وأنكر ذلك المسلمون ولم يسمعوه","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:434","bookId":"nasikh-nahhas","type":"section","seq":434,"chapter":"ص: 48","title":"ص: 576","page":"ج1 ص573","text":"واتصل الخبر بالمهاجرين في أرض الحبشة وأن الجماعة قد تبعت النبي عليه السلام فقدموا وقد نسخ الله ما ألقاه الشيطان فلحقهم الأذى والعنت» قال أبو جعفر: \" فقد تبين معنى الآية بهذا وبغيره وقال ابن جريج {ليجعل ما يلقي الشيطان فتنة للذين في قلوبهم مرض والقاسية قلوبهم} [الحج: 53] قال القاسية قلوبهم المشركون قال أبو جعفر: وهذا قول بين لأنهم لم تلن قلوبهم لاتباع الحق والذين في قلوبهم مرض المنافقون","bab":"باب ذكر الآية الثالثة قال جل وعز: {وما أرسلنا من قبلك من رسول ولا نبي إلا إذا تمنى ألقى الشيطان في أمنيته فينسخ الله ما يلقي الشيطان}"},{"id":"nasikh-nahhas:435","bookId":"nasikh-nahhas","type":"section","seq":435,"chapter":"ص: 48","title":"سورة المؤمنون","page":"ج1 ص577","text":"حدثنا أبو جعفر قال: حدثنا يموت، بإسناده عن ابن عباس، قال: «وسورة المؤمنون نزلت بمكة فهي مكية»\nوفي رواية المعتمر عن خالد، عن محمد بن سيرين، قال: \" كان النبي صلى الله عليه وسلم ينظر إلى السماء في الصلاة فأنزل الله تعالى هذه الآية {الذين هم في صلاتهم خاشعون} [المؤمنون: 2] فجعل رسول الله صلى الله عليه وسلم وجهه حيث يسجد \" وفي رواية هشيم كان المسلمون يلتفتون في الصلاة فينظرون حتى أنزل الله تعالى {قد أفلح المؤمنون الذين هم في صلاتهم خاشعون} [المؤمنون: 2] فأقبلوا على صلاتهم ونظروا أمامهم وكانوا يستحبون ألا يجاوز أحدهم بصره موضع سجوده","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:436","bookId":"nasikh-nahhas","type":"section","seq":436,"chapter":"ص: 48","title":"ص: 580","page":"ج1 ص579","text":"قال أبو جعفر: وأكثر العلماء على أن الخشوع في الصلاة أن ينظر إلى موضع سجوده إذا كان قائما ومنهم من قال إلا بمكة فإنه يستحب له أن ينظر إلى البيت","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:437","bookId":"nasikh-nahhas","type":"section","seq":437,"chapter":"ص: 48","title":"سورة النور","page":"ج1 ص579","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس، قال: «وسورة النور نزلت بالمدينة فهي مدنية» قال أبو جعفر: وقد ذكرنا قوله عز وجل: {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة} وأنه ناسخ لقوله تعالى {واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم} [النساء: 15] الآيتين في سورة النساء ووجدنا في هذه السورة آيات سوى هذه فأولاهن قوله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين} [النور\n: 3] للعلماء في الآية أربعة أقوال منهم من قال: هي منسوخة ومنهم من قال النكاح هاهنا الوطء، ومنهم من قال الزاني هاهنا المجلود في الزنا لا ينكح إلا زانية مجلودة في الزنا أو مشركة وكذا الزانية، ومنهم من قال: هي الزانية التي تتكسب بزناها وتنفق على زوجها واحتج بأن الآية في ذلك أنزلت فمن قال: هي منسوخة سعيد بن المسيب\nكما حدثنا إسحاق بن إبراهيم القطان، قال حدثنا يحيى بن عبد الله بن بكير، قال: حدثني الليث بن سعد، قال: حدثنا يحيى بن سعيد بن قيس الأنصاري، عن سعيد بن المسيب، في قول الله تعالى {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك} [النور: 3] قال: \" يزعمون أنها نسخت بالآية التي بعدها {وأنكحوا الأيامى} [النور: 32] منكم فدخلت الزانية في أيامى المسلمين \" وهذا القول الذي عليه أكثر العلماء وأهل الفتيا يقولون: إن من زنا بامرأة فله أن يتزوجها ولغيره أن يتزوجها وهو قول ابن عمر، وسالم، وجابر بن زيد، وعطاء، وطاوس، ومالك بن أنس، روى عنه ابن وهب أنه سئل عن الرجل يزني بامرأة ثم يريد نكاحها، قال ذلك له بعد أن تستبرئ من وطئها وهو قول أبي حنيفة وأصحابه","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:438","bookId":"nasikh-nahhas","type":"section","seq":438,"chapter":"ص: 48","title":"ص: 583","page":"ج1 ص582","text":"وقال الشافعي في الآية القول فيها كما قال سعيد بن المسيب إن شاء الله إنها منسوخة وممن قال بالقول الثاني: إن النكاح هاهنا الوطء ابن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا أبو صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، وقوله تعالى: {الزاني لا ينكح إلا زانية أو مشركة} [النور: 3] الآية، قال: «الزاني من أهل الملة لا يزني إلا بزانية مثله من أهل القبلة أو مشركة والزانية من أهل القبلة لا تزني إلا بزان مثلها من أهل القبلة أو مشرك وحرم الزنا على المؤمنين» واختار محمد بن جرير هذا القول وأومأ إلى أنه أولى الأقوال واحتج بأن الزانية من المسلمين لا يجوز لها أن تتزوج مشركا بحال وأن الزاني من المسلمين لا يجوز له أن يتزوج مشركة وثنية بحال فقد تبين أن المعنى الزاني من المسلمين لا يزني إلا بزانية لا تستحل الزنا من المسلمين أو مشركة تستحل الزنا والزانية لا تزني إلا بزان من المسلمين لا يستحل الزنا أو مشرك يستحل الزنا، وحرم ذلك الزنا وهو النكاح المذكور قبل هذا","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:439","bookId":"nasikh-nahhas","type":"section","seq":439,"chapter":"ص: 48","title":"ص: 584","page":"ج1 ص582","text":"والقول الثالث: إن الزاني المجلود لا ينكح إلا زانية مجلودة أو مشركة وكذا الزانية قول الحسن\nكما قرئ على إبراهيم بن موسى الجوزي، عن يعقوب الدورقي، قال: حدثنا وكيع، عن يزيد بن إبراهيم، عن الحسن، قال: «الزاني المجلود لا ينكح إلا زانية مجلودة مثله أو مشركة والزانية المجلودة لا ينكحها إلا زان مجلود مثلها أو مشرك»\nوحدثنا علي بن الحسين، قال: قال الحسن بن محمد الزعفراني، حدثنا عفان، قال: حدثنا يزيد بن زريع، قال: حدثنا حبيب المعلم، قال جاء رجل من أهل الكوفة إلى عمرو بن شعيب فقال: ألا تعجب من الحسن يزعم أن الزاني المجلود لا ينكح إلا مثله ويتأول هذه الآية {الزاني لا ينكح إلا زانية أو مشركة} [النور: 3] فقال ما يعجبك من هذا حدثني سعيد بن أبي سعيد عن أبي هريرة عن رسول الله صلى الله عليه وسلم قال: «الزاني المجلود لا ينكح إلا مثله» قال أبو جعفر: وهذا الحديث يجوز أن يكون منسوخا كما نسخت الآية في قول سعيد بن المسيب والقول الرابع: أن هذا كان في نسوة كان الرجل يتزوج إحداهن على أن تنفق عليه مما تكسبه من الزنا فحرم الله تعالى نكاحهن، قول مجاهد\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا أسباط بن محمد، قال: حدثنا عبد الملك بن أبي","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:440","bookId":"nasikh-nahhas","type":"section","seq":440,"chapter":"ص: 48","title":"ص: 585","page":"ج1 ص584","text":"سليمان، عن القاسم بن أبي بزة، عن مجاهد، في قوله تعالى {الزاني لا ينكح إلا زانية أو مشركة} [النور: 3] قال: «كن نساء بغايا وكانت منهن امرأة تدعى أم مهزم فكان الرجل يتزوج إحداهن لتنفق عليه من كسبها فنهاهم الله تعالى عن ذلك أن يتزوجهن أحد من المسلمين»\nقرئ على أحمد بن شعيب، عن عمرو بن علي، قال: حدثنا المعتمر، عن أبيه، عن الحضرمي يعني ابن لاحق، عن القاسم بن محمد، عن عبد الله بن عمرو، قال: \" كانت امرأة يقال لها أم مهزول وكانت بأجياد وكانت تسافح فأراد رجل من المسلمين أن يتزوجها فأنزل الله تعالى {والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين} [النور: 3] \" قال أبو جعفر: وهذا الحديث من أحسن ما روي في هذه الآية ذكر فيه السبب الذي نزلت فيه الآية فإذا صح جاز أن تكون الآية الناسخة بعده والله تعالى أعلم بحقيقة ذلك","bab":"باب ذكر الآية الرابعة قال جل وعز: {وجاهدوا في الله حق جهاده} [الحج: 78] من جعلها منسوخة قال: هي مثل قوله تعالى {اتقوا الله حق تقاته} [آل عمران: 102] فنسخها عنده"},{"id":"nasikh-nahhas:441","bookId":"nasikh-nahhas","type":"section","seq":441,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال تعالى: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون} [","page":"ج1 ص585","text":"هذا عاما في جميع البيوت ثم نسخ من هذا واستثنى فقال تعالى: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم} [النور: 29] ومنهم من قال الآيتان محكمتان فقوله تعالى {لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها} [النور: 27] يعني به البيوت التي لها أرباب وسكان، والآية الأخرى في البيوت التي ليس لها أرباب يعرفون ولا سكان فالقول الأول يروى عن ابن عباس، وعكرمة\nكما حدثنا أبو الحسن، عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، قال حدثنا جويبر، عن الضحاك، عن ابن عباس، {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا} [النور: 27] قال حتى تستأذنوا {وتسلموا على أهلها} [النور: 27] قال: \" فيه تقديم وتأخير حتى تسلموا على أهلها وتستأنسوا قال ثم استثنى البيوت التي على طرق الناس والتي ينزلها المسافرون فقال تعالى: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة} [النور: 29] يقول ليس لها أهل ولا سكان بغير تسليم ولا استئذان {فيها متاع لكم","bab":"باب ذكر الآية الثانية قال تعالى: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون} [النور: 27] للعلماء ف"},{"id":"nasikh-nahhas:442","bookId":"nasikh-nahhas","type":"section","seq":442,"chapter":"ص: 48","title":"ص: 587","page":"ج1 ص586","text":"قال متاع لكم} قال: منافع من الحر والبرد \"\nوروى يزيد، عن عكرمة، والحسن، {لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها} [النور: 27] ، قالا: \" ثم نسخ من ذلك واستثنى فقال {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم} [النور: 29] \" والقول الثاني: أنهما محكمتان قول أكثر أهل التأويل فأما ما روي عن ابن عباس وبعض الناس يقول عن سعيد بن جبير أنه قال: أخطأ الكاتب إنما هو حتى تستأذنوا فعظيم محظور القول به لأن الله تعالى قال: {لا يأتيه الباطل من بين يديه ولا من خلفه} [فصلت: 42] ، ومعنى {حتى تستأنسوا} [النور: 27] بين عند أهل التأويل وأهل العربية\nكما قرئ على عبد الله بن أحمد بن عبد السلام، عن أبي الأزهر، قال: حدثنا روح، عن عثمان بن غياث، عن عكرمة، {حتى تستأنسوا} [النور: 27] قال: «حتى\nتستأذنوا» وقال مجاهد: «هو التنحنح والتنخم» قال أبو جعفر وأهل العربية يشتقونه من جهتين: إحداهما {حتى تستأنسوا} [النور: 27] حتى تستعلموا قال تعالى {آنس من جانب الطور نارا} [القصص: 29] والجهة الأخرى حتى تأنسوا بأن الذي تريدون الدخول إليه قد رضي دخولكم والذي ذكرناه عن ابن عباس من التقديم والتأخير حسن أي لا تدخلوا بيوتا غير بيوتكم لها أرباب وفيها سكان حتى تسلموا وتستأذنوا فتقولوا السلام عليكم أأدخل؟ أو ما كان في معنى هذا من التنحنح والتنخم والإذن {ذلكم خير لكم} [البقرة: 54] من أن تدخلوا بغير إذن فتروا ما لا تحبون أن تروه وتعصوا الله تعالى {لعلكم تذكرون} [النور: 27] ما يجب لله تعالى عليكم من طاعته فتلزمونه فهذه محكمة في حكم غير حكم الثانية والثانية قد تكلم في معناها العلماء\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال حدثنا أبو معاوية، قال: حدثنا الحجاج بن أرطاة، عن سالم المكي، عن محمد بن علي بن الحنفية، في قوله: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم} [النور: 29] قال: «هي بيوت الخانات وبيوت الأسواق» فأما قول عبد الرحمن بن زيد هي بيوت التجار والحوانيت في","bab":"باب ذكر الآية الثانية قال تعالى: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون} [النور: 27] للعلماء ف"},{"id":"nasikh-nahhas:443","bookId":"nasikh-nahhas","type":"section","seq":443,"chapter":"ص: 48","title":"ص: 589","page":"ج1 ص588","text":"القيساريات والأسواق فقول مرغوب عنه لأن الحوانيت التي فيها متاع الناس لا يحل دخولها إلا بإذن صاحبها وإن فتحها وجلس لأن الناس أحق بأملاكهم وأيضا فنص القرآن {فيها متاع لكم} [النور: 29] وليس متاع التجار بمتاع للمخاطبين وقد قال مجاهد: «هي بيوت كانت في طريق المدينة يضع الناس فيها أمتعتهم فأذن لهم في دخولها بغير إذن» قال أبو جعفر: فإذا كانت هذه البيوت إنما بنيت لهذا فهي مباحات لا يحتاج فيها إلى إذن ومن أجمع ما قيل في الآية قول جابر بن زيد\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا إبراهيم بن مرزوق، قال: حدثنا يعقوب بن إسحاق الحضرمي، عن حبيب بن أبي حبيب، عن عمرو بن هرم، عن جابر بن زيد، في قوله: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم} [النور: 29] قال: «ليس يعني بالمتاع الجهاز ولكن ما سواه من الحاجة إما منزل ينزله قوم من ليل أو نهار أو خربة يدخلها الرجل لقضاء حاجته أو دار ينظر إليها فهذا متاع وكل منافع الدنيا متاع»\nقال أبو جعفر: وهذا شرح حسن من قول إمام من أئمة المسلمين وهو موافق للغة، والمتاع في كلام العرب المنفعة ومنه أمتع الله بك ومنه {فمتعوهن} [الأحزاب: 49] ، فالمعنى على قوله ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها منفعة لكم من قضاء حاجة أو دخول رجل إلى دار يقلبها لشراء أو إجارة وما تقدم من قول العلماء سوى ابن زيد داخل في هذا","bab":"باب ذكر الآية الثانية قال تعالى: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون} [النور: 27] للعلماء ف"},{"id":"nasikh-nahhas:444","bookId":"nasikh-nahhas","type":"section","seq":444,"chapter":"ص: 48","title":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الف","page":"ج1 ص590","text":"منسوخة ومنهم من قال: هي ندب غير واجبة ومنهم من قال: هي في النساء دون الرجال ومنهم من قال: هي في الرجال دون النساء ومنهم من قال كان العمل بها واجبا لأن القوم لم يكن لهم إغلاق ولا ستور فإن عاد الأمر إلى ذلك كان العمل بها واجبا ومنهم من قال: هي محكمة واجبة على المسلمين أن يعملوا بها كما أمر الله تعالى لأن أمره حتم إلا أن يقع دليل على غير ذلك فممن قال إنها منسوخة سعيد بن المسيب\nكما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق الحربي، قال: بلغني عن داود، عن سعيد بن المسيب، {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] الآية قال: «هي منسوخة»\nقال الحربي، وحدثنا بندار، قال: حدثنا غندر، قال: حدثنا شعبة","bab":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم"},{"id":"nasikh-nahhas:445","bookId":"nasikh-nahhas","type":"section","seq":445,"chapter":"ص: 48","title":"ص: 592","page":"ج1 ص591","text":"، عن أبي بشر، عن سعيد وهو ابن جبير: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] قال: «لا يعمل بها اليوم» قال أبو جعفر: فهذا قول\nوروى أيوب، عن أبي قلابة، {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] ، {وأشهدوا إذا تبايعتم} [البقرة: 282] قال: «إنما أمر بهذا نظرا لهم»\nحدثنا أبو جعفر قال حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبيد الله، قال: حدثنا يحيى بن سعيد، قال: حدثنا سفيان، عن أبي حصين، عن أبي عبد الرحمن، {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] قال: «النساء عني بها»","bab":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم"},{"id":"nasikh-nahhas:446","bookId":"nasikh-nahhas","type":"section","seq":446,"chapter":"ص: 48","title":"ص: 593","page":"ج1 ص592","text":"فهذه ثلاثة أقوال هذا القول منها بين الخطأ لأن الذين لا يكون للنساء في كلام العرب إنما يكون للنساء اللاتي واللائي\nوحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أبو بكر، قال: حدثنا يحيى بن يمان، قال: حدثنا سفيان، عن ليث، عن نافع، عن ابن عمر، {ليستأذنكم الذين ملكت أيمانكم} [النور: 58] قال: «هي في الرجال دون النساء» وهذا القول الرابع يستحسنه أهل النظر لأن الذين في كلام العرب للرجال وإن كان يجوز أن يدخل معهم النساء فإنما يقع ذلك بدليل والكلام على ظاهره غير أن في إسناده ليث بن أبي سليم\nوقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا عبد الرحمن بن زياد، قال: حدثنا الدراوردي، عن عمرو بن أبي عمرو، عن عكرمة، أن رجالا من أهل العراق سألوا ابن","bab":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم"},{"id":"nasikh-nahhas:447","bookId":"nasikh-nahhas","type":"section","seq":447,"chapter":"ص: 48","title":"ص: 594","page":"ج1 ص593","text":"عباس كيف ترى في هذه الآية في كتاب الله قول الله تعالى: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] لا يعمل بها أحد؟ فقال ابن عباس: «إن الله رفيق حليم رحيم بالمؤمنين يحب السترة عليهم وكان القوم ليس لهم ستور ولا حجال فربما دخل الخادم أو الولد أو يتيمه وهو مع أهله في حال جماع، فأمر الله تعالى بالاستئذان في هذه الثلاث الحالات» قال أبو جعفر وحدثنا بهذا الحديث، جعفر بن مجاشع، قال: حدثنا إبراهيم، قال: حدثنا ابن الصباح، قال: حدثنا خالد بن مخلد، قال: حدثنا سليمان بن بلال، عن عمرو، عن عكرمة، عن ابن عباس، نحوه، وزاد فيه ثم جاء الله باليسر وبسط في الرزق فاتخذ الناس الستور والحجال فرأى الناس ذلك قد كفاهم من الاستئذان الذي أمروا به وهذا القول الخامس: متنه حسن وليس فيه دليل على نسخ الآية ولكن على أنها كانت على حال ثم زالت فإن كان مثل تلك الحال فحكمها قائم كما كان، والقول السادس: إنها محكمة واجبة ثابتة على الرجال والنساء قول أكثر أهل العلم\nكما حدثنا محمد بن جعفر الأنباري، قال: حدثنا عبد الله بن يحيى، قال: حدثنا يعلى بن عبيد، قال: حدثنا عبد الملك بن أبي سليمان، عن عطاء، عن ابن عباس، قال: «ثلاث آيات من القرآن قد ترك الناس العمل بهن» قال عطاء حفظت آيتين ونسيت واحدة في قول الله تعالى: \" {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] حتى تختم الآية وفي الرجل يقول للآخر أنا أكرم","bab":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم"},{"id":"nasikh-nahhas:448","bookId":"nasikh-nahhas","type":"section","seq":448,"chapter":"ص: 48","title":"ص: 595","page":"ج1 ص593","text":"منك أحد أكرم من أحد إلا بالتقوى، وهو قول الله تعالى: {يا أيها الناس إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا إن أكرمكم عند الله أتقاكم} [الحجرات: 13] \" قال أبو جعفر: وهذا القول بأن الآية محكمة عامة قول القاسم بن محمد، وجابر بن زيد، والشعبي\nكما قرئ على إبراهيم بن موسى الجوزي، عن يعقوب الدورقي، قال: حدثنا وكيع، عن سفيان، عن موسى بن أبي عائشة، عن الشعبي، {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم} [النور: 58] قال: \" ليست بمنسوخة قلت إن الناس لا يعملون بها قال: الله عز وجل المستعان \"","bab":"باب في ذكر الآية الثالثة قال جل وعز: {يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم"},{"id":"nasikh-nahhas:449","bookId":"nasikh-nahhas","type":"section","seq":449,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من","page":"ج1 ص595","text":"ومنهم من قال كان الإنسان يتوقى أن يأكل مع الأعمى لأنه يقصر في الأكل وكذا الأعرج والمريض فأزيل ذلك والقول السادس: أن الآية محكمة فممن قال القول الأول إنها منسوخة من قوله تعالى {ولا على أنفسكم} [النور: 61] إلى آخر الآية عبد الرحمن بن زيد، قال: هذا شيء قد انقطع كانوا في أول الإسلام ليست على أبوابهم أغلاق فكانت الستور مرخاة فربما جاء الرجل فدخل البيت وهو جائع وليس فيه أحد فسوغه الله أن يأكل ثم صارت الأغلاق على البيوت فلا يحل لأحد أن يفتحها فذهب هذا وانقطع قال أبو جعفر ومما يدل على حظر هذا\nما حدثناه بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال: «لا يحتلبن أحدكم ماشية أخيه إلا بإذنه أيحب أحدكم أن تؤتى مشربته فتكسر خزانته فينتقل طعامه، فإنما تحرز لهم ضروع مواشيهم أطعمتهم فلا يحتلبن أحدكم ماشية أخيه إلا بإذنه» قال أبو جعفر: وكان في هذا الحديث حظر رسول الله صلى الله عليه وسلم هذا والقول بأنها ناسخة قول جماعة\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:450","bookId":"nasikh-nahhas","type":"section","seq":450,"chapter":"ص: 48","title":"ص: 598","page":"ج1 ص597","text":"طلحة، عن ابن عباس، قال: \" لما أنزل الله: {يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل} [النساء: 29] \" فقال المسلمون إن الله قد نهانا أن نأكل أموالنا بيننا بالباطل وإن الطعام من أفضل الأموال فلا يحل لأحد منا أن يأكل عند أحد فكف الناس عن ذلك فأنزل الله بعد ذلك {ليس على الأعمى حرج} [النور: 61] إلى {أو ما ملكتم مفاتحه} [النور: 61] قال هو الرجل يؤكل الرجل بضيعته والذي رخص الله تعالى أن يأكل الطعام والتمر ويشرب اللبن \" فذهب أبو عبيد إلى أن هذا إنما هو بعد الإذن لأن الناس توقفوا أن يأكلوا لأحد شيئا إذا لم يكن ذلك على سبيل تجارة أو عوض وإن أذن له صاحب الطعام فأباح الله ذلك إذا أذن فيه صاحبه وتأوله غيره على الإذن فيه وإن لم يطلق ذلك صاحبه إذا علم أنه ليس ممن يمنعه واستدل على صحة هذا القول أنه ليس في الآية ذكر الإذن وإنما قال تعالى {أن تأكلوا من بيوتكم} [النور: 61] لأن منزل الرجل قد يكون فيه ما ليس له وما يكون لأهله {أو بيوت آبائكم} [النور: 61] إلى آخر الآية ولم يذكر الابن فيها فتأول هذا بعض العلماء على أن منزل ابنه ومنزله واحد فلذلك لم يذكره","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:451","bookId":"nasikh-nahhas","type":"section","seq":451,"chapter":"ص: 48","title":"ص: 599","page":"ج1 ص597","text":"وعارضه بعضهم فقال هذا تحكم على كتاب الله تعالى بل الأولى في الظاهر أن يكون الابن مخالفا لهؤلاء وليس الاحتجاج بما روي عن النبي صلى الله عليه وسلم: «أنت ومالك لأبيك» بقوي لوهاء هذا الحديث وأنه لو صح لم يكن فيه حجة إذ قد يجوز أن يكون النبي صلى الله عليه وسلم علم أن مال ذلك المخاطب لأبيه وقد قيل إن معناه أنت لأبيك ومالك مبتدأ أي ومالك لك والقاطع لهذا التوارث بين الأب والابن وممن قال إن الآية ناسخة لما كان محظورا عليهم من الأكل مع الأعمى ومن ذكر معه مقسم\nكما روى سفيان، عن قيس بن مسلم، عن مقسم، قال: \" كانوا يتقون أن يأكلوا، مع الأعمى والأعرج والمريض حتى","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:452","bookId":"nasikh-nahhas","type":"section","seq":452,"chapter":"ص: 48","title":"ص: 600","page":"ج1 ص597","text":"أنزل الله تعالى {ليس على الأعمى حرج} [النور: 61] الآية \" قال أبو جعفر: وهذا القول غلط لأن الآية ليس على الأعمى حرج فكيف يكون هذا ناسخا للحظر عليهم الأكل معه ولو كان هذا كان يكون ليس للأكل مع الأعمى حرج على أن بعض النحويين قد احتال لهذا القول فقال: قد تكون على بمعنى في وفي بمعنى على ويكون التقدير على هذا ليس في الأعمى حرج وهذا القول بعيد لا ينبغي أن يحمل عليه كتاب الله إلا بحجة قاطعة وأما قول من قال كان الأعمى لا يأكل مع البصير وكذا الأعرج والمريض لئلا يلحقه منه أذى فيقول يجوز ولكن أهل التأويل على غيره والقول السادس: أن الآية محكمة وأنها نزلت في شيء بعينه، قول جماعة من أهل العلم ممن يقتدى بقوله منهم سعيد بن المسيب، وعبيد الله بن عبد الله بن عتبة في جماعة من أهل العلم\nكما حدثنا علي بن حسين، قال: حدثنا الحسن بن محمد، قال: حدثنا شبابة، قال: حدثنا أبو أويس، عن الزهري، عن سعيد بن المسيب، في هذه الآية لا جناح عليكم {أن تأكلوا من بيوتكم} [النور: 61] الآية: نزلت في أناس كانوا إذا خرجوا مع رسول الله صلى الله عليه وسلم وضعوا مفاتيح بيوتهم عند أهل العلة ممن يتخلف عن رسول الله صلى الله عليه وسلم عند الأعمى والأعرج والمريض وعند أقاربهم فكانوا يأذنون لهم أن يأكلوا مما في بيوتهم إذا احتاجوا إلى ذلك\nوكانوا يتقون أن يأكلوا منها ويقولون نخشى ألا تكون أنفسهم بذلك طيبة فأنزل الله في ذلك هذه الآيات فأحله لهم \" وقال عبيد الله بن عبد الله: \" إن الناس كانوا إذا خرجوا إلى الغزو دفعوا مفاتحهم إلى الزمنى وأحلوا لهم أن يأكلوا مما في بيوتهم فكانوا لا يفعلون ذلك ويتوقون ويقولون إنما أطلقوا لنا هذا عن غير طيب نفس، فأنزل الله عز وجل {ليس على الأعمى حرج} [النور: 61] \"\nحدثنا أحمد بن جعفر بن محمد السمان الأنباري، بالأنبار، قال حدثنا زيد بن أخزم قال حدثنا بشر بن عمر الزهراني: قال: حدثنا إبراهيم بن سعد، عن صالح بن كيسان، عن الزهري، عن عروة، عن عائشة، قالت: \" كان المسلمون يوعبون في النفير مع رسول الله صلى الله عليه وسلم فكانوا يدفعون مفاتيحهم إلى ضمناهم ويقولون إن احتجتم فكلوا فيقولون إنما أحلوه لنا عن غير طيب نفس فأنزل الله تعالى: ليس عليكم جناح {أن تأكلوا من بيوتكم أو بيوت آبائكم} [النور: 61] إلى آخر الآية \" قال أبو جعفر: يوعبون أي يخرجون بأجمعهم في المغازي يقال: أوعب بنو فلان لبني فلان إذا جاءوا بأجمعهم ويقال بيت وعيب إذا كان\nواسعا يستوعب كل ما جعل فيه والضمنى هم الزمنى واحدهم ضمن مثل زمن قال أبو جعفر: وهذا القول من أجل ما روي في الآية لما فيه عن الصحابة والتابعين من التوقيف أن الآية نزلت في شيء بعينه فيكون التقدير على هذا ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج ولا عليكم أن تأكلوا فإن تأكلوا خبر ليس ويكون هذا بعد الإذن وقال ابن زيد المعنى ليس على الأعمى حرج في الغزو وإذا كان على هذا فليست أن خبر ليس فأما {من بيوتكم} [النحل: 80] فمعناه من بيوت أنفسكم كذا ظاهره وقد تأول ذلك بعض أهل العلم على أنه بغير إذن كما ذكرنا\nوروى معمر، عن قتادة، «لا بأس أن تأكل من بيت صديقك وإن لم يأذن لك» ويتأول هذا على أنه إنما يكون مباحا إذا علمت أنه لا يمنعك وكان صديقا على الحقيقة إلا أن الأحاديث التي ذكرناها على الإذن والله أعلم","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:453","bookId":"nasikh-nahhas","type":"section","seq":453,"chapter":"ص: 48","title":"سورة الفرقان","page":"ج1 ص602","text":"حدثنا يموت، بإسناده عن ابن عباس، قال: «وسورة الفرقان نزلت بمكة فهي مكية» قال جل وعز: {وإذا خاطبهم الجاهلون قالوا سلاما} [الفرقان: 63] من العلماء من قال هذا منسوخ وإنما كان هذا قبل أن يؤمر المسلمون بحرب المشركين وليس سلاما من التسليم، وإنما هو من التسلم تقول العرب سلاما أي تسلما منك وهو منصوب على أحد أمرين يجوز أن يكون منصوبا بقالوا ويجوز أن يكون مصدرا وهذا قول سيبويه وكلامه يدل على أن الآية عنده منسوخة قال أبو جعفر: ولا نعلم لسيبويه كلاما في معنى الناسخ والمنسوخ إلا\nفي هذه الآية قال سيبويه: وزعم أبو الخطاب أن مثله يعني مثل قولك الحمد لله مما ينتصب على المصدر، قولك للرجل سلاما يريد تسلما منك كما قلت براءة منك أي لا أتلبس بشيء من أمرك قال: وزعم أن أبا ربيعة كان يقول إذا لقيت فلانا فقل سلاما فسأله ففسر له معنى براءة منك، قال: وزعم أن هذه الآية {وإذا خاطبهم الجاهلون قالوا سلاما} [الفرقان: 63] بمنزلة ذلك لأن الآية فيما زعم مكية فلم يؤمر المسلمون يومئذ أن يسلموا على المشركين ولكنه على قوله لا خير بيننا ولا شر قال أبو جعفر: وزعم محمد بن يزيد أن سيبويه أخطأ في هذا وأساء العبارة لأنه لا معنى لقوله ولم يؤمر المسلمون يومئذ أن يسلموا على المشركين وإنما كان ينبغي أن يقول ولم يؤمر المسلمون يومئذ أن يحاربوا المشركين ثم أمروا بحربهم قال أبو جعفر: كلام محمد بن يزيد يدل على أن الآية أيضا عنده منسوخة وإنما جاز فيها أن تكون منسوخة لأن معناها معنى الأمر أي إذا خاطبكم الجاهلون فقولوا سلاما فعلى هذا يكون النسخ فيها فأما كلام سيبويه فيحتمل أن يكون معناه لم يؤمر المسلمون يومئذ أن يسلموا على\nالمشركين ولكنهم أمروا أن يتسلموا منهم ويتبرءوا ثم نسخ ذلك بالأمر بالحرب وقد ذكرنا قوله عز وجل {والذين لا يدعون مع الله إلها آخر} [الفرقان: 68] إلى قوله عز وجل {إلا من تاب} [مريم: 60] وقول من قال هو منسوخ بقوله تعالى {ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها} [النساء: 93] في سورة النساء","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:454","bookId":"nasikh-nahhas","type":"section","seq":454,"chapter":"ص: 48","title":"سورة الشعراء","page":"ج1 ص605","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس، قال: وسورة الشعراء نزلت بمكة فهي مكية سوى خمس آيات من آخرها نزلن بالمدينة وفي ثلاثة نفر من الأنصار وهم شعراء رسول الله صلى الله عليه وسلم حسان بن ثابت، وكعب بن مالك، وعبد الله بن رواحة وهو قوله جل وعز {والشعراء يتبعهم الغاوون ألم تر أنهم في كل واد يهيمون وأنهم يقولون ما لا يفعلون إلا الذين آمنوا وعملوا الصالحات وذكروا الله} [الشعراء: 225] استثنى هؤلاء الثلاثة من جملة الشعراء إلى آخر السورة \"","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:455","bookId":"nasikh-nahhas","type":"section","seq":455,"chapter":"ص: 48","title":"ص: 608","page":"ج1 ص607","text":"قال أبو جعفر: قد أدخل هذه الآيات بعض الناس في الناسخ والمنسوخ\nحدثنا أبو الحسن عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، {والشعراء يتبعهم الغاوون} [الشعراء: 224] قال: \" نسختها الآية التي بعدها يعني {إلا الذين آمنوا وعملوا الصالحات} [الشعراء: 227] \"\nوحدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، عن علي بن أبي طلحة عن ابن عباس، {والشعراء يتبعهم الغاوون} [الشعراء: 224] قال: \" هم الكفار يتبعهم ضلال الجن والإنس قال ثم قال {ألم تر أنهم في كل واد يهيمون} [الشعراء: 225] يقول في كل لغو يخوضون {وأنهم يقولون ما لا يفعلون} [الشعراء: 226] يقول أكثر قولهم يكذبون قال ثم استثنى المؤمنين منهم فقال: {إلا الذين آمنوا وعملوا الصالحات وذكروا الله كثيرا} [الشعراء: 227] في كلامهم {وانتصروا من بعد ما ظلموا} [الشعراء: 227] ردوا على الكفار الذين كانوا يهجون به المؤمنين \" قال أبو جعفر: وهذا أحسن ما قيل في الآية ويزيده بيانا قوله","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:456","bookId":"nasikh-nahhas","type":"section","seq":456,"chapter":"ص: 48","title":"ص: 609","page":"ج1 ص608","text":"للكفار يدل على صحته الاستثناء الذي بعده وقوله يتبعهم ضلال الجن والإنس يدل على صحته أن الكلام عام\nوقد روى عكرمة، عن ابن عباس، {يتبعهم الغاوون} [الشعراء: 224] قال: «الرواة» والأول أولى لعموم الظاهر {ألم تر أنهم في كل واد يهيمون} [الشعراء: 225] كما قال وهو تمثيل أي في كل وجه من الباطل يفتنون فيمدحون بالباطل والتزيد وكذا يهجون بالكذب والزور وقوله: أكثر قولهم يكذبون تصحيحه في النحو أكثر قولهم الكذب ودل يكذبون على الكذب وقوله ثم استثنى المؤمنين منهم قول صحيح في العربية هذا الذي تسميه العرب استثناء لا نسخا، تقول جاء القوم إلا عمرا لا يقال هذا نسخ، والاستثناء عند سيبويه بمنزلة التوكيد لأنك تبين به كما تبين بالتوكيد وقوله: {وذكروا الله كثيرا} [الشعراء: 227] في كلامهم قول حسن لعموم اللفظ وغيره يقول {وذكروا الله} [الشعراء: 227] في شعرهم والأول أولى لعمومه، {وانتصروا من بعد ما ظلموا} [الشعراء: 227] كما قال أي انتصروا من الكفار الذين ظلموا المؤمنين بهجائهم إياهم","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:457","bookId":"nasikh-nahhas","type":"section","seq":457,"chapter":"ص: 48","title":"سورة النمل، والقصص، والعنكبوت، والروم","page":"ج1 ص609","text":"حدثنا أبو جعفر حدثنا يموت، بإسناده عن ابن عباس: «أنهن نزلن بمكة»","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:458","bookId":"nasikh-nahhas","type":"section","seq":458,"chapter":"ص: 48","title":"ص: 613","page":"ج1 ص611","text":"قال أبو جعفر: لم نجد فيهن إلا موضعين أحدهما في سورة القصص وهو قوله عز وجل: {وإذا سمعوا اللغو أعرضوا عنه وقالوا لنا أعمالنا ولكم أعمالكم سلام عليكم لا نبتغي الجاهلين} [القصص: 55] للعلماء فيه أربعة أقوال: منهم من قال: هي منسوخة بالنهي عن السلام على الكفار ومنهم من قال: هي منسوخة بالأمر بالقتال ومنهم من تأولها فأباح السلام على الكفار والقول الرابع: إن هذا قول جميل ومخاطبة حسنة وليس من جهة السلام ولا نسخ فيه قال أبو جعفر: فالقول الأول يحتج قائله بما صح عن رسول الله صلى الله عليه وسلم في الكفار «لا تبدءوهم بالسلام» قال ففي هذا نسخ","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:459","bookId":"nasikh-nahhas","type":"section","seq":459,"chapter":"ص: 48","title":"ص: 614","page":"ج1 ص611","text":"قال أبو جعفر: وهذا القول وإن كان قد صح عن رسول الله صلى الله عليه وسلم في الكفار «لا تبدءوهم بالسلام» فهو غلط لأن الآية ليست من هذا في شيء وإنما هي من المتاركة كما يقول الرجل للرجل دعني بسلام تستعمله العرب للمتاركة والقول الثاني إنها منسوخة بالأمر بالقتال قول جماعة من العلماء وقد بينا ذلك في قوله عز وجل: {وإذا خاطبهم الجاهلون قالوا سلاما} [الفرقان: 63] والقول الثالث قول من أباح السلام على الكفار غلط لأن هذه الآية ليست من السلام في شيء إنما هي من التسلم والمتاركة، وحظر السلام على الكفار واجب بكتاب الله عز وجل وسنة رسوله صلى الله عليه وسلم قال الله جل وعز: {والسلام على من اتبع الهدى} [طه: 47] وكذا كتب رسول الله صلى الله عليه وسلم إلى قيصر والسلام على من اتبع الهدى والقول الرابع: إنها مخاطبة حسنة قول حسن قال ابن زيد: «هؤلاء قوم من أهل الكتاب أسلموا فكانوا يمرون على قوم من أهل الكتاب يقرءون شيئا قد بدلوه من التوراة قد وقفوا هم على ذلك فيعرضون عنهم» وقال مجاهد «أسلم قوم من أهل الكتاب فكان المشركون يؤذونهم","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:460","bookId":"nasikh-nahhas","type":"section","seq":460,"chapter":"ص: 48","title":"ص: 615","page":"ج1 ص611","text":"وكانوا يصفحون عنهم ويقولون سلام عليكم» قال أبو جعفر: أصل اللغو في اللغة الباطل وما يجب أن يلغى ويطرح ومعنى أعرضوا عنه لم يصغوا إليه ولم يستمعوا ويدلك على صحة قول مجاهد أن بعده {لنا أعمالنا ولكم أعمالكم} [القصص: 55] أي قد رضينا بأعمالنا لأنفسنا ورضيتم بأعمالكم لأنفسكم {سلام عليكم} [القصص: 55] أي أمنة لكم منا أنا لا نحاوركم ولا نسابكم {لا نبتغي الجاهلين} [القصص: 55] لا نطلب عمل أهل الجهل والموضع الآخر في سورة العنكبوت قوله عز وجل: {ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن إلا الذين ظلموا منهم} [العنكبوت: 46] فيه ثلاثة أقوال من العلماء من قال هو منسوخ ومنهم من قال هو محكم يراد به من آمن منهم ومنهم من قال هو محكم يراد به ذوو العهد منهم فمن قال هو منسوخ احتج بأن الآية مكية فنسخ هذا بالأمر بالقتال\nكما حدثنا محمد بن جعفر الأنباري، قال حدثني موسى بن هارون، قال: حدثنا حسين، قال: حدثنا شيبان، عن قتادة، في قوله تعالى: {ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن} [العنكبوت: 46] قال: \" نسختها: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29]","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:461","bookId":"nasikh-nahhas","type":"section","seq":461,"chapter":"ص: 48","title":"ص: 616","page":"ج1 ص611","text":"\" والقول الثاني قول ابن زيد قال: \" لا يجادل المؤمنون منهم إذا أسلموا لعلهم يحدثون بالشيء فيكون كما قالوا: {إلا الذين ظلموا منهم} [البقرة: 150] من أقام على الكفر يجادل ويقال له الشر \" والقول الثالث قول مجاهد {ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن إلا الذين ظلموا منهم} [العنكبوت: 46] «من قاتل ولم يعط الجزية» قال أبو جعفر: فمن قال: هي منسوخة احتج بأنها مكية وقول مجاهد حسن لأن أحكام الله عز وجل لا ينبغي أن يقال فيها إنها منسوخة إلا بخبر يقطع العذر أو حجة من معقول فيكون المعنى ولا تجادلوا أهل الكتاب إلا بالقول الجميل أي بالدعاء إلى الله عز وجل والتنبيه على حججه وإذا حدثوكم بحديث يحتمل أن يكون كما قالوا فلا تصدقوهم ولا تكذبوهم فهذا الذي هو أحسن ويدل على صحته أنه\nقرئ على أحمد بن شعيب، عن محمد بن","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:462","bookId":"nasikh-nahhas","type":"section","seq":462,"chapter":"ص: 48","title":"ص: 617","page":"ج1 ص615","text":"المثنى، عن عثمان هو ابن عمر، قال: حدثنا علي وهو ابن المبارك، قال: حدثنا يحيى وهو ابن أبي كثير عن أبي سلمة، عن أبي هريرة، قال كان أهل الكتاب يقرءون التوراة بالعبرانية ويفسرونها بالعربية لأهل الإسلام فقال رسول الله صلى الله عليه وسلم: «لا تصدقوا أهل الكتاب ولا تكذبوهم وقولوا آمنا بالذي أنزل إلينا وأنزل إليكم وإلهنا وإلهكم واحد ونحن له مسلمون» قال أبو جعفر: ويكون الذين ظلموا كما قال مجاهد أهل الحرب وإن كان الكفار كلهم ظالمين لأنفسهم فإنما التقدير هاهنا إلا الذين ظلموا منهم أهل الإيمان وقولوا آمنا بالذي أنزل إلينا من القرآن وإليكم من التوراة والإنجيل والزبور وإلهنا وإلهكم واحد أي معبودنا واحد لا ما اتخذتموه إلها ونحن له مسلمون أي خاضعون متذللون لما أمرنا به ونهانا عنه","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:463","bookId":"nasikh-nahhas","type":"section","seq":463,"chapter":"ص: 48","title":"سورة لقمان والم السجدة","page":"ج1 ص616","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس، قال: \" وسورة لقمان نزلت بمكة فهي مكية سوى ثلاث آيات منها نزلن بالمدينة وذلك أنه لما هاجر رسول الله صلى الله عليه وسلم إلى المدينة أتته أحبار اليهود فقالوا: يا محمد بلغنا أنك تقول {وما أوتيتم من العلم إلا قليلا} [الإسراء: 85] أفعنيتنا أم عنيت غيرنا؟ فقال رسول الله صلى الله عليه وسلم: «عنيت الجميع» فقالت له اليهود: يا محمد أوما تعلم أن الله تعالى أنزل التوراة على موسى صلى الله عليه وسلم وخلفها موسى عليه السلام فينا ومعنا؟ فقال النبي صلى الله عليه وسلم لليهود: «التوراة وما فيها من الأنباء قليل في علم الله تعالى» فأنزل الله عز وجل بالمدينة ثلاث آيات وهن قوله تعالى: {ولو أنما في الأرض من شجرة أقلام والبحر يمده من بعده سبعة أبحر ما نفدت كلمات الله} [لقمان: 27] إلى تمام الثلاث الآيات \"","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:464","bookId":"nasikh-nahhas","type":"section","seq":464,"chapter":"ص: 48","title":"ص: 620","page":"ج1 ص619","text":"قال: \" وسورة الم السجدة نزلت بمكة فهي مكية سوى ثلاث آيات منها نزلن بالمدينة في رجلين من قريش شجر بينهما كلام فقال أحدهما","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:465","bookId":"nasikh-nahhas","type":"section","seq":465,"chapter":"ص: 48","title":"ص: 622","page":"ج1 ص619","text":"للآخر أنا أذرب منك لسانا وأحد منك سنانا وأرد للكتيبة، فقال له الآخر: اسكت فإنك فاسق فأنزل الله عز وجل: {أفمن كان مؤمنا كمن كان فاسقا لا يستوون} [السجدة: 18] إلى تمام الثلاث الآيات \" قال أبو جعفر: في سورة الم تنزيل السجدة موضع واحد قال جل وعز {فأعرض عنهم وانتظر إنهم منتظرون} [السجدة: 30]\nحدثنا أبو الحسن عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، قال: حدثنا جويبر، عن","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:466","bookId":"nasikh-nahhas","type":"section","seq":466,"chapter":"ص: 48","title":"ص: 623","page":"ج1 ص619","text":"الضحاك، عن ابن عباس، {فأعرض عنهم} [السجدة: 30] قال عن مشركي قريش بمكة {وانتظر إنهم منتظرون} [السجدة: 30] قال: نسختها آية السيف في براءة قوله تعالى {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية \"","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:467","bookId":"nasikh-nahhas","type":"section","seq":467,"chapter":"ص: 48","title":"سورة الأحزاب","page":"ج1 ص622","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس، قال: «وسورة الأحزاب نزلت بالمدينة فهي مدنية»","bab":"باب ذكر الآية الرابعة قال تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} [النور: 61] الآية للعلماء فيها ستة أقوال منهم من قال في قوله تعالى {"},{"id":"nasikh-nahhas:468","bookId":"nasikh-nahhas","type":"section","seq":468,"chapter":"ص: 48","title":"باب ذكر الآية الأولى منها قال الله جل وعز {ادعوهم لآبائهم هو أقسط عند الله فإن لم تعلموا آباءهم فإخوانكم في الدين ومواليكم} [الأحزاب: 5] فكا","page":"ج1 ص625","text":"أبيه المعروف فإن لم يكن له أب معروف نسبه إلى ولائه المعروف فإن لم يكن له ولاء معروف قال يا أخي يعني في الدين قال الله جل وعز {إنما المؤمنون إخوة} [الحجرات: 10] وهذا من نسخ السنة بالقرآن\nكما حدثنا علي بن الحسين، قال: حدثنا الحسن بن محمد، قال: حدثنا حجاج بن محمد، عن ابن جريج، قال: أخبرنا موسى بن عقبة، أن سالم بن عبد الله، حدثه، عن عبد الله بن عمر، عن زيد بن حارثة، قال: ما كنا ندعوه إلا زيد بن محمد حتى نزلت {ادعوهم لآبائهم} [الأحزاب: 5] \" قال أبو جعفر: وقد ذكرنا {وأولو الأرحام بعضهم أولى ببعض في كتاب الله من المؤمنين والمهاجرين} [الأحزاب: 6] وكذا {يا أيها الذين آمنوا إذا نكحتم المؤمنات ثم طلقتموهن من قبل أن تمسوهن فما لكم عليهن من عدة تعتدونها فمتعوهن} [الأحزاب: 49]","bab":"باب ذكر الآية الأولى منها قال الله جل وعز {ادعوهم لآبائهم هو أقسط عند الله فإن لم تعلموا آباءهم فإخوانكم في الدين ومواليكم} [الأحزاب: 5] فكان هذا ناسخا لما كانو"},{"id":"nasikh-nahhas:469","bookId":"nasikh-nahhas","type":"section","seq":469,"chapter":"ص: 48","title":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء","page":"ج1 ص626","text":"بعد من كان عنده ثم أطلقه له وأباحه بقوله تعالى {ترجي من تشاء منهن وتؤوي إليك من تشاء} [الأحزاب: 51] ومن العلماء من قال الآية محكمة ولم يكن له صلى الله عليه وسلم أن يتزوج سوى من كان عنده ثوابا من الله تعالى لهن حين اخترن الله ورسوله والدار الآخرة ومنهم من قال: هي محكمة ولكن لما حظر عليهن أن يتزوجن بعد موته حظر عليه أن يتزوج غيرهن ومنهم من قال المعنى لا يحل لك النساء من بعد هذه الصفة يعني {إنا أحللنا لك أزواجك اللاتي آتيت أجورهن} [الأحزاب: 50] الآية ومنهم من قال لا يحل لك النساء بعد المسلمات ولا تتزوج يهودية ولا نصرانية ومنهم من قال لا تبدل واحدة من أزواجك بيهودية ولا نصرانية\nوالقول الثامن: أن النبي صلى الله عليه وسلم لما قال الله تعالى {ما كان على النبي من حرج فيما فرض الله له سنة الله في الذين خلوا من قبل} [الأحزاب: 38] كان له أن يتزوج من النساء من شاء بغير عدد محظور كما كان للأنبياء قبله صلى الله عليه وعليهم، فالقول الأول إن الآية منسوخة بالسنة يدل عليه حديث عائشة رضي الله عنها\nكما قرئ على علي بن سعيد بن بشير، عن أبي كريب، قال: حدثنا ابن عيينة، عن عمرو، عن عطاء، عن عائشة، قالت: «ما مات رسول الله صلى الله عليه وسلم حتى أحل له النساء» فدل هذا الحديث على أن عائشة قد كان عندها أنه حظر عليه صلى الله عليه وسلم التزوج ثم أطلق له وأبيح وكان هذا على قول من أجاز أن ينسخ القرآن بالسنة والقول الثاني: عن جماعة من جلة الصحابة والتابعين\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا جعفر بن سليمان، قال: حدثنا إبراهيم بن المنذر، قال: حدثنا عمر بن أبي بكر الموصلي، قال","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:470","bookId":"nasikh-nahhas","type":"section","seq":470,"chapter":"ص: 48","title":"ص: 629","page":"ج1 ص628","text":"حدثني المغيرة بن عبد الرحمن، عن أبي النضر، مولى عمر بن عبيد الله عن عبد الله بن وهب بن زمعة، عن أم سلمة، قالت: \" لم يمت رسول الله صلى الله عليه وسلم حتى أحل الله له أن يتزوج من النساء من شاء إلا ذات محرم وذلك قول الله عز وجل {ترجي من تشاء منهن وتؤوي إليك من تشاء} [الأحزاب: 51] \" وهذا والله تعالى أعلم أولى ما قيل في الآية وهو وقول عائشة واحد في النسخ وقد يجوز أن تكون عائشة أرادت أحل له ذلك بالقرآن وهو مع هذا قول علي بن أبي طالب عليه السلام، وابن عباس، وعلي بن الحسين، والضحاك وقد عارض بعض الفقهاء الكوفيين فقال محال أن تنسخ هذه الآية يعني {ترجي من تشاء منهن وتؤوي إليك من تشاء} [الأحزاب: 51] {لا يحل لك النساء من بعد} [الأحزاب: 52] وهي قبلها في المصحف الذي أجمع المسلمون عليه وقوى قول من قال نسخت بالسنة لأنه مذهب بعض الكوفيين","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:471","bookId":"nasikh-nahhas","type":"section","seq":471,"chapter":"ص: 48","title":"ص: 630","page":"ج1 ص628","text":"قال أبو جعفر: وهذه المعارضة لا تلزم وقائلها غالط لأن القرآن بمنزلة سورة واحدة كما صح عن ابن عباس «أنزل القرآن جملة واحدة إلى السماء الدنيا في شهر رمضان» ويبين لك أن اعتراض هذا لا يلزم قوله عز وجل {والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج} [البقرة: 240] منسوخة على قول أهل التأويل لا نعلم بينهم خلافا بالآية التي قبلها {والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة: 234] والقول الثالث: إن المعنى أنه صلى الله عليه وسلم حظر عليه أن يتزوج على نسائه لأنهن اخترن الله جل وعز ورسوله صلى الله عليه وسلم والدار الآخرة فعوضن هذا قول الحسن، وابن سيرين، وأبي بكر بن عبد الرحمن بن الحارث بن هشام وهذا القول يجوز أن يكون هكذا ثم نسخ فإن قال كيف يجوز أن ينسخ ما كان ثوابا قيل يجوز أن ينسخ ما كان ثوابا بما هو أعظم منه في الثواب فيكون هذا نسخ وعوض منه أنهن أزواجه في الجنة فهذا أعظم خطرا وأجل مقدارا كما قال حذيفة لامرأته: «لا تزوجي بعدي فإن آخر أزواج المرأة زوجها في الجنة»","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:472","bookId":"nasikh-nahhas","type":"section","seq":472,"chapter":"ص: 48","title":"ص: 631","page":"ج1 ص628","text":"، ولذلك حظر على نساء النبي أن يتزوجن بعده والقول الرابع أنه لما حرم عليهن أن يتزوجن بعده حرم عليه أن يتزوج غيرهن قول أبي أمامة بن سهل بن حنيف والقول الخامس: إن المعنى لا يحل لك النساء من بعد هذه الصفة قول أبي رزين وهو يروي عن أبي بن كعب وهو اختيار محمد بن جرير","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:473","bookId":"nasikh-nahhas","type":"section","seq":473,"chapter":"ص: 48","title":"ص: 632","page":"ج1 ص628","text":"والقول السادس: إن المعنى لا يحل لك النساء من بعد المسلمات قول مجاهد، وسعيد بن جبير، وعكرمة قال مجاهد: «لئلا تكون كافرة أما للمؤمنين. هذا القول يبعد لأنه يقدره من بعد المسلمات ولم يجر للمسلمات ذكر» والقول السابع: إنه حرم عليه أن يبدل بعض نسائه بيهودية أو نصرانية أبعد من ذلك لأن نص القرآن {ولا أن تبدل بهن من أزواج} [الأحزاب: 52] وليس في القرآن ولا أن تبادل وحكى ابن زيد عن العرب، أنها كانت تبادل بأزواجها يقول أحدهم خذ زوجتي وأعطني زوجتك وهذا غير معروف عند الناقلين لأفعال العرب","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:474","bookId":"nasikh-nahhas","type":"section","seq":474,"chapter":"ص: 48","title":"ص: 633","page":"ج1 ص628","text":"والقول الثامن: إن النبي صلى الله عليه وسلم كان له حلال أن يتزوج من شاء من النساء ثم نسخ ذلك قول محمد بن كعب القرظي قال: وكذا كانت الأنبياء قبله عليه السلام، تزوج سليمان عليه السلام سبعمائة امرأة حرة وكان له ثلاثمائة مملوكة فذلك ألف وكان لداود عليه السلام مائة امرأة منهن أم سليمان امرأة أورياء بن حنان","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:475","bookId":"nasikh-nahhas","type":"section","seq":475,"chapter":"ص: 48","title":"ص: 635","page":"ج1 ص628","text":"وقال عمر مولى غفرة: \" لما قالت اليهود ما لمحمد صلى الله عليه وسلم شغل إلا التزوج فحسدوه على ذلك فأنزل الله جل وعز {أم يحسدون الناس على ما آتاهم الله من فضله فقد آتينا آل إبراهيم الكتاب والحكمة وآتيناهم ملكا عظيما} [النساء: 54] كان لسليمان عليه السلام ألف امرأة منها سبعمائة حرة وكان لداود عليه السلام مائة امرأة \"","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:476","bookId":"nasikh-nahhas","type":"section","seq":476,"chapter":"ص: 48","title":"سورة سبأ وفاطر، ويس والصافات","page":"ج1 ص628","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس،: \" أنهن نزلن بمكة ولم نجد فيهن إلا آية واحدة في والصافات قال جل وعز: {فلما بلغ معه السعي قال يا بني إني أرى في المنام أني أذبحك} [الصافات: 102] إلى تمام القصة \" للعلماء في هذه الآية ثلاثة أقوال: فمنهم من قال: هي منسوخة واحتج بقوله {قال يا أبت افعل ما تؤمر} [الصافات: 102] وأن بعده {وفديناه بذبح عظيم} [الصافات: 107] وأجاز قائل هذا أن ينسخ الشيء قبل أن يعمل به واحتج بأن رسول الله صلى الله عليه وسلم فرضت عليه خمسون صلاة ثم نقلت إلى خمس واحتج بقوله تعالى {يا أيها الذين آمنوا إذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة} [المجادلة: 12] وأن بعده {فإذ لم تفعلوا}","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:477","bookId":"nasikh-nahhas","type":"section","seq":477,"chapter":"ص: 48","title":"ص: 638","page":"ج1 ص637","text":"[المجادلة: 13] الآية وبقوله عز وجل {الآن خفف الله عنكم وعلم أن فيكم ضعفا} [الأنفال: 66] واحتج بقول الشافعي إن الله تعالى إذا فرض شيئا استعمل عباده منه بما أحب ثم نقلهم إذا شاء قال أبو جعفر: فهذا قول والقول الثاني إن هذا مما لا يجوز فيه نسخ لأنه أمر بشيء ليس بممتد فلا يجوز نسخ في مثل هذا. لو قال قائل لرجل قم ثم قال له لا تقم لكان هذا بدا ولا يجوز أن يكون هذا من صفات الله عز وجل أن يقال اذبح ثم يقال لا تذبح فهذا عظيم من القول لا يقع فيه ناسخ ولا منسوخ وقال قائل: هذا الذبح في اللغة القطع وقد فعل ذلك إبراهيم صلى الله عليه وسلم والقول الثالث إن هذا أيضا لا يكون فيه نسخ وإنما أمر إبراهيم عليه السلام بالذبح والذبح فعله وقد فعل ما يتهيأ له وليس منعه من ذلك بمنسوب إليه أنه لم يفعل ما أمر به وهذا قول صحيح حسن عليه أهل التأويل قال مجاهد: \" لما أمر الله تعالى إبراهيم بذبح ابنه إسحاق قال له يا أبه خذ بناصيتي واجلس بين كتفي فلا أوذيك إذا وجدت حر السكين فلما وضع السكين على حلقه وفي بعض الأخبار فلما أمر السكين على حلقه انقلبت فقال له مالك يا أبه؟ قال: انقلبت","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:478","bookId":"nasikh-nahhas","type":"section","seq":478,"chapter":"ص: 48","title":"ص: 639","page":"ج1 ص637","text":"قال فاطعن بها طعنا قال ففعل فانثنت فعلم الله تعالى منه الصدق ففداه بذبح عظيم \" قال أبو جعفر: وقد فعل إبراهيم عليه السلام ما أمر به والدليل على هذا قوله تعالى {وناديناه أن يا إبراهيم قد صدقت الرؤيا} [الصافات: 105] فهذا مما يجب أن يقف عليه المسلمون لئلا ينسب إلى الله عز وجل البداء وإنما أشكل على قائل ذلك القول الأول قوله تعالى {وفديناه بذبح عظيم} [الصافات: 107] لأنه جهل معناه ولم يدر من المفدي على الحقيقة وإنما المفدي ابنه وإبراهيم عليه السلام قد فعل ما أمر به فأما القول الثاني فلو صح عن أهل التأويل لما امتنع القول به والقول الأول عظيم من القول واحتجاج صاحبه بحديث النبي صلى الله عليه وسلم أنه أمر أن يأمر أمته بخمسين صلاة ثم نقل ذلك إلى خمس لا حجة له فيه لأنه ليس فيه نسخ ولا نعلم أن أحدا من العلماء قال نسخ الشيء من قبل أن ينزل من السماء إلى الأرض إلا القاشاني فإنه خرج عن قول الجماعة ليصح له قوله إن البيان لا يتأخر وإنما أمر النبي صلى الله عليه وسلم أن يأمر أمته بخمسين صلاة فمن قبل أن يأمرهم راجع وإنما مثل هذا أن يأمر الله تعالى جبريل صلى الله عليه وسلم بشيء فيراجع فيه فينقص منه أو يزال فلا يقال لهذا نسخ وأما الاحتجاج بقوله تعالى {الآن خفف الله عنكم} [الأنفال: 66] فمن أين لقائل هذا أن الآية الأولى لم يعمل بها","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:479","bookId":"nasikh-nahhas","type":"section","seq":479,"chapter":"ص: 48","title":"ص: 640","page":"ج1 ص637","text":"وأما احتجاجه بقوله تعالى {فإذ لم تفعلوا} [المجادلة: 13] فمن أين له أيضا أن الآية الأولى لم يعمل بها\nوقد حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أبو نعيم، عن موسى بن قيس، عن سلمة بن كهيل، {يا أيها الذين آمنوا إذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة} [المجادلة: 12] قال: «أول من عمل بها علي بن أبي طالب رضي الله عنه ثم نسخت» وأما قوله تعالى {كما كتب على الذين من قبلكم} [البقرة: 183] ثم قال تعالى: {علم الله أنكم كنتم تختانون أنفسكم} [البقرة: 187] وإنما فعل هذا واحد واحتجاجه بقول الشافعي لا معنى له لأن قول الشافعي إذا فرض الله تعالى شيئا استعمل عباده بما أحب منه لا دليل فيه على أن الشيء ينسخ قبل أن يستعمل بل لو قال قائل بل فيه دليل على أن الشيء لا ينسخ حتى يستعمل أو يستعمل بعضه لكان أولى بالصواب والدليل على أن الشيء لا ينسخ قبل أن يستعمل أن احتجاج العلماء في النسخ أن معناه إذا قلت افعل كذا وكذا في معناه إلى وقت كذا أو تشترط كذا فإذا نسخ فإنما أظهر ذلك الذي كان مضمرا","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:480","bookId":"nasikh-nahhas","type":"section","seq":480,"chapter":"ص: 48","title":"ص: 641","page":"ج1 ص637","text":"فإذا قيل صلوا إلى بيت المقدس فمعناه إلى أن أزيل ذلك أو إلى وقت كذا أو على أني أزيل ذلك وقت كذا وقد علم الله حقيقة ذلك ولا يجوز أن يقال: صل الظهر بعد الزوال على أني أزيلها عنك مع الزوال قال أبو جعفر: فهذا بين وأقوال العلماء أن البيان يجوز أن يتأخر فخالفهم قائل هذا وجعله نسخا ولو جاز أن يقال لهذا نسخ لجاز أن يقال في قول الله تعالى: {إن الله يأمركم أن تذبحوا بقرة} [البقرة: 67] ثم بين ما هي ولا يقول أحد من الأمة: إن هذا نسخ واحتجاجه بقول الشافعي يخالف فيه لأن أصحاب الشافعي الحذاق لا نعلم بينهم خلافا أن البيان يتأخر فممن احتج منهم لتأخره ابن سريج بقول الله تعالى {فإذا قرأناه فاتبع قرآنه ثم إن علينا بيانه} [القيامة: 19] وثم في اللغة تدل على أن الثاني بعد الأول والدليل على أن البيان خلاف النسخ أن البيان يكون في الأخبار والنسخ لا يكون في الأخبار وأيضا فإن البيان يكون معه دليل يدل على الخصوص إذا كان اللفظ عاما أو كان خاصا يراد به العام كما قال عز وجل {إن الإنسان لفي خسر} [العصر: 2] فلما قال: {إلا الذين آمنوا} [العصر: 3] دل على أن الإنسان بمعنى","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:481","bookId":"nasikh-nahhas","type":"section","seq":481,"chapter":"ص: 48","title":"ص: 642","page":"ج1 ص637","text":"الناس وقال جل وعز: {والملك} [الحاقة: 17] فلما قال: {على أرجائها} [الحاقة: 17] علم أن الملك بمعنى الملائكة فهكذا الخصوص والعموم وهكذا التخصيص في الاستثناء لا يسمى نسخا وهذا الباب من اللغة يحتاج إليه كل من نظر في العلم وبالله التوفيق","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:482","bookId":"nasikh-nahhas","type":"section","seq":482,"chapter":"ص: 48","title":"سورة ص والزمر","page":"ج1 ص640","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس،: \" أنهما نزلتا بمكة سوى ثلاث آيات منها نزلن بالمدينة في وحشي قاتل حمزة رضي الله عنه فإنه أسلم ودخل المدينة فكان يثقل على رسول الله صلى الله عليه وسلم النظر إليه حتى ساء ظن وحشي وخاف أن يكون الله تعالى لم يقبل إسلامه فأنزل الله تعالى بالمدينة ثلاث آيات وهن قوله: {قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله} [الزمر: 53] إلى تمام الثلاث الآيات \" قال أبو جعفر: في ص ثلاث مواضع مما يصلح في هذا الكتاب فالموضع الأول قوله تعالى {اصبر على ما يقولون} [ص: 17] ثم أمر بعد ذلك بالمدينة بالقتال وقد يجوز أن يكون هذا غير منسوخ ويكون تأديبا من الله تعالى له وأمرا منه للصبر على أذاهم لأن التقدير اصبر على ما يقولون مما يؤذونك به","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:483","bookId":"nasikh-nahhas","type":"section","seq":483,"chapter":"ص: 48","title":"ص: 644","page":"ج1 ص643","text":"والدليل على هذا أن قبله ذكر ما قد آذوه به قال الله تعالى: {وقالوا ربنا عجل لنا قطنا قبل يوم الحساب} [ص: 16] لأنهم قالوا هذا استهزاء وإنكارا لما جاء به\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس وقالوا: {ربنا عجل لنا قطنا} [ص: 16] قال: «العذاب» وقال قتادة: «نصيبا من العذاب» قال ذلك أبو جهل اللهم إن كان ما جاء به محمد حقا فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم وقال السدي قالوا للنبي صلى الله عليه وسلم: أرنا منازلنا من الجنة نتبعك وقال إسماعيل بن أبي خالد {عجل لنا قطنا} [ص: 16] «أي رزقنا»\nوقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال حدثنا وكيع، قال: حدثنا سفيان، عن أبي المقدام، عن سعيد بن جبير","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:484","bookId":"nasikh-nahhas","type":"section","seq":484,"chapter":"ص: 48","title":"ص: 645","page":"ج1 ص644","text":"، {وقالوا ربنا عجل لنا قطنا} [ص: 16] قال: «نصيبنا من الآخرة» قال أبو جعفر: \" وهذا من أحسن ما روي فيه وأصل القط في كلام العرب الكتاب بالجائزة وهو النصيب وهو مشتق من قولهم قط أي حسب أي يكفيك ويجوز أن يكون مشتقا من قططت أي قطعت قال أبو جعفر: وقد ذكرنا قول أهل التأويل فيه وأهل اللغة في اشتقاقه إلا شيئا حكاه القتبي أنهم لما أنزل الله تعالى: {فأما من أوتي كتابه بيمينه} [الحاقة: 19] الآية قالوا ربنا عجل لنا كتبنا حتى ننظر أيقع في أيماننا أم في شمائلنا استهزاء فأنزل الله تعالى: {وقالوا ربنا عجل لنا قطنا} [ص: 16] قال أبو جعفر: وهذا القول أصله عن الكلبي وكثيرا ما يعتمد عليه القتبي والفراء وأهل الدين من أصحاب الحديث يحظرون ذكر شيء عن الكلبي ولاسيما في كتاب الله والموضع الآخر قوله تعالى {فطفق مسحا بالسوق والأعناق} [ص: 33] فمن العلماء من قال أبيح هذا ثم نسخ وحظر علينا قال الحسن: «قطع أسوقها وأعناقها فعوضه الله مكانها خيرا منها وسخر له الريح»","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:485","bookId":"nasikh-nahhas","type":"section","seq":485,"chapter":"ص: 48","title":"ص: 646","page":"ج1 ص644","text":"وأحسن من هذا القول ما رواه ابن أبي طلحة عن ابن عباس قال: «طفق يمسح أعناقها وعراقيبها حبا» وهذا أولى لأنه لا يجوز أن ينسب إلى نبي من الأنبياء أنه عاقب خيلا ولاسيما بغير جناية إنما شغل بالنظر إليها ففرط في صلاة فلا ذنب لها في ذلك وروى الحارث عن علي بن أبي طالب عليه السلام قال: «الصلاة التي فرط فيها سليمان عليه السلام صلاة العصر»","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:486","bookId":"nasikh-nahhas","type":"section","seq":486,"chapter":"ص: 48","title":"ص: 647","page":"ج1 ص644","text":"والموضع الثالث قوله تعالى {وخذ بيدك ضغثا فاضرب به ولا تحنث} [ص: 44] فمن العلماء من قال هذا منسوخ في شريعتنا وإذا حلف رجل أن يضرب إنسانا عشر ضربات ثم لم يضربه عشر مرات حنث وقال قوم بل لا يحنث إذا ضربه بما فيه عشرة بعد أن تصيبه","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:487","bookId":"nasikh-nahhas","type":"section","seq":487,"chapter":"ص: 48","title":"ص: 648","page":"ج1 ص644","text":"العشرة وهذا قول الشافعي ومن قبله عطاء، قال: «هي عامة» وقال مجاهد «هي خاصة» وأهل المدينة يميلون إلى هذا القول","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:488","bookId":"nasikh-nahhas","type":"section","seq":488,"chapter":"ص: 48","title":"الحواميم السبع","page":"ج1 ص644","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس: «أنهن نزلن بمكة»","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:489","bookId":"nasikh-nahhas","type":"section","seq":489,"chapter":"ص: 48","title":"ص: 650","page":"ج1 ص649","text":"قال أبو جعفر: \" وإنما يذكر ما نزل بمكة والمدينة لأن فيه أعظم الفائدة في الناسخ والمنسوخ لأن الآية إذا كانت مكية وكان فيها حكم وكان في غيرها مما نزل بالمدينة حكم غيره علم أن المدنية نسخت المكية وجدنا في الحواميم ثمانية مواضع منها في حم عسق خمسة مواضع","bab":"باب ذكر الآية الثانية قال جل وعز: {لا يحل لك النساء من بعد ولا أن تبدل بهن من أزواج ولو أعجبك حسنهن إلا ما ملكت يمينك} [الأحزاب: 52] للعلماء في هذه الآية ثمانية"},{"id":"nasikh-nahhas:490","bookId":"nasikh-nahhas","type":"section","seq":490,"chapter":"ص: 48","title":"باب ذكر الموضع الأول منها قال جل وعز: {والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الأرض}","page":"ج1 ص649","text":"[الشورى: 5]\nحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم الحربي، قال حدثنا أحمد بن منصور، قال: حدثنا إبراهيم بن خالد، قال: حدثنا داود بن قيس الصنعاني، قال دخلت على وهب بن منبه مع ذي جولان فسألته عن قوله عز وجل {ويستغفرون لمن في الأرض} [الشورى: 5] فقال: \" نسختها الآية التي في الطول: {ويستغفرون للذين آمنوا} [غافر: 7] \" هذا لا يقع فيه ناسخ ولا منسوخ لأنه خبر من الله تعالى ولكن يجوز أن يكون وهب بن منبه أراد هذه الآية على نسخة تلك الآية لأنه لا فرق بينهما وكذا يجب أن يتأول للعلماء ولا يتأول عليهم الخطأ العظيم إذا كان لما قالوه وجه، والدليل على ما قلنا\nما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قوله تعالى: {ويستغفرون لمن في الأرض} [الشورى: 5] قال: «للمؤمنين منهم»","bab":"باب ذكر الموضع الأول منها قال جل وعز: {والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الأرض}"},{"id":"nasikh-nahhas:491","bookId":"nasikh-nahhas","type":"section","seq":491,"chapter":"ص: 48","title":"باب ذكر الموضع الثاني قال جل وعز إخبارا: {لنا أعمالنا ولكم أعمالكم لا حجة بيننا وبينكم} [الشورى: 15] فيها قولان محتملان فمن ذلك","page":"ج1 ص651","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، قال: وقوله عز وجل {لنا أعمالنا ولكم أعمالكم} [الشورى: 15] \" مخاطبة لليهود أي لنا ديننا ولكم دينكم قال: ثم نسخت بقوله تعالى: {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية \" وكذا قال مجاهد {لنا أعمالنا ولكم أعمالكم} [الشورى: 15] أي لنا ديننا ولكم دينكم {لا حجة بيننا وبينكم} [الشورى: 15] أي لا خصومة وهذا لليهود ثم نسخها {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] فهذا قول والقول الثاني: أن تكون غير منسوخة أي لا حجة بيننا وبينكم لأن البراهين قد ظهرت والحجة قد قامت\nوالقول الأول: يجوز لأن معنى {لا حجة بيننا وبينكم} [الشورى: 15] على ذلك القول لم نؤمر أن نحتج عليكم ونقاتلكم ثم نسخ كما أن قائلا لو قال من قبل أن تحول القبلة لا تصلي إلى الكعبة ثم حول الناس بعد لجاز أن يقال نسخ ذلك","bab":"باب ذكر الموضع الثاني قال جل وعز إخبارا: {لنا أعمالنا ولكم أعمالكم لا حجة بيننا وبينكم} [الشورى: 15] فيها قولان محتملان فمن ذلك"},{"id":"nasikh-nahhas:492","bookId":"nasikh-nahhas","type":"section","seq":492,"chapter":"ص: 48","title":"باب ذكر الموضع الثالث قال جل وعز {من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} [الشورى:","page":"ج1 ص653","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، قال: وقوله تعالى {من كان يريد حرث الآخرة} [الشورى: 20] \" من كان من الأبرار يريد بعمله الصالح ثواب الآخرة {نزد له في حرثه} [الشورى: 20] أي في حسناته {ومن كان يريد حرث الدنيا} [الشورى: 20] أي من كان من الفجار يريد بعمله الحسن الدنيا {نؤته منها} [آل عمران: 145] ثم نسخ ذلك في سورة سبحان {من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد} [الإسراء: 18] \" والقول الآخر إنها غير منسوخة وهو الذي لا يجوز غيره لأن هذا خبر والأشياء كلها بإرادة الله ألا ترى أنه قد صح عن النبي الله صلى الله عليه وسلم: «لا يقل أحدكم اللهم اغفر لي إن شئت اللهم ارحمني إن شئت»","bab":"باب ذكر الموضع الثالث قال جل وعز {من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} [الشورى: 20] فيه قولان من ذل"},{"id":"nasikh-nahhas:493","bookId":"nasikh-nahhas","type":"section","seq":493,"chapter":"ص: 48","title":"ص: 655","page":"ج1 ص654","text":"قال أبو جعفر: إلا أنه يجوز أن يتأول للقول الأول أن يكون معناه هذه على نسخه هذه فيصح ذلك وربما أغفل من لم ينعم النظر في مثل هذا فجعل في الأخبار ناسخا ومنسوخا فلحقه الغلط العظيم والدليل على أنها غير منسوخة أنه خبر وقد قال قتادة في الآية: من آثر الدنيا على الآخرة وكدح لها لم يكن له في الآخرة إلا النار ولم يزدد منها شيئا إلا ما قسم الله له","bab":"باب ذكر الموضع الثالث قال جل وعز {من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} [الشورى: 20] فيه قولان من ذل"},{"id":"nasikh-nahhas:494","bookId":"nasikh-nahhas","type":"section","seq":494,"chapter":"ص: 48","title":"باب ذكر الموضع الرابع قال جل وعز {قل لا أسألكم عليه أجرا إلا المودة في القربى} [الشورى: 23] في هذه الآية أربعة أقوال، فمن ذلك","page":"ج1 ص654","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، {قل لا أسألكم عليه أجرا} [الأنعام: 90] قال: \" لا أسألكم على الإيمان جعلا إلا أن تودوني لقرابتي وتصدقوني وتمنعوا مني ففعل ذلك بالأنصار ومنعوا منه منعهم عن أنفسهم وأولادهم، ثم نسختها {قل ما سألتكم من أجر فهو لكم إن أجري إلا على الله} [سبأ: 47] \" ومذهب عكرمة أنها ليست بمنسوخة قال: كانوا يصلون أرحامهم فلما بعث النبي صلى الله عليه وسلم قطعوه فقال: {قل لا أسألكم عليه أجرا} [الأنعام: 90] إلا أن تودوني وتحفظوني لقرابتي ولا تكذبوني وفي رواية قيس عن الأعمش عن سعيد بن جبير عن ابن عباس: \" لما أنزل الله تعالى {قل لا أسألكم عليه أجرا إلا المودة في القربى} [الشورى: 23] قالوا: يا رسول الله من هؤلاء الذين نودهم؟ قال\n: «علي وفاطمة وولدهما عليهم السلام» والقول الرابع من أجمعها وأبينها\nكما قرئ على عبد الله بن الصقر بن نصر، عن زياد بن أيوب، قال: حدثنا هشيم، قال: أخبرنا عوف، ومنصور، عن الحسن، {قل لا أسألكم عليه أجرا إلا المودة في القربى} [الشورى: 23] ، قال «التقرب إلى الله تعالى والتودد إليه بطاعته فهذا قول حسن» ويدل على صحته الحديث المسند عن رسول الله صلى الله عليه وسلم\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا الربيع بن سليمان المرادي، قال: حدثنا أسد بن موسى، قال: حدثنا قزعة وهو ابن سويد البصري، قال: حدثنا عبد الله بن أبي نجيح، عن مجاهد، عن ابن عباس، أن رسول الله صلى الله عليه وسلم قال: «لا أسألكم على ما أتيتكم به من البينات والهدى أجرا إلا أن توادوا والله تعالى وأن تتقربوا إليه بطاعته»","bab":"باب ذكر الموضع الرابع قال جل وعز {قل لا أسألكم عليه أجرا إلا المودة في القربى} [الشورى: 23] في هذه الآية أربعة أقوال، فمن ذلك"},{"id":"nasikh-nahhas:495","bookId":"nasikh-nahhas","type":"section","seq":495,"chapter":"ص: 48","title":"ص: 658","page":"ج1 ص657","text":"فهذا المبين عن الله عز وجل قد قال هذا وكذا قالت الأنبياء عليهم السلام أجمعين قبله {إن أجري إلا على الله} [يونس: 72]","bab":"باب ذكر الموضع الرابع قال جل وعز {قل لا أسألكم عليه أجرا إلا المودة في القربى} [الشورى: 23] في هذه الآية أربعة أقوال، فمن ذلك"},{"id":"nasikh-nahhas:496","bookId":"nasikh-nahhas","type":"section","seq":496,"chapter":"ص: 48","title":"باب ذكر الموضع الخامس قال الله جل وعز: {والذين إذا أصابهم البغي هم ينتصرون} [الشورى: 39] زعم ابن زيد أنها منسوخة قال: «المسلمون ينتصرون من ا","page":"ج1 ص657","text":"مشركا\nكما روى أسباط، عن السدي، {والذين إذا أصابهم البغي هم ينتصرون} [الشورى: 39] قال: «ينتصرون ممن بغى عليهم من غير أن يتعدوا» وهذا أولى من قول ابن زيد لأن الآية عامة {وجزاء سيئة سيئة مثلها} [الشورى: 40] أولى ما قيل فيه معاقبة المسيء بما يجب عليه وسميت الثانية سيئة لأنها مساءة للمقتص منه والنحويون يقولون هذا على الازدواج وأكثر العلماء على أن هذا في العقوبات والقصاص وأخذ المال لا في الكلام إلا ابن أبي نجيح\nكما حدثنا علي بن الحسين، عن الحسن بن محمد، عن ابن علية، عن ابن أبي نجيح، {وجزاء سيئة سيئة مثلها} [الشورى: 40] قال «","bab":"باب ذكر الموضع الخامس قال الله جل وعز: {والذين إذا أصابهم البغي هم ينتصرون} [الشورى: 39] زعم ابن زيد أنها منسوخة قال: «المسلمون ينتصرون من المشركين ثم نسخها أمر"},{"id":"nasikh-nahhas:497","bookId":"nasikh-nahhas","type":"section","seq":497,"chapter":"ص: 48","title":"ص: 660","page":"ج1 ص659","text":"إذا قال له أخزاك الله قال له أخزاك الله» وقال ابن زيد «هذا كله منسوخ بالجهاد وكذا عنده ولمن انتصر بعد ظلمه إنما هو للمشركين خاصة» وقول قتادة إنه عام وكذا يدل ظاهر الكلام والله عز وجل أعلم","bab":"باب ذكر الموضع الخامس قال الله جل وعز: {والذين إذا أصابهم البغي هم ينتصرون} [الشورى: 39] زعم ابن زيد أنها منسوخة قال: «المسلمون ينتصرون من المشركين ثم نسخها أمر"},{"id":"nasikh-nahhas:498","bookId":"nasikh-nahhas","type":"section","seq":498,"chapter":"ص: 48","title":"باب ذكر الموضع الذي في الزخرف قال الله جل وعز {فاصفح عنهم وقل سلام فسوف يعلمون} [الزخرف: 89] جماعة من العلماء يقولون إنها منسوخة بالأمر بالق","page":"ج1 ص659","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، {فاصفح عنهم} [الزخرف: 89] أي \" أعرض عنهم {وقل سلام} [الزخرف: 89] أي معروفا أي قل لمشركي أهل مكة فسوف يعلمون ثم نسخ هذا في سورة براءة بقوله تعالى {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] الآية \"\nقال أبو جعفر وحدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أحمد بن نيزك، عن الخفاف، عن سعيد، عن قتادة، {فاصفح عنهم} [الزخرف: 89] قال: «ثم نسخ ذلك وأمر بالقتال»","bab":"باب ذكر الموضع الذي في الزخرف قال الله جل وعز {فاصفح عنهم وقل سلام فسوف يعلمون} [الزخرف: 89] جماعة من العلماء يقولون إنها منسوخة بالأمر بالقتال فمن ذلك"},{"id":"nasikh-nahhas:499","bookId":"nasikh-nahhas","type":"section","seq":499,"chapter":"ص: 48","title":"باب ذكر الموضع الذي في الجاثية قال الله جل وعز {قل للذين آمنوا يغفروا للذين لا يرجون أيام الله ليجزي قوما بما كانوا يكسبون} [الجاثية: 14] قا","page":"ج1 ص661","text":"ما حدثناه عليل بن أحمد، قال: حدثنا محمد بن هشام، قال: حدثنا عاصم بن سليمان، عن جويبر، عن الضحاك، عن ابن عباس، {قل للذين آمنوا} [الجاثية: 14] : \" نزلت في عمر بن الخطاب رضي الله عنه شتمه رجل من المشركين بمكة قبل الهجرة فأراد أن يبطش به فأنزل الله تعالى {قل للذين آمنوا} [الجاثية: 14] يعني عمر بن الخطاب رضي الله عنه {يغفروا للذين لا يرجون أيام الله} [الجاثية: 14] ويعفوا ويتجاوزوا للذين لا يخافون مثل عقوبات الأيام الخالية {ليجزي قوما بما كانوا يكسبون} [الجاثية: 14] ثم نسخ","bab":"باب ذكر الموضع الذي في الجاثية قال الله جل وعز {قل للذين آمنوا يغفروا للذين لا يرجون أيام الله ليجزي قوما بما كانوا يكسبون} [الجاثية: 14] قال جماعة من العلماء ه"},{"id":"nasikh-nahhas:500","bookId":"nasikh-nahhas","type":"section","seq":500,"chapter":"ص: 48","title":"ص: 663","page":"ج1 ص662","text":"هذا في براءة بقوله {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \"\nقال أبو جعفر حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قوله تعالى: {قل للذين آمنوا يغفروا للذين لا يرجون أيام الله} [الجاثية: 14] قال: \" نسختها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \"","bab":"باب ذكر الموضع الذي في الجاثية قال الله جل وعز {قل للذين آمنوا يغفروا للذين لا يرجون أيام الله ليجزي قوما بما كانوا يكسبون} [الجاثية: 14] قال جماعة من العلماء ه"},{"id":"nasikh-nahhas:501","bookId":"nasikh-nahhas","type":"section","seq":501,"chapter":"ص: 48","title":"باب ذكر الآية التي في الأحقاف قال جل وعز: {قل ما كنت بدعا من الرسل وما أدري ما يفعل بي ولا بكم}","page":"ج1 ص663","text":"[الأحقاف: 9]\nقرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا حسين بن علي الجعفي، عن سفيان، {وما أدري ما يفعل بي ولا بكم} [الأحقاف: 9] قال: «يرون أنها نزلت قبل الفتح»\nوفي رواية الضحاك، عن ابن عباس،: نسخها {إنا فتحنا لك فتحا مبينا ليغفر لك الله ما تقدم من ذنبك وما تأخر} [الفتح: 2] الآية \"\nقال أبو جعفر: محال أن يكون في هذا ناسخ ولا منسوخ من جهتين إحداهما أنه خبر والآخر أن من أول السورة إلى هذا الموضع فيه خطاب للمشركين واحتجاج عليهم وتوبيخ لهم فوجب أن يكون هذا أيضا خطابا للمشركين كما كان ما قبله وما بعده ومحال أن يقول صلى الله عليه وسلم للمشركين {وما أدري ما يفعل بي ولا بكم} [الأحقاف: 9] في الآخرة ولم يزل صلى الله عليه وسلم من أول مبعثه إلى وفاته يخبر أن من مات على الكفر يخلد في النار ومن مات على الإيمان واتبعه وأطاعه فهو في الجنة، فقد درى صلى الله عليه وسلم ما يفعل به وبهم وليس يجوز أن يقول لهم: ما أدري ما يفعل بي ولا بكم في الآخرة فيقولوا كيف نتبعك وأنت لا تدري أتصير إلى خفض ودعة أم إلى عذاب وعقاب والصحيح في معنى الآية قول الحسن\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا وكيع، قال: حدثنا أبو بكر الهذلي، عن الحسن، {وما أدري ما يفعل بي ولا بكم} [الأحقاف: 9] : «في الدنيا»","bab":"باب ذكر الآية التي في الأحقاف قال جل وعز: {قل ما كنت بدعا من الرسل وما أدري ما يفعل بي ولا بكم}"},{"id":"nasikh-nahhas:502","bookId":"nasikh-nahhas","type":"section","seq":502,"chapter":"ص: 48","title":"ص: 666","page":"ج1 ص665","text":"قال أبو جعفر: وهذا أصح قول وأحسنه لا يدري صلى الله عليه وسلم ما يلحقه وإياهم من مرض وصحة ورخص وغلاء وغنى وفقر، ومثله {ولو كنت أعلم الغيب لاستكثرت من الخير وما مسني السوء} [الأعراف: 188]","bab":"باب ذكر الآية التي في الأحقاف قال جل وعز: {قل ما كنت بدعا من الرسل وما أدري ما يفعل بي ولا بكم}"},{"id":"nasikh-nahhas:503","bookId":"nasikh-nahhas","type":"section","seq":503,"chapter":"ص: 48","title":"سورة محمد صلى الله عليه وسلم","page":"ج1 ص665","text":"حدثنا يموت، بإسناده عن ابن عباس قال: «سورة محمد صلى الله عليه وسلم» مدنية قال أبو جعفر: وجدنا فيها موضعين","bab":"باب ذكر الآية التي في الأحقاف قال جل وعز: {قل ما كنت بدعا من الرسل وما أدري ما يفعل بي ولا بكم}"},{"id":"nasikh-nahhas:504","bookId":"nasikh-nahhas","type":"section","seq":504,"chapter":"ص: 48","title":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب","page":"ج1 ص667","text":"والناسخ لها عندهم {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] ومنهم من قال: هي في الكفار جميعا وهي منسوخة ومنهم من قال هي ناسخة لا يجوز أن يقتل الأسير ولكن يمن عليه أو يفادى به ومنهم من قال: لا يجوز الأسر إلا بعد الإثخان والقتل، فإذا أسر العدو بعد ذلك فللإمام أن يحكم فيه بما رأى من قتل أو من أو مفاداة والقول الخامس: إنها محكمة غير ناسخة ولا منسوخة والإمام مخير أيضا فممن قال القول ابن جريج وجماعة معه من ذلك \"\nما حدثنا الحسن بن غليب، عن يوسف بن عدي، قال حدثنا ابن المبارك، عن ابن","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:505","bookId":"nasikh-nahhas","type":"section","seq":505,"chapter":"ص: 48","title":"ص: 669","page":"ج1 ص668","text":"جريج، {فإما منا بعد وإما فداء} [محمد: 4] قال: \" نسخها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" قال أبو جعفر: وهذا معروف من قول ابن جريج: إن الآية منسوخة وإنها في كفار العرب وهو قول السدي وكثير من الكوفيين والقول الثاني: إنها في جميع الكفار وإنها منسوخة قول جماعة من العلماء وأهل النظر وقالوا إذا أسر المشرك لم يجز أن يمن عليه ولا أن يفادى به فيرد إلى المشركين ولا يجوز عندهم أن يفادى إلا بالمرأة؛ لأنها لا تقتل، والناسخ لها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] إذ كانت براءة آخر ما نزل بالتوقيف فوجب أن يقتل كل مشرك إلا من قامت الدلالة على تركه من النساء والصبيان، ومن تؤخذ منه الجزية، قالوا: والحجة لنا في قتل النبي صلى الله عليه وسلم عقبة بن أبي معيط وأبا عزة قيل فإن هذين","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:506","bookId":"nasikh-nahhas","type":"section","seq":506,"chapter":"ص: 48","title":"ص: 670","page":"ج1 ص668","text":"وغيرهما أهل أوثان وبراءة نزلت بعدها؛ لأن عقبة قتل يوم بدر وأبا عزة يوم أحد، قالوا: فليس في هذا حجة، فقيل فإن ثبت في هذا حجة فهو القتل كما هو فأما الاحتجاج بما فعله أبو بكر وعمر وعلي رضي الله عنهم من المن فليس فيه حجة؛ لأن أبا بكر إنما من على الأشعث؛ لأنه مرتد فحكمه أن يستتاب وإنما من عمر على الهرمزان؛ لأنه احتال عليه بأن قال: له \" اشرب فلا بأس عليك، فقال له: قد أمنتني","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:507","bookId":"nasikh-nahhas","type":"section","seq":507,"chapter":"ص: 48","title":"ص: 671","page":"ج1 ص668","text":"وعلي بن أبي طالب إنما من على قوم من المسلمين يشهدون شهادة الحق ويصلون ويصومون قال أبو أمامة: كنت معه بصفين فكان إذا جيء بأسير استحلفه أن لا يكثر عليه ودفع إليه أربعة دراهم فخلاه وكان هذا مذهبه أن لا يقتل الأسير من المسلمين ولا يغنم ماله ولا يتبعه إذا ولى ولا يجهز على جريح فكانت هذه سنته في قتال من بغى من أهل القبلة\nقال أبو جعفر،: وحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، {فإما منا بعد وإما فداء} [محمد: 4] قال: \" نسخها {فشرد بهم من خلفهم} [الأنفال: 57] «وقال مجاهد» نسخها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] \" وهو قول الحكم والقول الثالث: إنها ناسخة قول الضحاك وجماعة غيره\nكما روى","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:508","bookId":"nasikh-nahhas","type":"section","seq":508,"chapter":"ص: 48","title":"ص: 672","page":"ج1 ص671","text":"الثوري، عن جويبر، عن الضحاك، {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] قال: \" نسخها {فإما منا بعد وإما فداء} [محمد: 4] \"\nومن ذلك ما حدثناه أبو جعفر قال حدثناه الحسن بن غليب، عن يوسف بن عدي، قال: حدثنا ابن المبارك، عن ابن جريج، عن عطاء، {فإما منا بعد وإما فداء} [محمد: 4] قال: «فلا يقتل المشرك ولكن يمن عليه ويفادى إذا أسر كما قال جل وعز» وقال الأشعث: كان الحسن \" يكره أن يقتل الأسير ويتلو {فإما منا بعد وإما فداء} [محمد: 4] \" والقول الرابع: رواه شريك، عن سالم الأفطس، عن سعيد بن جبير قال: «لا يكون فداء ولا أسر إلا بعد الإثخان والقتل بالسيف» ، والقول الخامس قاله كثير من العلماء\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس، {فإما منا بعد وإما فداء} [محمد: 4] قال: «فجعل الله النبي صلى الله عليه وسلم","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:509","bookId":"nasikh-nahhas","type":"section","seq":509,"chapter":"ص: 48","title":"ص: 673","page":"ج1 ص672","text":"والمؤمنين بالخيار في الأسارى إن شاءوا قتلوهم وإن شاءوا استعبدوهم وإن شاءوا فادوا بهم» قال أبو جعفر: وهذا على أن الآيتين محكمتان معمول بهما وهو قول حسن؛ لأن النسخ إنما يكون بشيء قاطع فإذا أمكن العمل بالآيتين فلا معنى للقول بالنسخ إذ كان يجوز أن يقع التعبد إذا لقينا الذين كفروا قبل الأسر قتلناهم، فإذا كان الأسر جاز القتل والمفاداة، والمن على ما فيه الصلاح للمسلمين وهذا القول يروى عن أهل المدينة، والشافعي، وأبي عبيد، وبالله التوفيق","bab":"باب ذكر الموضع الأول منها قال عز وجل {فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء حتى تضع الحرب أوزارها} [محمد: 4] "},{"id":"nasikh-nahhas:510","bookId":"nasikh-nahhas","type":"section","seq":510,"chapter":"ص: 48","title":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {و","page":"ج1 ص672","text":"نزلتا في وقتين مختلفين، وقيل: يجوز أن يكون {وإن جنحوا للسلم} [الأنفال: 61] في قوم بأعيانهم، وتكون هذه الآية عامة","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:511","bookId":"nasikh-nahhas","type":"section","seq":511,"chapter":"ص: 48","title":"سورة الفتح، والحجرات","page":"ج1 ص674","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس،: «أنهما نزلتا بالمدينة» وقد ذكرنا قول من قال {إنا فتحنا لك فتحا مبينا ليغفر لك الله ما تقدم من ذنبك وما تأخر} [الفتح: 2] ناسخ لقوله تعالى {وما أدري ما يفعل بي ولا بكم} [الأحقاف: 9] وأن هذا لا يكون فيه نسخ ولم نذكر معنى {إنا فتحنا لك} [الفتح: 1] على استقصاء وهذا موضعه فمن الناس من يتوهم أنه يعنى بهذا: فتح مكة وذلك غلط والذي عليه الصحابة والتابعون غيره حتى كأنه إجماع\nكما روى أبو إسحاق، عن","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:512","bookId":"nasikh-nahhas","type":"section","seq":512,"chapter":"ص: 48","title":"ص: 676","page":"ج1 ص675","text":"البراء، {إنا فتحنا لك فتحا مبينا} [الفتح: 1] قال: «تعدون الفتح فتح مكة وإنما نعده فتح الحديبية كنا أربع عشرة مائة»\nوكذا روى الأعمش، عن أبي سفيان، عن جابر، قال: «تعدون الفتح فتح مكة وإنما هو الحديبية» وكذا قال أنس بن مالك، وابن عباس، وسهل بن حنيف، والمسور بن مخرمة، وقاله من التابعين الحسن، ومجاهد، والزهري، وقتادة وفي تسمية فتح الحديبية فتحا أقوال للعلماء بينة لو لم يكن فيها إلا أن الله تعالى أنزل على نبيه صلى الله عليه وسلم {لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة} [الفتح: 18]","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:513","bookId":"nasikh-nahhas","type":"section","seq":513,"chapter":"ص: 48","title":"ص: 677","page":"ج1 ص675","text":"بعد أن عرفه المغفرة له، ثم لم ينزل بعد ذلك سخطا على من رضي عنه، وأيضا فإن الحديبية بئر ورد عليها المسلمون وقد غاض ماؤها فتفل رسول الله صلى الله عليه وسلم فيها فجاء الماء حتى عمهم ولم يكن بين المسلمين والكفار إلا ترام حتى كان الفتح وقد كان بعض العلماء يتأول أنه إنما قيل ليوم الحديبية: الفتح؛ لأنه كان سببا لفتح مكة وجعله مجازا كما يقال: قد دخلنا المدينة إذا قاربنا دخولها وأبين ما في هذا\nما حدثناه أحمد بن محمد بن الحجاج، قال: حدثنا يحيى بن سليمان، قال: حدثني الأجلح، عن محمد بن إسحاق، عن ابن شهاب، بإسناده، قال: «لم يكن في الإسلام فتح أعظم منه كانت الحرب قد حجزت بين الناس فلا يتكلم أحد وإنما كان القتال فلما كانت الحديبية والصلح وضعت الحرب وأمن الناس فتلاقوا فلم يكلم أحد بعقد الإسلام إلا دخل فيه فلقد دخل في تلك السنين مثل من كان قبل ذلك أو أكثر» وهذا قول حسن بين\n، وقال جل وعز {لا يستوي منكم من أنفق من قبل الفتح وقاتل أولئك أعظم درجة من الذين أنفقوا من بعد وقاتلوا} [الحديد: 10] كان هذا في يوم الحديبية أيضا جاء بذلك التوقيف عن النبي صلى الله عليه وسلم أنه قال لأصحابه: «هذا فرق ما بينكم وبين الناس» وفي الحديث: «لا تسبوا أصحابي، فلو أنفق أحدكم ملء الأرض ما بلغ مد أحدهم ولا نصيفه» . وهذا للذين أنفقوا قبل الحديبية وقاتلوا","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:514","bookId":"nasikh-nahhas","type":"section","seq":514,"chapter":"ص: 48","title":"سورة ق والذرايات والطور والنجم والقمر والرحمن والواقعة","page":"ج1 ص678","text":"حدثنا أبو جعفر قال حدثنا يموت، بإسناده عن ابن عباس،: «أنهن نزلن بمكة» قال أبو جعفر: وجدنا فيهن خمسة مواضع، في سورة ق موضع، قال الله عز وجل {فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب ومن الليل فسبحه وأدبار السجود} [ق: 40] يجوز أن يكون {فاصبر على ما يقولون} [ق: 39] منسوخا بقوله عز وجل {قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر} [التوبة: 29] الآية، ويجوز أن يكون محكما أي: اصبر على أذاهم فإن الله تعالى لهم بالمرصاد، فهذا نزل في اليهود، جاء التوقيف بذلك لأنهم تكلموا بكلام لحق النبي صلى الله عليه وسلم منه أذى\nكما قرئ على إسحاق بن إبراهيم بن يونس، عن هناد بن السري، قال: حدثنا أبو بكر بن عياش، عن أبي سعد وهو سعيد بن المرزبان، عن عكرمة، عن ابن عباس، قال هناد: قرأته على أبي بكر إن اليهود، جاءت إلى النبي صلى الله عليه وسلم فسألته عن خلق السموات والأرض فقال: \" خلق الله تعالى الأرض يوم الأحد ويوم الاثنين، وخلق الجبال يوم الثلاثاء","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:515","bookId":"nasikh-nahhas","type":"section","seq":515,"chapter":"ص: 48","title":"ص: 681","page":"ج1 ص680","text":"بما فيها من منافع، وخلق الشجر والماء والمدائن والعمارات والخرب يوم الأربعاء قال جل وعز {قل أئنكم لتكفرون بالذي خلق الأرض في يومين} [فصلت: 9] إلى {سواء للسائلين} [فصلت: 10] قال: لمن سأل، وخلق السماء يوم الخميس، وخلق النجوم والشمس والقمر والملائكة يوم الجمعة إلى ثلاث ساعات بقين منه، وخلق في أول ساعة من هذه الثلاث الساعات الآجال حيث يموت من يموت، وفي الثانية ألقى الآفة على كل شيء ينتفع به الناس، وفي الثالثة آدم صلى الله عليه وسلم وأسكنه الجنة وأمر إبليس بالسجود له فأخرجه منها في آخر ساعة \"، قالت اليهود: ثم ماذا يا محمد؟ قال: «ثم استوى على العرش» ، قالوا: قد أصبت لو تممت: ثم استراح، فغضب النبي صلى الله عليه وسلم غضبا شديدا ونزلت {ولقد خلقنا السموات والأرض وما بينهما في ستة أيام وما مسنا من لغوب} \" قال: أبو جعفر: ثم قال تعالى {فاصبر على ما يقولون} [ق: 39] فتأول هذا بعض العلماء على أنه: إذا حزب إنسانا أمر فينبغي أن يفزع إلى الصلاة قال حذيفة: «كان النبي صلى الله عليه وسلم إذا حزبه أمر فزع إلى الصلاة» وعن، ابن عباس، أنه عرف وهو راحل بموت قثم أخيه فأمر بحط الراحلة ثم صلى ركعتين وتلا {واستعينوا بالصبر والصلاة وإنها لكبيرة إلا على الخاشعين} [البقرة: 45]","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:516","bookId":"nasikh-nahhas","type":"section","seq":516,"chapter":"ص: 48","title":"ص: 682","page":"ج1 ص680","text":"، ثم قال جل وعز {وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب} [ق: 39] قال أبو صالح: «الصبح والعصر» ، وقد قيل الصبح والظهر والعصر ويكون {ومن الليل} [ق: 40] للمغرب والعشاء الآخرة فأما {وأدبار السجود} [ق: 40] فبين العلماء فيه اختلاف فأكثرهم يقول: الركعتان بعد المغرب، ومنهم من يقول: وبعد كل صلاة مكتوبة ركعتان والظاهر يدل على هذا، إلا أن الأولى اتباع الأكثر ولا سيما وهو صحيح عن علي بن أبي طالب عليه السلام وهذا أمر بما قد أجمع المسلمون على أنه نافلة فيجوز أن يكون ندبا لا حتما، ويجوز أن يكون منسوخا بما صح عن رسول الله صلى الله عليه وسلم أنه لا يجب على أحد إلا خمس صلوات ونقل ذلك الجماعة وكان التأذين فيها والإقامة في عهد رسول الله صلى الله عليه وسلم والخلفاء الراشدين المهديين لا أحد منهم يوجب غيرها، وفي سورة والذاريات موضعان فالموضع الأول قوله تعالى {والذين في أموالهم حق للسائل والمحروم} من العلماء من قال: هي محكمة كما قال الحسن البصري وإبراهيم النخعي في المال حق سوى الزكاة","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:517","bookId":"nasikh-nahhas","type":"section","seq":517,"chapter":"ص: 48","title":"ص: 683","page":"ج1 ص680","text":". ومن قال: هي منسوخة قال: هي وإن كانت خبرا ففي الكلام معنى الأمر أي: أعطوا السائل والمحروم ويجعل هذا منسوخا بالزكاة المفروضة\nكما قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا مروان بن معاوية، قال: حدثنا سلمة بن نبيط، قال: سمعت الضحاك بن مزاحم، يقول: «نسخت الزكاة كل صدقة في القرآن» قال أبو جعفر: وللعلماء في المحروم ثمانية أقوال\nفقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا عبد الرحيم بن سليمان، قال: حدثنا زكريا بن أبي زائدة، عن أبي إسحاق السبيعي، عن قيس، قال: سألت ابن عباس عن قول الله تعالى {للسائل والمحروم} [الذاريات: 19] فقال: «السائل الذي يسأل والمحروم الذي لا يبقى له مال»\nوفي رواية شعبة والثوري، عن أبي إسحاق، عن قيس، عن ابن","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:518","bookId":"nasikh-nahhas","type":"section","seq":518,"chapter":"ص: 48","title":"ص: 684","page":"ج1 ص683","text":"عباس، قال: \" المحروم: المحارف \" وقال: محمد ابن الحنفية: \" المحروم الذي لم يشهد الحرب أي: فيكون له سهم في الغنيمة \" وقال زيد بن أسلم: «المحروم الذي لحقته جائحة فأتلفت زرعه» وقال الزهري: «المحروم الذي لا يسأل الناس» واحتج بحديث أبي هريرة عن النبي صلى الله عليه وسلم قيل له: من المسكين يا رسول الله قال: «الذي لا يجد ما يغنيه ولا يفطن له فيعطى ولا يسأل الناس» وقال عكرمة: «المحروم الذي لا ينمى له شيء» والقول الثامن: يروى عن عمر بن عبد العزيز قال: «المحروم الكلب» وإنما وقع الاختلاف في هذا لأنها صفة أقيمت مقام الموصوف، والمحروم هو الذي قد حرم الرزق واحتاج. فهذه الأقوال كلها داخلة في هذا غير أنه ليس فيها أجل مما روي عن ابن عباس ولا أجمع أنه المحارف والموضع الآخر قوله تعالى {فتول عنهم فما أنت بملوم} [الذاريات: 54]","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:519","bookId":"nasikh-nahhas","type":"section","seq":519,"chapter":"ص: 48","title":"ص: 685","page":"ج1 ص683","text":"في رواية الضحاك أن التولي عنهم منسوخ؛ بأنه قد أمر بالإقبال عليهم بالموعظة قال تعالى {يا أيها الرسول بلغ ما أنزل إليك من ربك وإن لم تفعل فما بلغت رسالته} [المائدة: 67] فأمر أن يبلغ كما أنزل الله كما قالت عائشة: «من زعم أن محمدا صلى الله عليه وسلم كتم شيئا من الوحي فقد أعظم الفرية» قال مجاهد: \" {فتول عنهم} [الذاريات: 54] فأعرض عنهم {فما أنت بملوم} [الذاريات: 54] أي: ليس يلومك ربك تعالى على تقصير كان منك \" وفي الطور {وسبح بحمد ربك حين تقوم} [الطور: 48] للعلماء فيه أقوال: فمن ذلك\nما حدثناه أحمد بن الحجاج، قال: حدثنا يحيى الجعفي، قال: حدثني ابن وهب، قال: حدثني أسامة بن زيد، سمع محمد بن كعب القرظي، يقول في هذه الآية {فسبح بحمد ربك حين تقوم} قال: «حين تقوم إلى الصلاة»\nقال الجعفي، وحدثني عمر بن هارون البلخي، قال: حدثني أبو مصلح، عن الضحاك، في هذه الآية {وسبح بحمد ربك حين تقوم} [الطور: 48] \" إلى الصلاة أن تكبر\nوتقول: سبحانك اللهم وبحمدك تبارك اسمك وتعالى جدك ولا إله غيرك \" فهذا قول إن هذه الآية في افتتاح الصلاة ورد هذا بعض العلماء وقال: قد أجمع المسلمون أنه من لم يستفتح الصلاة بها فصلاته جائزة فلو كان هذا أمرا من الله تعالى لكان موجبا فإن قيل: هو ندب قيل: لو صح أنه واجب بما تقوم به الحجة لجاز أن يكون ندبا أو منسوخا وقال أبو الجوزاء \" {وسبح بحمد ربك حين تقوم} [الطور: 48] من النوم \" واختار هذا القول محمد بن جرير قال: يكون هذا فرضا ويكون هذا النوم القائلة، ويعنى به صلاة الظهر؛ لأن صلاة الصبح مذكورة في الآية\nوالقول الثالث قول أبي الأحوص: \" أن يكون كلما قام من مجلس قال: سبحانك اللهم وبحمدك \" وهذا القول أولاها من جهات أوكدها أنه قد صح عن عبد الله بن مسعود، وإذا تكلم صحابي في آية ولم يعلم أحد من الصحابة خالفه لم تسع مخالفته لأنهم أعلم بالتنزيل والتأويل\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا أبو نعيم، قال: حدثنا سفيان، عن أبي إسحاق، عن أبي الأحوص، عن عبد الله، {وسبح بحمد ربك حين تقوم} [الطور: 48] قال: «حين تقوم من المجلس تقول سبحان الله وبحمده» قال أبو جعفر: فيكون هذا ندبا لجميع الناس. وقد صح عن رسول الله صلى الله عليه وسلم أنه قد رغب في ذلك وكان يقول كلما قام من مجلس: «سبحانك اللهم وبحمدك لا إله إلا أنت أستغفرك وأتوب إليك» . وفي بعض الحديث يغفر له كل ما كان في ذلك المجلس\nوقد يجوز أن يكون هذا لما كان مخاطبة للنبي صلى الله عليه وسلم كان فرضا عليه وحده وندبا على قول قوم. وحجة ثالثة: أن الكلام عام فلا يخص به القيام من النوم إلا بحجة، ثم قال جل وعز {ومن الليل فسبحه} [ق: 40] فيه ثلاثة أقوال من العلماء من قال: يعني به: المغرب والعشاء وقال ابن زيد: \" يعني به: المغرب \"\nوحدثنا علي بن الحسين، عن الحسن بن محمد، عن ابن علية، قال: حدثنا ابن جريج، عن مجاهد، قال: قال ابن عباس: {ومن الليل فسبحه} [ق: 40] «هو التسبيح في أدبار الصلوات» ثم قال عز وجل {وإدبار النجوم} [الطور: 49] فيه قولان قال الضحاك وابن زيد {إدبار النجوم} [الطور: 49] «صلاة الصبح» ، واختار محمد بن جرير هذا القول؛ لأن صلاة الصبح فرض. والأولى أن تحمل الآية عليها وأولى من هذا القول؛ لأنه جاء عن صحابي لا نعلم له مخالفا\nكما قرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا محمد بن فضيل، قال: حدثنا العلاء بن المسيب، عن أبي إسحاق، عن الحارث، عن علي، في قوله تعالى {وإدبار النجوم} [الطور: 49] قال: «الركعتان بعد الفجر»","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:520","bookId":"nasikh-nahhas","type":"section","seq":520,"chapter":"ص: 48","title":"ص: 689","page":"ج1 ص688","text":"فإن قيل فالركعتان غير واجبتين والأمر من الله تعالى على الحتم إلا أن تكون حجة تدل على أنه على غير الحتم فالجواب عن هذا أنه يجوز أن يكون حتما ثم نسخ؛ لأنه لا فرض إلا الصلوات الخمس، ويجوز أن يكون ندبا ويدل على ذلك ما أجمع العلماء عليه أن ركعتي الفجر ليستا بفرض ولكنهما مندوب إليهما لا ينبغي تركهما وفي والنجم قوله تعالى {وأن ليس للإنسان إلا ما سعى} [النجم: 39] قال أبو جعفر: للناس في هذا أقوال: فمنهم من قال: إنها منسوخة، ومنهم من قال: هي محكمة فلا ينفع أحدا أن يصدق عنه أحد، ولا أن يجعل له ثواب شيء عمله. قالوا: وليس للإنسان إلا ما سعى كما قال تعالى وقال قوم: قد جاءت أحاديث عن النبي صلى الله عليه وسلم بأسانيد صحاح وهي مضمومة إلى الآية، وقال قوم الأحاديث لها تأويل: وليس للإنسان على الحقيقة إلا ما سعى فممن تؤول عليه أن الآية منسوخة ابن عباس\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال حدثني معاوية بن صالح، قال: حدثني علي بن أبي طلحة، عن ابن عباس، قال: وقوله تعالى {وأن ليس للإنسان إلا ما سعى} [النجم: 39] \" فأنزل الله عز وجل بعد ذلك {والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذرياتهم} : فأدخل الله تعالى الآباء الجنة بصلاح الأبناء \" قال محمد بن جرير: يذهب إلى أنها منسوخة","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:521","bookId":"nasikh-nahhas","type":"section","seq":521,"chapter":"ص: 48","title":"ص: 690","page":"ج1 ص688","text":"قال أبو جعفر: كذا عندي في الحديث وكان يجب أن يكون أدخل الله الأبناء الجنة بصلاح الآباء إلا أنه يجوز أن يكون المعنى على أن الآباء يلحقون بالأبناء كما يلحق الأبناء بالآباء\nقال أبو جعفر وحدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا الثوري، عن عمرو بن مرة، عن سعيد بن جبير، عن ابن عباس، قال: \" إن الله تعالى يرفع ذرية المؤمن معه في درجة الجنة وإن كانوا دونه في العمل {والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم وما ألتناهم} [الطور: 21] أي: نقصناهم \"\nوحدثنا أحمد بن محمد الأزدي، قال: حدثنا إبراهيم بن أبي داود، قال: حدثنا أحمد بن شكيب الكوفي، قال حدثنا محمد بن بشر العبدي قال: حدثنا سفيان الثوري، عن سماعة، عن عمرو بن مرة، عن سعيد بن جبير، عن ابن عباس،: أن رسول الله صلى الله عليه وسلم قال: \" إن الله ليرفع ذرية المؤمن معه في درجته وإن كان لم يبلغها بعمله ليقر بهم عينه ثم قرأ {والذين آمنوا واتبعتهم ذريتهم بإيمان} [الطور: 21] الآية \" فصار الحديث مرفوعا عن رسول الله صلى الله عليه وسلم وكذا يجب","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:522","bookId":"nasikh-nahhas","type":"section","seq":522,"chapter":"ص: 48","title":"ص: 691","page":"ج1 ص690","text":"أن يكون؛ لأن ابن عباس لا يقول هذا إلا عن رسول الله صلى الله عليه وسلم؛ لأنه إخبار عن الله تعالى بما فعله وبمعنى آية أنزلها تعالى وأما قول من قال: لا ينفع أحدا أن يصدق عنه أحد ولم يتأول الأحاديث فقول مرغوب عنه؛ لأن ما صح عن النبي صلى الله عليه وسلم لم يسع أحدا رده قال جل وعز {وما آتاكم الرسول فخذوه} [الحشر: 7] وقد صح عن النبي صلى الله عليه وسلم أحاديث سنذكر منها شيئا\nحدثنا أبو جعفر قال حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال أخبرنا مالك، عن ابن شهاب، عن سليمان بن يسار، عن عبد الله بن عباس، قال: \" كان الفضل بن عباس رديف رسول الله صلى الله عليه وسلم فجاءته امرأة من خثعم تستفتيه فجعل الفضل بن عباس ينظر إليها وتنظر إليه فجعل رسول الله صلى الله عليه وسلم يصرف وجه الفضل إلى الشق الآخر فقالت: يا رسول الله إن فريضة الله على عباده بالحج أدركت أبي شيخا كبيرا لا يستطيع أن يثبت على الراحلة أفأحج عنه؟ قال: نعم وذلك في حجة الوداع \" وفي حديث ابن عيينة، عن عمرو، عن الزهري، عن سليمان، عن ابن عباس، زيادة وهي أن النبي صلى الله عليه وسلم قال لها: أرأيت لو","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:523","bookId":"nasikh-nahhas","type":"section","seq":523,"chapter":"ص: 48","title":"ص: 692","page":"ج1 ص690","text":"كان على أبيك دين أكنت تقضينه؟ قالت: نعم، قال: «فدين الله جل وعز أولى» فقال قوم: لا يحج أحد عن أحد واحتج له بعض أصحابه فقال: في الحج صلاة لا بد منها وقد أجمع العلماء على أن لا يصلي أحد عن أحد قيل لهم الحج مخالف للصلاة مع ثبات السنة. قال أبو جعفر: وسنذكر قول من تأول الحديث\nوقد روى شعبة، عن جعفر بن أبي وحشية، عن سعيد بن جبير، عن ابن عباس، أن، رجلا، قال: يا رسول الله إن أمي توفيت وعليها صيام قال: «فصم عنها» وقد قال من يقتدى بقوله من العلماء: لا يصم أحد عن أحد، فقال من أحتج له: هذا الحديث وإن كان مستقيم الإسناد، وسعيد بن جبير وإن كان له المحل الجليل فقد وقع في أحاديثه غلط وقد خالفه عبيد الله بن عبد الله، وعبيد الله من الإتقان على ما لا خفاء به\nكما حدثنا بكر بن سهل","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:524","bookId":"nasikh-nahhas","type":"section","seq":524,"chapter":"ص: 48","title":"ص: 693","page":"ج1 ص692","text":"، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك، عن ابن شهاب عن عبيد الله بن عبد الله بن عتبة بن مسعود الهذلي، عن عبد الله بن عباس، أن سعد بن عبادة، استفتى رسول الله صلى الله عليه وسلم فقال: يا رسول الله إن أمي ماتت وعليها نذر قال: «فاقضه عنها»\nوروى الزهري، عن أبي عبد الله الأغر، عن أبي هريرة، عن النبي صلى الله عليه وسلم قال: «يلحق المسلم أو ينفع المسلم ثلاث ولد صالح يدعو له، وعلم نشره، وصدقة جارية» ونذكر قول من تأول هذه الأحاديث فيها أقوال: ومن العلماء من قال بالأحاديث كلها ولم يجز فيها الترك منهم أحمد بن حنبل وكان هذا مذهبه فقال: يحج الإنسان عن الإنسان ويتصدق عنه كما قال رسول الله صلى الله عليه وسلم قال: «ومن مات وعليه صيام شهر رمضان أطعم عنه لكل يوم، ومن مات وعليه صيام نذر صام عنه وليه» ، كما أمر رسول الله صلى الله عليه وسلم","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:525","bookId":"nasikh-nahhas","type":"section","seq":525,"chapter":"ص: 48","title":"ص: 694","page":"ج1 ص692","text":"ومن العلماء من قال ببعض الأحاديث فقال: يحج الإنسان عن الإنسان ولا يصوم عنه ولا يصلي، وهذا مذهب الشافعي، ومنهم من قال: لا يجوز في عمل الأبدان أن يعملها أحد عن أحد ولا يحج أحد عن أحد وهذا قول مالك بن أنس ومنهم من قال: الأحاديث صحيحة ولكن هي محمولة على الآية وإنما يحج الإنسان عن الإنسان إذا أمره أو أوصى بذلك أو كان له فيه","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:526","bookId":"nasikh-nahhas","type":"section","seq":526,"chapter":"ص: 48","title":"ص: 695","page":"ج1 ص692","text":"سعي حتى يكون موافقا لقوله تعالى {وأن ليس للإنسان إلا ما سعى} [النجم: 39] ، ومنهم من قال: لا يعمل أحد عن أحد شيئا فإن عمله فهو لنفسه كما قال عز وجل {وأن ليس للإنسان إلا ما سعى} [النجم: 39] ، وقال في الأحاديث سبيل الأنبياء عليهم السلام أن لا يمنعوا أحدا من فعل الخير قال أبو جعفر: وقول أحمد في هذا بين حسن وهو أصل مذهب الشافعي، فإن قال قائل: فكيف يرد هذا إلى الآية ففي ذلك جوابان أحدهما أن ما قاله الرسول صلى الله عليه وسلم وصح عنه فهو مضموم إلى القرآن\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا عيسى بن إبراهيم الغافقي، قال: حدثنا ابن عيينة، عن ابن المنكدر، وأبي النضر، عن عبيد الله بن أبي رافع، عن","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:527","bookId":"nasikh-nahhas","type":"section","seq":527,"chapter":"ص: 48","title":"ص: 696","page":"ج1 ص693","text":"أبيه، أو غيره عن النبي صلى الله عليه وسلم قال: \" لا ألفين أحدكم متكئا على أريكته يأتيه الأمر من أمري مما أمرت به أو نهيت عنه فيقول: لا أدري ما وجدناه في كتاب الله اتبعناه \" قال أبو جعفر: وهذا جواب جماعة من الفقهاء أن يضم الحديث إلى القرآن كما قال تعالى {قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير} [الأنعام: 145] ثم حرم رسول الله صلى الله عليه وسلم كل ذي ناب من السباع وكل ذي مخلب من الطير فكان مضموما إلى الآية، وكان أحمد رحمه الله من أكثر الناس اتباعا لهذا حتى قال: من احتجم وهو صائم فقد أفطر هو وحاجمه كما قال رسول الله صلى الله عليه وسلم","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:528","bookId":"nasikh-nahhas","type":"section","seq":528,"chapter":"ص: 48","title":"ص: 697","page":"ج1 ص693","text":"، وفي الأحاديث تأويل آخر فيه لطف ودقة وهو أن الله عز وجل إنما قال: {وأن ليس للإنسان إلا ما سعى} [النجم: 39] ولام الخفض معناها في العربية الملك والإيجاب فليس يجب للإنسان إلا ما سعى وإذا تصدق عنه غيره فليس يجب له شيء إلا أن الله تعالى يتفضل عليه بما لم يجب له كما يتفضل على الأطفال بإدخالهم الجنة بغير عمل قال أبو جعفر: فعلى هذا يصح تأويل الأحاديث\nوقد روى هشام بن عروة، عن أبيه، عن عائشة، أن، رجلا، قال: يا رسول الله: إن أمي افتلتت نفسها فماتت ولم توص أفأتصدق عنها؟ قال: «نعم» قال أبو جعفر: فيكون في هذا الحديث ما ذكرنا من التأويلات، وفيه من الغريب قوله افتلتت معناه ماتت فجأة، ومنه قول عمر رضي الله عنه كانت بيعة أبي بكر رضي الله عنه فلتة فوقى الله تعالى شرها أي فجأة وفي هذا من المعنى أن عمر تواعد من فعل مثل ذلك، وذلك أن أبا بكر رضي الله عنه كان له من الفضائل الباهرة التي لا تدفع ما يستوجب به الخلافة وأن يبايع فجأة وليس هذا لغيره، وكان له استخلاف رسول الله صلى الله عليه وسلم إياه على الصلاة قال محمد بن جرير: «استخلافه إياه على الصلاة بمعنى استخلافه إياه على إمامة المسلمين والنظر في أمورهم؛ لأنه استخلفه على الصلوات التي لا تقيمها إلا الأئمة من الجمع والأعياد فروجع في ذلك فقال يأبى الله ورسوله والمسلمون إلا أبا بكر»","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:529","bookId":"nasikh-nahhas","type":"section","seq":529,"chapter":"ص: 48","title":"ص: 698","page":"ج1 ص695","text":"وقال غير محمد بن جرير\nروى شعبة، والثوري، عن الأعمش، ومنصور، عن سالم بن أبي الجعد، عن ثوبان، أن رسول الله صلى الله عليه وسلم قال: «استقيموا ولن تحصوا واعلموا أن خير أعمالكم الصلاة ولا يحافظ على الوضوء إلا مؤمن» ، فلما استخلف رسول الله صلى الله عليه وسلم أبا بكر على خير أعمالنا كان ما دونه تابعا له","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:530","bookId":"nasikh-nahhas","type":"section","seq":530,"chapter":"ص: 48","title":"سورة الحديد والمجادلة","page":"ج1 ص698","text":"حدثنا أبو جعفر قال: حدثنا يموت، بإسناده عن ابن عباس، «أنهما نزلتا بالمدينة» قال أبو جعفر: وجدنا في سورة المجادلة موضعين فأحدهما قوله تعالى: {والذين يظاهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل أن يتماسا} [المجادلة: 3] الآية فمن العلماء من قال: هذه ناسخة لما كانوا عليه؛ لأن الظهار كان","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:531","bookId":"nasikh-nahhas","type":"section","seq":531,"chapter":"ص: 48","title":"ص: 700","page":"ج1 ص699","text":"عندهم طلاقا فنسخ ذلك وجعلت فيه الكفارة قال أبو قلابة: «كان الظهار طلاق الجاهلية فكان الرجل إذا ظاهر من امرأته لم يرجع فيها أبدا»\nقال أبو جعفر: وقرئ على أحمد بن عمرو بن عبد الخالق، عن يوسف بن موسى، قال: حدثنا عبيد الله بن موسى، قال: حدثنا أبو حمزة الثمالي وهو ثابت بن أبي صفية، عن عكرمة، عن ابن عباس، قال: \" كان الرجل في الجاهلية إذا قال لامرأته: أنت علي كظهر أمي حرمت عليه وذكر الحديث وقال فيه: فأنزل الله تعالى {قد سمع الله} [المجادلة: 1] إلى آخر الآية «والموضع الآخر قوله تعالى {يا أيها الذين آمنوا إذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة» } [المجادلة: 12] أكثر العلماء على أن هذه منسوخة\nكما حدثنا جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا أبو نعيم، قال: حدثنا موسى بن قيس، عن سلمة بن كهيل، {يا أيها الذين آمنوا إذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة} [المجادلة: 12] قال: «أول من عمل بها علي بن أبي طالب رضي الله عنه ثم نسخت»\nوقرئ على علي بن سعيد بن بشير، عن محمد بن عبد الله الموصلي، قال: حدثنا القاسم بن يزيد الجرمي، قال: حدثنا سفيان الثوري، عن عثمان بن المغيرة، عن سالم بن أبي الجعد، عن علي بن علقمة، عن علي بن أبي طالب، رضي الله عنه قال: \" لما نزلت {يا أيها الذين آمنوا إذا ناجيتم} [المجادلة: 12] الرسول فقدموا بين يدي نجواكم صدقة قلت: يا رسول الله كم؟ قال: «دينار» ، قلت: لا يطيقونه، قال: «كم» ، قلت: حبة شعير، قال: «إنك لزهيد» ، قال: فنزلت {أأشفقتم أن تقدموا بين يدي نجواكم صدقات} [المجادلة: 13] \" الآية","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:532","bookId":"nasikh-nahhas","type":"section","seq":532,"chapter":"ص: 48","title":"سورة الحشر","page":"ج1 ص701","text":"أخبرنا أبو جعفر قال: حدثنا يموت، بإسناده، عن ابن عباس، «أنها مدنية» لم نجد فيها إلا موضعا واحدا قال جل وعز {ما أفاء الله على رسوله من أهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل} [الحشر: 7] في هذه الآية ستة أقوال للعلماء منهم من قال: هي منسوخة وقال: الفيء، والغنيمة واحد وكان في بدء الإسلام تقسم الغنيمة على هذه الأصناف ولا يكون لمن قاتل عليها شيء إلا أن يكون من هذه الأصناف ثم نسخ الله تعالى ذلك في سورة الأنفال فجعل لهؤلاء الخمس، وجعل الأربعة الأخماس لمن حارب فقال جل وعز {واعلموا أنما غنمتم من شيء فأن لله خمسه} [الأنفال: 41] الآية وهذا قول قتادة رواه عنه سعيد ومنهم من قال: الفيء خلاف الغنيمة الغنيمة ما أخذ عنوة بالغلبة والحرب يكون خمسه في هذه الأصناف وأربعة أخماسه للذين قاتلوا عليه، والفيء ما صولح أهل الحرب عليه فيكون مقسوما في هذه الأربعة الأصناف ولا يخمس\n، هذا قول سفيان الثوري رواه عنه وكيع. وقال غيره من الفقهاء: الفيء أيضا غير الغنيمة وهو ما صولحوا عليه أيضا إلا أنه يخرج خمسه في هذه الأصناف وتكون أربعة أخماسه خارجة في صلاح المسلمين ومنهم من قال: هذه الآية تبيين لما قبلها من قوله عز وجل {وما أفاء الله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب} [الحشر: 6] وقال يزيد بن رومان: الفيء ما قوتل عليه وأوجف عليه بالخيل والركاب والقول السادس:\nحدثناه أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، في قول الله تعالى {ما أفاء الله على رسوله من أهل القرى} [الحشر: 7] قال: \" بلغني أنه الجزية، والخراج خراج القرى يعني: القرى التي تؤدي الخراج \" قال أبو جعفر: أما القول الأول إنها منسوخة فلا معنى له؛ لأنه ليست إحداهما تنافي الأخرى فيكون النسخ والقول الثاني: إن الفيء خلاف الغنيمة قول مستقيم صحيح وذلك أن الفيء مشتق من فاء يفيء إذا رجع، فأموال الكفار المحاربين حلال للمسلم فإذا امتنعوا ثم صالحوا رجع إلى المسلمين منهم ما صولحوا عليه وقول معمر إنها الجزية والخراج داخل في هذه الآية مما صولحوا عليه","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:533","bookId":"nasikh-nahhas","type":"section","seq":533,"chapter":"ص: 48","title":"ص: 705","page":"ج1 ص704","text":"وأما قول من قال: إن الآية الثانية مبينة للأولى فغلط؛ لأن الآية الأولى جاء التوقيف أنها نزلت في بني النضير حين جلوا عن بلادهم بغير حرب، وفيهم نزلت سورة الحشر {هو الذي أخرج الذين كفروا من أهل الكتاب من ديارهم لأول الحشر} [الحشر: 2] فجعل الله عز وجل أموالهم للنبي صلى الله عليه وسلم خاصة فلم يستأثر بها صلى الله عليه وسلم وفرقها في المهاجرين ولم يعط الأنصار منها شيئا إلا لرجلين سهل بن حنيف وأبي دجانة سماك بن خرشة، ولم يأخذ منها صلى الله عليه وسلم إلا ما يكفيه ويكفي أهله ففي هذا نزلت الآية الأولى والآية الثانية لأصناف بعينهم فقد علم أن ما كان في أصناف بعينهم خلاف ما كان للنبي صلى الله عليه وسلم وحده ويبين لك هذا الحديث حين تخاصم علي والعباس رضي الله عنهما إلى عمر رضي الله عنه في هذا بعينه\nكما قرئ على أحمد بن شعيب بن","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:534","bookId":"nasikh-nahhas","type":"section","seq":534,"chapter":"ص: 48","title":"ص: 706","page":"ج1 ص704","text":"علي، عن عمرو بن علي، قال: حدثنا بشر بن عمر، قال: حدثنا مالك بن أنس، عن الزهري، عن مالك بن أوس بن الحدثان، قال: \" أرسل إلي عمر بن الخطاب رضي الله عنه حين تعالى النهار فجئته فوجدته جالسا على سرير مفضيا إلى رمالة فقال حين دخلت عليه: يا مال: أما إنه قد دف أهل أبيات من قومك وقد أمرت برضخ فخذه فاقسمه بينهم، قلت له: لو أمرت غيري بذلك، قال: خذه فجاء يرفأ فقال: يا أمير المؤمنين هل لك في عثمان بن عفان، وعبد الرحمن بن عوف، والزبير بن العوام، وسعد بن أبي وقاص رضي الله عنهم؟ قال: نعم، فأذن لهم فدخلوا ثم جاءه فقال: يا أمير المؤمنين هل لك في العباس وعلي؟ قال: نعم فأذن لهما فدخلا، فقال العباس: يا أمير المؤمنين اقض بيني وبين هذا يعني: عليا عليه السلام فقال بعضهم أجل يا أمير المؤمنين فاقض بينهما وأرحهما، قال مالك بن أوس: خيل إلي أنهما قدما أولئك النفر لذلك، فقال عمر: أنشدكم، ثم أقبل على أولئك الرهط فقال: أنشدكم بالله الذي بإذنه تقوم السماء والأرض هل تعلمون أن رسول الله صلى الله عليه وسلم قال: «لا نورث ما تركنا صدقة» ؟ قالوا: نعم، ثم أقبل على علي والعباس فقال: أنشدكما بالله","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:535","bookId":"nasikh-nahhas","type":"section","seq":535,"chapter":"ص: 48","title":"ص: 707","page":"ج1 ص704","text":"الذي بإذنه تقوم السماء والأرض هل تعلمان أن رسول الله صلى الله عليه وسلم قال: «لا نورث ما تركنا صدقة» ؟ قالا: نعم، قال: فإن الله تعالى خص نبيه صلى الله عليه وسلم بخاصة لم يخص بها أحدا من الناس فقال {وما أفاء الله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير} [الحشر: 6] فكان الله أفاء على رسوله صلى الله عليه وسلم بني النضير فوالله ما استأثرها عليكم ولا أخذها دونكم فكان رسول الله صلى الله عليه وسلم يأخذ منها نفقة سنة ويجعل ما بقي أسوة المال، ثم أقبل على أولئك الرهط فقال: أنشدكم بالله الذي بإذنه تقوم السماء والأرض هل تعلمون ذلك؟ قالوا: نعم، ثم أقبل على علي والعباس فقال: أنشدكما بالله الذي بإذنه تقوم السماء والأرض هل تعلمان ذلك؟ قالا: نعم، فلما توفي رسول الله صلى الله عليه وسلم قال أبو بكر: أنا ولي رسول الله صلى الله عليه وسلم فجئت أنت وهذا إلى أبي بكر فجئت أنت تطلب ميراثك من ابن أخيك ويطلب هذا ميراث امرأته من أبيها فقال أبو بكر رضي الله عنه: قال رسول الله صلى الله عليه وسلم: «لا نورث ما تركنا صدقة» فوليها أبو بكر فلما توفي أبو بكر رضي الله عنه قلت: أنا ولي رسول الله وولي أبي بكر فوليتها بما شاء الله أن أليها، ثم جئت أنت وهذا وأنتما جميع وأمركما واحد فسألتمانيها فقلت: إن شئتما أن أدفعها إليكما على أن عليكما عهد الله لتليانها بالذي كان رسول الله صلى الله عليه وسلم يليها به فأخذتماها على ذلك ثم جئتماني لأقضي بينكما بغير ذلك فوالله لا أقضي بينكما بغير ذلك حتى تقوم الساعة فإن عجزتما عنها فرداها إلي \"","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:536","bookId":"nasikh-nahhas","type":"section","seq":536,"chapter":"ص: 48","title":"ص: 708","page":"ج1 ص704","text":"قال أبو جعفر: وقد تبين بهذا الحديث أن قوله تعالى {وما أفاء الله على رسوله} [الحشر: 6] الأول خلاف الثاني وأنه جعل لرسول الله صلى الله عليه وسلم خاصة وأن الثاني خلافه؛ لأنه لأجناس جماعة، وفي الحديث قوله عليه السلام: «لا نورث ما تركنا صدقة» ، فأصحاب الحديث يفرقون هذا الحديث ويجعلونه من حديث عمر، ثم يجعلونه من حديث عثمان، ومن حديث علي، ومن حديث الزبير، ومن حديث سعد، ومن حديث عبد الرحمن بن عوف، ومن حديث العباس لأنهم جميعا قد اجتمعوا عليه وفي قوله صلى الله عليه وسلم: «لا نورث» قولان أحدهما أنه يخبر عنه وحده صلى الله عليه وسلم كما يقول الرئيس: فعلنا وصنعنا، والقول الآخر أن يكون لا نورث لجميع الأنبياء عليهم السلام، وأكثر أهل العلم على هذا القول فإن أشكل على أحد قوله تعالى إخبارا {وإني خفت الموالي من ورائي} [مريم: 5] وما بعده فقد بين هذا أهل العلم فقالوا: إنما قال زكريا {وإني خفت الموالي من ورائي} [مريم: 5] ؛ لأنه خاف أن لا يكون في مواليه مطيع لله تعالى يرث النبوة من بعده والشريعة، فقال {هب لي من لدنك وليا يرثني ويرث من آل يعقوب} ثم قال: {واجعله رب رضيا} [مريم: 6] وكذلك قوله تعالى {وورث سليمان داود} فإن أشكل على أحد فقال: إن سليمان قد كان نبيا في وقت أبيه قيل له: قد كان ذلك إلا أن الشرائع كانت إلى داود عليه السلام وكان سليمان معينا له فيها، وكذا كانت سبيل الأنبياء صلوات الله عليهم إذا اجتمعوا أن تكون الشريعة إلى واحد منهم فورث سليمان ذلك","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:537","bookId":"nasikh-nahhas","type":"section","seq":537,"chapter":"ص: 48","title":"ص: 709","page":"ج1 ص704","text":"وأما قوله صلى الله عليه وسلم: «ما تركنا صدقة» ، فللعلماء فيه ثلاثة أقوال منهم من قال: هو بمنزلة الصدقة أي: لا يورث وإنما هو في مصالح المسلمين، ومنهم من قال: كان النبي صلى الله عليه وسلم قد تصدق به والقول الثالث أن تكون الرواية: «لا نورث ما تركناه صدقة» بالنصب وتكون ما بمعنى الذي وتكون في موضع نصب أيضا والمعاني في هذا متقاربة؛ لأن المقصود أنه لا يورث عليه السلام","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:538","bookId":"nasikh-nahhas","type":"section","seq":538,"chapter":"ص: 48","title":"سورة الممتحنة","page":"ج1 ص705","text":"حدثنا يموت، بإسناده عن ابن عباس،: «أنها نزلت بالمدينة» فيها أربع آيات أولاهن قوله تعالى {لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبروهم وتقسطوا إليهم إن الله يحب المقسطين} [الممتحنة: 8] للعلماء فيها أربعة أقوال منهم من قال: هي منسوخة ومنهم من قال: هي مخصوصة في الذين آمنوا ولم يهاجروا، ومنهم من قال: هي في حلفاء النبي صلى الله عليه وسلم ومن بينه وبينه عهد لم يقضه، ومنهم من قال: هي عامة محكمةفممن قال: هي منسوخة قتادة\nقال أبو جعفر: كما حدثنا أحمد بن محمد بن نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة، في قوله تعالى {لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبروهم وتقسطوا إليهم} [الممتحنة: 8] قال: \" نسخها {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5]","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:539","bookId":"nasikh-nahhas","type":"section","seq":539,"chapter":"ص: 48","title":"ص: 712","page":"ج1 ص711","text":"\" والقول الثاني قول مجاهد قال: « {والذين لم يقاتلوكم في الدين} الذين آمنوا وأقاموا بمكة ولم يهاجروا» والقول الثالث قول أبي صالح قال: «هم خزاعة» وقال الحسن: «هم خزاعة وبنو الحارث بن عبد مناف» {أن تبروهم وتقسطوا إليهم} [الممتحنة: 8] قال: توفوا لهم بالعهد الذي بينكم وبينهم والقول الرابع: إنها عامة محكمة قول حسن بين وفيه أربع حجج منها: أن ظاهر الآية يدل على العموم، ومنها: أن الأقوال الثلاثة مطعون فيها،؛ لأن قول قتادة إنها منسوخة قد رد عليه؛ لأن مثل هذا ليس بمحظور، وأن قوله تعالى {فإذا انسلخ الأشهر الحرم فاقتلوا المشركين} [التوبة: 5] ليس بعام لجميع المشركين ولا هو على ظاهره فيكون كما قال قتادة وإنما هو مثل قوله تعالى {والسارق والسارقة فاقطعوا أيديهما} [المائدة: 38] ثم ثبت عن النبي صلى الله عليه وسلم القطع في ربع دينار فصاعدا فصارت الآية لبعض السراق؛ لأن النبي صلى الله عليه وسلم المبين عن الله جل ثناؤه فكذا {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] قد خرج أهل الكتاب إن أدوا الجزية، وخرج منه الرسول بسنة النبي صلى الله عليه وسلم كما قال أبو وائل، عن عبد الله بن مسعود: كنت عند رسول الله صلى الله عليه وسلم حتى وافاه رسولان من مسيلمة فقال لهما: «أتشهدان أني رسول الله؟» فقالا","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:540","bookId":"nasikh-nahhas","type":"section","seq":540,"chapter":"ص: 48","title":"ص: 713","page":"ج1 ص711","text":": أتشهد أنت أن مسيلمة رسول الله؟ فقال: «آمنت بالله وبرسوله لولا أن الرسول لا يقتل لقتلتكما» ونهى رسول الله صلى الله عليه وسلم عن قتل العسيف \" فهذا كله خارج من الآية وقد علم أن المعنى {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5] على ما أمرتم فلا يمتنع أن يكون ما أمرنا به من الإقساط إليهم وهو العدل فيهم، ومن برهم أي: الإحسان إليهم بوعظهم، أو غير ذلك من الإحسان ثابتا، فمن ذلك أنه قد أجمع العلماء: أن العدو إذا بعد وجب أن لا يقاتل حتى يدعى ويعرض عليه الإسلام فهذا من الإحسان إليهم والعدل فيهم وقد روي عن، عمر بن عبد العزيز رضي الله عنه، أنه كان إذا غزا قوما إلى بلاد الروم أمرهم ألا يقاتلوا حتى يدعوا من عزموا على قتاله إلى الإسلام فهذا قول مالك بن أنس في كل من عزم على قتاله وهو مروي عن حذيفة","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:541","bookId":"nasikh-nahhas","type":"section","seq":541,"chapter":"ص: 48","title":"ص: 714","page":"ج1 ص711","text":"وقول الحسن، والنخعي، وربيعة، والزهري، والليث بن سعد أنه: لا يدعى من بلغته الدعوة وهو قول الشافعي، وأحمد، وإسحاق والقول الثاني: إنها مخصوصة في المؤمنين الذين لم يهاجروا مطعون فيه؛ لأن أول السورة {يا أيها الذين آمنوا لا تتخذوا عدوي وعدوكم أولياء} [الممتحنة: 1] والكلام متصل فليس من آمن ولم يهاجر يكون عدوا لله وللمؤمنين، والقول الثالث يرد بهذا فصح القول الرابع وفيه من الحجة أيضا أن بر المؤمن من بينه وبينه نسب أو قرابة من أهل الحرب غير منهي عنه ولا محرم؛ لأنه ليس في ذلك تقوية له ولا لأهل دينه بسلاح ولا كراع ولا فيه إظهار عورة للمسلمين والحجة الرابعة: أن تفسير الآية إذا جاء عن صحابي لم يسع أحدا مخالفته ولا سيما إذا كان مع قوله توقيف بسبب نزول الآية\nقال أبو جعفر: وقد وجدنا هذا حدثنا أحمد بن محمد الأزدي، قال: حدثنا إسماعيل بن يحيى، قال: حدثنا محمد بن إدريس، عن أنس بن عياض، عن هشام بن عروة، عن أبيه، عن أسماء ابنة أبي بكر، قالت: قدمت علي","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:542","bookId":"nasikh-nahhas","type":"section","seq":542,"chapter":"ص: 48","title":"ص: 715","page":"ج1 ص711","text":"أمي وهي مشركة في عهد قريش إذ عاهدوا رسول الله صلى الله عليه وسلم، فاستفتيت رسول الله صلى الله عليه وسلم فقلت: يا رسول الله إن أمي قدمت علي وهي مشركة أفأصلها؟ قال: «نعم صلي أمك»\nحدثنا أحمد بن محمد، قال: حدثنا محمد بن عبد الله الأصبهاني، قال: حدثنا إبراهيم بن الحجاج، قال: حدثني عبد الله بن المبارك، عن مصعب بن ثابت بن عبد الله بن الزبير، عن عامر بن عبد الله بن الزبير، عن أبيه، قال: \" قدمت قتيلة ابنة العزى بن أسعد على ابنتها أسماء ابنة أبي بكر بهدايا: سمن وتمر وقرظ، فأبت أن تقبلها ولم تدخلها منزلها فسألت لها عائشة عن ذلك فنزلت {لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبروهم} [الممتحنة: 8] \" قال أبو جعفر: فقد بان ما قلنا بهذين الحديثين وبما ذكرناه من الحجج","bab":"باب ذكر الموضع الثاني قال الله جل وعز: {فلا تهنوا وتدعوا إلى السلم وأنتم الأعلون} [محمد: 35] قال أبو جعفر: من قال: هذه ناسخة لقوله عز وجل {وإن جنحوا للسلم فاجنح"},{"id":"nasikh-nahhas:543","bookId":"nasikh-nahhas","type":"section","seq":543,"chapter":"ص: 48","title":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموه","page":"ج1 ص715","text":"عليه قريشا: أنه إذا جاءه أحد منهم مسلما رده إليهم، فنقض الله تعالى هذا في النساء ونسخه وأمر المؤمنين إذا جاءتهم امرأة مسلمة مهاجرة امتحنوها فإن كانت مؤمنة على الحقيقة لم يردوها إليهم، واحتج من قال هذا: بأن القرآن ينسخ السنة ومنهم من قال: وهذا كله منسوخ في الرجال والنساء ولا يجوز للإمام أن يهادن الكفار على أنه من جاء منهم مسلما رده إليهم؛ لأنه لا يجوز عند أحد من العلماء أن يقيم مسلم بأرض الشرك تجري عليه أحكام أهل الشرك واختلفوا في التجارة إلى أرض الشرك قال أبو جعفر: وسنذكر ذلك بعد ذكر الحديث الذي فيه خبر صلح النبي صلى الله عليه وسلم وما في ذلك من النسخ، والأحكام والفوائد\nفمن ذلك ما قرئ على أحمد بن شعيب بن علي، عن سعيد بن عبد الرحمن، قال: حدثنا سفيان، عن الزهري قال: وثبتني معمر بعد، عن الزهري، عن عروة بن الزبير: أن مسور بن مخرمة، ومروان بن","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:544","bookId":"nasikh-nahhas","type":"section","seq":544,"chapter":"ص: 48","title":"ص: 717","page":"ج1 ص716","text":"الحكم يزيد أحدهما على صاحبه قالا: \" خرج رسول الله صلى الله عليه وسلم عام الحديبية في بضع عشرة مائة من أصحابه فلما أتى ذا الحليفة قلد الهدي وأشعره وأحرم منها ثم بعث عينا له من خزاعة وسار النبي صلى الله عليه وسلم حتى إذا كان وذكر كلمة - قال أبو جعفر: الصواب حتى إذا كان بغدير الأشطاط أتى عينه فقال: إن قريشا جمعوا لك جموعا وجمعوا لك الأحابيش وإنهم مقاتلوك وصادوك عن البيت، فقال النبي صلى الله عليه وسلم: \" أشيروا علي أترون أن نميل على ذراري هؤلاء القوم الذين أعانوا علينا فإن نجوا يكون الله تعالى والصواب: يكن قد قطع عنقا من الكفار، وإلا تركتهم محروبين موتورين \"، فقال أبو بكر: يا رسول الله إنما خرجت لهذا الوجه عامدا لهذا البيت لا تريد قتال أحد فتوجه له فمن صدنا عنه قاتلناه، فقال النبي صلى الله عليه وسلم: «امضوا على اسم الله» قال أبو جعفر: أحسب أن أبا عبد الرحمن اختصر هذا الحديث لما فيه والذي فيه يحتاج إلى تفسيره والحكمة فيه أو يكون جاء","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:545","bookId":"nasikh-nahhas","type":"section","seq":545,"chapter":"ص: 48","title":"ص: 718","page":"ج1 ص716","text":"بما يقدر أنه يحتاج إليه منه؛ لأن عبد الرزاق رواه عن معمر، عن الزهري، عن عروة، عن المسور ومروان بتمامه، فذكر نحو هذا ثم قال: فراحوا يعني: حتى إذا كانوا ببعض الطريق قال: النبي صلى الله عليه وسلم: «إن خالد بن الوليد بالغميم في خيل لقريش طليعة فخذوا ذات اليمين» ، فوالله ما شعر بهم خالد حتى إذا هو بغبرة الجيش فانطلق يركض نذيرا لقريش، ثم سار رسول الله صلى الله عليه وسلم حتى إذا كان بالثنية التي يهبط عليهم منها بركت به راحلته فقال الناس: حل حل فألحت، فقالوا: خلأت القصواء خلأت، فقال النبي صلى الله عليه وسلم: «ما خلأت القصواء وما ذلك لها بخلق، ولكن حبسها حابس الفيل» ، ثم قال: «والذي نفسي بيده لا يسألوني خطة يعظمون فيها حرمات الله إلا أعطيتهم إياها» ، ثم زجرها فوثبت به قال: فعدل عنهم حتى نزل أقصى الحديبية على ثمد قليل الماء إنما تبرضه الناس تبرضا فلم تلبثه الناس أن نزحوه فشكي إلى رسول الله صلى الله عليه وسلم العطش فانتزع سهما من كنانته ثم أمرهم أن يجعلوه فيه فوالله ما زال يجيش لهم بالري حتى صدروا عنه، فبينا هم كذلك إذا جاء بديل بن ورقاء الخزاعي في نفر من قومه","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:546","bookId":"nasikh-nahhas","type":"section","seq":546,"chapter":"ص: 48","title":"ص: 719","page":"ج1 ص716","text":"خزاعة وكان عيبة نصح رسول الله صلى الله عليه وسلم من أهل تهامة فقال: إني تركت كعب بن لؤي لإعداد مياه الحديبية معهم العود المطافيل وهم مقاتلوك وصادوك عن البيت، فقال رسول الله: «إنا لم نجئ لقتال أحد ولكنا جئنا معتمرين، وإن قريشا نهكتهم الحرب فأضرت بهم فإن شاءوا هادنتهم مدة ويخلوا بيني وبين الناس فإن أظهر فإن شاءوا أن يدخلوا فيما دخل فيه الناس فعلوا، وإلا فقد جموا وإن أبوا فوالذي نفسي بيده لأقاتلنهم على أمري هذا حتى تنفرد سالفتي أو لينفذن الله عز وجل أمره» فقال بديل: سأبلغهم ما تقول، فانطلق حتى أتى قريشا فقال: إنا قد جئناكم من عند هذا الرجل وسمعناه يقول قولا إن شئتم أن نعرضه عليكم فعلنا، فقال سفهاؤهم: لا حاجة لنا أن تحدثنا عنه بشيء، وقال ذوو الرأي منهم: هات ما سمعته يقول قال: سمعته يقول: كذا وكذا، فحدثهم بما قال رسول الله صلى الله عليه وسلم، فقال عروة بن مسعود الثقفي: أي قومي ألستم بالولد؟ قالوا: بلى، قال: ألست بالوالد؟ قالوا: بلى قال: فهل تتهموني؟ قالوا: لا، قال: ألستم تعلمون أني استنفرت أهل عكاظ عليكم جئتكم بأهلي وولدي ومن أطاعني؟ قالوا: بلى، قال: فإن هذا قد عرض عليكم خطة رشد فاقبلوها","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:547","bookId":"nasikh-nahhas","type":"section","seq":547,"chapter":"ص: 48","title":"ص: 720","page":"ج1 ص716","text":"ودعوني آته، قالوا: ائته، فأتاه فجعل يكلم النبي صلى الله عليه وسلم، فقال له النبي صلى الله عليه وسلم نحوا من قوله لبديل، فقال عروة عند ذلك: أي محمد أرأيت إن استأصلت قومك هل سمعت أن أحدا من العرب اجتاح أصله قبلك؟ وإن تكن الأخرى فوالله إني لأرى وجوها وأرى أوباشا من الناس خلقاء أن يفروا ويدعوك، فقال أبو بكر رضي الله عنه: امصص بظر اللات، أنحن نفر وندعه، فقال: من ذا؟ فقالوا: أبو بكر، فقال: أما والذي نفسي بيده لولا يد لك عندي لم أجزك بها لأجبتك، قال: وجعل يكلم النبي صلى الله عليه وسلم فكلما كلمه أخذ بلحيته والمغيرة بن شعبة قائم على رأس النبي صلى الله عليه وسلم ومعه السيف وعلى رأسه المغفر، فكلما أهوى عروة بيده إلى لحية رسول الله صلى الله عليه وسلم ضرب يده بنعل السيف وقال: أخر يدك عن لحية رسول الله صلى الله عليه وسلم فرفع عروة رأسه وقال: من هذا؟ فقالوا","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:548","bookId":"nasikh-nahhas","type":"section","seq":548,"chapter":"ص: 48","title":"ص: 721","page":"ج1 ص716","text":": المغيرة بن شعبة، فقال: أي غدر أولست أسعى في غدرتك، وكان المغيرة قد صحب قوما في الجاهلية فقتلهم وأخذ أموالهم ثم جاء فأسلم فقال النبي صلى الله عليه وسلم: «أما الإسلام فأقبل، وأما المال فلست منه في شيء» ، ثم إن عروة جعل يرمق صحابة النبي صلى الله عليه وسلم بعينيه قال: فوالله ما يتنخم رسول الله صلى الله عليه وسلم نخامة إلا وقعت في يد رجل منهم فدلك بها وجهه وجلده وإذا أمرهم ابتدروا أمره، وإذا توضأ كادوا يقتتلون على وضوئه، وإذا تكلم خفضوا أصواتهم عنده وما يحدون النظر إليه تعظيما له، قال: فرجع عروة إلى أصحابه فقال: أي قومي والله لقد وفدت على الملوك ووفدت على كسرى وقيصر والنجاشي، والله إن رأيت ملكا قط يعظمه أصحابه ما يعظم أصحاب محمد محمدا، والله إن ينتخم نخامة إلا وقعت في كف رجل منهم فدلك بها وجهه وجلده وإذا أمرهم ابتدروا أمره، وإذا توضأ كادوا يقتتلون على وضوئه، وإذا تكلم خفضوا أصواتهم عنده، وما يحدون النظر إليه تعظيما له، وإنه قد عرض عليكم خطة رشد فاقبلوها منه، فقال رجل من بني كنانة: دعوني آته فقالوا: ائته، فلما أشرف على النبي وأصحابه قال النبي صلى الله عليه وسلم: «هذا فلان من قوم يعظمون البدن فابعثوها","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:549","bookId":"nasikh-nahhas","type":"section","seq":549,"chapter":"ص: 48","title":"ص: 722","page":"ج1 ص716","text":"له» فبعثت له، واستقبله القوم يلبون فلما رأى ذلك قال: سبحان الله ما ينبغي لهؤلاء أن يصدوا عن البيت، فقال رجل منهم يقال له: مكرز بن حفص دعوني آته، قالوا: ائته، فلماأشرف عليهم قال النبي صلى الله عليه وسلم: \" هذا مكرز وهو رجل فاجر فجعل يكلم النبي صلى الله عليه وسلم، فبينا هو يكلمه إذ جاء سهيل بن عمر وفقال: هات اكتب بيننا وبينكم كتابا، فدعا الكاتب فقال رسول الله صلى الله عليه وسلم: «اكتب بسم الله الرحمن الرحيم» ، فقال سهيل: أما الرحمن فوالله ما أدري ما هو، ولكن اكتب باسمك اللهم، كما كنت تكتب، فقال المسلمون: والله ما نكتبها إلا بسم الله الرحمن الرحيم، فقال النبي صلى الله عليه وسلم: «اكتب باسمك اللهم» ، ثم قال: «هذا ما قاضى عليه محمد رسول الله صلى الله عليه وسلم» ، فقال سهيل: والله لو كنا نعلم أنك رسوله ما صددناك عن البيت ولا قاتلناك ولكن اكتب من محمد بن عبد الله، فقال: قال الزهري: وذلك قوله: لا يسألونني خطة يعظمون فيها حرمات الله عز وجل إلا أعطيتهم إياها","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:550","bookId":"nasikh-nahhas","type":"section","seq":550,"chapter":"ص: 48","title":"ص: 723","page":"ج1 ص716","text":"، فقال النبي: «أن تخلوا بيننا وبين البيت نطوف به» ، فقال سهيل بن عمر و: والله لا تتحدث العرب أنا أخذنا ضغطة ولكن لك من العام المقبل، فكتب، فقال سهيل: وعلى أنه لا يأتيك منا رجل وإن كان على دينك إلا رددته إلينا، فقال المسلمون: سبحان الله كيف يرد إلى المشركين وقد جاء مسلما، فبينا هم كذلك إذ جاء أبو جندل بن سهيل بن عمر وهو يرسف في قيوده قد خرج من أسفل مكة حتى رمى بنفسه بين أظهر المسلمين فقال سهيل: هذا يا محمد أول ما نقاضيك عليه أن ترده إلي، فقال النبي: «إنا لم نقض الكتاب بعد» ، قال: فوالله إذن لا أصالحك على شيء أبدا، قال النبي فأجزه لي \"، قال: ما أنا بمجيزه لك، قال: \" بلى فافعل، قال: ما أنا بفاعل، فقال مكرز: بلى، قد أجزناه لك، فقال أبو جندل: أي معاشر المسلمين أأرد إلى المشركين وقد جئت مسلما، ألا ترون ماذا لقيت - وكان قد عذب عذابا شديدا في الله - فقال عمر بن الخطاب رضي الله عنه: والله ما شككت منذ أسلمت إلا يومئذ فأتيت النبي صلى الله عليه وسلم فقلت: ألست نبي الله حقا؟ قال: «بلى» ، قلت: ألسنا على الحق، وعدونا على الباطل؟ قال: «بلى» ، قلت: فلم نعطي الدنية في ديننا إذن، قال: «إني رسول ولست أعصيه وهو ناصري» ، قلت: أوليس كنت قد وعدتنا أنا سنأتي البيت فنطوف به؟ قال: \" بلى، أفأخبرتك أنك تأتيه العام؟ قال: لا، قال: «فإنك تأتيه وتطوف به» ، قال: فأتيت أبا بكر فقلت: يا أبا بكر أليس هذا نبي الله حقا؟ قال: بلى، قلت: ألسنا على الحق وعدونا على الباطل؟ قال: بلى، قلت: فلم نعطي الدنية في ديننا إذن؟ قال: أيها","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:551","bookId":"nasikh-nahhas","type":"section","seq":551,"chapter":"ص: 48","title":"ص: 724","page":"ج1 ص716","text":"الرجل إنه رسول الله وليس يعصي ربه وهو ناصره فاستمسك بغرزه حتى تموت فوالله إنه لعلى الحق، قلت: أو ليس كان يحدثنا أنا سنأتي البيت ونطوف به؟، قال: بلى أفأخبرك أنك تأتيه العام؟ قال: لا، قال: فإنك آتيه وتطوف به قال الزهري: قال عمر: فعملت لذلك أعمالافلما فرغ من قضية الكتاب قال رسول الله صلى الله عليه وسلم لأصحابه: «قوموا فانحروا ثم احلقوا» ، قال: فوالله ما قام رجل منهم حتى قال ذلك ثلاث مرات، فلما لم يقم منهم أحد، قام فدخل على أم سلمة فذكر لها ما لقي من الناس، فقالت أم سلمة: يا نبي الله أتحب ذلك اخرج ثم لا تكلم أحدا منهم حتى تنحر وتحلق، فخرج فنحر بدنه ودعا حالقه فحلقه، فلما رأوا ذلك قاموا فنحروا وجعل بعضهم يحلق بعضا حتى كاد بعضهم يقتل بعضا غما ثم جاءه نسوة مؤمنات فأنزل الله عز وجل {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن} [الممتحنة: 10] حتى بلغ {بعصم الكوافر} [الممتحنة: 10] فطلق عمر يومئذ امرأتين كانا له في الشرك فتزوج إحداهما معاوية بن أبي سفيان والأخرى صفوان بن أمية","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:552","bookId":"nasikh-nahhas","type":"section","seq":552,"chapter":"ص: 48","title":"ص: 725","page":"ج1 ص716","text":"، ثم رجع النبي صلى الله عليه وسلم إلى المدينة فجاءه أبو بصير قال أبو جعفر: وعتبة بن أسد بن حارثة الثقفي رجل من قريش وهو مسلم، فأرسلوا في طلبه رجلين فقالوا: العهد الذي جعلت لنا، فدفعه النبي إلى الرجلين فخرجا به حتى بلغا ذا الحليفة فنزلوا يأكلون من تمر لهم، قال أبو بصير لأحد الرجلين: والله إني لأرى سيفك يا فلان جيدا، فاستله الآخر فقال: أجل والله إنه لجيد لقد جربت به ثم جربت، فقال أبو بصير: أرني أنظر إليه فأمكنه منه فضربه به حتى برد وفر الأخر حتى أتى المدينة فدخل المسجد يعدو، فقال النبي صلى الله عليه وسلم: «لقد رأي هذا ذعرا» ، فلما انتهى إلى النبي صلى الله عليه وسلم قال: قتل والله صاحبي وإني لمقتول، فجاء أبو بصير فقال: يا نبي الله قد والله أوفى الله ذمتك قد رددتني إليهم ثم أنجاني الله منهم فقال النبي صلى الله عليه وسلم: «ويل أمه مسعر حرب لو كان له أحد» ، فلما سمع ذلك علم أنه سيرده إليهم","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:553","bookId":"nasikh-nahhas","type":"section","seq":553,"chapter":"ص: 48","title":"ص: 726","page":"ج1 ص716","text":"، فخرج حتى أتى سيف البحر قال: وينفلت منهم أبو جندل بن سهيل قال: فلحق بأبي بصير فجعل لايخرج من قريش رجل قد أسلم إلا لحق بأبي بصير حتى اجتمعت منهم عصابة، قال: فوالله ما يسمعون بعير لقريش إلى الشام إلا اعترضوا لها فقتلوهم وأخذوا أموالهم، فأرسلت قريش إلى النبي صلى الله عليه وسلم يناشدونه بالله والرحم إلا أرسل إليهم فمن أتاه فهو آمن، فأرسل النبي صلى الله عليه وسلم إليهم فأنزل الله عز وجل {وهو الذي كف أيديهم عنكم وأيديكم عنهم ببطن مكة} [الفتح: 24] حتى بلغ {حمية الجاهلية} [الفتح: 26]","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:554","bookId":"nasikh-nahhas","type":"section","seq":554,"chapter":"ص: 48","title":"ص: 727","page":"ج1 ص716","text":"، وكانت حميتهم أنهم لم يقروا أنه نبي الله ولم يقروا ببسم الله الرحمن الرحيم والأحكام وحالوا بينه وبين البيت \" قال أبو جعفر: في هذا الحديث من الناسخ والمنسوخ والآداب والأحكام من الحج والجهاد وغيرهما ومن التفسير وغيره نيف وثلاثون موضعا نذكر منها موضعا موضعا إن شاء الله. فمن ذلك الوقوف على أن أصحاب رسول الله صلى الله عليه وسلم الذين كانوا بالحديبية بضع عشرة مائة وهم الذين أنزل الله عز وجل فيهم {لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة} [الفتح: 18] وإن البضع يقع لأربع قال جابر بن عبد الله: كنا ألفا وأربعمائة وإن المائة تعد عدد الواحدة وفيه أن رسول الله صلى الله عليه وسلم سن لمن أراد العمرة من المدينة وأهل من ذي الحليفة سنة ست ثم أقام الأمر على ذلك\nكما روى مالك، عن نافع، عن ابن عمر، أن النبي صلى الله عليه وسلم قال: «يهل أهل المدينة من ذي الحليفة، وأهل الشام من الجحفة» وذكر الحديث وفيه أن الإحرام من الميقات أفضل من الإحرام من بلد الرجل؛ لأن رسول الله صلى الله عليه وسلم منه أحرم بعمرة في هذا الوقت","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:555","bookId":"nasikh-nahhas","type":"section","seq":555,"chapter":"ص: 48","title":"ص: 728","page":"ج1 ص716","text":"، ومنه أيضا أنه ليس معنى قول الله تعالى {وأتموا الحج والعمرة لله} [البقرة: 196] أن يحرم الإنسان من دويرة أهله ولو كان كذا لكان رسول الله صلى الله عليه وسلم أولى الناس بالعمل به فإن قيل فقد قال علي بن أبي طالب رضي الله عنه: «إتمام العمرة أن تحرم من دويرة أهلك» قيل: هذا يتأول على أنه خاص لمن كان بين الميقات ومكة كما روي عن، ابن عباس، عن النبي صلى الله عليه وسلم: «من كان أهله دون الميقات فمهله من حيث كان أهله» كما يهل أهل مكة من مكة وفيه أن رسول الله صلى الله عليه وسلم أشعر البدن فكانت هذه سنة على خلاف ما يقول الكوفيون: أنه لا يجوز إشعار البدن\nوقرئ على أحمد بن شعيب، عن العباس بن عبد العظيم، قال: حدثنا عثمان بن عمر، قال: حدثنا مالك بن أنس، عن عبد الله بن أبي بكر، عن عروة، عن عائشة، رضي الله عنها قالت: قلد رسول الله صلى الله عليه وسلم هديه بيديه وأشعره ثم لم يحرم شيئا كان الله تعالى أحله له وبعث","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:556","bookId":"nasikh-nahhas","type":"section","seq":556,"chapter":"ص: 48","title":"ص: 729","page":"ج1 ص727","text":"بالهدي مع أبي \" قال أبو جعفر: فدل هذا الحديث على خلاف ما يقول الكوفيون لأنهم زعموا: أن الإشعار منسوخ بنهي النبي صلى الله عليه وسلم عن المثلة، ونهي النبي صلى الله عليه وسلم عن المثلة إنما كان في وقعة أحد وقيل في وقعة خيبر، وحج أبو بكر رضي الله عنه بالناس بعد ذلك فكان الإشعار بعد، ومحال أن ينسخ الأول الآخر وقد كان الإشعار أيضا في حجة الوداع وفيه أيضا سنة التقليد وفيه أن الإشعار والتقليد قبل الإحرام وفيه السنة في التوجيه بعين إلى العدو وفيه التوجيه برجل واحد فدل هذا على أنه يجوز للرجل أن يسافر وحده في حال الضرورة، وفيه أنه يجوز للواحد في حال الضرورة أن يهجم على الجماعة كما قال النبي صلى الله عليه وسلم يوم الأحزاب: «من يعرف لنا خبر القوم» ؟ فقال الزبير: أنا، فقال النبي صلى الله عليه وسلم: «لكل نبي حواري وحواريي الزبير» وفيه: الدليل على صحة خبر الواحد ولولا أنه مقبول ما وجه النبي صلى الله عليه وسلم بواحد ليخبره بخبر القوم وفيه: مشاورة النبي صلى الله عليه وسلم أصحابه، فقال الحسن: فعل ذلك لتستن به أمته، وما شاور قوم إلا هدوا لأرشد الأمور وقال سفيان الثوري: بلغني أن المشورة نصف العقل\nوحدثني أحمد بن عاصم، قال: حدثنا عبد الله بن سعيد بن الحكم بن محمد","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:557","bookId":"nasikh-nahhas","type":"section","seq":557,"chapter":"ص: 48","title":"ص: 730","page":"ج1 ص728","text":"، قال حدثني أبي، قال: حدثنا ابن عيينة، عن عمرو بن دينار، عن ابن عباس، في قول الله تعالى {وشاورهم في الأمر} [آل عمران: 159] قال: «أبو بكر وعمر رضي الله عنهما» وفيه: مشورة أم سلمة على النبي صلى الله عليه وسلم أن يخرج إلى الناس فينحر ويحلق، لأنها رأت أنهم لا يخالفون فعله، فدل هذا على أن الحديث في أمر النساء ليس في المشورة وإنما هو في الولاية وفيه: السنة على أن النحر قبل الحلق لقول النبي صلى الله عليه وسلم: «انحروا، ثم احلقوا» وفيه: أن من قلد وأشعر فلم يحرم على خلاف ما يقول بعض الفقهاء وفيه: إباحة سبي ذراري المشركين إذا خرج المشركون فأعانوا مشركين","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:558","bookId":"nasikh-nahhas","type":"section","seq":558,"chapter":"ص: 48","title":"ص: 731","page":"ج1 ص728","text":"آخرين، لقول النبي: «أترون أن نميل على ذراري هؤلاء الذين أعانوهم فنصيبهم» وفيه: إجازة قتال المحرم من صده عن البيت ومنعه من نسكه لقول النبي صلى الله عليه وسلم: «أو ترون أن نؤم البيت فمن صدنا عنه قاتلناه» وفيه: قول النبي عليه السلام: «والذي نفسي بيده لا يسألونني خطة يعظمون بها حرمات الله إلا أعطيتهم إياها» ، ولم يقل إن شاء الله قال أبو جعفر: ففي هذا أجوبة منها: أن يكون هذا شيئا قد علم أنه كذا فلا يحتاج أن يستثني فيه؛ لأن الإنسان إنما أمر بالاستثناء فيما يخاف أن يمنع منه، فيجوز أن يكون الاستثناء حذفا لعلم السامع، أو لم يكن يذكره المحدث، أو جرى على وجه النسيان. وفيه: إعطاء النبي صلى الله عليه وسلم السهم لأصحابه حتى جعلوه في الماء فكان ذلك من علامات نبوته صلى الله عليه وسلم وازديادهم بصيرة وفيه: إجازة مهادنة المشركين بلا مال يؤخذ منهم إذا كان ثم ضعف وفيه: أن محمد بن إسحاق قال: «هادنهم عشر سنين» ، فعمل بذلك جماعة من الفقهاء، وقالوا: لا تجوز المهادنة أكثر من عشر سنين إذا كان ثم خوف ومنهم من قال: ذلك إلى الإمام يفعل ما فيه صلاح المسلمين","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:559","bookId":"nasikh-nahhas","type":"section","seq":559,"chapter":"ص: 48","title":"ص: 732","page":"ج1 ص728","text":"وفيه: إجازة مهادنة المشركين على ما فيه ضعف على المسلمين مما ليس فيه معصية لله عز وجل إذا احتيج إلى ذلك،؛ لأن النبي صلى الله عليه وسلم لما كتب علي بن أبي طالب رضي الله عنه: بسم الله الرحمن الرحيم امتنعوا من ذلك وأبوا أن يكتبوا إلا: باسمك اللهم فأجابهم إلى ذلك؛ لأن هذا كله لله عز وجل، وكذا لما قالوا: لا تكتب إلا ما قاضى عليه محمد بن عبد الله فأجابهم إلى ذلك رسول الله صلى الله عليه وسلم وهو محمد بن عبد الله وفيه: من المشكل أنه قاضاهم على أنه: من جاءه منهم مسلما رده إليهم حتى نفر جماعة من الصحابة من هذا منهم عمر بن الخطاب رضي الله عنه حتى ثبته أبو بكر رضي الله عنهما، وتكلم العلماء في هذا الفعل فمنهم من قال: فعل النبي صلى الله عليه وسلم هذا لقلة أصحابه وكثرة المشركين وأنه أراد أن يشتغل بغير قريش حتى يفرغ لهم، وأن يقوي أصحابه ومن أصح ما قيل فيه: وهو مذهب محمد بن إسحاق أنه كثر الإسلام بعد ذلك حتى إنه كان لا يخاطب أحدا يعقل الإسلام إلا أسلم فمعنى هذا أن الله عز وجل علم أن منهم من سيسلم وأن في هذا الصلاح، ولم يكن في رده من أسلم إليهم إلا أحدأمرين: إما أن يفتن فيقول بلسانه ما ليس بقلبه فالوزر ساقط عنه، وإما أن يعذب في الله فيثاب، على أنهم إنما كانوا بحي أهاليهم وأقربائهم فهم مشفقون عليهم، والدليل على أن الله عز وجل علم أن في ذلك الصلاح إحمادهم العاقبة بأن سأل الكفار المسلمين أن يحوزوا إليهم كل من أسلموا","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:560","bookId":"nasikh-nahhas","type":"section","seq":560,"chapter":"ص: 48","title":"ص: 733","page":"ج1 ص728","text":"فيه قوله صلى الله عليه وسلم: \" إني رسول الله لا أعصيه فدل على أن هذا كان عن أمر الله عز وجل وفيه تبيين فضل أبي بكر رضي الله عنه وأنه أعلم الناس بعد رسول الله صلى الله عليه وسلم بأحكام الله عز وجل وشرائع نبيه صلى الله عليه وسلم؛ لأنه أجاب عمر بمثل جواب رسول الله صلى الله عليه وسلم وثبته وإنما كان ذلك من عمر كراهة لإعطاء الدنية في الإسلام وفيه: هذا ما قاضى عليه محمد بن عبد الله، وكان في هذا الرد على من زعم من الفقهاء أنه لا يجوز أن يكتب: هذا ما شهد عليه الشهود، قال:؛ لأن هذا يكون نفيا قال أبو جعفر: هذا إغفال، قال الله عز وجل {هذا ما توعدون ليوم الحساب} [ص: 53] وفيه: إجازة صلح الإمام لواحد من المشركين عن جميعهم،؛ لأن سهيل بن عمر وهو الذي صالح، وفيه: استحباب الفأل لقول رسول الله صلى الله عليه وسلم لما جاء سهيل: «قد سهل لكم من أمركم» وفيه: إجازة قيام الناس على رأس الإمام بالسيوف إذا كان ذلك ترهيبا للعدو ومخافة للغدر،؛ لأن في الحديث أن المغيرة بن شعبة كان قائما على رأس النبي صلى الله عليه وسلم متقلدا سيفه فكلما أهوى عروة بيده إلى لحية النبي صلى الله عليه وسلم ضربه المغيرة بنعل - سيفه، وقال له أخر عن لحية رسول الله صلى الله عليه وسلم فنزع يده","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:561","bookId":"nasikh-nahhas","type":"section","seq":561,"chapter":"ص: 48","title":"ص: 734","page":"ج1 ص728","text":"وفيه: خبر المغيرة أنه لما خرج مع قوم من المشركين فقتلهم وأخذ مالهم، ثم جاء إلى النبي صلى الله عليه وسلم مسلما فقال له النبي صلى الله عليه وسلم: أما إسلامك فأقبله، وأما المال فلست منه في شيء \"،؛ لأن المشركين وإن كانت أموالهم مغنومة عند القهر فلا يحل أخذها عند الأمن، وإذا كان الإنسان مصاحبا لهم فقد أمن كل واحد منهم صاحبه، فسفك الدماء وأخذ المال عند ذلك غدر، والغدر محظور، وأموال الأبرار والفجار لهم يستوون في ذلك لا يؤخذ منها شيء إلا بالحق وفيه: طهارة النخامة؛ لأن أصحاب رسول الله صلى الله عليه وسلم كان إذا تنخم: منهم من يأخذ النخامة فيحك بها جلده، على خلاف ما قال إبراهيم النخعي: أن النخامة إذا سقطت في ماء اهريق. وفيه: من قول النبي صلى الله عليه وسلم: «فإنك تأتيه» ، فدل هذا على أنه: من حلف على فعل ولم يوجب وقتا أن وقته أيام حياته وفيه: أن من أحرم بحج أو عمرة فحصره عدو حل من إحرامه ونحر هديه مكانه،؛ لأن النبي صلى الله عليه وسلم كذا فعل لما حصر يوم الحديبية حل، ونحر في الحل وأمر أصحابه بذلك وفيه: أن أبا بصير لما سلمه النبي صلى الله عليه وسلم إلى الرجلين فقتل أحدهما وهو ممن دخل في الصلح فلم يطالبه النبي صلى الله عليه وسلم به لما لم يطالب به أولياؤه، فكان الحكم فكذا في نظير هذا وفيه: أنه وقع الصلح على أن يرد إليهم من جاء منهم فلما اعتزل","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:562","bookId":"nasikh-nahhas","type":"section","seq":562,"chapter":"ص: 48","title":"ص: 735","page":"ج1 ص728","text":"أبو بصير بسيف البحر واجتمع إليه كل من أسلم لم يأمر بردهم فدل هذا على أنه ليس على الإمام إن صالح على مثل هذا في قول من يقول: ليس بمنسوخ فليس عليه أن يرد من لم يكن عنده وفيه: ولا يأتيك منا رجل وإن كان على دينك إلا رددته إلينا وكان هذا ليس فيه ذكر النساء فلا نسخ على هذه الرواية وفي رواية عقيل: ولا يأتيك منا أحد وإن كان على دينك إلا رددته إلينا، وأحد محيط بالرجال والنساء، ثم أنزل الله عز وجل نسخ هذا في النساء وكان فيه دليل أنه من شرط شرطا ليس في كتاب الله عز وجل فهو باطل كما روي عن النبي صلى الله عليه وسلم: «كل شرط ليس في كتاب الله عز وجل فهو باطل» وفيه: أن المسلمين لما اجتمعوا بسيف البحر وضيقوا على قريش سألوا النبي صلى الله عليه وسلم أن يضمهم إليه فأنزل الله عز وجل {وهو الذي كف أيديهم عنكم وأيديكم عنهم ببطن مكة من بعد أن أظفركم عليهم} [الفتح: 24] وقد روي في نزول هذه الآية غير هذا\nكما حدثنا أحمد بن محمد الأزدي، قال: حدثنا محمد بن بحر بن مطر، قال: حدثنا يزيد بن هارون، قال: أخبرنا حماد بن سلمة، عن ثابت البناني، عن أنس بن مالك،: \" أن ثمانين رجلا من أهل مكة هبطوا على رسول الله صلى الله عليه وسلم","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:563","bookId":"nasikh-nahhas","type":"section","seq":563,"chapter":"ص: 48","title":"ص: 736","page":"ج1 ص729","text":"وأصحابه من التنعيم عند صلاة الفجر ليقتلوهم فأخذهم رسول الله صلى الله عليه وسلم فأعتقهم فأنزل الله عز وجل {وهو الذي كف أيديهم عنكم وأيديكم عنهم ببطن مكة من بعد أن أظفركم عليهم} [الفتح: 24] \" قال أبو جعفر: وهذا إسناد مستقيم وهو أولى من الأول من غير جهة وذلك أن في هذا الحديث: هبطوا من التنعيم والتنعيم من بطن مكة، وأبو بصير كان بسيف البحر، وسيف البحر ليس من بطن مكة، وأيضا فإن في هذا الحديث الظفر بهم، وليس في ذلك ظفر وفي الحديث الأول ما دل على أنه من جالس إماما أو عالما فرأى إنسانا قد ألحقه مكروها فينبغي له أن يغيره ويصون الإمام أو العالم عن الكلام فيه؛ لأن عروة بن مسعود لما أخذ بلحية النبي صلى الله عليه وسلم ضرب المغيرة بن شعبة يده بنعل السيف وقال: أخر يدك عن لحية رسول الله صلى الله عليه وسلم وفيه: استعمال الحلم من أدب رسول الله صلى الله عليه وسلم كما أمره الله جل وعز في كتابه فقال جل ثناؤه {ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم} [فصلت: 34] ، {وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم} [فصلت: 35] قال أبو جعفر: ومن حسن ما قيل في هذه الآية ما قاله ابن عباس رضي الله عنهما\nكما حدثنا بكر بن سهل، قال: حدثنا عبد الله بن صالح، قال: حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس رضي الله عنه، {ادفع بالتي هي أحسن} [فصلت: 34] قال: \" أمر الله عز وجل المؤمنين بالصبر عند الجزع، والحلم عند الجهل، والعفو عند الإساءة، فإذا فعلوا ذلك عصمهم الله من الشيطان وخضع لهم عدوهم {كأنه ولي} [فصلت: 35] حميم وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:564","bookId":"nasikh-nahhas","type":"section","seq":564,"chapter":"ص: 48","title":"ص: 737","page":"ج1 ص735","text":"قال: الذين أعد الله لهم الجنة \" وفي الآية التي قصدت لذكرها {وآتوهم ما أنفقوا} [الممتحنة: 10] فللشافعي فيها قولان أحدهما أن هذا منسوخ، قال: الشافعي رحمه الله وإذا جاءتنا المرأة الحرة من أهل الهدنة مسلمة مهاجرة من أهل الحرب إلى الإمام في دار الإسلام أو دار الحرب فمن طلبها من ولي سوى زوجها منع منها بلا عوض، وإذا طلبها زوجها لنفسه أو غيره بوكالته ففيه قولان أحدهما يعطى العوض، والقول ما قال الله عز وجل، وفيه قول آخر وهو ألا يعطى الزوج المشرك الذي جاءت زوجته مسلمة العوض وإن شرط الإمام رد النساء كان الشرط منتقضا، ومن قال هذا قال: إن شرط رسول الله صلى الله عليه وسلم لأهل الحديبية إذا فيه: أن يرد من جاء منهم، وكان النساء منهم كان شرطا صحيحا ففسخه الله جل وعز ورد العوض من فسخ من فسخه منهم، فلما قضى الله جل وعز ثم رسوله صلى الله عليه وسلم أن لا يرد النساء كان شرط من شرط رد النساء مفسوخا وليس عليه عوض؛ لأن الشرط المفسوخ باطل ولا عوض للباطل قال أبو جعفر: وهذا القول عنده أشبه القولين ألا يعطى عوضا وقد تكلم على أن النبي صلى الله عليه وسلم صالحهم على رد النساء، ثم إن الله جل وعز نسخ ذلك فكان في هذا نسخ السنة بالقرآن ومذهبه غير هذا؛ لأن مذهبه أن لا ينسخ القرآن إلا قرآن ولا ينسخ السنة إلا سنة، فقال بعض أصحابه: لما أنزل الله عز وجل الآية لم يرد النبي صلى الله عليه وسلم النساء فنسخت السنة السنة","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:565","bookId":"nasikh-nahhas","type":"section","seq":565,"chapter":"ص: 48","title":"ص: 738","page":"ج1 ص735","text":"وثبت أنه لا يجوز أن يشترط الإمام رد النساء بحكم الله عز وجل ثم بحكم رسول الله صلى الله عليه وسلم واختلف العلماء في صلح الإمام للمشركين على أن يرد إليهم من جاء منهم مسلما، فقال قوم: لا يجوز هذا وهو منسوخ\nواحتجوا بحديث إسماعيل بن أبي خالد، عن قيس بن أبي حازم، عن خالد بن الوليد، أن رسول الله صلى الله عليه وسلم بعثه إلى قوم من خثعم فاعتصموا بالسجود فقتلهم فوداهم رسول الله صلى الله عليه وسلم بنصف الدية وقال: «أنا بريء من كل مسلم أقام مع مشرك في دار الحرب لا تراءى نارهما» قالوا: فهذا ناسخ لرد المسلمين إلى المشركين إذ كان رسول الله صلى الله عليه وسلم قد برئ ممن أقام معهم في دار الحرب","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:566","bookId":"nasikh-nahhas","type":"section","seq":566,"chapter":"ص: 48","title":"ص: 739","page":"ج1 ص736","text":"قال أبو جعفر: وهذا قول الكوفيين ومذهب مالك، والشافعي رحمهما الله أن هذا الحكم غير منسوخ قال الشافعي: وليس لأحد أن يعقد هذا العقد إلا الخليفة أو رجل بأمره؛ لأنه يلي الأموال كلها فمن عقد غير الخليفة هذا العقد فهو مردود قال أبو جعفر: وفي هذه الآية {ولا تمسكوا بعصم الكوافر} [الممتحنة: 10] ففي هذا قولان أحدهما: أنه منسوخ منه كما قال الله عز وجل {والمحصنات من الذين أوتوا الكتاب من قبلكم} [المائدة: 5] ولو كان إلى ظاهر الآية لم تحل كافرة بوجه وقال قوم: هي محكمة إلا أنها مخصوصة لمن كان من غير أهل الكتاب فإذا أسلم وثني أو مجوسي ولم تسلم امرأته فرق بينهما، وهذا قول بعض أهل العلم، ومنهم من قال: ينتظر بها تمام العدة فممن قال: يفرق بينهما ولا ينتظر تمام العدة مالك بن أنس، وهو قول الحسن، وطاوس، ومجاهد، وعطاء، وعكرمة، وقتادة، والحكم وقال الزهري: ينتظر بها العدة، وهو قول الشافعي، وأحمد رحمهما الله وقال أصحاب الرأي: ينتظر بها ثلاث حيض إذا كانا جميعا في دار الحرب أو في دار الإسلام، فإن كان أحدهما في دار الحرب والآخر في","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:567","bookId":"nasikh-nahhas","type":"section","seq":567,"chapter":"ص: 48","title":"ص: 740","page":"ج1 ص736","text":"دار الإسلام انقطعت العصمة بينهما قال أبو جعفر: وهذا الاختلاف في المدخول بها، فإن كانت غير مدخول بها فلا نعلم اختلافا في انقطاع العصمة بينهما، وكذا يقول مالك في المرأة ترتد وزوجها مسلم: انقطعت العصمة بينهما وحجته {ولا تمسكوا بعصم الكوافر} [الممتحنة: 10] وهو قول الحسن البصري والحسن بن صالح، ومذهب الشافعي وأحمد: أنه ينتظر بها تمام العدة فإن كان الزوجان نصرانيين فأسلمت الزوجة ففيه أيضا اختلاف، فمذهب مالك والشافعي وأحمد وهو قول مجاهد: الوقوف إلى تمام العدة ومن العلماء من قال: انفسخ النكاح بينهما، قال يزيد بن علقمة: أسلم جدي ولم تسلم جدتي ففرق بينهما عمر رضي الله عنه، وهو قول طاوس وجماعة غيره، منهم عطاء، والحسن، وعكرمة، وقالوا: لا سبيل عليها إلا بخطبة، واحتج بعضهم بقوله جل وعز {ولا تمسكوا بعصم الكوافر} [الممتحنة: 10] وهذا الاحتجاج غلط لأن الكوافر لا يكون إلا للنساء ولا يجمع كافر على كوافر. الحجة فيه {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221] ومن العلماء من قال: يستتاب فإن تاب وإلا وقعت الفرقة","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:568","bookId":"nasikh-nahhas","type":"section","seq":568,"chapter":"ص: 48","title":"ص: 741","page":"ج1 ص736","text":"ومنهم من قال: «لا يزول النكاح إذا كانا في دار الهجرة» وهذا قول النخعي ومنهم من قال: يزول النكاح باختلاف الدارين ومنهم من قال: تخير فإن شاءت أقامت معه، وإن شاءت فارقته. فإن أسلم الزوج فهي زوجته بحالها لأنها كتابية، فإن أسلما جميعا فهما على نكاحهما لا اختلاف في ذلك","bab":"باب ذكر الآية الثانية من هذه السورة قال الله جل وعز {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن الله أعلم بإيمانهن فإن علمتموهن مؤمنات فلا ترجعوهن"},{"id":"nasikh-nahhas:569","bookId":"nasikh-nahhas","type":"section","seq":569,"chapter":"ص: 48","title":"باب ذكر الآية الثالثة قال الله عز وجل {وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا} [الممتحنة: 11] أك","page":"ج1 ص738","text":"وقال الزهري: «انقطع هذا يوم الفتح» وقال سفيان الثوري: «لا يعمل به اليوم» وقال مجاهد: \" {وإن فاتكم شيء من أزواجكم إلى الكفار} [الممتحنة: 11] الذين بينكم وبينهم عهد أو ليس بينكم وبينهم عهد {فعاقبتم} [الممتحنة: 11] أي: فاقتصصتم {فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا} [الممتحنة: 11] أي: الصدقات \"، فصار قول مجاهد: أنها في جميع الكفار، وقول قتادة: أنها فيمن لم يكن له عهد وقول ثالث: أنها نزلت في قريش حين كان بينهم وبين النبي صلى الله عليه وسلم عهد\nكما روى الزهري، عن عروة، عن عائشة، قالت: \" حكم الله جل وعز بينهم فقال: عز وجل {واسألوا ما أنفقتم وليسألوا ما أنفقوا} [الممتحنة: 10] فكتب إليهم المسلمون: قد حكم الله بأنه إن جاءتكم امرأة منا أن توجهوا إلينا بصداقها، وإن جاءتنا امرأة منكم وجهنا إليكم بصداقها. فكتبوا إليهم: أما نحن فلا نعلم لكم عندنا شيئا، فإن كان لنا عندكم شيء فوجهوا به، فأنزل الله تعالى {وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا} [الممتحنة: 11] \"","bab":"باب ذكر الآية الثالثة قال الله عز وجل {وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا} [الممتحنة: 11] أكثر العلماء على أنها "},{"id":"nasikh-nahhas:570","bookId":"nasikh-nahhas","type":"section","seq":570,"chapter":"ص: 48","title":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء","page":"ج1 ص743","text":"وبين النسخ فقال: هذا هو إطلاق الترك من غير أن ينسخ بآية، واحتج بقوله تعالى {ما ننسخ من آية أو ننسها} [البقرة: 106] قال: ننسها نطلق لكم تركها قال أبو جعفر: هذا قول حسن وأصله عن ابن عباس وهو الذي فرق بين ننسخ وننسي وقال بعض أهل النظر: الآية محكمة، فإذا تباعدت الدار واحتيج إلى المحنة كان على إمام المؤمنين إقامة المحنة","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:571","bookId":"nasikh-nahhas","type":"section","seq":571,"chapter":"ص: 48","title":"سورة الصف، والجمعة، والمنافقين، والتغابن، والطلاق، والتحريم","page":"ج1 ص744","text":"قال أبو جعفر: قرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثنا أحمد بن بشير، عن سعيد، عن قتادة،: «أن هذه السور، مدنيات نزلن بالمدينة»\nوحدثنا يموت، بإسناده عن ابن عباس،: \" أن سورة الصف، نزلت بمكة، وأن سورة الجمعة والمنافقين نزلتا بالمدينة، وأن سورة التغابن نزلت بمكة إلا آيات من آخرها نزلن بالمدينة في عوف بن مالك الأشجعي شكا إلى","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:572","bookId":"nasikh-nahhas","type":"section","seq":572,"chapter":"ص: 48","title":"ص: 746","page":"ج1 ص745","text":"النبي صلى الله عليه وسلم جفاء أهله وولده فأنزل الله تعالى {يا أيها الذين آمنوا إن من أزواجكم وأولادكم عدوا لكم فاحذروهم} [التغابن: 14] إلى آخر السورة، وأن سورة الطلاق، والتحريم، مدنيتان \" قال أبو جعفر: والقول الأول يروى عن مجاهد، وعن كريب، عن ابن عباس في هذه السور قوله تعالى {فاتقوا الله ما استطعتم} [التغابن: 16] قد ذكرناه في سورة آل عمران، وذكرنا قول من قال: إنه ناسخ لقوله تعالى {يا أيها الذين آمنوا اتقوا الله حق تقاته} [آل عمران: 102] وفيهن {وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق: 4] قال أبو جعفر: قد ذكرناه في سورة البقرة، وقول من قال: هو ناسخ لحكم المتوفى عنها زوجها وهي حامل، فأما المطلقة فلا اختلاف في حكمها: أنها إذ ولدت فقد انقضت عدتها، وإنما الاختلاف في المتوفى عنها زوجها وهي حامل فمن الصحابة من يقول: عدتها آخر الأجلين، فمنهم علي بن أبي طالب وابن عباس، ومنهم من قال: إذا ولدت فقد انقضت عدتها منهم","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:573","bookId":"nasikh-nahhas","type":"section","seq":573,"chapter":"ص: 48","title":"ص: 747","page":"ج1 ص745","text":"عبد الله بن مسعود قال: نزلت هذه بعد تلك قال أبو جعفر: وظاهر القرآن يدل على ما قال ابن مسعود، قال جل وعز {وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق: 4] ولم يفرق بين المطلقة والمتوفى عنها زوجها، وكذا السنة","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:574","bookId":"nasikh-nahhas","type":"section","seq":574,"chapter":"ص: 48","title":"سورة الملك، ونون، والحاقة، وسأل سائل، ونوح، والجن","page":"ج1 ص745","text":"قال أبو جعفر: حدثنا يموت، بإسناده عن ابن عباس،: «أنهن نزلن بمكة فهن مكيات» فيهن قوله تعالى {فاصبر صبرا جميلا} [المعارج: 5] مذهب ابن زيد: أن هذا منسوخ، وأنه كان قبل الأمر بالقتال، فلما أمر بالقتال أمر بالغلظة والشدة على الكفار والمنافقين ورد عليه هذا بعض أهل العلم قال: لأن النبي صلى الله عليه وسلم لم يزل صابرا عليهم","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:575","bookId":"nasikh-nahhas","type":"section","seq":575,"chapter":"ص: 48","title":"ص: 750","page":"ج1 ص749","text":"صبرا جميلا، ولم يكن في وقت خلاف وقت فيكون كما قال ابن زيد وفيهن {والذين في أموالهم حق معلوم للسائل والمحروم} [المعارج: 25] قال أبو جعفر: وقد ذكرنا هذا في سورة والذاريات بما لا يحتاج معه إلى زيادة","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:576","bookId":"nasikh-nahhas","type":"section","seq":576,"chapter":"ص: 48","title":"سورة المزمل","page":"ج1 ص749","text":"حدثنا يموت، بإسناده عن ابن عباس،: \" أنها نزلت بمكة فهي مكية إلا آيتين منها فإنهما نزلتا بالمدينة وهما قوله تعالى {إن ربك يعلم أنك تقوم أدنى من ثلثي الليل} [المزمل: 20] إلى آخرها \" فيها موضعان قال الله تعالى {يا أيها المزمل قم الليل إلا قليلا} [المزمل: 2] الآية، فجاز أن يكون هذا ندبا وحضا، وأن يكون حتما وفرضا، غير أن بابه أن يكون حتما وفرضا إلا أن يدل دليل على غير ذلك والدلائل تقوي أنه كان حتما وفرضا وذلك أن الندب والحض لا يقع على بعض الليل دون بعض لأن قيامه ليس مخصوصا به وقت دون وقت، وأيضا فقد جاء التوقيف بما سنذكره - إن شاء الله - وجاز أن يكون هذا حتما وفرضا على النبي صلى الله عليه وسلم وحده، وجاز أن يكون عليه وعلى أمته فجاء التوقيف: بأنه كان عليه وعلى المؤمنين ثم نسخ\nكما قرئ على أحمد بن شعيب، عن إسماعيل بن مسعود، قال: حدثنا خالد بن الحارث، قال: حدثنا سعيد، قال: حدثنا قتادة، عن زرارة بن","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:577","bookId":"nasikh-nahhas","type":"section","seq":577,"chapter":"ص: 48","title":"ص: 752","page":"ج1 ص751","text":"أوفى، عن سعد بن هشام، قال: انطلقنا إلى عائشة فاستأذنا عليها فقلت: أنبئيني بقيام رسول الله صلى الله عليه وسلم، فقالت: ألست تقرأ هذه السورة يا أيها المزمل؟، قلت: بلى، قالت: إن الله تعالى افترض القيام في أول {يا أيها المزمل} [المزمل: 1] على النبي صلى الله عليه وسلم وعلى أصحابه حولا حتى انتفخت أقدامهم فأمسك الله تعالى خاتمتها اثني عشر شهرا، ثم أنزل التخفيف في أخر هذه السورة فصار قيام الليل تطوعا بعد أن كان فريضة \" قال أبو عبد الرحمن مختصر قال أبو جعفر: فتبين بهذا الحديث أنه كان فرضا عليه وعلى أصحابه ثم نسخ وقول عائشة حولا يبين لك ما في الناسخ والمنسوخ مما يشكل على قوم وذلك أنه قيل لهم: صلوا كذا إلى حول، أو قيل لهم: صلوا كذا ثم نسخ بعد فقد كان في معنى قوله: صلوا كذا أنه إلى وقت كذا وإن لم يذكر فعلى هذا يكون النسخ\nوقرئ على محمد بن جعفر بن حفص، عن يوسف بن موسى، قال: حدثنا وكيع، ويعلى، قالا: حدثنا مسعر، عن سماك الحنفي، قال: سمعت ابن عباس، يقول: \" لما نزلت أول {يا أيها المزمل} [المزمل: 1] كانوا يقومون نحوا من","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:578","bookId":"nasikh-nahhas","type":"section","seq":578,"chapter":"ص: 48","title":"ص: 753","page":"ج1 ص751","text":"قيامهم في شهر رمضان حتى نزلت آخرها وكان بين أولها وبين آخرها نحو من سنة \"\nقال أبو جعفر: وحدثني جعفر بن مجاشع، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا إبراهيم بن عبد الله، قال: حدثنا حجاج، عن ابن جريج، عن عطاء الخراساني، عن ابن عباس، {يا أيها المزمل قم الليل إلا قليلا} [المزمل: 2] \" فلما قدم النبي صلى الله عليه وسلم المدينة نسختها هذه الآية {إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك والله يقدر الليل والنهار} [المزمل: 20] إلى آخرها \"\nحدثنا محمد بن رمضان بن شاكر، قال: حدثنا الربيع بن سليمان، قال: حدثنا محمد بن إدريس الشافعي، قال: ومما نقل بعض من سمعت منه من أهل العلم: \" أن الله تعالى أنزل فرضا في الصلاة قبل فرض الصلوات الخمس فقال: {يا أيها المزمل قم الليل إلا قليلا نصفه أو انقص منه قليلا أو زد عليه ورتل القرآن ترتيلا} [المزمل: 2] ثم نسخ هذا في السورة معه فقال: {إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك} [المزمل: 20] إلى {وآتوا الزكاة} [المزمل: 20] ولما ذكر الله تعالى بعد أمره بقيام","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:579","bookId":"nasikh-nahhas","type":"section","seq":579,"chapter":"ص: 48","title":"ص: 754","page":"ج1 ص753","text":"الليل نصفه إلا قليلا أو الزيادة عليه فقال: {أدنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك} [المزمل: 20] فخفف فقال: {علم أن سيكون منكم مرضى} [المزمل: 20] إلى {فاقرءوا ما تيسر منه} كان بينا في كتاب الله تعالى نسخ قيام الليل ونصفه والنقصان من النصف والزيادة عليه بقول الله تعالى {فاقرءوا ما تيسر منه} ثم احتمل قول الله تعالى {فاقرءوا ما تيسر منه} معنيين أحدهما: أن يكون فرضا ثابتا لأنه أزيل به فرض غيره، والآخر: أن يكون فرضا منسوخا أزيل بغيره كما أزيل به غيره وذلك لقول الله تعالى {ومن الليل فتهجد به نافلة لك عسى أن يبعثك ربك مقاما محمودا} [الإسراء: 79] ، فاحتمل قوله تعالى {ومن الليل فتهجد به نافلة} [الإسراء: 79] أن يتهجد بغير الذي فرض عليه مما تيسر منه قال الشافعي: فكان الواجب طلب الاستدلال بالسنة على أحد المعنيين فوجدنا سنة رسول الله صلى الله عليه وسلم تدل على أن لا واجب من الصلاة إلا الخمس \"","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:580","bookId":"nasikh-nahhas","type":"section","seq":580,"chapter":"ص: 48","title":"ص: 755","page":"ج1 ص753","text":"قال أبو جعفر: وأما الموضع الثاني فقوله تعالى {واصبر على ما يقولون واهجرهم هجرا جميلا} [المزمل: 10]\nقرئ على أحمد بن محمد بن الحجاج، عن يحيى بن سليمان، قال: حدثني محمد بن بكر البصري، قال: حدثنا همام بن يحيى، عن قتادة، في قوله تعالى {واصبر على ما يقولون واهجرهم هجرا جميلا} [المزمل: 10] قال: «كان هذا قبل أن يؤمر بالقتال، ثم أمر بعد بقتالهم وقتلهم فنسخت آية القتال ما كان قبلها من الترك»","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:581","bookId":"nasikh-nahhas","type":"section","seq":581,"chapter":"ص: 48","title":"سورة المدثر إلى آخر {اقرأ باسم ربك}","page":"ج1 ص755","text":"[العلق: 1]\nحدثنا يموت، بإسناده عن ابن عباس،: «أنهن نزلن بمكة» وجدنا فيهن أربعة مواضع","bab":"باب ذكر الآية الرابعة قال الله جل وعز {يا أيها النبي إذا جاءك المؤمنات يبايعنك على أن لا يشركن بالله شيئا} [الممتحنة: 12] الآية فمن العلماء من قال: هي منسوخة با"},{"id":"nasikh-nahhas:582","bookId":"nasikh-nahhas","type":"section","seq":582,"chapter":"ص: 48","title":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله","page":"ج1 ص757","text":"[الإسراء: 79] \"\nباب\nذكر الموضع الثاني قال الله جل وعز {قد أفلح من تزكى وذكر اسم ربه فصلى} [الأعلى: 15] تكلم العلماء في هذه الآية بأجوبة فروي عن ابن عباس، أنه قال: \" {من تزكى} [طه: 76] من الشرك \" وروي عنه أنه قال: «أخرجوا زكاة الفطر قبل صلاة العيد» وعن أبي مالك، \" {من تزكى} [طه: 76] : من آمن «وعن عكرمة» {من تزكى} [طه: 76] : من قال: لا إله إلا الله «وعن قتادة،» {من تزكى} [طه: 76] بالعمل الصالح والورع «وعن ابن جريج» {من تزكى} [طه: 76] بماله وعمله \" وعن عطاء: «الصدقات كلها»\nوعن عبد الله: \" إذا خرجت إلى الصلاة فتصدق بشيء إن استطعت فإن الله تعالى يقول {قد أفلح من تزكى وذكر اسم ربه فصلى} [الأعلى: 14] \" قال أبو جعفر: فهذه الأقوال متقاربة لأن التزكي في اللغة التطهر، وهذا كله تطهر لأنه انتهاء إلى ما يكفر الذنوب، وقيل زكاة من هذا، لأنها تطهير لما في المال، وقيل: هي من الزكاء أي من الزيادة والنماء، وإنما أدخلت هذه الآية في الناسخ والمنسوخ لأن جماعة من العلماء تأولوها على أنها من زكاة الفطر، منهم عمر بن عبد العزيز قال: \" أخرجوا زكاة الفطر من قبل أن تصلوا صلاة العيد فإن الله تعالى يقول {قد أفلح من تزكى وذكر اسم ربه فصلى} [الأعلى: 14] \" وهو قول سعيد بن المسيب، وأبي العالية، وموسى بن وردان، فقد ثبت أن رسول الله صلى الله عليه وسلم أمر بزكاة الفطر وفرضها قبل أن تفرض الزكاة، فجاز أن تكون ناسخة لأنها بعدها، وجاز أن تكونا واجبتين، وقد ثبت وجوبهما، وإن كان حديث قيس بن سعد بن عبادة ربما أشكل فتوهم سامعه النسخ في ذلك\nكما قرئ على أحمد بن شعيب بن علي، عن محمد بن عبد الله بن المبارك، قال: حدثنا وكيع، قال: حدثنا سفيان، عن سلمة بن كهيل، عن","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:583","bookId":"nasikh-nahhas","type":"section","seq":583,"chapter":"ص: 48","title":"ص: 762","page":"ج1 ص761","text":"القاسم بن مخيمرة، عن أبي عمار، عن قيس بن سعد، قال: «أمرنا رسول الله صلى الله عليه وسلم بصدقة الفطر قبل أن تنزل الزكاة فلما نزلت الزكاة لم يأمرنا ولم ينهنا ونحن نفعله» قال أبو جعفر: وهذا الحديث لا يدل على النسخ لأنه قد ثبت أن رسول الله صلى الله عليه وسلم قد أمرهم بها، والأمر مرة واحدة يكفي ولا يزول إلا بشيء ينسخه. والقول بأنها واجبة على الغني والفقير قول أبي هريرة، وابن عمر، وأبي العالية، والزهري وابن سيرين، والشعبي، ومالك، والشافعي، وابن المبارك غير أن الشافعي، وابن المبارك قالا: «إذا كان عنده فضل على قوته وقوت من يعوله كانت واجبة عليه» وأهل الرأي يقولون: لا تجب زكاة الفطر على من تحل له الصدقة وقال إسحاق بن راهويه: «أوجب رسول الله صلى الله عليه وسلم زكاة الفطر وعمل به الخلفاء الراشدون المهديون، وهذا يدل على أنه إجماع»\nقال","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:584","bookId":"nasikh-nahhas","type":"section","seq":584,"chapter":"ص: 48","title":"ص: 763","page":"ج1 ص761","text":": حدثنا بكر بن سهل، قال: حدثنا عبد الله بن يوسف، قال: أخبرنا مالك بن أنس، عن نافع، عن عبد الله بن عمر، قال: «فرض رسول الله صلى الله عليه وسلم زكاة الفطر في رمضان صاعا من تمر، أو صاعا من شعير على كل حر وعبد ذكر وأنثى من المسلمين» قال أبو جعفر: وقد أشكل هذا الحديث على بعض أهل النظر فقال: ليس على الرجل أن يخرج عن عبده لأن العبد فرض عليه ولم يفرض على مولاه في الحديث أن يخرج عنه فذلك على العبد أن يخرج عن نفسه إذا أعتق وهذا قول بالظاهر، وقد بين ذلك الحديث الآخر الثابت الذي لا تدفع صحته\nروى عبيد الله، عن نافع، عن ابن عمر، قال: «أمرنا رسول الله صلى الله عليه وسلم بصدقة الفطر عن كل صغير وكبير حر أو عبد صاع من شعير، أو صاع من تمر» فقد بين هذا الحديث ذلك فيجوز أن يكون المعنى على كل حر وعبد يخرج عنه الحر، ويجوز أن تكون على بمعنى عن وذلك معروف في اللغة وموجود قال الله عز وجل {أفتمارونه على ما يرى} [النجم: 12] لا نعلم اختلافا أن معناه: عما يرى وأنشد النحويون\n[البحر الوافر]\nإذا رضيت علي بنو قشير ... لعمر أبيك أعجبني رضاها","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:585","bookId":"nasikh-nahhas","type":"section","seq":585,"chapter":"ص: 48","title":"ص: 764","page":"ج1 ص762","text":"قال محمد بن جرير: «أجمع أهل العلم على أن زكاة الفطر فرضت ثم اختلفوا في نسخها» قال أبو جعفر: فلما ثبت بالإجماع وبالأسانيد الصحاح عن النبي صلى الله عليه وسلم لم يجز أن تزال إلا بإجماع أو حديث يزيلها ويبين نسخها، ولم يأت من ذلك شيء وصح عن الصحابة والتابعين إيجابها، واختلفوا في مقدار ما يخرج منها من البر والزبيب، وأجمعوا على أنه لا يجوز من الشعير والتمر إلا صاع فممن قال: لا يجزئ من البر إلا صاع الحسن، ومالك، والشافعي، وأحمد، ويروى هذا القول عن علي بن أبي طالب، وابن العباس، واختلف عنهما وممن قال: يجزئ نصف صاع من الصحابة أبو بكر الصديق، وعثمان، وعبد الله بن مسعود، وأسماء، وجابر، وابن الزبير، وأبو هريرة، ومعاوية، فهؤلاء ثمانية من الصحابة ومن التابعين سعيد بن المسيب، وعمر بن عبد العزيز، وعروة، وأبو سلمة","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:586","bookId":"nasikh-nahhas","type":"section","seq":586,"chapter":"ص: 48","title":"ص: 765","page":"ج1 ص762","text":"، وعطاء، وطاوس، ومجاهد، وسعيد بن جبير، وأبو قلابة، وعبد الله بن شداد، ومصعب بن سعد، فهؤلاء أحد عشر من التابعين، وممن دونهم الليث بن سعد، والثوري، وأبو حنيفة وصاحباه، قال أبو جعفر: والحجة للقول الأول: أن رسول الله صلى الله عليه وسلم لما فرض صاعا من شعير، أو صاعا من تمر وكان ذلك قوتهم فوجب أن يكون كل قوت كذلك والحجة للقول الثاني: أن الصحابة هم الذين قدروا نصف صاع بر، وهم أعلم الناس بأمر رسول الله صلى الله عليه وسلم ولا تجوز مخالفتهم إلا إلى قول بعضهم، فإن قيل: فقد خالفهم علي بن أبي طالب، وابن عباس رضي الله عنهم، فالجواب أنه قد اختلف عنهما وليس أحد القولين أولى من الآخر إلا بالاحتجاج بغيرهما\nوقرئ على أحمد بن شعيب، عن عمران بن موسى، عن عبد الوارث، قال: حدثنا أيوب، عن نافع عن ابن عمر، قال: «فرض رسول الله صلى الله عليه وسلم زكاة رمضان صاعا من تمر، أو صاعا من شعير على كل حر وعبد ذكر وأنثى فعدل الناس به نصف صاع بر» قال أبو جعفر: فهذا ابن عمر يخبر: أن الناس فعلوا هذا والناس أتباعه","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:587","bookId":"nasikh-nahhas","type":"section","seq":587,"chapter":"ص: 48","title":"ص: 767","page":"ج1 ص763","text":"، فأما الزبيب فأهل العلم مجمعون على أنه لا يجزئ منه في زكاة الفطر إلا صاع خلا أبا حنيفة، فإن أبا يوسف روى عنه أنه يخرج منه نصف صاع كما يخرج من البر وأما الاختيار فيما يخرج فأهل العلم مختلفون في ذلك: فيروى عن ابن عمر أنه كان يخرج التمر، وقال مالك: أحب ما أخرج أهل المدينة إلي التمر، وقال أحمد: «إخراج التمر أحب إلي وإن كانوا يقتاتون غيره» ، وقال غيره: لأن التمر منفعته عاجلة، وقال الشافعي: «البر أحب إلي» ، وقال أبو يوسف: «أعجلها منفعة الدقيق يخرج نصف صاع دقيق من بر، أو صاعا من دقيق الشعير» قال أبو جعفر: فأما إخراج القيمة فمختلف فيه أيضا، فممن أجاز","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:588","bookId":"nasikh-nahhas","type":"section","seq":588,"chapter":"ص: 48","title":"ص: 768","page":"ج1 ص763","text":"ذلك عمر بن عبد العزيز، والحسن، وأهل الرأي ولم يجز مالك، والشافعي، وأحمد إلا إخراج المكيلة كما جاءت به السنة، وقال إسحاق: «يجوز ذلك عند الضرورة» فأما دفع زكاة الفطر إلى إنسان واحد وإن كانت عن جماعة فمما اختلف فيه أيضا، فأجازه أهل المدينة، وقال الشافعي: «تقسم كما تقسم الزكاة» ، وأما إعطاء أهل الذمة منها فمختلف فيه أيضا، فأكثر أهل العلم لا يجيزه، ومنهم من أجازه، فممن أجازه مرة الهمداني، وهو قول أهل الرأي فرقوا بينها وبين الزكاة فلم يجيزوا في الزكاة إلا دفعها إلى المسلمين، وأجازوا في زكاة الفطر أن تدفع إلى أهل الذمة وأما دفع الرجل عن زوجته فمختلف فيه أيضا، فأكثر أهل العلم يوجبون عليه ذلك، وقال الثوري، وأهل الرأي: لا «يجب ذلك عليه»","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:589","bookId":"nasikh-nahhas","type":"section","seq":589,"chapter":"ص: 48","title":"ص: 769","page":"ج1 ص763","text":"واختلفوا أيضا في أهل البادية فقال عطاء، والزهري، وربيعة: لا تجب عليهم زكاة الفطر، وقال سعيد بن المسيب: هي واجبة عليهم {قد أفلح من تزكى وذكر اسم ربه فصلى} [الأعلى: 15] وهو قول أكثر أهل المدينة، وأهل الكوفة وأما العبد المأذون له في التجارة فمختلف في أداء زكاة الفطر عنه أيضا، فقال الحسن، وعطاء: «لا يجب على مولاه أن يؤديها عنه» ، وهو قول أهل الرأي، وقال مالك، والليث، والأوزاعي، والشافعي: «عليه أن يؤديها عنه»","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:590","bookId":"nasikh-nahhas","type":"section","seq":590,"chapter":"ص: 48","title":"ص: 770","page":"ج1 ص763","text":"واختلفوا أيضا في المكاتب فقال مالك: «على مولاه أن يؤدي عنه» ، وقال أهل الرأي، والشافعي: «ليس ذلك عليه» وكذلك روي عن ابن عمر، ولهذا الاختلاف قال بعض العلماء: ليس على الرجل أن يؤدي إلا عن نفسه، كما قال رسول الله صلى الله عليه وسلم: «على كل حر وعبد» ، فالحر يؤدي عن نفسه، والعبد يؤدي عن نفسه\nكما روى عبيد الله، عن نافع، عن ابن عمر، قال: «ليس على العبد في ماله شيء إلا صدقة الفطر» إلا أن الفقهاء الذين تدور عليهم الفتيا يقولون","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:591","bookId":"nasikh-nahhas","type":"section","seq":591,"chapter":"ص: 48","title":"ص: 771","page":"ج1 ص766","text":": عليه أن يخرج عن عبده فأما تقدير الصاع فقد قدره جماعة من أهل العلم على أنه خمس ويبة، والمد ربعه قال أبو جعفر: لا نعلم اختلافا في الكيل، فمن قال: يخرج الإنسان صاعا من بر قال: يخرج الويبة عن خمسة، ومن قال: يخرج نصف صاع من بر قال: الوبية عن عشرة وهذا قول الليث، والمتفقهون من أهل الرأي يقولون: عن ثمانية واختلفوا في مقدار الصاع من الوزن فقول الشافعي، وأبي يوسف: «أنه خمسة أرطال وثلث» ، وعن أهل المدينة أخذ هذا، وهم","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:592","bookId":"nasikh-nahhas","type":"section","seq":592,"chapter":"ص: 48","title":"ص: 772","page":"ج1 ص766","text":"أعلم الناس به، وقال أبو حنيفة، ومحمد: «هو ثمانية أرطال» وأما الموضع الثالث فقوله جل وعز {فذكر إنما أنت مذكر لست عليهم بمصيطر} [الغاشية: 22] قال ابن زيد: \" أي لست تكرههم على الإيمان، ثم جاء بعد ذلك {جاهد الكفار والمنافقين واغلظ عليهم} [التوبة: 73] ، {واقعدوا لهم كل مرصد} [التوبة: 5] فنسخ هذا {لست عليهم بمصيطر} [الغاشية: 22] فجاء: قتله أو يسلم، والتذكرة كما هي لم تنسخ «وفي رواية ابن أبي طلحة، عن، ابن عباس،» {لست عليهم بمصيطر} [الغاشية: 22] قال: بجبار \" قال أبو جعفر: وهذا معروف في اللغة يقال: تسيطر على القوم إذا تسلط عليهم، أي: لست تجبرهم على الإسلام إنما عليك أن تدعوهم إليه، ثم تكلهم إلى الله عز وجل وأما الموضع الرابع: فقوله عز وجل {فإذا فرغت فانصب وإلى ربك فارغب} [الشرح: 7] قال أبو جعفر: اختلف العلماء في معناه\nفمن ذلك ما حدثناه أحمد بن محمد بن","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:593","bookId":"nasikh-nahhas","type":"section","seq":593,"chapter":"ص: 48","title":"ص: 773","page":"ج1 ص770","text":"نافع، قال: حدثنا سلمة، قال: حدثنا عبد الرزاق، قال: أخبرنا معمر، عن قتادة،: {فإذا فرغت فانصب} [الشرح: 7] قال: «إذا فرغت من صلاتك فانصب في الدعاء» وقال الحسن: «إذا فرغت من غزوك وجهادك فتعبد لله تعالى» وقال مجاهد: «إذا فرغت من شغلك بأمور الدنيا فصل واجعل رغبتك إلى الله تعالى» قال أبو جعفر: وإنما أدخل هذا في الناسخ والمنسوخ لأن عبد الله بن مسعود رضي الله عنه قال في معنى فانصب: أنه «فانصب لقيام الليل، وفرض قيام الليل منسوخ على أن هذا غير واجب» والمعاني في الآية متقاربة أي: إذا فرغت من شغلك بما يجوز أن تشتغل به من أمور الدنيا أو الآخرة فانصب، أي: انتصب لله تعالى واشتغل بذكره ودعائه والصلاة له، ولا تشتغل باللهو وما يؤثم وقد بين ابن مسعود رضي الله عنه ما أراد بقوله: فإذا فرغت من الفرائض فانصب لقيام الليل","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "},{"id":"nasikh-nahhas:594","bookId":"nasikh-nahhas","type":"section","seq":594,"chapter":"ص: 48","title":"سورة القدر إلى آخر القرآن","page":"ج1 ص772","text":"حدثنا يموت، بإسناده عن ابن عباس،: «أن سورة القدر، ولم يكن مدنيتان، وأن إذا زلزلت الأرض زلزالها إلى آخر قل يا أيها الكافرون مكية، وأن إذا جاء نصر الله إلى آخر قل أعوذ برب الناس مدنية»\nوقال كريب: وجدنا في كتاب ابن عباس: «أن من سورة القدر إلى آخر القرآن مكية إلا إذا زلزلت الأرض، وإذا جاء نصر الله، وقل هو الله أحد\n، وقل أعوذ برب الفلق، وقل أعوذ برب الناس فإنهن مدنيات» وقال أبو جعفر: لم يجد فيهن ناسخا ولا منسوخا، وإذا تدبرت ذلك وجدت أكثرهن وأكثر ما ليس فيه ناسخ ولا منسوخ إنما هو فيما لا يجوز أن يقع فيه نسخ لأنه لا يجوز أن يقع نسخ في توحيد الله عز وجل، ولا في أسمائه، ولا في صفاته، والعلماء يقولون: ولا في إخباره، ومعناه: ولا في إخباره بما كان وما يكون والحكمة في هذا: أن النسخ إنما يكون في أحكام الشرائع من الصلاة، والصيام، والحظر، والإباحة، وقد يجوز أن ينقل الشيء من الأمر إلى النهي، ومن النهي إلى الأمر لأنك إذا قلت: افعل كذا، وكذا محرم عليك سنة، جاز أن تبيحه بعد سنة، وإذا قلت: افعل كذا، وكذا محرم عليك، وأنت لا تريد وقتا أو شرطا فكذا أيضا سواء عليك ذكرته أم لم تذكره، فهذا محال في توحيد الله عز وجل، وأسمائه، وصفاته، وإخباره بما كان وما يكون ألا ترى أنه محال أن تقول: قام فلان، ثم تقول بعد وقت: لم يقم، لأنه لم يقع في الأول اشتراط، ولا زمان، فالنسخ في الإخبار بما كان وما يكون\nكذب، وفي الأمر والنهي أيضا مما لا يقع فيه نسخ وذلك الأمر بتوحيد الله عز وجل واتباع رسله صلى الله عليهم أجمعين وخص محمدا صلى الله عليه وسلم نبي الرحمة بالصلاة والتسليم وعلى آله وأصحابه وأزواجه واتباعه بإحسان وفضل وكرم، والحمد لله رب العالمين","bab":"باب ذكر الموضع الأول قال الله جل وعز {ومن الليل فاسجد له وسبحه ليلا طويلا} [الإنسان: 26] قال ابن زيد: \" كان هذا أول شيء فريضة، ثم خففها الله تعالى فقال جل وعز: "}]};